    // --- integrator_inner (forwards the FD inner's Minv F-region lever) ---
    template <typename T, bool MINV_F_IN_SMEM = true> __host__ __device__ constexpr size_t INTEGRATOR_INNER_SMEM_BYTES() { return MINV_F_IN_SMEM ? sizeof(T) * static_cast<size_t>(3398) : sizeof(T) * static_cast<size_t>(1454); }
