    template <typename T, uint32_t N, uint32_t K,
              FillMode FILL = FillMode::Full, bool TRANSPOSE = false, bool ROW_MAJOR = false, bool TRAILING_SYNC = true>
    __device__ void syr2k(T alpha, const T *A, const T *B, T *C)
    {
