    template <typename T>
    __device__
    void mx4_scaled(T *s_vecX, const T *s_vec, const T alpha) {
        glass::thread::motion_cross_mul<T, 4, false>(alpha, s_vec, nullptr, static_cast<T>(0), s_vecX);
