    /**
     * Updates the (d)XmatsHom in (shared) GPU memory acording to the configuration
     *
     * @param s_XmatsHom is the (shared) memory destination location for the XmatsHom
     * @param s_d2XmatsHom is the (shared) memory destination location for the d2XmatsHom
     * @param s_dXmatsHom is the (shared) memory destination location for the dXmatsHom
     * @param s_q is the (shared) memory location of the current configuration
     * @param s_topology_helpers is the (shared) memory location for the topology_helpers (nullptr/unused for serial chains with identical Ss)
     * @param d_robotModel is the pointer to the initialized model specific helpers (XImats, mxfuncs, topology_helpers, etc.)
     * @param s_temp is temporary (shared) memory used to compute sin and cos if needed of size: 38
     */
    template <typename T>
    __device__ __forceinline__
    void load_update_XmatsHom_helpers(T *s_XmatsHom, T *s_dXmatsHom, T *s_d2XmatsHom, int *s_topology_helpers, const T *s_q, const robotModel<T> *d_robotModel, T *s_temp) {
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 672; ind += blockDim.x*blockDim.y){
            s_XmatsHom[ind] = d_robotModel->d_XImats[ind+936];
        }
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 304; ind += blockDim.x*blockDim.y){
            s_dXmatsHom[ind] = d_robotModel->d_XImats[ind+1608];
        }
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 5776; ind += blockDim.x*blockDim.y){
            s_d2XmatsHom[ind] = d_robotModel->d_XImats[ind+1912];
        }
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 115; ind += blockDim.x*blockDim.y){
            s_topology_helpers[ind] = d_robotModel->d_topology_helpers[ind];
        }
        for(int k = threadIdx.x + threadIdx.y*blockDim.x; k < 19; k += blockDim.x*blockDim.y){
            s_temp[k] = static_cast<T>(sin(s_q[k]));
            s_temp[k+19] = static_cast<T>(cos(s_q[k]));
        }
        __syncthreads();
        if(threadIdx.x == 0 && threadIdx.y == 0){
            // X_hom[0]
            s_XmatsHom[0] = static_cast<T>(-2.0*pow(s_q[4], 2)/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)) - 2.0*pow(s_q[5], 2)/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)) + 1.0);
            s_XmatsHom[1] = static_cast<T>(2.0*s_q[3]*s_q[4]/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)) + 2.0*s_q[5]*s_q[6]/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)));
            s_XmatsHom[2] = static_cast<T>(2.0*s_q[3]*s_q[5]/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)) - 2.0*s_q[4]*s_q[6]/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)));
            s_XmatsHom[4] = static_cast<T>(2.0*s_q[3]*s_q[4]/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)) - 2.0*s_q[5]*s_q[6]/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)));
            s_XmatsHom[5] = static_cast<T>(-2.0*pow(s_q[3], 2)/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)) - 2.0*pow(s_q[5], 2)/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)) + 1.0);
            s_XmatsHom[6] = static_cast<T>(2.0*s_q[3]*s_q[6]/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)) + 2.0*s_q[4]*s_q[5]/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)));
