                T Br_00 = static_cast<T>(0);
                T Br_01 = static_cast<T>(0);
                T Br_02 = static_cast<T>(0);
                T Br_10 = static_cast<T>(0);
                T Br_11 = static_cast<T>(0);
                T Br_12 = static_cast<T>(0);
                T Br_20 = static_cast<T>(0);
                T Br_21 = static_cast<T>(0);
                T Br_22 = static_cast<T>(0);
                T Bt_0 = static_cast<T>(0);
                T Bt_1 = static_cast<T>(0);
                T Bt_2 = static_cast<T>(0);
                if (sshape == 0) {
                    T adotb = uw_0*vw_0 + uw_1*vw_1 + uw_2*vw_2;
                    Br_00 = static_cast<T>(0.5) * (uw_0*vw_0 + vw_0*uw_0) - adotb;
                    Br_01 = static_cast<T>(0.5) * (uw_0*vw_1 + vw_0*uw_1);
                    Br_02 = static_cast<T>(0.5) * (uw_0*vw_2 + vw_0*uw_2);
                    Br_10 = static_cast<T>(0.5) * (uw_1*vw_0 + vw_1*uw_0);
                    Br_11 = static_cast<T>(0.5) * (uw_1*vw_1 + vw_1*uw_1) - adotb;
                    Br_12 = static_cast<T>(0.5) * (uw_1*vw_2 + vw_1*uw_2);
                    Br_20 = static_cast<T>(0.5) * (uw_2*vw_0 + vw_2*uw_0);
                    Br_21 = static_cast<T>(0.5) * (uw_2*vw_1 + vw_2*uw_1);
                    Br_22 = static_cast<T>(0.5) * (uw_2*vw_2 + vw_2*uw_2) - adotb;
                    Bt_0 = -(Br_00*pax + Br_01*pay + Br_02*paz);
                    Bt_1 = -(Br_10*pax + Br_11*pay + Br_12*paz);
                    Bt_2 = -(Br_20*pax + Br_21*pay + Br_22*paz);
                }
                else if (sshape == 1) {
                    Bt_0 = static_cast<T>(0.5) * (uw_1*vw_2 - uw_2*vw_1);
                    Bt_1 = static_cast<T>(0.5) * (uw_2*vw_0 - uw_0*vw_2);
                    Bt_2 = static_cast<T>(0.5) * (uw_0*vw_1 - uw_1*vw_0);
                }
                T Hxyz_x = Br_00*pex + Br_01*pey + Br_02*pez + Bt_0;
                T Hxyz_y = Br_10*pex + Br_11*pey + Br_12*pez + Bt_1;
                T Hxyz_z = Br_20*pex + Br_21*pey + Br_22*pez + Bt_2;
                // Read [Jw_i]_x and [Jw_j]_x for the H_w correction
                T Si00 = s_Sworld[si_base + 0];
                T Si10 = s_Sworld[si_base + 1];
                T Si20 = s_Sworld[si_base + 2];
                T Si01 = s_Sworld[si_base + 4];
                T Si11 = s_Sworld[si_base + 5];
                T Si21 = s_Sworld[si_base + 6];
                T Si02 = s_Sworld[si_base + 8];
                T Si12 = s_Sworld[si_base + 9];
                T Si22 = s_Sworld[si_base + 10];
                T Sj00 = s_Sworld[sj_base + 0];
                T Sj10 = s_Sworld[sj_base + 1];
                T Sj20 = s_Sworld[sj_base + 2];
                T Sj01 = s_Sworld[sj_base + 4];
                T Sj11 = s_Sworld[sj_base + 5];
                T Sj21 = s_Sworld[sj_base + 6];
                T Sj02 = s_Sworld[sj_base + 8];
                T Sj12 = s_Sworld[sj_base + 9];
                T Sj22 = s_Sworld[sj_base + 10];
                T SiSj00 = Si00*Sj00 + Si01*Sj10 + Si02*Sj20;
                T SiSj01 = Si00*Sj01 + Si01*Sj11 + Si02*Sj21;
                T SiSj02 = Si00*Sj02 + Si01*Sj12 + Si02*Sj22;
                T SiSj10 = Si10*Sj00 + Si11*Sj10 + Si12*Sj20;
                T SiSj11 = Si10*Sj01 + Si11*Sj11 + Si12*Sj21;
                T SiSj12 = Si10*Sj02 + Si11*Sj12 + Si12*Sj22;
                T SiSj20 = Si20*Sj00 + Si21*Sj10 + Si22*Sj20;
                T SiSj21 = Si20*Sj01 + Si21*Sj11 + Si22*Sj21;
                T SiSj22 = Si20*Sj02 + Si21*Sj12 + Si22*Sj22;
                T HW_x = static_cast<T>(0.5) * ((Br_21 - SiSj21) - (Br_12 - SiSj12));
                T HW_y = static_cast<T>(0.5) * ((Br_02 - SiSj02) - (Br_20 - SiSj20));
                T HW_z = static_cast<T>(0.5) * ((Br_10 - SiSj10) - (Br_01 - SiSj01));
                s_end_effector_pose_hessian[out_base + 0 * 324] = Hxyz_x;
                s_end_effector_pose_hessian[out_base + 1 * 324] = Hxyz_y;
                s_end_effector_pose_hessian[out_base + 2 * 324] = Hxyz_z;
                s_end_effector_pose_hessian[out_base + 3 * 324] = HW_x;
                s_end_effector_pose_hessian[out_base + 4 * 324] = HW_y;
                s_end_effector_pose_hessian[out_base + 5 * 324] = HW_z;
            }
        }
        __syncthreads();
        //
        // Step 6: rpy chain rule -- replace rows 3..5 with H_rpy = dEinv/dv_j @ J_w_i + Einv @ H_w
        //
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 1296; ind += blockDim.x*blockDim.y){
            int vj = ind % 18;
            int vi = (ind / 18) % 18;
            int ee = ind / 324;
            T cy = s_E_sc[4*ee + 0]; T sy = s_E_sc[4*ee + 1]; T cp = s_E_sc[4*ee + 2]; T sp = s_E_sc[4*ee + 3];
            T inv_cp = static_cast<T>(1) / cp;
            // Einv (3x3); row 0 = roll, row 1 = pitch, row 2 = yaw
            T Einv00 = cy * inv_cp;       T Einv01 = sy * inv_cp;       T Einv02 = static_cast<T>(0);
            T Einv10 = -sy;               T Einv11 = cy;                T Einv12 = static_cast<T>(0);
            T Einv20 = cy * sp * inv_cp;  T Einv21 = sy * sp * inv_cp;  T Einv22 = static_cast<T>(1);
            int dee_base_j = ee * 108 + 6 * vj;
            T drpy_j0 = s_end_effector_pose_gradient[dee_base_j + 3];
            T drpy_j1 = s_end_effector_pose_gradient[dee_base_j + 4];
            T drpy_j2 = s_end_effector_pose_gradient[dee_base_j + 5];
            int dee_base_i = ee * 108 + 6 * vi;
            T drpy_i0 = s_end_effector_pose_gradient[dee_base_i + 3];
            T drpy_i1 = s_end_effector_pose_gradient[dee_base_i + 4];
            T drpy_i2 = s_end_effector_pose_gradient[dee_base_i + 5];
            int hw_base = ee * 1944 + 3 * 324 + vi * 18 + vj;
            T Hw_x = s_end_effector_pose_hessian[hw_base + 0 * 324];
            T Hw_y = s_end_effector_pose_hessian[hw_base + 1 * 324];
            T Hw_z = s_end_effector_pose_hessian[hw_base + 2 * 324];
            T dE00 = -cy * sp * drpy_j1 - sy * cp * drpy_j2;
            T dE01 = -cy * drpy_j2;
            // dE02 = 0
            T dE10 = -sy * sp * drpy_j1 + cy * cp * drpy_j2;
            T dE11 = -sy * drpy_j2;
            // dE12 = 0
            T dE20 = -cp * drpy_j1;
            // dE21 = dE22 = 0
            // row 0 (roll): U_0 = Einv[0,:] @ dE_total
            T U0_0 = Einv00 * dE00 + Einv01 * dE10 + Einv02 * dE20;
            T U0_1 = Einv00 * dE01 + Einv01 * dE11;
            // row 1 (pitch)
            T U1_0 = Einv10 * dE00 + Einv11 * dE10 + Einv12 * dE20;
            T U1_1 = Einv10 * dE01 + Einv11 * dE11;
            // row 2 (yaw)
            T U2_0 = Einv20 * dE00 + Einv21 * dE10 + Einv22 * dE20;
            T U2_1 = Einv20 * dE01 + Einv21 * dE11;
            T H_rpy_0 = -(U0_0 * drpy_i0 + U0_1 * drpy_i1) + (Einv00 * Hw_x + Einv01 * Hw_y + Einv02 * Hw_z);
            T H_rpy_1 = -(U1_0 * drpy_i0 + U1_1 * drpy_i1) + (Einv10 * Hw_x + Einv11 * Hw_y + Einv12 * Hw_z);
            T H_rpy_2 = -(U2_0 * drpy_i0 + U2_1 * drpy_i1) + (Einv20 * Hw_x + Einv21 * Hw_y + Einv22 * Hw_z);
            int out_base = ee * 1944 + 3 * 324 + vi * 18 + vj;
            s_end_effector_pose_hessian[out_base + 0 * 324] = H_rpy_0;
            s_end_effector_pose_hessian[out_base + 1 * 324] = H_rpy_1;
            s_end_effector_pose_hessian[out_base + 2 * 324] = H_rpy_2;
        }
        __syncthreads();
        //
        // Step 7: symmetrize H_rpy (rows 3..5) over (i, j)
        //
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 3888; ind += blockDim.x*blockDim.y){
            int e = ind / 972;
            int cji = ind % 972;
            int rrow = cji / 324;   // 0..2 -> c = 3 + rrow
            int ji = cji % 324;
            int i = ji / 18; int j = ji % 18;
            if (i <= j) {
                int c = 3 + rrow;
                int idx_ij = e * 1944 + c * 324 + i * 18 + j;
                int idx_ji = e * 1944 + c * 324 + j * 18 + i;
                T avg = static_cast<T>(0.5) * (s_end_effector_pose_hessian[idx_ij] + s_end_effector_pose_hessian[idx_ji]);
                s_end_effector_pose_hessian[idx_ij] = avg;
                if (i != j) { s_end_effector_pose_hessian[idx_ji] = avg; }
            }
        }
        __syncthreads();
    }

    /**
     * Computes the Hessian (and Jacobian) of the End Effector Pose with respect to generalized velocity (d^2/dv^2 tangent, pinocchio convention)
     *
     * Notes:
     *   Inline-CUDA users: at TIER_LITE/TIER_MINIMAL the large s_end_effector_pose_hessian output (~7776*sizeof(T) bytes) moves from shared memory to d_workspace, freeing smem for the caller's outer kernel
     *
     * @param s_end_effector_pose_hessian is a pointer to shared memory of size 6*NUM_VEL*NUM_VEL*NUM_EE where NUM_VEL = 18 and NUM_EE = 4 (d^2/dv^2 tangent, pinocchio convention)
     * @param s_end_effector_pose_gradient is a pointer to shared memory of size 6*NUM_VEL*NUM_EE (d/dv tangent Jacobian)
     * @param s_q is the vector of joint positions
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param d_workspace is the global scratch buffer; size END_EFFECTOR_POSE_HESSIAN_DEVICE_INLINE_WORKSPACE_BYTES<T, RESOURCE_TIER>() bytes (= 0 at TIER_SHARED, 7776*sizeof(T) at TIER_LITE+). Pass nullptr at TIER_SHARED
     */
    template <typename T, int RESOURCE_TIER = TIER_SHARED>
    __device__
    void end_effector_pose_hessian_device(T *s_end_effector_pose_hessian, T *s_end_effector_pose_gradient, const T *s_q, const robotModel<T> *d_robotModel, T *d_workspace = nullptr) {
        // GRID shared arena layout
        //   T s_XmatsHom[672]
        //   T s_temp[1840]
        //   int s_topology_helpers[115]
        //   bytes s_linalg_smem[GRID_EE_LINALG_SHARED_BYTES<T>()]
        extern __shared__ __align__(16) unsigned char s_arena[];
        size_t s_arena_offset = 0;
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_XmatsHom = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(672);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(1840);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
        int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(int) * static_cast<size_t>(115);
        unsigned char *s_linalg_smem = nullptr;
        if (static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>()) > 0) {
            s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
            s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
            s_arena_offset += static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>());
        }
        #ifdef GRID_CUDA_DEBUG_LAYOUT
        assert(s_arena_offset == grid_shared_arena_bytes<T>(2512, 115, GRID_EE_LINALG_SHARED_BYTES<T>()));
        #endif
        (void)s_arena_offset;
        load_update_XmatsHom_helpers<T>(s_XmatsHom, s_topology_helpers, s_q, d_robotModel, s_temp);
        end_effector_pose_hessian_inner<T, D2EE_OUT_IN_SMEM<RESOURCE_TIER>()>(s_end_effector_pose_hessian, s_end_effector_pose_gradient, s_q, s_XmatsHom, s_topology_helpers, s_temp, d_workspace, d_robotModel, s_linalg_smem);
    }

    /**
     * Computes the Hessian (and Jacobian) of the End Effector Pose with respect to generalized velocity (d^2/dv^2 tangent, pinocchio convention)
     *
     * Notes:
     *   Output d^2(pose)/dv^2 is in tangent-space convention (d/dv), shape 6 x nv x nv per ee, C-order. Matches pinocchio.
     *
     * @param d_end_effector_pose_hessian is the vector of end effector pose Hessians (6 x nv x nv per ee)
     * @param d_end_effector_pose_gradient is the vector of end effector pose Jacobians (6 x nv per ee)
     * @param d_workspace is the generated global spill workspace
     * @param d_q is the vector of joint positions
     * @param stride_q is the stide between each q
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
     */
    template <typename T, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER, bool MUJOCO_OUTPUT = false>
    __global__
    __launch_bounds__(tier_max_threads<RESOURCE_TIER>())
    void end_effector_pose_hessian_kernel_single_timing(T *d_end_effector_pose_hessian, T *d_end_effector_pose_gradient, unsigned char *d_workspace, const T *d_q, const int stride_q, const robotModel<T> *d_robotModel, const int NUM_TIMESTEPS) {
        if constexpr (RESOURCE_TIER == TIER_SHARED) {
            // GRID shared arena layout
            //   T s_q[19]
            //   T s_end_effector_pose_hessian[7776]
            //   T s_end_effector_pose_gradient[432]
            //   T s_XmatsHom[672]
            //   T s_temp[1840]
            //   int s_topology_helpers[115]
            //   bytes s_linalg_smem[GRID_EE_LINALG_SHARED_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(19);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_end_effector_pose_hessian = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(7776);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_end_effector_pose_gradient = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(432);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XmatsHom = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(672);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(1840);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
            int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(int) * static_cast<size_t>(115);
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(10739, 115, GRID_EE_LINALG_SHARED_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            // load to shared mem
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 19; ind += blockDim.x*blockDim.y){
                s_q[ind] = d_q[ind];
            }
            __syncthreads();
            if constexpr (MUJOCO_OUTPUT) {
                // mjx input convert: base quaternion wxyz->xyzw (q-only; value frame-independent)
                if (threadIdx.x == 0 && threadIdx.y == 0) {
                    T qw_in = s_q[3];
                    s_q[3] = s_q[4]; s_q[4] = s_q[5]; s_q[5] = s_q[6]; s_q[6] = qw_in;
                }
                __syncthreads();
            }
            (void)d_workspace;
            // compute with NUM_TIMESTEPS as NUM_REPS for timing
            for (int rep = 0; rep < NUM_TIMESTEPS; rep++){
                // anti-LICM: volatile reload of inputs each rep
                for(int _aopt_i = threadIdx.x + threadIdx.y*blockDim.x; _aopt_i < 19; _aopt_i += blockDim.x*blockDim.y){
                    reinterpret_cast<volatile T *>(s_q)[_aopt_i] = reinterpret_cast<const volatile T *>(d_q)[_aopt_i];
                }
                __syncthreads();
                // anti-LICM (1/2): stomp one input slot with `rep`
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    reinterpret_cast<volatile T *>(s_q)[rep % (19)] = static_cast<T>(rep);
                }
                // anti-LICM (2/2): feedback prev rep's d_end_effector_pose_hessian into s_q (true loop-carried dep)
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    T _aopt_fb1 = reinterpret_cast<const volatile T *>(d_end_effector_pose_hessian)[(rep + 0x3FF) & 0x3FF];
                    T _aopt_fb2 = reinterpret_cast<const volatile T *>(d_end_effector_pose_hessian)[(rep + 0x3FE) & 0x3FF];
                    T _aopt_fb3 = reinterpret_cast<const volatile T *>(d_end_effector_pose_hessian)[(rep + 0x3FD) & 0x3FF];
                    reinterpret_cast<volatile T *>(s_q)[(rep + 1) % (19)] += _aopt_fb1;
                    reinterpret_cast<volatile T *>(s_q)[(rep + 2) % (19)] += _aopt_fb2;
                    reinterpret_cast<volatile T *>(s_q)[(rep + 3) % (19)] += _aopt_fb3;
                }
                __syncthreads();
                load_update_XmatsHom_helpers<T>(s_XmatsHom, s_topology_helpers, s_q, d_robotModel, s_temp);
                end_effector_pose_hessian_inner<T, true>(s_end_effector_pose_hessian, s_end_effector_pose_gradient, s_q, s_XmatsHom, s_topology_helpers, s_temp, nullptr, d_robotModel, s_linalg_smem);
                __syncthreads();
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) { reinterpret_cast<volatile T *>(d_end_effector_pose_hessian)[rep & 1023] = reinterpret_cast<const volatile T *>(s_end_effector_pose_hessian)[rep & 7]; }
            }
            // save down to global
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 7776; ind += blockDim.x*blockDim.y){
                d_end_effector_pose_hessian[ind] = s_end_effector_pose_hessian[ind];
            }
            __syncthreads();
            // save down to global
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 432; ind += blockDim.x*blockDim.y){
                d_end_effector_pose_gradient[ind] = s_end_effector_pose_gradient[ind];
            }
            __syncthreads();
        }
        else if constexpr (RESOURCE_TIER == TIER_LITE) {
            // GRID shared arena layout
            //   T s_q[19]
            //   T s_end_effector_pose_hessian[7776]
            //   T s_end_effector_pose_gradient[432]
            //   T s_XmatsHom[672]
            //   T s_temp[1840]
            //   int s_topology_helpers[115]
            //   bytes s_linalg_smem[GRID_EE_LINALG_SHARED_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(19);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_end_effector_pose_hessian = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(7776);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_end_effector_pose_gradient = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(432);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XmatsHom = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(672);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(1840);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
            int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(int) * static_cast<size_t>(115);
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(10739, 115, GRID_EE_LINALG_SHARED_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            // load to shared mem
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 19; ind += blockDim.x*blockDim.y){
