        gpuErrchk(grid_check_dynamic_shared_memory_bytes("end_effector_pose_hessian", END_EFFECTOR_POSE_HESSIAN_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()));
        struct timespec start, end; clock_gettime(CLOCK_MONOTONIC,&start);
        dim3 _grid_thr_clamped_8 = grid_host_clamp_threads((const void*)&end_effector_pose_hessian_kernel_single_timing<T, RESOURCE_TIER, MUJOCO_OUTPUT>, thread_dimms);
        if (USE_COMPRESSED_MEM) {end_effector_pose_hessian_kernel_single_timing<T, RESOURCE_TIER, MUJOCO_OUTPUT><<<block_dimms,_grid_thr_clamped_8,END_EFFECTOR_POSE_HESSIAN_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_end_effector_pose_hessian,hd_data->d_end_effector_pose_gradient,hd_data->d_workspace,hd_data->d_q,stride_q,d_robotModel,num_timesteps);}
        else                    {end_effector_pose_hessian_kernel_single_timing<T, RESOURCE_TIER, MUJOCO_OUTPUT><<<block_dimms,_grid_thr_clamped_8,END_EFFECTOR_POSE_HESSIAN_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_end_effector_pose_hessian,hd_data->d_end_effector_pose_gradient,hd_data->d_workspace,hd_data->d_q_qd_u,stride_q,d_robotModel,num_timesteps);}
        gpuErrchkKernel();
        clock_gettime(CLOCK_MONOTONIC,&end);
        // finally transfer the result back
        gpuErrchk(cudaMemcpy(hd_data->h_end_effector_pose_gradient,hd_data->d_end_effector_pose_gradient,6*NUM_EES*NUM_VEL*sizeof(T),cudaMemcpyDeviceToHost));
        gpuErrchk(cudaMemcpy(hd_data->h_end_effector_pose_hessian,hd_data->d_end_effector_pose_hessian,6*NUM_EES*NUM_VEL*NUM_VEL*sizeof(T),cudaMemcpyDeviceToHost));
        gpuErrchkKernel();
        printf("Single Call END_EFFECTOR_POSE_HESSIAN %fus\n",time_delta_us_timespec(start,end)/static_cast<double>(num_timesteps));
    }

    /**
     * Computes the Hessian (and Jacobian) of the End Effector Pose with respect to generalized velocity (d^2/dv^2 tangent, pinocchio convention)
     *
     * @param hd_data is the packaged input and output pointers
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
     * @param streams are pointers to CUDA streams for async memory transfers (if needed)
     */
    template <typename T, bool USE_COMPRESSED_MEM = false, gridDataKind KIND = GRID_DATA_ALL, bool MUJOCO_OUTPUT = false, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void end_effector_pose_hessian_compute_only(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const int num_timesteps,
                                             const dim3 block_dimms, const dim3 thread_dimms) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_KINEMATICS, "end_effector_pose_hessian requires all-data or kinematics gridData");
        int stride_q = USE_COMPRESSED_MEM ? NUM_JOINTS: 3*NUM_JOINTS;
        // then call the kernel
        if (END_EFFECTOR_POSE_HESSIAN_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>() > GRID_CUDA_TARGET_SHARED_MEM_BYTES) {fprintf(stderr,"GRID end_effector_pose_hessian shared-memory request %zu exceeds compile target %d; regenerate with a deeper Hessian spill fallback or a higher GRID_CUDA_TARGET_SHARED_MEM_BYTES.\n", END_EFFECTOR_POSE_HESSIAN_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>(), GRID_CUDA_TARGET_SHARED_MEM_BYTES); gpuErrchk(cudaErrorInvalidConfiguration);}
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("end_effector_pose_hessian", END_EFFECTOR_POSE_HESSIAN_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()));
        const int _grid_ws_n = (hd_data->workspace_timestep_slots > 0 && hd_data->workspace_timestep_slots < num_timesteps) ? hd_data->workspace_timestep_slots : num_timesteps;
        dim3 _ws_grid = block_dimms;
        if ((int)(_ws_grid.x*_ws_grid.y*_ws_grid.z) > _grid_ws_n) { _ws_grid = dim3(_grid_ws_n,1,1); }
        dim3 _grid_thr_clamped_9 = grid_host_clamp_threads((const void*)&end_effector_pose_hessian_kernel<T, RESOURCE_TIER, MUJOCO_OUTPUT>, thread_dimms);
        if (USE_COMPRESSED_MEM) {end_effector_pose_hessian_kernel<T, RESOURCE_TIER, MUJOCO_OUTPUT><<<_ws_grid,_grid_thr_clamped_9,END_EFFECTOR_POSE_HESSIAN_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_end_effector_pose_hessian,hd_data->d_end_effector_pose_gradient,hd_data->d_workspace,hd_data->d_q,stride_q,d_robotModel,num_timesteps);}
        else                    {end_effector_pose_hessian_kernel<T, RESOURCE_TIER, MUJOCO_OUTPUT><<<_ws_grid,_grid_thr_clamped_9,END_EFFECTOR_POSE_HESSIAN_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_end_effector_pose_hessian,hd_data->d_end_effector_pose_gradient,hd_data->d_workspace,hd_data->d_q_qd_u,stride_q,d_robotModel,num_timesteps);}
        gpuErrchkKernel();
    }

    /**
     * Computes the End Effector Position
     *
     * Notes:
     *   Assumes the Xhom matricies have already been updated for the given q
     *   Defaults to all leave nodes if fixed_target_name is not provided
     *
     * @param s_end_effector_pose is a pointer to shared memory of size 6*NUM_EE where NUM_EE = 1
     * @param s_q is the vector of joint positions
     * @param s_Xhom is the pointer to the homogenous transformation matricies 
     * @param s_temp is a pointer to helper shared memory of size 32
     * @param d_workspace is the global-memory chain workspace used in place of s_temp when !TEMP_IN_SMEM
     * @param s_topology_helpers is the (shared) memory location for the topology_helpers (nullptr/unused for serial chains with identical Ss)
     * @param s_linalg_smem is optional byte-addressed shared memory (reserved; unused by this inner)
     */
    template <typename T, bool TEMP_IN_SMEM = true>
    __device__
    void end_effector_pose_inner_imu_joint(T *s_end_effector_pose, const T *s_q, const T *s_Xhom, int *s_topology_helpers, T *s_temp, T *d_workspace, unsigned char *s_linalg_smem) {
        if constexpr (!TEMP_IN_SMEM) { s_temp = d_workspace; } else { (void)d_workspace; }
        //
        // For each branch in parallel chain up the transform
        // Keep chaining until reaching the root (starting from the leaves)
        //
        // First set to leaf transform
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 16; ind += blockDim.x*blockDim.y){
            int rc = ind % 16;
            // non-branching pointer selector
            int eeInd = (ind < 16) * 14;
            s_temp[ind] = s_Xhom[16*eeInd + rc];
        }
        __syncthreads();
        // Update with parent transform until you reach the base [level 1/3]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 16; ind += blockDim.x*blockDim.y){
            int row = ind % 4; int col = (ind / 4) % 4; int eeOffset = ind - (ind % 16);
            // non-branching pointer selector
            int parent_jid = (ind < 16) * 0;
            s_temp[ind + 16] = dot_prod<T,4,4,1>(&s_Xhom[16*parent_jid + row], &s_temp[0 + eeOffset + 4*col]);
        }
        __syncthreads();
        // Update with parent transform until you reach the base [level 2/3]
        //
        // Now extract the end_effector_pose from the Tansforms
        // TODO: ADD OFFSETS
        //
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 3; ind += blockDim.x*blockDim.y){
            // xyz is easy
            int xyzInd = ind % 3; int eeInd = ind / 3; T *s_Xmat_hom = &s_temp[16 + 16*eeInd];
            s_end_effector_pose[6*eeInd + xyzInd] = s_Xmat_hom[12 + xyzInd];
            // roll pitch yaw is a bit more difficult
            if(xyzInd > 0){continue;}
            s_end_effector_pose[6*eeInd + 3] = atan2(s_Xmat_hom[6],s_Xmat_hom[10]);
            s_end_effector_pose[6*eeInd + 4] = -atan2(s_Xmat_hom[2],sqrt(s_Xmat_hom[6]*s_Xmat_hom[6] + s_Xmat_hom[10]*s_Xmat_hom[10]));
            s_end_effector_pose[6*eeInd + 5] = atan2(s_Xmat_hom[1],s_Xmat_hom[0]);
        }
        __syncthreads();
    }

    /**
     * Computes the End Effector Position
     *
     * @param s_end_effector_pose is a pointer to shared memory of size 6*NUM_EE where NUM_EE = 1
     * @param s_q is the vector of joint positions
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     */
    template <typename T>
    __device__
    void end_effector_pose_device_imu_joint(T *s_end_effector_pose, const T *s_q, const robotModel<T> *d_robotModel) {
        // GRID shared arena layout
        //   T s_XmatsHom[672]
        //   T s_temp[32]
        //   int s_topology_helpers[115]
        //   bytes s_linalg_smem[GRID_EE_LINALG_SHARED_BYTES<T>()]
        extern __shared__ __align__(16) unsigned char s_arena[];
        size_t s_arena_offset = 0;
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_XmatsHom = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(672);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(32);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
        int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(int) * static_cast<size_t>(115);
        unsigned char *s_linalg_smem = nullptr;
        if (static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>()) > 0) {
            s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
            s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
            s_arena_offset += static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>());
        }
        #ifdef GRID_CUDA_DEBUG_LAYOUT
        assert(s_arena_offset == grid_shared_arena_bytes<T>(704, 115, GRID_EE_LINALG_SHARED_BYTES<T>()));
        #endif
        (void)s_arena_offset;
        load_update_XmatsHom_helpers<T>(s_XmatsHom, s_topology_helpers, s_q, d_robotModel, s_temp);
        end_effector_pose_inner_imu_joint<T, true>(s_end_effector_pose, s_q, s_XmatsHom, s_topology_helpers, s_temp, nullptr, s_linalg_smem);
    }

    /**
     * Compute the End Effector Position
     *
     * @param d_end_effector_pose is the vector of end effector positions
     * @param d_q is the vector of joint positions
     * @param stride_q is the stide between each q
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
     */
    template <typename T, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER, bool MUJOCO_OUTPUT = false>
    __global__
    __launch_bounds__(tier_max_threads<RESOURCE_TIER>())
    void end_effector_pose_kernel_imu_joint_single_timing(T *d_end_effector_pose, const T *d_q, const int stride_q, const robotModel<T> *d_robotModel, const int NUM_TIMESTEPS) {
        // GRID shared arena layout
        //   T s_q[19]
        //   T s_end_effector_pose[6]
        //   T s_XmatsHom[672]
        //   T s_temp[32]
        //   int s_topology_helpers[115]
        //   bytes s_linalg_smem[GRID_EE_LINALG_SHARED_BYTES<T>()]
        extern __shared__ __align__(16) unsigned char s_arena[];
        size_t s_arena_offset = 0;
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_q = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(19);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_end_effector_pose = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(6);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_XmatsHom = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(672);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(32);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
        int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(int) * static_cast<size_t>(115);
        unsigned char *s_linalg_smem = nullptr;
        if (static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>()) > 0) {
            s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
            s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
            s_arena_offset += static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>());
        }
        #ifdef GRID_CUDA_DEBUG_LAYOUT
        assert(s_arena_offset == grid_shared_arena_bytes<T>(729, 115, GRID_EE_LINALG_SHARED_BYTES<T>()));
        #endif
        (void)s_arena_offset;
        // load to shared mem
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 19; ind += blockDim.x*blockDim.y){
            s_q[ind] = d_q[ind];
        }
        __syncthreads();
        if constexpr (MUJOCO_OUTPUT) {
            // mjx input convert: base quaternion wxyz->xyzw (q-only; value frame-independent)
            if (threadIdx.x == 0 && threadIdx.y == 0) {
                T qw_in = s_q[3];
                s_q[3] = s_q[4]; s_q[4] = s_q[5]; s_q[5] = s_q[6]; s_q[6] = qw_in;
            }
            __syncthreads();
        }
        // compute with NUM_TIMESTEPS as NUM_REPS for timing
        for (int rep = 0; rep < NUM_TIMESTEPS; rep++){
            // anti-LICM: volatile reload of inputs each rep
            for(int _aopt_i = threadIdx.x + threadIdx.y*blockDim.x; _aopt_i < 19; _aopt_i += blockDim.x*blockDim.y){
                reinterpret_cast<volatile T *>(s_q)[_aopt_i] = reinterpret_cast<const volatile T *>(d_q)[_aopt_i];
            }
            __syncthreads();
            // anti-LICM (1/2): stomp one input slot with `rep`
            if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                reinterpret_cast<volatile T *>(s_q)[rep % (19)] = static_cast<T>(rep);
            }
            // anti-LICM (2/2): feedback prev rep's d_end_effector_pose into s_q (true loop-carried dep)
            if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                T _aopt_fb1 = reinterpret_cast<const volatile T *>(d_end_effector_pose)[(rep + 0x3FF) & 0x3FF];
                T _aopt_fb2 = reinterpret_cast<const volatile T *>(d_end_effector_pose)[(rep + 0x3FE) & 0x3FF];
                T _aopt_fb3 = reinterpret_cast<const volatile T *>(d_end_effector_pose)[(rep + 0x3FD) & 0x3FF];
                reinterpret_cast<volatile T *>(s_q)[(rep + 1) % (19)] += _aopt_fb1;
                reinterpret_cast<volatile T *>(s_q)[(rep + 2) % (19)] += _aopt_fb2;
                reinterpret_cast<volatile T *>(s_q)[(rep + 3) % (19)] += _aopt_fb3;
            }
            __syncthreads();
            load_update_XmatsHom_helpers<T>(s_XmatsHom, s_topology_helpers, s_q, d_robotModel, s_temp);
            end_effector_pose_inner_imu_joint<T, true>(s_end_effector_pose, s_q, s_XmatsHom, s_topology_helpers, s_temp, nullptr, s_linalg_smem);
            __syncthreads();
            if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) { reinterpret_cast<volatile T *>(d_end_effector_pose)[rep & 1023] = reinterpret_cast<const volatile T *>(s_end_effector_pose)[rep & 7]; }
        }
        // save down to global
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 6; ind += blockDim.x*blockDim.y){
            d_end_effector_pose[ind] = s_end_effector_pose[ind];
        }
        __syncthreads();
    }

    /**
     * Compute the End Effector Position
     *
     * @param d_end_effector_pose is the vector of end effector positions
     * @param d_q is the vector of joint positions
     * @param stride_q is the stide between each q
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
     */
    template <typename T, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER, bool MUJOCO_OUTPUT = false>
    __global__
    __launch_bounds__(tier_max_threads<RESOURCE_TIER>())
    void end_effector_pose_kernel_imu_joint(T *d_end_effector_pose, const T *d_q, const int stride_q, const robotModel<T> *d_robotModel, const int NUM_TIMESTEPS) {
        // GRID shared arena layout
        //   T s_q[19]
        //   T s_end_effector_pose[6]
        //   T s_XmatsHom[672]
        //   T s_temp[32]
        //   int s_topology_helpers[115]
        //   bytes s_linalg_smem[GRID_EE_LINALG_SHARED_BYTES<T>()]
        extern __shared__ __align__(16) unsigned char s_arena[];
        size_t s_arena_offset = 0;
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_q = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(19);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_end_effector_pose = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(6);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_XmatsHom = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(672);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(32);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
        int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(int) * static_cast<size_t>(115);
        unsigned char *s_linalg_smem = nullptr;
        if (static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>()) > 0) {
            s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
            s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
            s_arena_offset += static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>());
        }
        #ifdef GRID_CUDA_DEBUG_LAYOUT
        assert(s_arena_offset == grid_shared_arena_bytes<T>(729, 115, GRID_EE_LINALG_SHARED_BYTES<T>()));
        #endif
        (void)s_arena_offset;
        for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
            // load to shared mem
            const T *d_q_k = &d_q[k*stride_q];
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 19; ind += blockDim.x*blockDim.y){
                s_q[ind] = d_q_k[ind];
            }
            __syncthreads();
            if constexpr (MUJOCO_OUTPUT) {
                // mjx input convert: base quaternion wxyz->xyzw (q-only; value frame-independent)
                if (threadIdx.x == 0 && threadIdx.y == 0) {
                    T qw_in = s_q[3];
                    s_q[3] = s_q[4]; s_q[4] = s_q[5]; s_q[5] = s_q[6]; s_q[6] = qw_in;
                }
                __syncthreads();
            }
            // compute
            load_update_XmatsHom_helpers<T>(s_XmatsHom, s_topology_helpers, s_q, d_robotModel, s_temp);
            end_effector_pose_inner_imu_joint<T, true>(s_end_effector_pose, s_q, s_XmatsHom, s_topology_helpers, s_temp, nullptr, s_linalg_smem);
            __syncthreads();
            // save down to global
            T *d_end_effector_pose_k = &d_end_effector_pose[k*6];
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 6; ind += blockDim.x*blockDim.y){
                d_end_effector_pose_k[ind] = s_end_effector_pose[ind];
            }
            __syncthreads();
        }
    }

    /**
     * Compute the End Effector Pose
     *
     * @param hd_data is the packaged input and output pointers
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
     * @param streams are pointers to CUDA streams for async memory transfers (if needed)
     */
    template <typename T, bool USE_COMPRESSED_MEM = false, gridDataKind KIND = GRID_DATA_ALL, bool MUJOCO_OUTPUT = false, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void end_effector_pose_imu_joint(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const int num_timesteps,
                                const dim3 block_dimms, const dim3 thread_dimms, cudaStream_t *streams) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_KINEMATICS, "end_effector_pose requires all-data or kinematics gridData");
        // start code with memory transfer
        int stride_q;
        if (USE_COMPRESSED_MEM) {stride_q = NUM_JOINTS; gpuErrchk(cudaMemcpyAsync(hd_data->d_q,hd_data->h_q,stride_q*num_timesteps*sizeof(T),cudaMemcpyHostToDevice,streams[0]));}
        else {stride_q = 3*NUM_JOINTS; gpuErrchk(cudaMemcpyAsync(hd_data->d_q_qd_u,hd_data->h_q_qd_u,stride_q*num_timesteps*sizeof(T),cudaMemcpyHostToDevice,streams[0]));}
        gpuErrchkKernel();
        // then call the kernel
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("end_effector_pose", END_EFFECTOR_POSE_DYNAMIC_SHARED_MEM_BYTES<T>()));
        dim3 _grid_thr_clamped_10 = grid_host_clamp_threads((const void*)&end_effector_pose_kernel_imu_joint<T, RESOURCE_TIER, MUJOCO_OUTPUT>, thread_dimms);
        if (USE_COMPRESSED_MEM) {end_effector_pose_kernel_imu_joint<T, RESOURCE_TIER, MUJOCO_OUTPUT><<<block_dimms,_grid_thr_clamped_10,END_EFFECTOR_POSE_DYNAMIC_SHARED_MEM_BYTES<T>()>>>(hd_data->d_end_effector_pose,hd_data->d_q,stride_q,d_robotModel,num_timesteps);}
        else                    {end_effector_pose_kernel_imu_joint<T, RESOURCE_TIER, MUJOCO_OUTPUT><<<block_dimms,_grid_thr_clamped_10,END_EFFECTOR_POSE_DYNAMIC_SHARED_MEM_BYTES<T>()>>>(hd_data->d_end_effector_pose,hd_data->d_q_qd_u,stride_q,d_robotModel,num_timesteps);}
        gpuErrchkKernel();
        // finally transfer the result back
        gpuErrchk(cudaMemcpy(hd_data->h_end_effector_pose,hd_data->d_end_effector_pose,6*NUM_EES*num_timesteps*sizeof(T),cudaMemcpyDeviceToHost));
        gpuErrchkKernel();
    }

    /**
     * Compute the End Effector Pose
     *
     * @param hd_data is the packaged input and output pointers
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
     * @param streams are pointers to CUDA streams for async memory transfers (if needed)
     */
    template <typename T, bool USE_COMPRESSED_MEM = false, gridDataKind KIND = GRID_DATA_ALL, bool MUJOCO_OUTPUT = false, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void end_effector_pose_imu_joint_single_timing(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const int num_timesteps,
                                              const dim3 block_dimms, const dim3 thread_dimms, cudaStream_t *streams) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_KINEMATICS, "end_effector_pose requires all-data or kinematics gridData");
        // start code with memory transfer
        int stride_q;
        if (USE_COMPRESSED_MEM) {stride_q = NUM_JOINTS; gpuErrchk(cudaMemcpyAsync(hd_data->d_q,hd_data->h_q,stride_q*sizeof(T),cudaMemcpyHostToDevice,streams[0]));}
        else {stride_q = 3*NUM_JOINTS; gpuErrchk(cudaMemcpyAsync(hd_data->d_q_qd_u,hd_data->h_q_qd_u,stride_q*sizeof(T),cudaMemcpyHostToDevice,streams[0]));}
        gpuErrchkKernel();
        // then call the kernel
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("end_effector_pose", END_EFFECTOR_POSE_DYNAMIC_SHARED_MEM_BYTES<T>()));
        struct timespec start, end; clock_gettime(CLOCK_MONOTONIC,&start);
        dim3 _grid_thr_clamped_11 = grid_host_clamp_threads((const void*)&end_effector_pose_kernel_imu_joint_single_timing<T, RESOURCE_TIER, MUJOCO_OUTPUT>, thread_dimms);
        if (USE_COMPRESSED_MEM) {end_effector_pose_kernel_imu_joint_single_timing<T, RESOURCE_TIER, MUJOCO_OUTPUT><<<block_dimms,_grid_thr_clamped_11,END_EFFECTOR_POSE_DYNAMIC_SHARED_MEM_BYTES<T>()>>>(hd_data->d_end_effector_pose,hd_data->d_q,stride_q,d_robotModel,num_timesteps);}
        else                    {end_effector_pose_kernel_imu_joint_single_timing<T, RESOURCE_TIER, MUJOCO_OUTPUT><<<block_dimms,_grid_thr_clamped_11,END_EFFECTOR_POSE_DYNAMIC_SHARED_MEM_BYTES<T>()>>>(hd_data->d_end_effector_pose,hd_data->d_q_qd_u,stride_q,d_robotModel,num_timesteps);}
        gpuErrchkKernel();
        clock_gettime(CLOCK_MONOTONIC,&end);
        // finally transfer the result back
        gpuErrchk(cudaMemcpy(hd_data->h_end_effector_pose,hd_data->d_end_effector_pose,6*NUM_EES*sizeof(T),cudaMemcpyDeviceToHost));
        gpuErrchkKernel();
        printf("Single Call END_EFFECTOR_POSE %fus\n",time_delta_us_timespec(start,end)/static_cast<double>(num_timesteps));
    }

    /**
     * Compute the End Effector Pose
     *
     * @param hd_data is the packaged input and output pointers
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
     * @param streams are pointers to CUDA streams for async memory transfers (if needed)
     */
    template <typename T, bool USE_COMPRESSED_MEM = false, gridDataKind KIND = GRID_DATA_ALL, bool MUJOCO_OUTPUT = false, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void end_effector_pose_imu_joint_compute_only(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const int num_timesteps,
                                             const dim3 block_dimms, const dim3 thread_dimms) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_KINEMATICS, "end_effector_pose requires all-data or kinematics gridData");
        int stride_q = USE_COMPRESSED_MEM ? NUM_JOINTS: 3*NUM_JOINTS;
        // then call the kernel
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("end_effector_pose", END_EFFECTOR_POSE_DYNAMIC_SHARED_MEM_BYTES<T>()));
        dim3 _grid_thr_clamped_12 = grid_host_clamp_threads((const void*)&end_effector_pose_kernel_imu_joint<T, RESOURCE_TIER, MUJOCO_OUTPUT>, thread_dimms);
        if (USE_COMPRESSED_MEM) {end_effector_pose_kernel_imu_joint<T, RESOURCE_TIER, MUJOCO_OUTPUT><<<block_dimms,_grid_thr_clamped_12,END_EFFECTOR_POSE_DYNAMIC_SHARED_MEM_BYTES<T>()>>>(hd_data->d_end_effector_pose,hd_data->d_q,stride_q,d_robotModel,num_timesteps);}
        else                    {end_effector_pose_kernel_imu_joint<T, RESOURCE_TIER, MUJOCO_OUTPUT><<<block_dimms,_grid_thr_clamped_12,END_EFFECTOR_POSE_DYNAMIC_SHARED_MEM_BYTES<T>()>>>(hd_data->d_end_effector_pose,hd_data->d_q_qd_u,stride_q,d_robotModel,num_timesteps);}
        gpuErrchkKernel();
    }

    /**
     * Computes the Gradient of the End Effector Pose with respect to generalized velocity (d/dv tangent, pinocchio convention)
     *
     * Notes:
     *   Assumes s_Xhom has been populated with the per-joint LOCAL transforms for the given q.
     *   Output d/dv (TANGENT) is 6 x nv per ee (was 6 x nq for d/dq) -- matches pinocchio.
     *
     * @param s_end_effector_pose_gradient is a pointer to shared memory of size 6*NUM_VEL*NUM_EE where NUM_VEL = 18 and NUM_EE = 1
     * @param s_q is the vector of joint positions (unused; kept for signature compatibility)
     * @param s_Xhom is the pointer to the LOCAL homogeneous transformation matrices (per-joint Xhom_local)
     * @param s_dXhom is the pointer to the LOCAL d-transforms (unused by the geometric-Jacobian path; kept for signature compatibility)
     * @param s_temp is a pointer to helper shared memory of size 1120
     * @param d_workspace is the global-memory chain workspace used in place of s_temp when !TEMP_IN_SMEM
     * @param s_topology_helpers is the (shared) memory location for the topology_helpers (nullptr/unused for serial chains with identical Ss)
     * @param s_linalg_smem is optional byte-addressed shared memory (reserved; unused)
     */
    template <typename T, bool TEMP_IN_SMEM = true>
    __device__
    void end_effector_pose_gradient_inner_imu_joint(T *s_end_effector_pose_gradient, const T *s_q, const T *s_Xhom, const T *s_dXhom, int *s_topology_helpers, T *s_temp, T *d_workspace, unsigned char *s_linalg_smem) {
        if constexpr (!TEMP_IN_SMEM) { s_temp = d_workspace; } else { (void)d_workspace; }
        (void)s_q; (void)s_dXhom; (void)s_linalg_smem;
        // scratch layout: Xworld | Jv (3 x nv x ee) | Jw (3 x nv x ee) | E_sincos (4 x ee)
        T *s_Xworld = &s_temp[0];
        T *s_Jv     = &s_temp[672];
        T *s_Jw     = &s_temp[726];
        T *s_E_sc   = &s_temp[780];   // cy,sy,cp,sp per ee
        //
        // Step 1: build world transforms for every joint via BFS-level chain-up
        //
        // BFS level 0 -> joints [0]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 16; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            // branch to get pointer locations
            int jid; int par;
                 if (slot < 1){ jid = 0; par = -1; }
            if (par == -1) {
                s_Xworld[16*jid + ele] = s_Xhom[16*jid + ele];
            }
            else {
                s_Xworld[16*jid + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*jid + 4*col]);
            }
        }
        __syncthreads();
        // BFS level 1 -> joints [1, 4, 7, 10]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 64; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            // branch to get pointer locations
            int jid; int par;
                 if (slot < 1){ jid = 1; par = 0; }
            else if (slot < 2){ jid = 4; par = 0; }
            else if (slot < 3){ jid = 7; par = 0; }
            else              { jid = 10; par = 0; }
            if (par == -1) {
                s_Xworld[16*jid + ele] = s_Xhom[16*jid + ele];
            }
            else {
                s_Xworld[16*jid + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*jid + 4*col]);
            }
        }
        __syncthreads();
        // BFS level 2 -> joints [2, 5, 8, 11]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 64; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            // branch to get pointer locations
            int jid; int par;
                 if (slot < 1){ jid = 2; par = 1; }
            else if (slot < 2){ jid = 5; par = 4; }
            else if (slot < 3){ jid = 8; par = 7; }
            else              { jid = 11; par = 10; }
            if (par == -1) {
                s_Xworld[16*jid + ele] = s_Xhom[16*jid + ele];
            }
            else {
                s_Xworld[16*jid + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*jid + 4*col]);
            }
        }
        __syncthreads();
        // BFS level 3 -> joints [3, 6, 9, 12]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 64; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            // branch to get pointer locations
            int jid; int par;
                 if (slot < 1){ jid = 3; par = 2; }
            else if (slot < 2){ jid = 6; par = 5; }
            else if (slot < 3){ jid = 9; par = 8; }
            else              { jid = 12; par = 11; }
            if (par == -1) {
                s_Xworld[16*jid + ele] = s_Xhom[16*jid + ele];
            }
            else {
                s_Xworld[16*jid + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*jid + 4*col]);
            }
        }
        __syncthreads();
        //
        // Step 1b: world transform of the fixed kinematic target(s): Xworld[anchor] = Xworld[parent] @ Xhom_local[anchor]
        //
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 16; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            // branch to get pointer locations
            int anc; int par;
                 if (slot < 1){ anc = 14; par = 0; }
            s_Xworld[16*anc + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*anc + 4*col]);
        }
        __syncthreads();
        //
        // Step 2: zero the J_v and J_w scratch (out-of-chain columns stay zero)
        //
        glass::set_const<T, 108>(static_cast<T>(0), s_Jv);
        //
        // Step 3: per-chain-joint columns of J_v, J_w (one block-parallel work-item per (ee, S-column))
        //
        static const int eeg_job_j[] = { 0, 0, 0, 0, 0, 0 };
        static const int eeg_job_anc[] = { 14, 14, 14, 14, 14, 14 };
        static const int eeg_job_rev[] = { 0, 0, 0, 1, 1, 1 };
        static const int eeg_job_base[] = { 0, 3, 6, 9, 12, 15 };
        static const T eeg_job_ax[] = { static_cast<T>(1), static_cast<T>(0), static_cast<T>(0), static_cast<T>(0), static_cast<T>(1), static_cast<T>(0), static_cast<T>(0), static_cast<T>(0), static_cast<T>(1), static_cast<T>(1), static_cast<T>(0), static_cast<T>(0), static_cast<T>(0), static_cast<T>(1), static_cast<T>(0), static_cast<T>(0), static_cast<T>(0), static_cast<T>(1) };
        for(int job_idx = threadIdx.x + threadIdx.y*blockDim.x; job_idx < 6; job_idx += blockDim.x*blockDim.y){
            int j   = eeg_job_j[job_idx];
            int ee_anchor = eeg_job_anc[job_idx];
            int col_base = eeg_job_base[job_idx];
            T ax0 = eeg_job_ax[3*job_idx + 0]; T ax1 = eeg_job_ax[3*job_idx + 1]; T ax2 = eeg_job_ax[3*job_idx + 2];
            T axw_0 = s_Xworld[16*j + 0]*ax0 + s_Xworld[16*j + 4]*ax1 + s_Xworld[16*j + 8]*ax2;
            T axw_1 = s_Xworld[16*j + 1]*ax0 + s_Xworld[16*j + 5]*ax1 + s_Xworld[16*j + 9]*ax2;
            T axw_2 = s_Xworld[16*j + 2]*ax0 + s_Xworld[16*j + 6]*ax1 + s_Xworld[16*j + 10]*ax2;
            if (eeg_job_rev[job_idx]) {
                s_Jw[col_base + 0] = axw_0; s_Jw[col_base + 1] = axw_1; s_Jw[col_base + 2] = axw_2;
                T dx = s_Xworld[16*ee_anchor + 12] - s_Xworld[16*j + 12];
                T dy = s_Xworld[16*ee_anchor + 13] - s_Xworld[16*j + 13];
                T dz = s_Xworld[16*ee_anchor + 14] - s_Xworld[16*j + 14];
                s_Jv[col_base + 0] = axw_1*dz - axw_2*dy;
                s_Jv[col_base + 1] = axw_2*dx - axw_0*dz;
                s_Jv[col_base + 2] = axw_0*dy - axw_1*dx;
            }
            else {
                s_Jv[col_base + 0] = axw_0; s_Jv[col_base + 1] = axw_1; s_Jv[col_base + 2] = axw_2;
            }
        }
        __syncthreads();
        //
        // Step 4: extract (cy, sy, cp, sp) from each ee's world rotation for E(rpy)^{-1}
        //
        for(int ee = threadIdx.x + threadIdx.y*blockDim.x; ee < 1; ee += blockDim.x*blockDim.y){
            const int ee_jid = 14;
            T R20 = s_Xworld[16*ee_jid + 2];
            T R21 = s_Xworld[16*ee_jid + 6];
            T R22 = s_Xworld[16*ee_jid + 10];
            T R10 = s_Xworld[16*ee_jid + 1];
            T R00 = s_Xworld[16*ee_jid + 0];
            T cp_term = sqrt(R22*R22 + R21*R21);
            T yaw = atan2(R10, R00);
            T pitch = atan2(-R20, cp_term);
            s_E_sc[4*ee + 0] = cos(yaw);
            s_E_sc[4*ee + 1] = sin(yaw);
            s_E_sc[4*ee + 2] = cos(pitch);
            s_E_sc[4*ee + 3] = sin(pitch);
        }
        __syncthreads();
        //
        // Step 5: write s_end_effector_pose_gradient (rows 0..2 = J_v, rows 3..5 = E(rpy)^{-1} J_w)
        //
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 108; ind += blockDim.x*blockDim.y){
            int row = ind % 6; int rem = ind / 6; int vi = rem % 18; int ee = rem / 18;
            int jv_base = 3 * (18 * ee + vi);
            if (row < 3) {
                s_end_effector_pose_gradient[ind] = s_Jv[jv_base + row];
            }
            else {
                T cy = s_E_sc[4*ee + 0]; T sy = s_E_sc[4*ee + 1]; T cp = s_E_sc[4*ee + 2]; T sp = s_E_sc[4*ee + 3];
                T Jw0 = s_Jw[jv_base + 0]; T Jw1 = s_Jw[jv_base + 1]; T Jw2 = s_Jw[jv_base + 2];
                T outv;
                if (row == 3) { outv = (cy*Jw0 + sy*Jw1) / cp; }
                else if (row == 4) { outv = -sy*Jw0 + cy*Jw1; }
                else { outv = (sp / cp) * (cy*Jw0 + sy*Jw1) + Jw2; }
                s_end_effector_pose_gradient[ind] = outv;
            }
        }
        __syncthreads();
    }

    /**
     * Computes the Gradient of the End Effector Pose with respect to joint position
     *
     * @param s_end_effector_pose_gradient is a pointer to shared memory of size 6*NUM_VEL*NUM_EE where NUM_VEL = 18 and NUM_EE = 1
     * @param s_q is the vector of joint positions
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     */
    template <typename T>
    __device__
    void end_effector_pose_gradient_device_imu_joint(T *s_end_effector_pose_gradient, const T *s_q, const robotModel<T> *d_robotModel) {
        // GRID shared arena layout
        //   T s_XmatsHom[672]
        //   T s_temp[784]
        //   int s_topology_helpers[115]
        //   bytes s_linalg_smem[GRID_EE_LINALG_SHARED_BYTES<T>()]
        extern __shared__ __align__(16) unsigned char s_arena[];
        size_t s_arena_offset = 0;
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_XmatsHom = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(672);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(784);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
        int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(int) * static_cast<size_t>(115);
        unsigned char *s_linalg_smem = nullptr;
        if (static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>()) > 0) {
            s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
            s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
            s_arena_offset += static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>());
        }
        #ifdef GRID_CUDA_DEBUG_LAYOUT
        assert(s_arena_offset == grid_shared_arena_bytes<T>(1456, 115, GRID_EE_LINALG_SHARED_BYTES<T>()));
        #endif
        (void)s_arena_offset;
        load_update_XmatsHom_helpers<T>(s_XmatsHom, s_topology_helpers, s_q, d_robotModel, s_temp);
        end_effector_pose_gradient_inner_imu_joint<T, true>(s_end_effector_pose_gradient, s_q, s_XmatsHom, nullptr, s_topology_helpers, s_temp, nullptr, s_linalg_smem);
    }

    /**
     * Computes the Gradient of the End Effector Pose with respect to joint position
     *
     * @param d_end_effector_pose_gradient is the vector of end effector positions gradients
     * @param d_workspace is the generated global spill workspace
     * @param d_q is the vector of joint positions
     * @param stride_q is the stide between each q
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
     */
    template <typename T, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER, bool MUJOCO_OUTPUT = false>
    __global__
    __launch_bounds__(tier_max_threads<RESOURCE_TIER>())
    void end_effector_pose_gradient_kernel_imu_joint_single_timing(T *d_end_effector_pose_gradient, unsigned char *d_workspace, const T *d_q, const int stride_q, const robotModel<T> *d_robotModel, const int NUM_TIMESTEPS) {
        if constexpr (RESOURCE_TIER == TIER_SHARED) {
            // GRID shared arena layout
            //   T s_q[19]
            //   T s_end_effector_pose_gradient[108]
            //   T s_XmatsHom[672]
            //   T s_temp[784]
            //   int s_topology_helpers[115]
            //   bytes s_linalg_smem[GRID_EE_LINALG_SHARED_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(19);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_end_effector_pose_gradient = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(108);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XmatsHom = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(672);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(784);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
            int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
