    /**
     * Computes the Hessian (and Jacobian) of the End Effector Pose with respect to generalized velocity (d^2/dv^2 tangent, pinocchio convention)
     *
     * Notes:
     *   Inline-CUDA users: at TIER_LITE/TIER_MINIMAL the large s_end_effector_pose_hessian output (~1944*sizeof(T) bytes) moves from shared memory to d_workspace, freeing smem for the caller's outer kernel
     *
     * @param s_end_effector_pose_hessian is a pointer to shared memory of size 6*NUM_VEL*NUM_VEL*NUM_EE where NUM_VEL = 18 and NUM_EE = 1 (d^2/dv^2 tangent, pinocchio convention)
     * @param s_end_effector_pose_gradient is a pointer to shared memory of size 6*NUM_VEL*NUM_EE (d/dv tangent Jacobian)
     * @param s_q is the vector of joint positions
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param d_workspace is the global scratch buffer; size END_EFFECTOR_POSE_HESSIAN_DEVICE_INLINE_WORKSPACE_BYTES<T, RESOURCE_TIER>() bytes (= 0 at TIER_SHARED, 1944*sizeof(T) at TIER_LITE+). Pass nullptr at TIER_SHARED
     */
    template <typename T, int RESOURCE_TIER = TIER_SHARED>
    __device__
    void end_effector_pose_hessian_device_imu_joint(T *s_end_effector_pose_hessian, T *s_end_effector_pose_gradient, const T *s_q, const robotModel<T> *d_robotModel, T *d_workspace = nullptr) {
        // GRID shared arena layout
        //   T s_XmatsHom[672]
        //   T s_temp[964]
        //   int s_topology_helpers[115]
        //   bytes s_linalg_smem[GRID_EE_LINALG_SHARED_BYTES<T>()]
        extern __shared__ __align__(16) unsigned char s_arena[];
        size_t s_arena_offset = 0;
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_XmatsHom = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(672);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(964);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
        int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(int) * static_cast<size_t>(115);
        unsigned char *s_linalg_smem = nullptr;
        if (static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>()) > 0) {
            s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
            s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
            s_arena_offset += static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>());
        }
        #ifdef GRID_CUDA_DEBUG_LAYOUT
        assert(s_arena_offset == grid_shared_arena_bytes<T>(1636, 115, GRID_EE_LINALG_SHARED_BYTES<T>()));
        #endif
        (void)s_arena_offset;
        load_update_XmatsHom_helpers<T>(s_XmatsHom, s_topology_helpers, s_q, d_robotModel, s_temp);
        end_effector_pose_hessian_inner_imu_joint<T, D2EE_OUT_IN_SMEM<RESOURCE_TIER>()>(s_end_effector_pose_hessian, s_end_effector_pose_gradient, s_q, s_XmatsHom, s_topology_helpers, s_temp, d_workspace, d_robotModel, s_linalg_smem);
    }

    /**
     * Computes the Hessian (and Jacobian) of the End Effector Pose with respect to generalized velocity (d^2/dv^2 tangent, pinocchio convention)
     *
     * Notes:
     *   Output d^2(pose)/dv^2 is in tangent-space convention (d/dv), shape 6 x nv x nv per ee, C-order. Matches pinocchio.
     *
     * @param d_end_effector_pose_hessian is the vector of end effector pose Hessians (6 x nv x nv per ee)
     * @param d_end_effector_pose_gradient is the vector of end effector pose Jacobians (6 x nv per ee)
     * @param d_workspace is the generated global spill workspace
     * @param d_q is the vector of joint positions
     * @param stride_q is the stide between each q
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
     */
    template <typename T, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER, bool MUJOCO_OUTPUT = false>
    __global__
    __launch_bounds__(tier_max_threads<RESOURCE_TIER>())
    void end_effector_pose_hessian_kernel_imu_joint_single_timing(T *d_end_effector_pose_hessian, T *d_end_effector_pose_gradient, unsigned char *d_workspace, const T *d_q, const int stride_q, const robotModel<T> *d_robotModel, const int NUM_TIMESTEPS) {
        if constexpr (RESOURCE_TIER == TIER_SHARED) {
            // GRID shared arena layout
