                // Use d_end_effector_pose_hessian directly as the spill target so the inner writes into the persistent output buffer (one allocation, no extra copy).
                T *s_end_effector_pose_hessian_ws = &d_end_effector_pose_hessian[k*1944];
                // compute
                load_update_XmatsHom_helpers<T>(s_XmatsHom, s_topology_helpers, s_q, d_robotModel, s_temp);
                end_effector_pose_hessian_inner_imu_joint<T, false>(s_end_effector_pose_hessian, s_end_effector_pose_gradient, s_q, s_XmatsHom, s_topology_helpers, s_temp, s_end_effector_pose_hessian_ws, d_robotModel, s_linalg_smem);
                __syncthreads();
                if constexpr (MUJOCO_OUTPUT) {
                    // mjx output: EE-pose Hessian convention transform (double col-reframe + sym frame term)
                    // (A) double column-reframe Rb H Rb^T on the base-linear 3-block, per (ee,out-row) slab
                    for(int s = threadIdx.x + threadIdx.y*blockDim.x; s < 6; s += blockDim.x*blockDim.y){
                        T qx = s_q[3], qy = s_q[4], qz = s_q[5], qw = s_q[6];
                        T xx = qx*qx, yy = qy*qy, zz = qz*qz;
                        T xy = qx*qy, xz = qx*qz, yz = qy*qz, wx = qw*qx, wy = qw*qy, wz = qw*qz;
                        T R[9];
                        R[0] = static_cast<T>(1) - static_cast<T>(2)*(yy+zz); R[1] = static_cast<T>(2)*(xy-wz);                    R[2] = static_cast<T>(2)*(xz+wy);
                        R[3] = static_cast<T>(2)*(xy+wz);                    R[4] = static_cast<T>(1) - static_cast<T>(2)*(xx+zz); R[5] = static_cast<T>(2)*(yz-wx);
                        R[6] = static_cast<T>(2)*(xz-wy);                    R[7] = static_cast<T>(2)*(yz+wx);                    R[8] = static_cast<T>(1) - static_cast<T>(2)*(xx+yy);
                        int ee = s / 6; int c = s - 6*ee;
                        T *Hc = s_end_effector_pose_hessian_ws + ee * 1944 + c * 324;
                        for (int k = 0; k < 18; k++) { T m0 = Hc[0*18 + k], m1 = Hc[1*18 + k], m2 = Hc[2*18 + k];
                          Hc[0*18 + k] = R[0]*m0 + R[1]*m1 + R[2]*m2; Hc[1*18 + k] = R[3]*m0 + R[4]*m1 + R[5]*m2; Hc[2*18 + k] = R[6]*m0 + R[7]*m1 + R[8]*m2; }
                        for (int a = 0; a < 18; a++) { T m0 = Hc[a*18 + 0], m1 = Hc[a*18 + 1], m2 = Hc[a*18 + 2];
                          Hc[a*18 + 0] = m0*R[0] + m1*R[1] + m2*R[2]; Hc[a*18 + 1] = m0*R[3] + m1*R[4] + m2*R[5]; Hc[a*18 + 2] = m0*R[6] + m1*R[7] + m2*R[8]; }
                    }
                    __syncthreads();
                    // (B) frame term term[i,l,3+a] = dpose[i,0:3] . (-[e_a]x R^T), then 0.5*(term+term^T) into H, per (ee,out-row)
                    for(int s = threadIdx.x + threadIdx.y*blockDim.x; s < 6; s += blockDim.x*blockDim.y){
                        T qx = s_q[3], qy = s_q[4], qz = s_q[5], qw = s_q[6];
                        T xx = qx*qx, yy = qy*qy, zz = qz*qz;
                        T xy = qx*qy, xz = qx*qz, yz = qy*qz, wx = qw*qx, wy = qw*qy, wz = qw*qz;
                        T R[9];
                        R[0] = static_cast<T>(1) - static_cast<T>(2)*(yy+zz); R[1] = static_cast<T>(2)*(xy-wz);                    R[2] = static_cast<T>(2)*(xz+wy);
                        R[3] = static_cast<T>(2)*(xy+wz);                    R[4] = static_cast<T>(1) - static_cast<T>(2)*(xx+zz); R[5] = static_cast<T>(2)*(yz-wx);
                        R[6] = static_cast<T>(2)*(xz-wy);                    R[7] = static_cast<T>(2)*(yz+wx);                    R[8] = static_cast<T>(1) - static_cast<T>(2)*(xx+yy);
                        int ee = s / 6; int i = s - 6*ee;
                        T *gb = s_end_effector_pose_gradient + ee * 108;
                        T di0 = gb[6*0 + i], di1 = gb[6*1 + i], di2 = gb[6*2 + i];
                        T t0_0 = di1*( R[2]) + di2*(-R[1]); T t0_1 = di1*( R[5]) + di2*(-R[4]); T t0_2 = di1*( R[8]) + di2*(-R[7]);  // k=3
                        T t1_0 = di0*(-R[2]) + di2*( R[0]); T t1_1 = di0*(-R[5]) + di2*( R[3]); T t1_2 = di0*(-R[8]) + di2*( R[6]);  // k=4
                        T t2_0 = di0*( R[1]) + di1*(-R[0]); T t2_1 = di0*( R[4]) + di1*(-R[3]); T t2_2 = di0*( R[7]) + di1*(-R[6]);  // k=5
                        T *Hi = s_end_effector_pose_hessian_ws + ee * 1944 + i * 324;
                        Hi[3] += static_cast<T>(0.5)*t0_0; Hi[54] += static_cast<T>(0.5)*t0_0;
                        Hi[21] += static_cast<T>(0.5)*t0_1; Hi[55] += static_cast<T>(0.5)*t0_1;
                        Hi[39] += static_cast<T>(0.5)*t0_2; Hi[56] += static_cast<T>(0.5)*t0_2;
                        Hi[4] += static_cast<T>(0.5)*t1_0; Hi[72] += static_cast<T>(0.5)*t1_0;
                        Hi[22] += static_cast<T>(0.5)*t1_1; Hi[73] += static_cast<T>(0.5)*t1_1;
                        Hi[40] += static_cast<T>(0.5)*t1_2; Hi[74] += static_cast<T>(0.5)*t1_2;
                        Hi[5] += static_cast<T>(0.5)*t2_0; Hi[90] += static_cast<T>(0.5)*t2_0;
                        Hi[23] += static_cast<T>(0.5)*t2_1; Hi[91] += static_cast<T>(0.5)*t2_1;
                        Hi[41] += static_cast<T>(0.5)*t2_2; Hi[92] += static_cast<T>(0.5)*t2_2;
                    }
                    __syncthreads();
                    // mjx output: column reframe s_end_effector_pose_gradient G^{-1} (base-linear cols . R^T)
                    if (threadIdx.x == 0 && threadIdx.y == 0) {
                        T qx = s_q[3], qy = s_q[4], qz = s_q[5], qw = s_q[6];
                        T xx = qx*qx, yy = qy*qy, zz = qz*qz;
                        T xy = qx*qy, xz = qx*qz, yz = qy*qz, wx = qw*qx, wy = qw*qy, wz = qw*qz;
                        T R[9];
                        R[0] = static_cast<T>(1) - static_cast<T>(2)*(yy+zz); R[1] = static_cast<T>(2)*(xy-wz);                    R[2] = static_cast<T>(2)*(xz+wy);
                        R[3] = static_cast<T>(2)*(xy+wz);                    R[4] = static_cast<T>(1) - static_cast<T>(2)*(xx+zz); R[5] = static_cast<T>(2)*(yz-wx);
                        R[6] = static_cast<T>(2)*(xz-wy);                    R[7] = static_cast<T>(2)*(yz+wx);                    R[8] = static_cast<T>(1) - static_cast<T>(2)*(xx+yy);
                        for (int r = 0; r < 6; r++) { T j0 = s_end_effector_pose_gradient[r + 6*0], j1 = s_end_effector_pose_gradient[r + 6*1], j2 = s_end_effector_pose_gradient[r + 6*2]; s_end_effector_pose_gradient[r + 6*0] = j0*R[0] + j1*R[1] + j2*R[2]; s_end_effector_pose_gradient[r + 6*1] = j0*R[3] + j1*R[4] + j2*R[5]; s_end_effector_pose_gradient[r + 6*2] = j0*R[6] + j1*R[7] + j2*R[8]; }
                    }
                    __syncthreads();
                }
                // save down to global
                T *d_end_effector_pose_gradient_k = &d_end_effector_pose_gradient[k*108];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 108; ind += blockDim.x*blockDim.y){
                    d_end_effector_pose_gradient_k[ind] = s_end_effector_pose_gradient[ind];
                }
                __syncthreads();
            }
        }
    }

