    /**
     * Thread-per-sample forward kinematics: serial chain walk that fills the full cumulative (world-frame) joint transforms s_jointXforms from s_q. Robot-general (any DoF / joint types). Reads s_jointXforms[16*target_idx] for the world pose of frame target_idx.
     *
     * Notes:
     *   Assumes the constant (q-independent) cells of s_XmatsHom are pre-loaded; only the q-dependent cells are refreshed here.
     *
     * @param s_jointXforms is the pointer to the cumulative (world) joint transforms (16 per joint)
     * @param s_XmatsHom is the pointer to the per-joint homogeneous transforms (16 per joint)
     * @param s_q is the vector of joint positions
     * @param target_idx is the joint index whose world transform is desired (full array is filled)
     */
    template <typename T>
    __device__
    void ee_pose_inner_thread(T *s_jointXforms, T *s_XmatsHom, T *s_q, int target_idx) {
        (void)target_idx;
        // X_hom[0] floating root from s_q[0..6] (pos + xyzw quat)
        {
            s_XmatsHom[16*0 + 0] = static_cast<T>(-2.0*pow(s_q[4], 2)/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)) - 2.0*pow(s_q[5], 2)/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)) + 1.0);
            s_XmatsHom[16*0 + 1] = static_cast<T>(2.0*s_q[3]*s_q[4]/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)) + 2.0*s_q[5]*s_q[6]/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)));
            s_XmatsHom[16*0 + 2] = static_cast<T>(2.0*s_q[3]*s_q[5]/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)) - 2.0*s_q[4]*s_q[6]/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)));
            s_XmatsHom[16*0 + 4] = static_cast<T>(2.0*s_q[3]*s_q[4]/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)) - 2.0*s_q[5]*s_q[6]/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)));
            s_XmatsHom[16*0 + 5] = static_cast<T>(-2.0*pow(s_q[3], 2)/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)) - 2.0*pow(s_q[5], 2)/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)) + 1.0);
            s_XmatsHom[16*0 + 6] = static_cast<T>(2.0*s_q[3]*s_q[6]/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)) + 2.0*s_q[4]*s_q[5]/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)));
            s_XmatsHom[16*0 + 8] = static_cast<T>(2.0*s_q[3]*s_q[5]/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)) + 2.0*s_q[4]*s_q[6]/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)));
            s_XmatsHom[16*0 + 9] = static_cast<T>(-2.0*s_q[3]*s_q[6]/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)) + 2.0*s_q[4]*s_q[5]/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)));
            s_XmatsHom[16*0 + 10] = static_cast<T>(-2.0*pow(s_q[3], 2)/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)) - 2.0*pow(s_q[4], 2)/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)) + 1.0);
            s_XmatsHom[16*0 + 12] = static_cast<T>(s_q[0]);
            s_XmatsHom[16*0 + 13] = static_cast<T>(s_q[1]);
            s_XmatsHom[16*0 + 14] = static_cast<T>(s_q[2]);
        }
        // X_hom[1] q-dependent cells
        {
            const T s = static_cast<T>(sin(s_q[7]));
            const T c = static_cast<T>(cos(s_q[7]));
            (void)s; (void)c;
            s_XmatsHom[16*1 + 5] = static_cast<T>(c);
            s_XmatsHom[16*1 + 6] = static_cast<T>(s);
            s_XmatsHom[16*1 + 9] = static_cast<T>(-s);
            s_XmatsHom[16*1 + 10] = static_cast<T>(c);
        }
        // X_hom[2] q-dependent cells
        {
            const T s = static_cast<T>(sin(s_q[8]));
            const T c = static_cast<T>(cos(s_q[8]));
            (void)s; (void)c;
            s_XmatsHom[16*2 + 0] = static_cast<T>(c);
            s_XmatsHom[16*2 + 2] = static_cast<T>(-s);
            s_XmatsHom[16*2 + 8] = static_cast<T>(s);
            s_XmatsHom[16*2 + 10] = static_cast<T>(c);
        }
        // X_hom[3] q-dependent cells
        {
            const T s = static_cast<T>(sin(s_q[9]));
            const T c = static_cast<T>(cos(s_q[9]));
            (void)s; (void)c;
            s_XmatsHom[16*3 + 0] = static_cast<T>(c);
            s_XmatsHom[16*3 + 2] = static_cast<T>(-s);
            s_XmatsHom[16*3 + 8] = static_cast<T>(s);
            s_XmatsHom[16*3 + 10] = static_cast<T>(c);
        }
        // X_hom[4] q-dependent cells
        {
            const T s = static_cast<T>(sin(s_q[10]));
            const T c = static_cast<T>(cos(s_q[10]));
            (void)s; (void)c;
            s_XmatsHom[16*4 + 5] = static_cast<T>(c);
            s_XmatsHom[16*4 + 6] = static_cast<T>(s);
            s_XmatsHom[16*4 + 9] = static_cast<T>(-s);
            s_XmatsHom[16*4 + 10] = static_cast<T>(c);
        }
        // X_hom[5] q-dependent cells
        {
            const T s = static_cast<T>(sin(s_q[11]));
            const T c = static_cast<T>(cos(s_q[11]));
            (void)s; (void)c;
            s_XmatsHom[16*5 + 0] = static_cast<T>(c);
            s_XmatsHom[16*5 + 2] = static_cast<T>(-s);
            s_XmatsHom[16*5 + 8] = static_cast<T>(s);
            s_XmatsHom[16*5 + 10] = static_cast<T>(c);
        }
        // X_hom[6] q-dependent cells
        {
            const T s = static_cast<T>(sin(s_q[12]));
            const T c = static_cast<T>(cos(s_q[12]));
            (void)s; (void)c;
            s_XmatsHom[16*6 + 0] = static_cast<T>(c);
            s_XmatsHom[16*6 + 2] = static_cast<T>(-s);
            s_XmatsHom[16*6 + 8] = static_cast<T>(s);
            s_XmatsHom[16*6 + 10] = static_cast<T>(c);
        }
        // X_hom[7] q-dependent cells
        {
            const T s = static_cast<T>(sin(s_q[13]));
            const T c = static_cast<T>(cos(s_q[13]));
            (void)s; (void)c;
            s_XmatsHom[16*7 + 5] = static_cast<T>(c);
            s_XmatsHom[16*7 + 6] = static_cast<T>(s);
            s_XmatsHom[16*7 + 9] = static_cast<T>(-s);
            s_XmatsHom[16*7 + 10] = static_cast<T>(c);
        }
        // X_hom[8] q-dependent cells
        {
            const T s = static_cast<T>(sin(s_q[14]));
            const T c = static_cast<T>(cos(s_q[14]));
            (void)s; (void)c;
            s_XmatsHom[16*8 + 0] = static_cast<T>(c);
            s_XmatsHom[16*8 + 2] = static_cast<T>(-s);
            s_XmatsHom[16*8 + 8] = static_cast<T>(s);
            s_XmatsHom[16*8 + 10] = static_cast<T>(c);
        }
        // X_hom[9] q-dependent cells
        {
            const T s = static_cast<T>(sin(s_q[15]));
            const T c = static_cast<T>(cos(s_q[15]));
            (void)s; (void)c;
            s_XmatsHom[16*9 + 0] = static_cast<T>(c);
            s_XmatsHom[16*9 + 2] = static_cast<T>(-s);
            s_XmatsHom[16*9 + 8] = static_cast<T>(s);
            s_XmatsHom[16*9 + 10] = static_cast<T>(c);
        }
        // X_hom[10] q-dependent cells
        {
            const T s = static_cast<T>(sin(s_q[16]));
            const T c = static_cast<T>(cos(s_q[16]));
            (void)s; (void)c;
            s_XmatsHom[16*10 + 5] = static_cast<T>(c);
            s_XmatsHom[16*10 + 6] = static_cast<T>(s);
            s_XmatsHom[16*10 + 9] = static_cast<T>(-s);
            s_XmatsHom[16*10 + 10] = static_cast<T>(c);
        }
        // X_hom[11] q-dependent cells
        {
            const T s = static_cast<T>(sin(s_q[17]));
            const T c = static_cast<T>(cos(s_q[17]));
            (void)s; (void)c;
            s_XmatsHom[16*11 + 0] = static_cast<T>(c);
            s_XmatsHom[16*11 + 2] = static_cast<T>(-s);
            s_XmatsHom[16*11 + 8] = static_cast<T>(s);
            s_XmatsHom[16*11 + 10] = static_cast<T>(c);
        }
        // X_hom[12] q-dependent cells
        {
            const T s = static_cast<T>(sin(s_q[18]));
            const T c = static_cast<T>(cos(s_q[18]));
            (void)s; (void)c;
            s_XmatsHom[16*12 + 0] = static_cast<T>(c);
            s_XmatsHom[16*12 + 2] = static_cast<T>(-s);
            s_XmatsHom[16*12 + 8] = static_cast<T>(s);
            s_XmatsHom[16*12 + 10] = static_cast<T>(c);
        }
        // chain up cumulative world transforms (parent always < child)
        #pragma unroll
        for (int j = 0; j < 13; ++j) {
            const T* c = &s_XmatsHom[j * 16];
            T* o = &s_jointXforms[j * 16];
            int par = ((const int[]) {-1,0,1,2,0,4,5,0,7,8,0,10,11})[j];
            if (par < 0) {
                o[0]=c[0];   o[1]=c[1];   o[2]=c[2];
                o[4]=c[4];   o[5]=c[5];   o[6]=c[6];
                o[8]=c[8];   o[9]=c[9];   o[10]=c[10];
                o[12]=c[12]; o[13]=c[13]; o[14]=c[14];
            }
            else {
                const T* p = &s_jointXforms[par * 16];
                o[0]  = p[0]*c[0]   + p[4]*c[1]   + p[8]*c[2];
                o[1]  = p[1]*c[0]   + p[5]*c[1]   + p[9]*c[2];
                o[2]  = p[2]*c[0]   + p[6]*c[1]   + p[10]*c[2];
                o[4]  = p[0]*c[4]   + p[4]*c[5]   + p[8]*c[6];
                o[5]  = p[1]*c[4]   + p[5]*c[5]   + p[9]*c[6];
                o[6]  = p[2]*c[4]   + p[6]*c[5]   + p[10]*c[6];
                o[8]  = p[0]*c[8]   + p[4]*c[9]   + p[8]*c[10];
                o[9]  = p[1]*c[8]   + p[5]*c[9]   + p[9]*c[10];
                o[10] = p[2]*c[8]   + p[6]*c[9]   + p[10]*c[10];
                o[12] = p[0]*c[12]  + p[4]*c[13]  + p[8]*c[14]  + p[12];
                o[13] = p[1]*c[12]  + p[5]*c[13]  + p[9]*c[14]  + p[13];
                o[14] = p[2]*c[12]  + p[6]*c[13]  + p[10]*c[14] + p[14];
            }
            o[3]=(T)0; o[7]=(T)0; o[11]=(T)0; o[15]=(T)1;
        }
    }

    /**
     * Single-joint homogeneous-transform builder: writes joint j's 4x4 local transform (16 cells) into s_Xj at an EXPLICIT angle theta, sourcing the constant cells from the pre-loaded s_XmatsHom and overriding only the q-dependent cells. Robot-general (switch over the parser's per-joint Xmats). Lets a caller re-evaluate one perturbed joint without recomputing the whole chain (coordinate-descent candidate FK / suffix recompute).
     *
     * Notes:
     *   Assumes the constant (q-independent) cells of s_XmatsHom are pre-loaded.
     *
     * @param s_Xj is the 16-element destination for joint j's local transform
     * @param s_XmatsHom is the pointer to the per-joint homogeneous transforms (16 per joint)
     * @param j is the joint id to (re)build
     * @param theta is the joint angle to evaluate at
     */
    template <typename T>
    __device__ __forceinline__
    void update_XmatHom_joint(T *s_Xj, const T *s_XmatsHom, int j, T theta) {
        const T s = static_cast<T>(sin(theta));
        const T c = static_cast<T>(cos(theta));
        (void)s; (void)c;
        #pragma unroll
        for (int m = 0; m < 16; ++m) { s_Xj[m] = s_XmatsHom[16*j + m]; }
        switch (j) {
            case 1: {
                s_Xj[5] = static_cast<T>(c);
                s_Xj[6] = static_cast<T>(s);
                s_Xj[9] = static_cast<T>(-s);
                s_Xj[10] = static_cast<T>(c);
            } break;
            case 2: {
                s_Xj[0] = static_cast<T>(c);
                s_Xj[2] = static_cast<T>(-s);
                s_Xj[8] = static_cast<T>(s);
                s_Xj[10] = static_cast<T>(c);
            } break;
            case 3: {
                s_Xj[0] = static_cast<T>(c);
                s_Xj[2] = static_cast<T>(-s);
                s_Xj[8] = static_cast<T>(s);
                s_Xj[10] = static_cast<T>(c);
            } break;
            case 4: {
                s_Xj[5] = static_cast<T>(c);
                s_Xj[6] = static_cast<T>(s);
                s_Xj[9] = static_cast<T>(-s);
                s_Xj[10] = static_cast<T>(c);
            } break;
            case 5: {
                s_Xj[0] = static_cast<T>(c);
                s_Xj[2] = static_cast<T>(-s);
                s_Xj[8] = static_cast<T>(s);
                s_Xj[10] = static_cast<T>(c);
            } break;
            case 6: {
                s_Xj[0] = static_cast<T>(c);
                s_Xj[2] = static_cast<T>(-s);
                s_Xj[8] = static_cast<T>(s);
                s_Xj[10] = static_cast<T>(c);
            } break;
            case 7: {
                s_Xj[5] = static_cast<T>(c);
                s_Xj[6] = static_cast<T>(s);
                s_Xj[9] = static_cast<T>(-s);
                s_Xj[10] = static_cast<T>(c);
            } break;
            case 8: {
                s_Xj[0] = static_cast<T>(c);
                s_Xj[2] = static_cast<T>(-s);
                s_Xj[8] = static_cast<T>(s);
                s_Xj[10] = static_cast<T>(c);
            } break;
            case 9: {
                s_Xj[0] = static_cast<T>(c);
                s_Xj[2] = static_cast<T>(-s);
                s_Xj[8] = static_cast<T>(s);
                s_Xj[10] = static_cast<T>(c);
            } break;
            case 10: {
                s_Xj[5] = static_cast<T>(c);
                s_Xj[6] = static_cast<T>(s);
                s_Xj[9] = static_cast<T>(-s);
                s_Xj[10] = static_cast<T>(c);
            } break;
            case 11: {
                s_Xj[0] = static_cast<T>(c);
                s_Xj[2] = static_cast<T>(-s);
                s_Xj[8] = static_cast<T>(s);
                s_Xj[10] = static_cast<T>(c);
            } break;
            case 12: {
                s_Xj[0] = static_cast<T>(c);
                s_Xj[2] = static_cast<T>(-s);
                s_Xj[8] = static_cast<T>(s);
                s_Xj[10] = static_cast<T>(c);
            } break;
            default: break;
        }
    }

    /**
     * Warp-per-sample forward kinematics: warp-cooperative chain walk that fills the full cumulative (world-frame) joint transforms s_jointXforms from s_q. Robot-general (any DoF / joint types). 3 lanes own the matrix rows; __syncwarp between levels. Reads s_jointXforms[16*target_idx] for the world pose of frame target_idx.
     *
     * Notes:
     *   Assumes the constant (q-independent) cells of s_XmatsHom are pre-loaded; only the q-dependent cells are refreshed here.
     *
     * @param s_jointXforms is the pointer to the cumulative (world) joint transforms (16 per joint)
     * @param s_XmatsHom is the pointer to the per-joint homogeneous transforms (16 per joint)
     * @param s_q is the vector of joint positions
     * @param target_idx is the joint index whose world transform is desired (full array is filled)
     */
    template <typename T>
    __device__ inline void ee_pose_inner_warp(
        T* __restrict__ s_jointXforms,
        T* __restrict__ s_XmatsHom,
        const T* __restrict__ s_q,
        int target_idx)
    {
        (void)target_idx;
        const int lane = threadIdx.x & 31;
        const unsigned mask = 0xFFFFFFFFu;
        // refresh q-dependent X_hom cells: lane j owns joint j
        if (lane == 0) {
            s_XmatsHom[16*0 + 0] = static_cast<T>(-2.0*pow(s_q[4], 2)/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)) - 2.0*pow(s_q[5], 2)/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)) + 1.0);
            s_XmatsHom[16*0 + 1] = static_cast<T>(2.0*s_q[3]*s_q[4]/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)) + 2.0*s_q[5]*s_q[6]/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)));
            s_XmatsHom[16*0 + 2] = static_cast<T>(2.0*s_q[3]*s_q[5]/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)) - 2.0*s_q[4]*s_q[6]/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)));
            s_XmatsHom[16*0 + 4] = static_cast<T>(2.0*s_q[3]*s_q[4]/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)) - 2.0*s_q[5]*s_q[6]/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)));
            s_XmatsHom[16*0 + 5] = static_cast<T>(-2.0*pow(s_q[3], 2)/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)) - 2.0*pow(s_q[5], 2)/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)) + 1.0);
            s_XmatsHom[16*0 + 6] = static_cast<T>(2.0*s_q[3]*s_q[6]/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)) + 2.0*s_q[4]*s_q[5]/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)));
            s_XmatsHom[16*0 + 8] = static_cast<T>(2.0*s_q[3]*s_q[5]/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)) + 2.0*s_q[4]*s_q[6]/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)));
            s_XmatsHom[16*0 + 9] = static_cast<T>(-2.0*s_q[3]*s_q[6]/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)) + 2.0*s_q[4]*s_q[5]/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)));
            s_XmatsHom[16*0 + 10] = static_cast<T>(-2.0*pow(s_q[3], 2)/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)) - 2.0*pow(s_q[4], 2)/(pow(s_q[3], 2) + pow(s_q[4], 2) + pow(s_q[5], 2) + pow(s_q[6], 2)) + 1.0);
            s_XmatsHom[16*0 + 12] = static_cast<T>(s_q[0]);
            s_XmatsHom[16*0 + 13] = static_cast<T>(s_q[1]);
            s_XmatsHom[16*0 + 14] = static_cast<T>(s_q[2]);
        }
        if (lane == 1) {
            const T s = static_cast<T>(sin(s_q[7]));
            const T c = static_cast<T>(cos(s_q[7]));
            (void)s; (void)c;
            s_XmatsHom[16*1 + 5] = static_cast<T>(c);
            s_XmatsHom[16*1 + 6] = static_cast<T>(s);
            s_XmatsHom[16*1 + 9] = static_cast<T>(-s);
            s_XmatsHom[16*1 + 10] = static_cast<T>(c);
        }
        if (lane == 2) {
            const T s = static_cast<T>(sin(s_q[8]));
            const T c = static_cast<T>(cos(s_q[8]));
            (void)s; (void)c;
            s_XmatsHom[16*2 + 0] = static_cast<T>(c);
            s_XmatsHom[16*2 + 2] = static_cast<T>(-s);
            s_XmatsHom[16*2 + 8] = static_cast<T>(s);
            s_XmatsHom[16*2 + 10] = static_cast<T>(c);
        }
        if (lane == 3) {
            const T s = static_cast<T>(sin(s_q[9]));
            const T c = static_cast<T>(cos(s_q[9]));
            (void)s; (void)c;
            s_XmatsHom[16*3 + 0] = static_cast<T>(c);
            s_XmatsHom[16*3 + 2] = static_cast<T>(-s);
            s_XmatsHom[16*3 + 8] = static_cast<T>(s);
            s_XmatsHom[16*3 + 10] = static_cast<T>(c);
        }
        if (lane == 4) {
            const T s = static_cast<T>(sin(s_q[10]));
            const T c = static_cast<T>(cos(s_q[10]));
            (void)s; (void)c;
            s_XmatsHom[16*4 + 5] = static_cast<T>(c);
            s_XmatsHom[16*4 + 6] = static_cast<T>(s);
            s_XmatsHom[16*4 + 9] = static_cast<T>(-s);
            s_XmatsHom[16*4 + 10] = static_cast<T>(c);
        }
        if (lane == 5) {
            const T s = static_cast<T>(sin(s_q[11]));
            const T c = static_cast<T>(cos(s_q[11]));
            (void)s; (void)c;
            s_XmatsHom[16*5 + 0] = static_cast<T>(c);
            s_XmatsHom[16*5 + 2] = static_cast<T>(-s);
            s_XmatsHom[16*5 + 8] = static_cast<T>(s);
            s_XmatsHom[16*5 + 10] = static_cast<T>(c);
        }
        if (lane == 6) {
            const T s = static_cast<T>(sin(s_q[12]));
            const T c = static_cast<T>(cos(s_q[12]));
            (void)s; (void)c;
            s_XmatsHom[16*6 + 0] = static_cast<T>(c);
            s_XmatsHom[16*6 + 2] = static_cast<T>(-s);
            s_XmatsHom[16*6 + 8] = static_cast<T>(s);
            s_XmatsHom[16*6 + 10] = static_cast<T>(c);
        }
        if (lane == 7) {
            const T s = static_cast<T>(sin(s_q[13]));
            const T c = static_cast<T>(cos(s_q[13]));
            (void)s; (void)c;
            s_XmatsHom[16*7 + 5] = static_cast<T>(c);
            s_XmatsHom[16*7 + 6] = static_cast<T>(s);
            s_XmatsHom[16*7 + 9] = static_cast<T>(-s);
            s_XmatsHom[16*7 + 10] = static_cast<T>(c);
        }
        if (lane == 8) {
            const T s = static_cast<T>(sin(s_q[14]));
            const T c = static_cast<T>(cos(s_q[14]));
            (void)s; (void)c;
            s_XmatsHom[16*8 + 0] = static_cast<T>(c);
            s_XmatsHom[16*8 + 2] = static_cast<T>(-s);
            s_XmatsHom[16*8 + 8] = static_cast<T>(s);
            s_XmatsHom[16*8 + 10] = static_cast<T>(c);
        }
        if (lane == 9) {
            const T s = static_cast<T>(sin(s_q[15]));
            const T c = static_cast<T>(cos(s_q[15]));
            (void)s; (void)c;
            s_XmatsHom[16*9 + 0] = static_cast<T>(c);
            s_XmatsHom[16*9 + 2] = static_cast<T>(-s);
            s_XmatsHom[16*9 + 8] = static_cast<T>(s);
            s_XmatsHom[16*9 + 10] = static_cast<T>(c);
        }
        if (lane == 10) {
            const T s = static_cast<T>(sin(s_q[16]));
            const T c = static_cast<T>(cos(s_q[16]));
            (void)s; (void)c;
            s_XmatsHom[16*10 + 5] = static_cast<T>(c);
            s_XmatsHom[16*10 + 6] = static_cast<T>(s);
            s_XmatsHom[16*10 + 9] = static_cast<T>(-s);
            s_XmatsHom[16*10 + 10] = static_cast<T>(c);
        }
        if (lane == 11) {
            const T s = static_cast<T>(sin(s_q[17]));
            const T c = static_cast<T>(cos(s_q[17]));
            (void)s; (void)c;
            s_XmatsHom[16*11 + 0] = static_cast<T>(c);
            s_XmatsHom[16*11 + 2] = static_cast<T>(-s);
            s_XmatsHom[16*11 + 8] = static_cast<T>(s);
            s_XmatsHom[16*11 + 10] = static_cast<T>(c);
        }
        if (lane == 12) {
            const T s = static_cast<T>(sin(s_q[18]));
            const T c = static_cast<T>(cos(s_q[18]));
            (void)s; (void)c;
            s_XmatsHom[16*12 + 0] = static_cast<T>(c);
            s_XmatsHom[16*12 + 2] = static_cast<T>(-s);
            s_XmatsHom[16*12 + 8] = static_cast<T>(s);
            s_XmatsHom[16*12 + 10] = static_cast<T>(c);
        }
        __syncwarp(mask);
        // chain up cumulative world transforms (parent always < child)
        #pragma unroll
        for (int j = 0; j < 13; ++j) {
            const T* c = &s_XmatsHom[j * 16];
            T* o = &s_jointXforms[j * 16];
            int par = ((const int[]) {-1,0,1,2,0,4,5,0,7,8,0,10,11})[j];
            if (par < 0) {
                if (lane == 0) { o[0]=c[0]; o[4]=c[4]; o[8]=c[8];  o[12]=c[12]; o[3]=(T)0; o[7]=(T)0; o[11]=(T)0; o[15]=(T)1; }
                else if (lane == 1) { o[1]=c[1]; o[5]=c[5]; o[9]=c[9];  o[13]=c[13]; }
                else if (lane == 2) { o[2]=c[2]; o[6]=c[6]; o[10]=c[10]; o[14]=c[14]; }
            }
            else {
                const T* p = &s_jointXforms[par * 16];
                if (lane == 0) {
                    o[0]  = p[0]*c[0]  + p[4]*c[1]  + p[8]*c[2];
                    o[4]  = p[0]*c[4]  + p[4]*c[5]  + p[8]*c[6];
                    o[8]  = p[0]*c[8]  + p[4]*c[9]  + p[8]*c[10];
                    o[12] = p[0]*c[12] + p[4]*c[13] + p[8]*c[14] + p[12];
                    o[3]  = (T)0;      o[7]  = (T)0;      o[11] = (T)0;      o[15] = (T)1;
                }
                else if (lane == 1) {
                    o[1]  = p[1]*c[0]  + p[5]*c[1]  + p[9]*c[2];
                    o[5]  = p[1]*c[4]  + p[5]*c[5]  + p[9]*c[6];
                    o[9]  = p[1]*c[8]  + p[5]*c[9]  + p[9]*c[10];
                    o[13] = p[1]*c[12] + p[5]*c[13] + p[9]*c[14] + p[13];
                }
                else if (lane == 2) {
                    o[2]  = p[2]*c[0]  + p[6]*c[1]  + p[10]*c[2];
                    o[6]  = p[2]*c[4]  + p[6]*c[5]  + p[10]*c[6];
                    o[10] = p[2]*c[8]  + p[6]*c[9]  + p[10]*c[10];
                    o[14] = p[2]*c[12] + p[6]*c[13] + p[10]*c[14] + p[14];
                }
            }
            __syncwarp(mask);
        }
    }

    /**
     * Batched forward kinematics: one block per sample, pos+quat output.
     *
     * Notes:
     *   USE_WARP picks the warp-cooperative inner (warp 0) vs the thread inner (thread 0).
     *   target_idx selects the output frame (defaults to the leaf EE joint id).
     *
     * @param d_pose7 is the (B x 7) output: [tx,ty,tz, qw,qx,qy,qz] per sample
     * @param d_q is the (B x NUM_POS) joint-position input (batch-major, stride stride_q)
     * @param stride_q is the stride between samples in d_q (== NUM_POS)
     * @param d_robotModel holds the per-robot constants (XImats, topology helpers)
     * @param B is the batch size (== gridDim.x)
     * @param target_idx is the joint frame whose world pose is written
     */
    template <typename T, bool USE_WARP = false, bool MUJOCO_OUTPUT = false>
    __global__
    void ee_pose_fk_batched_kernel(T *d_pose7, const T *d_q, const int stride_q, const robotModel<T> *d_robotModel, const int B, const int target_idx = 3) {
        __shared__ T s_q[19];
        __shared__ T s_XmatsHom[672];
        __shared__ T s_jointXforms[208];
        __shared__ T s_temp[38];
        __shared__ int s_topology_helpers[115];
        for (int b = blockIdx.x; b < B; b += gridDim.x) {
            for (int j = threadIdx.x; j < 19; j += blockDim.x) { s_q[j] = d_q[b*stride_q + j]; }
            __syncthreads();
            if constexpr (MUJOCO_OUTPUT) {
                // mjx input convert: base quaternion wxyz->xyzw (q-only; value frame-independent)
                if (threadIdx.x == 0 && threadIdx.y == 0) {
                    T qw_in = s_q[3];
                    s_q[3] = s_q[4]; s_q[4] = s_q[5]; s_q[5] = s_q[6]; s_q[6] = qw_in;
                }
                __syncthreads();
            }
            load_update_XmatsHom_helpers<T>(s_XmatsHom, s_topology_helpers, s_q, d_robotModel, s_temp);
            __syncthreads();
            if (USE_WARP) {
                if ((threadIdx.x >> 5) == 0) { ee_pose_inner_warp<T>(s_jointXforms, s_XmatsHom, s_q, target_idx); }
            }
            else {
                if (threadIdx.x == 0) { ee_pose_inner_thread<T>(s_jointXforms, s_XmatsHom, s_q, target_idx); }
            }
            __syncthreads();
            if (threadIdx.x == 0) {
                const T* X = &s_jointXforms[16*target_idx];
                // rotation block (column-major): R[r][c] = X[4*c + r]
                const T r00=X[0], r10=X[1], r20=X[2];
                const T r01=X[4], r11=X[5], r21=X[6];
                const T r02=X[8], r12=X[9], r22=X[10];
                T* o = &d_pose7[b*7];
                o[0]=X[12]; o[1]=X[13]; o[2]=X[14];
                // quaternion (w,x,y,z) from rotation (Shepperd's method)
                const T tr = r00 + r11 + r22;
                T qw,qx,qy,qz;
                if (tr > (T)0) {
                    T S = sqrt(tr + (T)1) * (T)2; qw = (T)0.25*S; qx=(r21-r12)/S; qy=(r02-r20)/S; qz=(r10-r01)/S;
                }
                else if (r00 > r11 && r00 > r22) {
                    T S = sqrt((T)1 + r00 - r11 - r22) * (T)2; qw=(r21-r12)/S; qx=(T)0.25*S; qy=(r01+r10)/S; qz=(r02+r20)/S;
                }
                else if (r11 > r22) {
                    T S = sqrt((T)1 + r11 - r00 - r22) * (T)2; qw=(r02-r20)/S; qx=(r01+r10)/S; qy=(T)0.25*S; qz=(r12+r21)/S;
                }
                else {
                    T S = sqrt((T)1 + r22 - r00 - r11) * (T)2; qw=(r10-r01)/S; qx=(r02+r20)/S; qy=(r12+r21)/S; qz=(T)0.25*S;
                }
                o[3]=qw; o[4]=qx; o[5]=qy; o[6]=qz;
            }
            __syncthreads();
        }
    }

    /**
     * Host launcher for batched FK (<<<B, threads>>>, one block per sample).
     *
     * Notes:
     *   USE_WARP selects the warp- vs thread-cooperative per-sample inner.
     *
     * @param d_pose7 is the device (B x 7) output buffer
     * @param d_q is the device (B x NUM_POS) input buffer (batch-major)
     * @param B is the batch size
     * @param d_robotModel holds the per-robot constants
     * @param threads is the per-block thread count (>=32 for the warp variant)
     * @param target_idx selects the output frame (defaults to the leaf EE)
     * @param stream is the CUDA stream
     */
    template <typename T, bool USE_WARP = false, bool MUJOCO_OUTPUT = false>
    __host__
    void ee_pose_fk_batched(T *d_pose7, const T *d_q, const int B, const robotModel<T> *d_robotModel, const int threads = 32, const int target_idx = 3, cudaStream_t stream = (cudaStream_t)0) {
        const int stride_q = 19;
        ee_pose_fk_batched_kernel<T, USE_WARP, MUJOCO_OUTPUT><<<B, threads, 0, stream>>>(d_pose7, d_q, stride_q, d_robotModel, B, target_idx);
    }

    #define GRID_HAS_FK_BATCHED 1
    // ---- GATO Ask-4: stable end-effector TARGET aliases -------------------------
    // Resolve to the named fixed kinematic target when one was generated, else to the
    // generic (last-moving-joint) family. ALWAYS defined, so a consumer never has to
    // name a robot-specific joint (indy7 '_EE' vs panda '_panda_hand') or feature-test.
    // NAMED target_imu_joint -> TRUE ee_frame (== pinocchio oMf[target]); NUM_EE = 1.
    // 
    const int NUM_TARGET_EES = 1;
    #define GRID_EE_FIXED_TARGET_NAME "imu_joint"
    
    template <typename T, bool TEMP_IN_SMEM = true, typename... Args>
    __device__ __forceinline__
    void end_effector_pose_target_inner(Args... args) { end_effector_pose_inner_imu_joint<T, TEMP_IN_SMEM>(args...); }
    
    template <typename T, typename... Args>
    __device__ __forceinline__
    void end_effector_pose_target_device(Args... args) { end_effector_pose_device_imu_joint<T>(args...); }
    
    template <typename T, bool TEMP_IN_SMEM = true, typename... Args>
    __device__ __forceinline__
    void end_effector_pose_gradient_target_inner(Args... args) { end_effector_pose_gradient_inner_imu_joint<T, TEMP_IN_SMEM>(args...); }
    
    template <typename T, typename... Args>
    __device__ __forceinline__
    void end_effector_pose_gradient_target_device(Args... args) { end_effector_pose_gradient_device_imu_joint<T>(args...); }
    
    template <typename T, bool OUT_IN_SMEM = true, typename... Args>
    __device__ __forceinline__
    void end_effector_pose_hessian_target_inner(Args... args) { end_effector_pose_hessian_inner_imu_joint<T, OUT_IN_SMEM>(args...); }
    
    template <typename T, int RESOURCE_TIER = TIER_SHARED, typename... Args>
    __device__ __forceinline__
    void end_effector_pose_hessian_target_device(Args... args) { end_effector_pose_hessian_device_imu_joint<T, RESOURCE_TIER>(args...); }
    
    // ---- grid_rbd EE binding entry-point aliases (single named target routes here) ----
    #define GRID_RBD_NUM_EES 1
    #define GRID_RBD_EE_POSE_FN end_effector_pose_imu_joint
    #define GRID_RBD_EE_POSE_GRADIENT_FN end_effector_pose_gradient_imu_joint
    #define GRID_RBD_EE_POSE_HESSIAN_FN end_effector_pose_hessian_imu_joint
    #define GRID_RBD_EE_POSE_KERNEL end_effector_pose_kernel_imu_joint
    #define GRID_RBD_EE_POSE_GRADIENT_KERNEL end_effector_pose_gradient_kernel_imu_joint
    #define GRID_RBD_EE_POSE_HESSIAN_KERNEL end_effector_pose_hessian_kernel_imu_joint
    
    
    // ---- contact frames (GATO ask 1 C.2): world-aligned contact wrench -> joint-local f_ext
    //   'FR_foot_joint' -> body 6 @ local offset (0, 0, -0.213)
    //   'FL_foot_joint' -> body 3 @ local offset (0, 0, -0.213)
    //   'RR_foot_joint' -> body 12 @ local offset (0, 0, -0.213)
    //   'RL_foot_joint' -> body 9 @ local offset (0, 0, -0.213)
    #define GRID_HAS_CONTACT_FRAMES 1
    const int NUM_CONTACT_FRAMES = 4;
    /**
     * Contact-frame wrenches -> joint-local f_ext
     *
     * Notes:
     *   f_ext[b] += [ R^T n_w + r_c x (R^T f_w) ; R^T f_w ] -- rotate into the body frame, then TRANSPORT the moment from the contact origin to the joint origin.
     *   Output is fully zeroed first, so bodies with no contact stay 0 and the array can be handed straight to grid_plant::plant_step(..., d_f_ext).
     *   A pure point force is n_w = 0; the 6D form subsumes the 3D case.
     *
     * @param s_f_ext is the output, size 6*NUM_BODIES (joint-local Featherstone [angular;linear]); ZEROED then scattered
     * @param s_f_c is the contact wrench input, size 6*NUM_CONTACT_FRAMES = 24 ([n_w; f_w] per frame, WORLD-ALIGNED axes, moment about the contact origin)
     * @param s_q is the vector of joint positions
     * @param s_Xhom is the per-joint local homogeneous transforms (already updated for q)
     * @param s_temp is helper shared memory (holds s_Xworld = 16*NUM_JOINTS)
     * @param s_topology_helpers is the (shared) memory location for the topology_helpers (nullptr/unused for serial chains with identical Ss)
     * @param d_workspace is the global-memory scratch used when !TEMP_IN_SMEM
     */
    template <typename T, bool TEMP_IN_SMEM = true>
    __device__
    void f_ext_body_inner(T *s_f_ext, const T *s_f_c, const T *s_q, const T *s_Xhom, int *s_topology_helpers, T *s_temp, T *d_workspace, unsigned char *s_linalg_smem) {
        if constexpr (!TEMP_IN_SMEM) { s_temp = d_workspace; } else { (void)d_workspace; }
        (void)s_q; (void)s_linalg_smem;
        T *s_Xworld = s_temp;   // 16 * 13
        //
        // Build world transforms for every joint via BFS-level chain-up
        //
        // BFS level 0 -> joints [0]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 16; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            // branch to get pointer locations
            int jid; int par;
                 if (slot < 1){ jid = 0; par = -1; }
            if (par == -1) {
                s_Xworld[16*jid + ele] = s_Xhom[16*jid + ele];
            }
            else {
                s_Xworld[16*jid + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*jid + 4*col]);
            }
        }
        __syncthreads();
        // BFS level 1 -> joints [1, 4, 7, 10]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 64; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            // branch to get pointer locations
            int jid; int par;
                 if (slot < 1){ jid = 1; par = 0; }
            else if (slot < 2){ jid = 4; par = 0; }
            else if (slot < 3){ jid = 7; par = 0; }
            else              { jid = 10; par = 0; }
            if (par == -1) {
                s_Xworld[16*jid + ele] = s_Xhom[16*jid + ele];
            }
            else {
                s_Xworld[16*jid + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*jid + 4*col]);
            }
        }
        __syncthreads();
        // BFS level 2 -> joints [2, 5, 8, 11]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 64; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            // branch to get pointer locations
            int jid; int par;
                 if (slot < 1){ jid = 2; par = 1; }
            else if (slot < 2){ jid = 5; par = 4; }
            else if (slot < 3){ jid = 8; par = 7; }
            else              { jid = 11; par = 10; }
            if (par == -1) {
                s_Xworld[16*jid + ele] = s_Xhom[16*jid + ele];
            }
            else {
                s_Xworld[16*jid + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*jid + 4*col]);
            }
        }
        __syncthreads();
        // BFS level 3 -> joints [3, 6, 9, 12]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 64; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            // branch to get pointer locations
            int jid; int par;
                 if (slot < 1){ jid = 3; par = 2; }
            else if (slot < 2){ jid = 6; par = 5; }
            else if (slot < 3){ jid = 9; par = 8; }
            else              { jid = 12; par = 11; }
            if (par == -1) {
                s_Xworld[16*jid + ele] = s_Xhom[16*jid + ele];
            }
            else {
                s_Xworld[16*jid + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*jid + 4*col]);
            }
        }
        __syncthreads();
        // baked contact set: body id + LOCAL frame origin offset per contact
        static const T fc_offset[] = { static_cast<T>(0), static_cast<T>(0), static_cast<T>(-0.21299999999999999), static_cast<T>(0), static_cast<T>(0), static_cast<T>(-0.21299999999999999), static_cast<T>(0), static_cast<T>(0), static_cast<T>(-0.21299999999999999), static_cast<T>(0), static_cast<T>(0), static_cast<T>(-0.21299999999999999) };
        // body-grouped: one writer per output slot, fixed-order sums, NO atomics (determinism)
        static const int fc_uniq[] = { 3, 6, 9, 12 };
        static const int fc_start[] = { 0, 1, 2, 3 };
        static const int fc_count[] = { 1, 1, 1, 1 };
        static const int fc_ids[] = { 1, 0, 3, 2 };
        // zero every slot: bodies with no contact contribute nothing
        glass::set_const<T, 78>(static_cast<T>(0), s_f_ext);
        // one thread per (contacted body, component): single writer, fixed-order sum
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 24; ind += blockDim.x*blockDim.y){
            int k = ind % 6; int u = ind / 6;
            const int b = fc_uniq[u];
            T acc = static_cast<T>(0);
            for (int t = 0; t < fc_count[u]; ++t) {
                const int c = fc_ids[fc_start[u] + t];
                const T *nw = &s_f_c[6*c];       // world angular (moment about the CONTACT origin)
                const T *fw = &s_f_c[6*c + 3];   // world linear
                T g[3], h[3];
                for (int a = 0; a < 3; ++a) {
                    const T *Ra = &s_Xworld[16*b + 4*a];   // column a of R  ->  row a of R^T
                    g[a] = Ra[0]*nw[0] + Ra[1]*nw[1] + Ra[2]*nw[2];
                    h[a] = Ra[0]*fw[0] + Ra[1]*fw[1] + Ra[2]*fw[2];
                }
                const T r0 = fc_offset[3*c+0], r1 = fc_offset[3*c+1], r2 = fc_offset[3*c+2];
                if (k >= 3) { acc += h[k-3]; }
                else {
                    // angular = g + r_c x h
                    const T rxh0 = r1*h[2] - r2*h[1];
                    const T rxh1 = r2*h[0] - r0*h[2];
                    const T rxh2 = r0*h[1] - r1*h[0];
                    acc += g[k] + ((k == 0) ? rxh0 : ((k == 1) ? rxh1 : rxh2));
                }
            }
            s_f_ext[6*b + k] = acc;
        }
        __syncthreads();
    }

    /**
     * d(f_ext)/d(contact wrench) -- f_c-independent
     *
     * Notes:
     *   f_c-INDEPENDENT by construction (the map is linear in f_c) -- takes no f_c argument.
     *   Compose with grid::f_ext_gradient_device's dqdd/dfext to get dqdd/df_c.
     *
     * @param s_dfext_dfc is the output, size 1872 (column-major [row + 78*col], col = 6*c + j)
     * @param s_q is the vector of joint positions
     * @param s_Xhom is the per-joint local homogeneous transforms (already updated for q)
     * @param s_temp is helper shared memory (holds s_Xworld = 16*NUM_JOINTS)
     * @param s_topology_helpers is the (shared) memory location for the topology_helpers (nullptr/unused for serial chains with identical Ss)
     * @param d_workspace is the global-memory scratch used when !TEMP_IN_SMEM
     */
    template <typename T, bool TEMP_IN_SMEM = true>
    __device__
    void f_ext_body_jacobian_dfc_inner(T *s_dfext_dfc, const T *s_q, const T *s_Xhom, int *s_topology_helpers, T *s_temp, T *d_workspace, unsigned char *s_linalg_smem) {
        if constexpr (!TEMP_IN_SMEM) { s_temp = d_workspace; } else { (void)d_workspace; }
        (void)s_q; (void)s_linalg_smem;
        T *s_Xworld = s_temp;   // 16 * 13
        //
        // Build world transforms for every joint via BFS-level chain-up
        //
        // BFS level 0 -> joints [0]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 16; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            // branch to get pointer locations
            int jid; int par;
                 if (slot < 1){ jid = 0; par = -1; }
            if (par == -1) {
                s_Xworld[16*jid + ele] = s_Xhom[16*jid + ele];
            }
            else {
                s_Xworld[16*jid + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*jid + 4*col]);
            }
        }
        __syncthreads();
        // BFS level 1 -> joints [1, 4, 7, 10]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 64; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            // branch to get pointer locations
            int jid; int par;
                 if (slot < 1){ jid = 1; par = 0; }
            else if (slot < 2){ jid = 4; par = 0; }
            else if (slot < 3){ jid = 7; par = 0; }
            else              { jid = 10; par = 0; }
            if (par == -1) {
                s_Xworld[16*jid + ele] = s_Xhom[16*jid + ele];
            }
            else {
                s_Xworld[16*jid + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*jid + 4*col]);
            }
        }
        __syncthreads();
        // BFS level 2 -> joints [2, 5, 8, 11]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 64; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            // branch to get pointer locations
            int jid; int par;
                 if (slot < 1){ jid = 2; par = 1; }
            else if (slot < 2){ jid = 5; par = 4; }
            else if (slot < 3){ jid = 8; par = 7; }
            else              { jid = 11; par = 10; }
            if (par == -1) {
                s_Xworld[16*jid + ele] = s_Xhom[16*jid + ele];
            }
            else {
                s_Xworld[16*jid + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*jid + 4*col]);
            }
        }
        __syncthreads();
        // BFS level 3 -> joints [3, 6, 9, 12]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 64; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            // branch to get pointer locations
            int jid; int par;
                 if (slot < 1){ jid = 3; par = 2; }
            else if (slot < 2){ jid = 6; par = 5; }
            else if (slot < 3){ jid = 9; par = 8; }
            else              { jid = 12; par = 11; }
            if (par == -1) {
                s_Xworld[16*jid + ele] = s_Xhom[16*jid + ele];
            }
            else {
                s_Xworld[16*jid + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*jid + 4*col]);
            }
        }
        __syncthreads();
        // baked contact set: body id + LOCAL frame origin offset per contact
        static const int fc_body[] = { 6, 3, 12, 9 };
        static const T fc_offset[] = { static_cast<T>(0), static_cast<T>(0), static_cast<T>(-0.21299999999999999), static_cast<T>(0), static_cast<T>(0), static_cast<T>(-0.21299999999999999), static_cast<T>(0), static_cast<T>(0), static_cast<T>(-0.21299999999999999), static_cast<T>(0), static_cast<T>(0), static_cast<T>(-0.21299999999999999) };
        // zero: only the (body of contact c) rows are nonzero for column block c
        glass::set_const<T, 1872>(static_cast<T>(0), s_dfext_dfc);
        // one thread per (contact, out-component k, in-component j)
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 144; ind += blockDim.x*blockDim.y){
            int j = ind % 6; int rest = ind / 6; int k = rest % 6; int c = rest / 6;
            const int b = fc_body[c];
            const T r0 = fc_offset[3*c+0], r1 = fc_offset[3*c+1], r2 = fc_offset[3*c+2];
            // Rt(a, r) = R^T[a][r] = R[r][a] = s_Xworld[16*b + 4*a + r]
            T val = static_cast<T>(0);
            if (k >= 3) {
                // linear rows: [ 0 | R^T ] -> only the linear half of f_c contributes
                if (j >= 3) { val = s_Xworld[16*b + 4*(k-3) + (j-3)]; }
            }
            else {
                // angular rows: [ R^T | skew(r_c) R^T ]
                if (j < 3) { val = s_Xworld[16*b + 4*k + j]; }
                else {
                    // (skew(r) R^T)[k][j-3] = sum_a skew(r)[k][a] * R^T[a][j-3]
                    const int jj = j - 3;
                    const T Rt0 = s_Xworld[16*b + 4*0 + jj];
                    const T Rt1 = s_Xworld[16*b + 4*1 + jj];
                    const T Rt2 = s_Xworld[16*b + 4*2 + jj];
                    // skew(r) rows: [0,-r2,r1], [r2,0,-r0], [-r1,r0,0]
                    val = (k == 0) ? (-r2*Rt1 + r1*Rt2)
                        : ((k == 1) ? ( r2*Rt0 - r0*Rt2)
                                    : (-r1*Rt0 + r0*Rt1));
                }
            }
            s_dfext_dfc[(6*b + k) + 78*(6*c + j)] = val;
        }
        __syncthreads();
    }

    /**
     * d(f_ext)/dq at fixed contact wrench
     *
     * Notes:
     *   d(f_ext[b])/dq_v = [ -w_v x g - r_c x (w_v x h) ; -w_v x h ], with w_v the ANGULAR half of body b's LOCAL body-Jacobian column v (= -s_dtau_dfext[v + nv*(6b+k)], k in 0..2).
     *   This is the chain-rule term a solver DROPS if it treats the applied wrench as q-independent.
     *
     * @param s_dfext_dq is the output, size 6*NUM_BODIES*NUM_VEL, column-major [row + 6*NUM_BODIES*v]
     * @param s_f_c is the contact wrench input, size 6*NUM_CONTACT_FRAMES (the Jacobian is LINEAR in it)
     * @param s_dtau_dfext is -J^T from grid::f_ext_gradient_device, size NUM_VEL*6*NUM_BODIES (column-major [v + NUM_VEL*(6*i+k)]); its columns ARE the local body Jacobian
     * @param s_q is the vector of joint positions
     * @param s_Xhom is the per-joint local homogeneous transforms (already updated for q)
     * @param s_temp is helper shared memory (holds s_Xworld = 16*NUM_JOINTS)
     * @param s_topology_helpers is the (shared) memory location for the topology_helpers (nullptr/unused for serial chains with identical Ss)
     * @param d_workspace is the global-memory scratch used when !TEMP_IN_SMEM
     */
    template <typename T, bool TEMP_IN_SMEM = true>
    __device__
    void f_ext_body_jacobian_dq_inner(T *s_dfext_dq, const T *s_f_c, const T *s_dtau_dfext, const T *s_q, const T *s_Xhom, int *s_topology_helpers, T *s_temp, T *d_workspace, unsigned char *s_linalg_smem) {
        if constexpr (!TEMP_IN_SMEM) { s_temp = d_workspace; } else { (void)d_workspace; }
        (void)s_q; (void)s_linalg_smem;
        T *s_Xworld = s_temp;   // 16 * 13
        //
        // Build world transforms for every joint via BFS-level chain-up
        //
        // BFS level 0 -> joints [0]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 16; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            // branch to get pointer locations
            int jid; int par;
                 if (slot < 1){ jid = 0; par = -1; }
            if (par == -1) {
                s_Xworld[16*jid + ele] = s_Xhom[16*jid + ele];
            }
            else {
                s_Xworld[16*jid + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*jid + 4*col]);
            }
        }
        __syncthreads();
        // BFS level 1 -> joints [1, 4, 7, 10]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 64; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            // branch to get pointer locations
            int jid; int par;
                 if (slot < 1){ jid = 1; par = 0; }
            else if (slot < 2){ jid = 4; par = 0; }
            else if (slot < 3){ jid = 7; par = 0; }
            else              { jid = 10; par = 0; }
            if (par == -1) {
                s_Xworld[16*jid + ele] = s_Xhom[16*jid + ele];
            }
            else {
                s_Xworld[16*jid + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*jid + 4*col]);
            }
        }
        __syncthreads();
        // BFS level 2 -> joints [2, 5, 8, 11]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 64; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            // branch to get pointer locations
            int jid; int par;
                 if (slot < 1){ jid = 2; par = 1; }
            else if (slot < 2){ jid = 5; par = 4; }
            else if (slot < 3){ jid = 8; par = 7; }
            else              { jid = 11; par = 10; }
            if (par == -1) {
                s_Xworld[16*jid + ele] = s_Xhom[16*jid + ele];
            }
            else {
                s_Xworld[16*jid + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*jid + 4*col]);
            }
        }
        __syncthreads();
        // BFS level 3 -> joints [3, 6, 9, 12]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 64; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            // branch to get pointer locations
            int jid; int par;
                 if (slot < 1){ jid = 3; par = 2; }
            else if (slot < 2){ jid = 6; par = 5; }
            else if (slot < 3){ jid = 9; par = 8; }
            else              { jid = 12; par = 11; }
            if (par == -1) {
                s_Xworld[16*jid + ele] = s_Xhom[16*jid + ele];
            }
            else {
                s_Xworld[16*jid + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*jid + 4*col]);
            }
        }
        __syncthreads();
        // baked contact set: body id + LOCAL frame origin offset per contact
        static const T fc_offset[] = { static_cast<T>(0), static_cast<T>(0), static_cast<T>(-0.21299999999999999), static_cast<T>(0), static_cast<T>(0), static_cast<T>(-0.21299999999999999), static_cast<T>(0), static_cast<T>(0), static_cast<T>(-0.21299999999999999), static_cast<T>(0), static_cast<T>(0), static_cast<T>(-0.21299999999999999) };
        // body-grouped: one writer per output slot, fixed-order sums, NO atomics (determinism)
        static const int fc_uniq[] = { 3, 6, 9, 12 };
        static const int fc_start[] = { 0, 1, 2, 3 };
        static const int fc_count[] = { 1, 1, 1, 1 };
        static const int fc_ids[] = { 1, 0, 3, 2 };
        // zero every slot: bodies with no contact have zero sensitivity
        glass::set_const<T, 1404>(static_cast<T>(0), s_dfext_dq);
        // one thread per (contacted body, component, velocity): single writer
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 432; ind += blockDim.x*blockDim.y){
            int k = ind % 6; int rest = ind / 6; int u = rest % 4; int v = rest / 4;
            const int b = fc_uniq[u];
            // w_v = angular half of body b's LOCAL body-Jacobian column v = -s_dtau_dfext[v + nv*(6b+kk)]
            const T w0 = -s_dtau_dfext[v + 18*(6*b + 0)];
            const T w1 = -s_dtau_dfext[v + 18*(6*b + 1)];
            const T w2 = -s_dtau_dfext[v + 18*(6*b + 2)];
            T acc = static_cast<T>(0);
            for (int t = 0; t < fc_count[u]; ++t) {
                const int c = fc_ids[fc_start[u] + t];
                const T *nw = &s_f_c[6*c];       // world angular (moment about the CONTACT origin)
                const T *fw = &s_f_c[6*c + 3];   // world linear
                T g[3], h[3];
                for (int a = 0; a < 3; ++a) {
                    const T *Ra = &s_Xworld[16*b + 4*a];   // column a of R  ->  row a of R^T
                    g[a] = Ra[0]*nw[0] + Ra[1]*nw[1] + Ra[2]*nw[2];
                    h[a] = Ra[0]*fw[0] + Ra[1]*fw[1] + Ra[2]*fw[2];
                }
                const T r0 = fc_offset[3*c+0], r1 = fc_offset[3*c+1], r2 = fc_offset[3*c+2];
                // dh = -w x h ;  dg = -w x g
                const T dh0 = -(w1*h[2] - w2*h[1]), dh1 = -(w2*h[0] - w0*h[2]), dh2 = -(w0*h[1] - w1*h[0]);
                if (k >= 3) { acc += (k == 3) ? dh0 : ((k == 4) ? dh1 : dh2); }
                else {
                    const T dg0 = -(w1*g[2] - w2*g[1]), dg1 = -(w2*g[0] - w0*g[2]), dg2 = -(w0*g[1] - w1*g[0]);
                    // angular sensitivity = dg + r_c x dh
                    const T rxd0 = r1*dh2 - r2*dh1;
                    const T rxd1 = r2*dh0 - r0*dh2;
                    const T rxd2 = r0*dh1 - r1*dh0;
                    acc += ((k == 0) ? (dg0 + rxd0) : ((k == 1) ? (dg1 + rxd1) : (dg2 + rxd2)));
                }
            }
            s_dfext_dq[(6*b + k) + 78*v] = acc;
        }
        __syncthreads();
    }

    /**
     * Contact-frame wrenches -> the joint-local f_ext array plant_step consumes
     *
     * @param s_f_ext is the output joint-local wrench array, size 78
     * @param s_f_c is the contact wrench input, size 24 ([n_w; f_w] per frame, WORLD-ALIGNED, moment about the contact origin)
     * @param s_q is the vector of joint positions
     * @param d_robotModel is the initialized model-specific helpers on the GPU
     * @param d_workspace is the global scratch (= 0 bytes at TIER_SHARED, 672*sizeof(T) at TIER_LITE+); pass nullptr at TIER_SHARED
     */
    template <typename T, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __device__
    void f_ext_body_device(T *s_f_ext, const T *s_f_c, const T *s_q, const robotModel<T> *d_robotModel, T *d_workspace = nullptr) {
        // GRID shared arena layout
        //   T s_XmatsHom[672]
        //   T s_temp[672] (TIER_SHARED only; LITE/MINIMAL route to d_workspace)
        //   int s_topology_helpers[115]
        //   bytes s_linalg_smem[GRID_EE_LINALG_SHARED_BYTES<T>()]
        extern __shared__ __align__(16) unsigned char s_arena[];
        size_t s_arena_offset = 0;
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_XmatsHom = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(672);
        T *s_temp;
        if constexpr (RESOURCE_TIER == TIER_SHARED) {
            (void)d_workspace;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(672);
        }
        else {
            s_temp = d_workspace;
        }
        s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
        int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(int) * static_cast<size_t>(115);
        unsigned char *s_linalg_smem = nullptr;
        if (static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>()) > 0) {
            s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
            s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
            s_arena_offset += static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>());
        }
        #ifdef GRID_CUDA_DEBUG_LAYOUT
        if constexpr (RESOURCE_TIER == TIER_SHARED) {
            assert(s_arena_offset == grid_shared_arena_bytes<T>(1344, 115, GRID_EE_LINALG_SHARED_BYTES<T>()));
        }
        else {
            assert(s_arena_offset == grid_shared_arena_bytes<T>(672, 115, GRID_EE_LINALG_SHARED_BYTES<T>()));
        }
        #endif
        (void)s_arena_offset;
        load_update_XmatsHom_helpers<T>(s_XmatsHom, s_topology_helpers, s_q, d_robotModel, s_temp);
        f_ext_body_inner<T>(s_f_ext, s_f_c, s_q, s_XmatsHom, s_topology_helpers, s_temp, nullptr, s_linalg_smem);
    }

    /**
     * d(f_ext)/d(contact wrench) -- compose with dqdd/dfext to get dqdd/df_c
     *
     * @param s_dfext_dfc is the output d(f_ext)/d(f_c), size 1872 (column-major [row + 78*(6*c+j)])
     * @param s_q is the vector of joint positions
     * @param d_robotModel is the initialized model-specific helpers on the GPU
     * @param d_workspace is the global scratch (= 0 bytes at TIER_SHARED, 672*sizeof(T) at TIER_LITE+); pass nullptr at TIER_SHARED
     */
    template <typename T, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __device__
    void f_ext_body_jacobian_dfc_device(T *s_dfext_dfc, const T *s_q, const robotModel<T> *d_robotModel, T *d_workspace = nullptr) {
        // GRID shared arena layout
        //   T s_XmatsHom[672]
        //   T s_temp[672] (TIER_SHARED only; LITE/MINIMAL route to d_workspace)
        //   int s_topology_helpers[115]
        //   bytes s_linalg_smem[GRID_EE_LINALG_SHARED_BYTES<T>()]
        extern __shared__ __align__(16) unsigned char s_arena[];
        size_t s_arena_offset = 0;
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_XmatsHom = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(672);
        T *s_temp;
        if constexpr (RESOURCE_TIER == TIER_SHARED) {
            (void)d_workspace;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(672);
        }
        else {
            s_temp = d_workspace;
        }
        s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
        int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(int) * static_cast<size_t>(115);
        unsigned char *s_linalg_smem = nullptr;
        if (static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>()) > 0) {
            s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
            s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
            s_arena_offset += static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>());
        }
        #ifdef GRID_CUDA_DEBUG_LAYOUT
        if constexpr (RESOURCE_TIER == TIER_SHARED) {
            assert(s_arena_offset == grid_shared_arena_bytes<T>(1344, 115, GRID_EE_LINALG_SHARED_BYTES<T>()));
        }
        else {
            assert(s_arena_offset == grid_shared_arena_bytes<T>(672, 115, GRID_EE_LINALG_SHARED_BYTES<T>()));
        }
        #endif
        (void)s_arena_offset;
        load_update_XmatsHom_helpers<T>(s_XmatsHom, s_topology_helpers, s_q, d_robotModel, s_temp);
        f_ext_body_jacobian_dfc_inner<T>(s_dfext_dfc, s_q, s_XmatsHom, s_topology_helpers, s_temp, nullptr, s_linalg_smem);
    }

    /**
     * d(f_ext)/dq at fixed contact wrench (the chain-rule term solvers drop)
     *
     * @param s_dfext_dq is the output d(f_ext)/dq, size 1404 (column-major [row + 78*v])
     * @param s_f_c is the contact wrench input, size 24 ([n_w; f_w] per frame, WORLD-ALIGNED, moment about the contact origin)
     * @param s_dtau_dfext is -J^T from grid::f_ext_gradient_device, size 1404
     * @param s_q is the vector of joint positions
     * @param d_robotModel is the initialized model-specific helpers on the GPU
     * @param d_workspace is the global scratch (= 0 bytes at TIER_SHARED, 672*sizeof(T) at TIER_LITE+); pass nullptr at TIER_SHARED
     */
    template <typename T, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __device__
    void f_ext_body_jacobian_dq_device(T *s_dfext_dq, const T *s_f_c, const T *s_dtau_dfext, const T *s_q, const robotModel<T> *d_robotModel, T *d_workspace = nullptr) {
        // GRID shared arena layout
        //   T s_XmatsHom[672]
        //   T s_temp[672] (TIER_SHARED only; LITE/MINIMAL route to d_workspace)
        //   int s_topology_helpers[115]
        //   bytes s_linalg_smem[GRID_EE_LINALG_SHARED_BYTES<T>()]
        extern __shared__ __align__(16) unsigned char s_arena[];
        size_t s_arena_offset = 0;
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_XmatsHom = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(672);
        T *s_temp;
        if constexpr (RESOURCE_TIER == TIER_SHARED) {
            (void)d_workspace;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(672);
        }
        else {
            s_temp = d_workspace;
        }
        s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
        int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(int) * static_cast<size_t>(115);
        unsigned char *s_linalg_smem = nullptr;
        if (static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>()) > 0) {
            s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
            s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
            s_arena_offset += static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>());
        }
        #ifdef GRID_CUDA_DEBUG_LAYOUT
        if constexpr (RESOURCE_TIER == TIER_SHARED) {
            assert(s_arena_offset == grid_shared_arena_bytes<T>(1344, 115, GRID_EE_LINALG_SHARED_BYTES<T>()));
        }
        else {
            assert(s_arena_offset == grid_shared_arena_bytes<T>(672, 115, GRID_EE_LINALG_SHARED_BYTES<T>()));
        }
        #endif
        (void)s_arena_offset;
        load_update_XmatsHom_helpers<T>(s_XmatsHom, s_topology_helpers, s_q, d_robotModel, s_temp);
        f_ext_body_jacobian_dq_inner<T>(s_dfext_dq, s_f_c, s_dtau_dfext, s_q, s_XmatsHom, s_topology_helpers, s_temp, nullptr, s_linalg_smem);
    }

    // W1b batched multi-target world positions (opt-in via multi_target_batch); NUM_MULTI_TARGETS = 50
    const int NUM_MULTI_TARGETS = 50;
    template <typename T, int TIER = GRID_DEFAULT_RESOURCE_TIER> __host__ __device__ inline size_t MULTI_TARGET_POSITION_DYNAMIC_SHARED_MEM_BYTES() { if constexpr (TIER == TIER_SHARED) return grid_shared_arena_bytes<T>(1344, TOPOLOGY_HELPERS_COUNT, GRID_EE_LINALG_SHARED_BYTES<T>()); else return grid_shared_arena_bytes<T>(672, TOPOLOGY_HELPERS_COUNT, GRID_EE_LINALG_SHARED_BYTES<T>()); }
