    template <typename T, bool TEMP_IN_SMEM = true>
    __device__
    void multi_target_position_inner(T *s_out_pos, const T *s_q, const T *s_Xhom, int *s_topology_helpers, T *s_temp, T *d_workspace, unsigned char *s_linalg_smem) {
