        grid_linalg_segmented_row_strided_gemv<T,6,6,6,true>(4, seg_a_off_lvl3, seg_a_x_off_lvl3, seg_a_y_off_lvl3, s_XImats, s_vaf, s_vaf, static_cast<T>(1), static_cast<T>(0), seg_s_off_lvl3, S_sel_lvl3, s_temp, s_linalg_smem);
        // sync before a += MxS(v)*qd[S] 
        __syncthreads();
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 4; ind += blockDim.x*blockDim.y){
            // non-branching pointer selector
            int jid = (ind == 0) * 3 + (ind == 1) * 6 + (ind == 2) * 9 + (ind == 3) * 12;
            mxX_peq_scaled<T>(&s_vaf[78 + 6*jid], &s_vaf[6*jid], (((s_topology_helpers[18 + jid]) > 0 ? 1 : -1)) * s_qd[jid + 5], ((s_topology_helpers[18 + jid]) > 0 ? (s_topology_helpers[18 + jid]) - 1 : -(s_topology_helpers[18 + jid]) - 1));
        }
        __syncthreads();
        //
        // s_f in parallel given all v, a
        //
        // s_f[k] = I[k]*a[k] + fx(v[k])*I[k]*v[k]
        // start with s_f[k] = I[k]*a[k] and temp = *I[k]*v[k]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 156; ind += blockDim.x*blockDim.y){
            int row = ind % 6; int comp = ind / 6; int jid = comp % 13;
            bool IaFlag = comp == jid; int jid6 = 6*jid; int vaOffset = IaFlag * 78 + jid6;
            T *dst = IaFlag ? &s_vaf[156] : s_temp;
            // compute based on the branch and save Iv to temp to prep for fx(v)*Iv and then sync
            dst[jid6 + row] = dot_prod<T,6,6,1>(&s_XImats[468 + 6*jid6 + row], &s_vaf[vaOffset]);
        }
        __syncthreads();
        // finish with s_f[k] += fx(v[k])*Iv[k]
        for(int jid = threadIdx.x + threadIdx.y*blockDim.x; jid < 13; jid += blockDim.x*blockDim.y){
            int jid6 = 6*jid;
            fx_times_v_peq<T>(&s_vaf[156 + jid6], &s_vaf[jid6], &s_temp[jid6]);
            if (d_f_ext != nullptr) {
                for (int r = 0; r < 6; r++) { s_vaf[156 + jid6 + r] -= d_f_ext[jid6 + r]; }
            }
        }
        __syncthreads();
        //
        // Backward Pass
        //
        // s_f update where bfs_level is 3
        //     joints are: FL_calf_joint, FR_calf_joint, RL_calf_joint, RR_calf_joint
        //     links are: FL_calf, FR_calf, RL_calf, RR_calf
        // s_f[parent_k] += X[k]^T*f[k]
        grid_linalg_gemv<T,6,6,true>(&s_XImats[108], &s_vaf[174], &s_vaf[168], static_cast<T>(1), static_cast<T>(1));
        grid_linalg_gemv<T,6,6,true>(&s_XImats[216], &s_vaf[192], &s_vaf[186], static_cast<T>(1), static_cast<T>(1));
        grid_linalg_gemv<T,6,6,true>(&s_XImats[324], &s_vaf[210], &s_vaf[204], static_cast<T>(1), static_cast<T>(1));
        grid_linalg_gemv<T,6,6,true>(&s_XImats[432], &s_vaf[228], &s_vaf[222], static_cast<T>(1), static_cast<T>(1));
        // s_f update where bfs_level is 2
        //     joints are: FL_thigh_joint, FR_thigh_joint, RL_thigh_joint, RR_thigh_joint
        //     links are: FL_thigh, FR_thigh, RL_thigh, RR_thigh
        // s_f[parent_k] += X[k]^T*f[k]
        grid_linalg_gemv<T,6,6,true>(&s_XImats[72], &s_vaf[168], &s_vaf[162], static_cast<T>(1), static_cast<T>(1));
        grid_linalg_gemv<T,6,6,true>(&s_XImats[180], &s_vaf[186], &s_vaf[180], static_cast<T>(1), static_cast<T>(1));
        grid_linalg_gemv<T,6,6,true>(&s_XImats[288], &s_vaf[204], &s_vaf[198], static_cast<T>(1), static_cast<T>(1));
        grid_linalg_gemv<T,6,6,true>(&s_XImats[396], &s_vaf[222], &s_vaf[216], static_cast<T>(1), static_cast<T>(1));
        // s_f update where bfs_level is 1
        //     joints are: FL_hip_joint, FR_hip_joint, RL_hip_joint, RR_hip_joint
        //     links are: FL_hip, FR_hip, RL_hip, RR_hip
        // s_f[parent_k] += X[k]^T*f[k]
        grid_linalg_gemv<T,6,6,true>(&s_XImats[36], &s_vaf[162], &s_vaf[156], static_cast<T>(1), static_cast<T>(1));
        grid_linalg_gemv<T,6,6,true>(&s_XImats[144], &s_vaf[180], &s_vaf[156], static_cast<T>(1), static_cast<T>(1));
        grid_linalg_gemv<T,6,6,true>(&s_XImats[252], &s_vaf[198], &s_vaf[156], static_cast<T>(1), static_cast<T>(1));
        grid_linalg_gemv<T,6,6,true>(&s_XImats[360], &s_vaf[216], &s_vaf[156], static_cast<T>(1), static_cast<T>(1));
    }

    /**
     * Compute the RNEA (Recursive Newton-Euler Algorithm)
     *
     * Notes:
     *   Assumes the XI matricies have already been updated for the given q
     *   used to compute vaf as helper values
     *   optimized for qdd = 0
     *
     * @param s_vaf is a pointer to shared memory of size 3*6*NUM_JOINTS = 234
