        static const int seg_a_x_off_lvl2[4] = {84, 102, 120, 138};
        static const int seg_a_y_off_lvl2[4] = {90, 108, 126, 144};
        grid_linalg_segmented_row_strided_gemv<T,6,6,6>(4, seg_a_off_lvl2, seg_a_x_off_lvl2, seg_a_y_off_lvl2, s_XImats, s_vaf, s_vaf, static_cast<T>(1), static_cast<T>(0));
        // sync before a += MxS(v)*qd[S] 
