        __syncthreads();
        grid_linalg_segmented_row_strided_gemv<T,6,6,6,true>(4, seg_a_off_lvl3, seg_v_x_off_lvl3, seg_v_y_off_lvl3, s_XImats, s_vaf, s_vaf, static_cast<T>(1), static_cast<T>(0), seg_s_off_lvl3, S_sel_lvl3, s_temp, s_linalg_smem);
        static const int seg_a_x_off_lvl3[4] = {90, 108, 126, 144};
        static const int seg_a_y_off_lvl3[4] = {96, 114, 132, 150};
        grid_linalg_segmented_row_strided_gemv<T,6,6,6>(4, seg_a_off_lvl3, seg_a_x_off_lvl3, seg_a_y_off_lvl3, s_XImats, s_vaf, s_vaf, static_cast<T>(1), static_cast<T>(0));
