            fx_times_v_peq<T>(&s_vaf[156 + jid6], &s_vaf[jid6], &s_temp[jid6]);
            if (d_f_ext != nullptr) {
                for (int r = 0; r < 6; r++) { s_vaf[156 + jid6 + r] -= d_f_ext[jid6 + r]; }
            }
        }
        __syncthreads();
        //
        // Backward Pass
        //
        // s_f update where bfs_level is 3
        //     joints are: FL_calf_joint, FR_calf_joint, RL_calf_joint, RR_calf_joint
        //     links are: FL_calf, FR_calf, RL_calf, RR_calf
        // s_f[parent_k] += X[k]^T*f[k]
        grid_linalg_gemv<T,6,6,true>(&s_XImats[108], &s_vaf[174], &s_vaf[168], static_cast<T>(1), static_cast<T>(1));
        grid_linalg_gemv<T,6,6,true>(&s_XImats[216], &s_vaf[192], &s_vaf[186], static_cast<T>(1), static_cast<T>(1));
        grid_linalg_gemv<T,6,6,true>(&s_XImats[324], &s_vaf[210], &s_vaf[204], static_cast<T>(1), static_cast<T>(1));
        grid_linalg_gemv<T,6,6,true>(&s_XImats[432], &s_vaf[228], &s_vaf[222], static_cast<T>(1), static_cast<T>(1));
