    /**
     * Compute the inverse of the mass matrix
     *
     * Notes:
     *   CALLER CONTRACT (direct *_inner callers): s_XImats must ALREADY be populated for the current s_q (READ-only here) via load_update_XImats_helpers(...) + __syncthreads(), and s_temp MUST be MINV_INNER_SMEM_BYTES<T, F_IN_SMEM>() bytes -- at F_IN_SMEM=true the 6*NV*NV F-band lives in the TAIL of s_temp (d_workspace=0/nullptr does NOT mean the band is free). Under-populating XImats or under-sizing s_temp reads never-written shared -> NaN (race-clean, DoF-specific since the band scales as 6*NV*NV). Prefer minv_device, which handles both.
     *   Outputs a SYMMETRIC_UPPER triangular matrix for Minv
     *   Inner-controlled placement: F_IN_SMEM selects where the 6*NV*NV F-region lives.
     *     true  -> tail of s_temp (shared; fastest, default).  false -> d_workspace (global).
     *   The choice is made at the top of this fn so the caller just sizes both arenas from
     *   the MINV_INNER_*_BYTES constants and hands both pointers in. Codegen maps each
     *   RESOURCE_TIER to an F_IN_SMEM value per robot (MINV_F_IN_SMEM<TIER>()).
     *
     * @param s_Minv is a pointer to memory for the final result
     * @param s_q is the vector of joint positions
     * @param s_temp is the (shared) scratch; size MINV_INNER_SMEM_BYTES<T, F_IN_SMEM>() (= 1093 always, plus the 1944-float F-region when F_IN_SMEM)
     * @param s_XImats is the (shared) memory holding the updated XI matricies for the given s_q
     * @param s_topology_helpers is the (shared) memory location for the topology_helpers (nullptr/unused for serial chains with identical Ss)
     * @param d_workspace is the global scratch; size MINV_INNER_WORKSPACE_BYTES<T, F_IN_SMEM>() (= 1944 when !F_IN_SMEM, else 0). Pass nullptr when F_IN_SMEM
     */
    template <typename T, bool F_IN_SMEM = true>
    __device__ __forceinline__
    void minv_inner(T *s_Minv, const T *s_q, T *s_XImats, int *s_topology_helpers, T *s_temp, T *d_workspace) {
        unsigned char *s_linalg_smem = nullptr;
        T *s_F;
        if constexpr (F_IN_SMEM) { s_F = &s_temp[1093]; (void)d_workspace; }
        else { s_F = d_workspace; }
        // T *s_F (param) [size 6*NV*NV]; T *s_IA = &s_temp[0]; T *s_U = &s_temp[648]; T *s_Dinv = &s_temp[756]; T *s_Ia = &s_temp[805]; T *s_IaTemp = &s_temp[949];
        // Initialize IA = I
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 468; ind += blockDim.x*blockDim.y){
            s_temp[0 + ind] = s_XImats[468 + ind];
        }
        // Zero Minv and F
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 2268; ind += blockDim.x*blockDim.y){
            if(ind < 1944){s_F[0 + ind] = static_cast<T>(0);}
            else{s_Minv[ind - 1944] = static_cast<T>(0);}
        }
        __syncthreads();
        //
        // Backward Pass
        //
        // backward pass updates where bfs_level is 3
        //     joints are: FL_calf_joint, FR_calf_joint, RL_calf_joint, RR_calf_joint
        //     links are: FL_calf, FR_calf, RL_calf, RR_calf
        // U = IA*S, D = S^T*U, DInv = 1/D, Minv[i,i] = Dinv
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 24; ind += blockDim.x*blockDim.y){
            int row = ind % 6;
            // non-branching pointer selector
            int jid = (ind < 6) * 3 + (ind < 12 && ind >= 6) * 6 + (ind < 18 && ind >= 12) * 9 + (ind >= 18) * 12;
            int jid6 = 6*jid;
            s_temp[648 + jid6 + row] = (((s_topology_helpers[18 + jid]) > 0 ? 1 : -1)) * s_temp[0 + 6*jid6 + 6*((s_topology_helpers[18 + jid]) > 0 ? (s_topology_helpers[18 + jid]) - 1 : -(s_topology_helpers[18 + jid]) - 1) + row];
            if(row == ((s_topology_helpers[18 + jid]) > 0 ? (s_topology_helpers[18 + jid]) - 1 : -(s_topology_helpers[18 + jid]) - 1)){
                s_temp[756 + jid] = static_cast<T>(1)/((((s_topology_helpers[18 + jid]) > 0 ? 1 : -1)) * s_temp[648 + jid6 + ((s_topology_helpers[18 + jid]) > 0 ? (s_topology_helpers[18 + jid]) - 1 : -(s_topology_helpers[18 + jid]) - 1)]);
                s_Minv[19 * (jid + 5)] = s_temp[756 + jid];
            }
        }
        __syncthreads();
        // Minv[i,subTreeInds] -= Dinv*F[i,Srow,SubTreeInds]
        // Temp Comp: F[i,:,subTreeInds] += U*Minv[i,subTreeInds] - to start Fparent Update
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 4; ind += blockDim.x*blockDim.y){
            // non-branching pointer selector
            int jid = (ind < 1) * 3 + (ind < 2 && ind >= 1) * 6 + (ind < 3 && ind >= 2) * 9 + (ind >= 3) * 12;
            int subTreeAdj = (ind < 1) * 0 + (ind < 2 && ind >= 1) * 1 + (ind < 3 && ind >= 2) * 2 + (ind >= 3) * 3;
            int jid_subtree = (jid + 5) + (ind - subTreeAdj); int jid_subtree6 = 6*jid_subtree; int jid_subtreeN = 18*jid_subtree;
            s_Minv[jid_subtreeN + (jid + 5)] -= s_temp[756 + jid] * (((s_topology_helpers[18 + jid]) > 0 ? 1 : -1)) * s_F[0 + 108*(jid + 5) + jid_subtree6 + ((s_topology_helpers[18 + jid]) > 0 ? (s_topology_helpers[18 + jid]) - 1 : -(s_topology_helpers[18 + jid]) - 1)];
            for(int row = 0; row < 6; row++) {
                s_F[0 + 108*(jid + 5) + jid_subtree6 + row] += s_temp[648 + 6*jid + row] * s_Minv[jid_subtreeN + (jid + 5)];
            }
        }
        // Ia = IA - U^T Dinv U | to start IAparent Update
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 144; ind += blockDim.x*blockDim.y){
            // non-branching pointer selector
            int jid = (ind < 36) * 3 + (ind < 72 && ind >= 36) * 6 + (ind < 108 && ind >= 72) * 9 + (ind >= 108) * 12;
            int ind36 = (ind % 36); int row = ind36 % 6; int col = ind36 / 6; int jid6 = 6*jid;
            s_temp[805 + ind] = s_temp[0 + 6*jid6 + ind36] - (s_temp[648 + jid6 + row] * s_temp[756 + jid] * s_temp[648 + jid6 + col]);
        }
        __syncthreads();
        // F[parent_ind,:,subTreeInds] += Xmat^T * F[ind,:,subTreeInds]
        // IA_Update_Temp = Xmat^T * Ia | for IAparent Update
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 168; ind += blockDim.x*blockDim.y){
            int row = ind % 6; int col = ind / 6;
            // non-branching pointer selector
            int jid = (col < 1) * 3 + (col < 2 && col >= 1) * 6 + (col < 3 && col >= 2) * 9 + (col >= 3) * 12;
            int subTreeAdj = (col < 1) * 0 + (col < 2 && col >= 1) * 1 + (col < 3 && col >= 2) * 2 + (col >= 3) * 3;
            int jid_subtree = (jid + 5) + (col - subTreeAdj);
            T *src = &s_F[0 + 108*(jid + 5) + 6*jid_subtree]; T *dst = &s_F[0 + 108*(5 + s_topology_helpers[jid]) + 6*jid_subtree];
            // adjust for temp comps
            if (col >= 4) {
                col -= 4; src = &s_temp[805 + 6*col]; dst = &s_temp[949 + 6*col];
                int jid_selector = col / 6;
                // non-branching pointer selector
                jid = (jid_selector == 0) * 3 + (jid_selector == 1) * 6 + (jid_selector == 2) * 9 + (jid_selector == 3) * 12;
            }
            dst[row] = dot_prod<T,6,1,1>(&s_XImats[36*jid + 6*row],src);
        }
        __syncthreads();
        // IA[parent_ind] += IA_Update_Temp * Xmat
        grid_linalg_gemm<T,6,6,6>(&s_temp[949], &s_XImats[108], &s_temp[72], static_cast<T>(1), static_cast<T>(1), s_linalg_smem);
        grid_linalg_gemm<T,6,6,6>(&s_temp[985], &s_XImats[216], &s_temp[180], static_cast<T>(1), static_cast<T>(1), s_linalg_smem);
        grid_linalg_gemm<T,6,6,6>(&s_temp[1021], &s_XImats[324], &s_temp[288], static_cast<T>(1), static_cast<T>(1), s_linalg_smem);
        grid_linalg_gemm<T,6,6,6>(&s_temp[1057], &s_XImats[432], &s_temp[396], static_cast<T>(1), static_cast<T>(1), s_linalg_smem);
        // backward pass updates where bfs_level is 2
        //     joints are: FL_thigh_joint, FR_thigh_joint, RL_thigh_joint, RR_thigh_joint
        //     links are: FL_thigh, FR_thigh, RL_thigh, RR_thigh
        // U = IA*S, D = S^T*U, DInv = 1/D, Minv[i,i] = Dinv
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 24; ind += blockDim.x*blockDim.y){
            int row = ind % 6;
            // non-branching pointer selector
            int jid = (ind < 6) * 2 + (ind < 12 && ind >= 6) * 5 + (ind < 18 && ind >= 12) * 8 + (ind >= 18) * 11;
            int jid6 = 6*jid;
            s_temp[648 + jid6 + row] = (((s_topology_helpers[18 + jid]) > 0 ? 1 : -1)) * s_temp[0 + 6*jid6 + 6*((s_topology_helpers[18 + jid]) > 0 ? (s_topology_helpers[18 + jid]) - 1 : -(s_topology_helpers[18 + jid]) - 1) + row];
            if(row == ((s_topology_helpers[18 + jid]) > 0 ? (s_topology_helpers[18 + jid]) - 1 : -(s_topology_helpers[18 + jid]) - 1)){
                s_temp[756 + jid] = static_cast<T>(1)/((((s_topology_helpers[18 + jid]) > 0 ? 1 : -1)) * s_temp[648 + jid6 + ((s_topology_helpers[18 + jid]) > 0 ? (s_topology_helpers[18 + jid]) - 1 : -(s_topology_helpers[18 + jid]) - 1)]);
                s_Minv[19 * (jid + 5)] = s_temp[756 + jid];
            }
        }
        __syncthreads();
        // Minv[i,subTreeInds] -= Dinv*F[i,Srow,SubTreeInds]
        // Temp Comp: F[i,:,subTreeInds] += U*Minv[i,subTreeInds] - to start Fparent Update
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 8; ind += blockDim.x*blockDim.y){
            // non-branching pointer selector
            int jid = (ind < 2) * 2 + (ind < 4 && ind >= 2) * 5 + (ind < 6 && ind >= 4) * 8 + (ind >= 6) * 11;
            int subTreeAdj = (ind < 2) * 0 + (ind < 4 && ind >= 2) * 2 + (ind < 6 && ind >= 4) * 4 + (ind >= 6) * 6;
            int jid_subtree = (jid + 5) + (ind - subTreeAdj); int jid_subtree6 = 6*jid_subtree; int jid_subtreeN = 18*jid_subtree;
            s_Minv[jid_subtreeN + (jid + 5)] -= s_temp[756 + jid] * (((s_topology_helpers[18 + jid]) > 0 ? 1 : -1)) * s_F[0 + 108*(jid + 5) + jid_subtree6 + ((s_topology_helpers[18 + jid]) > 0 ? (s_topology_helpers[18 + jid]) - 1 : -(s_topology_helpers[18 + jid]) - 1)];
            for(int row = 0; row < 6; row++) {
                s_F[0 + 108*(jid + 5) + jid_subtree6 + row] += s_temp[648 + 6*jid + row] * s_Minv[jid_subtreeN + (jid + 5)];
            }
        }
        // Ia = IA - U^T Dinv U | to start IAparent Update
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 144; ind += blockDim.x*blockDim.y){
            // non-branching pointer selector
            int jid = (ind < 36) * 2 + (ind < 72 && ind >= 36) * 5 + (ind < 108 && ind >= 72) * 8 + (ind >= 108) * 11;
            int ind36 = (ind % 36); int row = ind36 % 6; int col = ind36 / 6; int jid6 = 6*jid;
            s_temp[805 + ind] = s_temp[0 + 6*jid6 + ind36] - (s_temp[648 + jid6 + row] * s_temp[756 + jid] * s_temp[648 + jid6 + col]);
        }
        __syncthreads();
        // F[parent_ind,:,subTreeInds] += Xmat^T * F[ind,:,subTreeInds]
        // IA_Update_Temp = Xmat^T * Ia | for IAparent Update
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 192; ind += blockDim.x*blockDim.y){
            int row = ind % 6; int col = ind / 6;
            // non-branching pointer selector
            int jid = (col < 2) * 2 + (col < 4 && col >= 2) * 5 + (col < 6 && col >= 4) * 8 + (col >= 6) * 11;
            int subTreeAdj = (col < 2) * 0 + (col < 4 && col >= 2) * 2 + (col < 6 && col >= 4) * 4 + (col >= 6) * 6;
            int jid_subtree = (jid + 5) + (col - subTreeAdj);
            T *src = &s_F[0 + 108*(jid + 5) + 6*jid_subtree]; T *dst = &s_F[0 + 108*(5 + s_topology_helpers[jid]) + 6*jid_subtree];
            // adjust for temp comps
            if (col >= 8) {
                col -= 8; src = &s_temp[805 + 6*col]; dst = &s_temp[949 + 6*col];
                int jid_selector = col / 6;
                // non-branching pointer selector
                jid = (jid_selector == 0) * 2 + (jid_selector == 1) * 5 + (jid_selector == 2) * 8 + (jid_selector == 3) * 11;
            }
            dst[row] = dot_prod<T,6,1,1>(&s_XImats[36*jid + 6*row],src);
        }
        __syncthreads();
        // IA[parent_ind] += IA_Update_Temp * Xmat
        grid_linalg_gemm<T,6,6,6>(&s_temp[949], &s_XImats[72], &s_temp[36], static_cast<T>(1), static_cast<T>(1), s_linalg_smem);
        grid_linalg_gemm<T,6,6,6>(&s_temp[985], &s_XImats[180], &s_temp[144], static_cast<T>(1), static_cast<T>(1), s_linalg_smem);
        grid_linalg_gemm<T,6,6,6>(&s_temp[1021], &s_XImats[288], &s_temp[252], static_cast<T>(1), static_cast<T>(1), s_linalg_smem);
        grid_linalg_gemm<T,6,6,6>(&s_temp[1057], &s_XImats[396], &s_temp[360], static_cast<T>(1), static_cast<T>(1), s_linalg_smem);
        // backward pass updates where bfs_level is 1
        //     joints are: FL_hip_joint, FR_hip_joint, RL_hip_joint, RR_hip_joint
        //     links are: FL_hip, FR_hip, RL_hip, RR_hip
        // U = IA*S, D = S^T*U, DInv = 1/D, Minv[i,i] = Dinv
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 24; ind += blockDim.x*blockDim.y){
            int row = ind % 6;
            // non-branching pointer selector
            int jid = (ind < 6) * 1 + (ind < 12 && ind >= 6) * 4 + (ind < 18 && ind >= 12) * 7 + (ind >= 18) * 10;
            int jid6 = 6*jid;
            s_temp[648 + jid6 + row] = (((s_topology_helpers[18 + jid]) > 0 ? 1 : -1)) * s_temp[0 + 6*jid6 + 6*((s_topology_helpers[18 + jid]) > 0 ? (s_topology_helpers[18 + jid]) - 1 : -(s_topology_helpers[18 + jid]) - 1) + row];
            if(row == ((s_topology_helpers[18 + jid]) > 0 ? (s_topology_helpers[18 + jid]) - 1 : -(s_topology_helpers[18 + jid]) - 1)){
                s_temp[756 + jid] = static_cast<T>(1)/((((s_topology_helpers[18 + jid]) > 0 ? 1 : -1)) * s_temp[648 + jid6 + ((s_topology_helpers[18 + jid]) > 0 ? (s_topology_helpers[18 + jid]) - 1 : -(s_topology_helpers[18 + jid]) - 1)]);
                s_Minv[19 * (jid + 5)] = s_temp[756 + jid];
            }
        }
        __syncthreads();
        // Minv[i,subTreeInds] -= Dinv*F[i,Srow,SubTreeInds]
        // Temp Comp: F[i,:,subTreeInds] += U*Minv[i,subTreeInds] - to start Fparent Update
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 12; ind += blockDim.x*blockDim.y){
            // non-branching pointer selector
            int jid = (ind < 3) * 1 + (ind < 6 && ind >= 3) * 4 + (ind < 9 && ind >= 6) * 7 + (ind >= 9) * 10;
            int subTreeAdj = (ind < 3) * 0 + (ind < 6 && ind >= 3) * 3 + (ind < 9 && ind >= 6) * 6 + (ind >= 9) * 9;
            int jid_subtree = (jid + 5) + (ind - subTreeAdj); int jid_subtree6 = 6*jid_subtree; int jid_subtreeN = 18*jid_subtree;
            s_Minv[jid_subtreeN + (jid + 5)] -= s_temp[756 + jid] * (((s_topology_helpers[18 + jid]) > 0 ? 1 : -1)) * s_F[0 + 108*(jid + 5) + jid_subtree6 + ((s_topology_helpers[18 + jid]) > 0 ? (s_topology_helpers[18 + jid]) - 1 : -(s_topology_helpers[18 + jid]) - 1)];
            for(int row = 0; row < 6; row++) {
                s_F[0 + 108*(jid + 5) + jid_subtree6 + row] += s_temp[648 + 6*jid + row] * s_Minv[jid_subtreeN + (jid + 5)];
            }
        }
        // Ia = IA - U^T Dinv U | to start IAparent Update
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 144; ind += blockDim.x*blockDim.y){
            // non-branching pointer selector
            int jid = (ind < 36) * 1 + (ind < 72 && ind >= 36) * 4 + (ind < 108 && ind >= 72) * 7 + (ind >= 108) * 10;
            int ind36 = (ind % 36); int row = ind36 % 6; int col = ind36 / 6; int jid6 = 6*jid;
            s_temp[805 + ind] = s_temp[0 + 6*jid6 + ind36] - (s_temp[648 + jid6 + row] * s_temp[756 + jid] * s_temp[648 + jid6 + col]);
        }
        __syncthreads();
        // F[parent_ind,:,subTreeInds] += Xmat^T * F[ind,:,subTreeInds]
        // IA_Update_Temp = Xmat^T * Ia | for IAparent Update
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 216; ind += blockDim.x*blockDim.y){
            int row = ind % 6; int col = ind / 6;
            // non-branching pointer selector
            int jid = (col < 3) * 1 + (col < 6 && col >= 3) * 4 + (col < 9 && col >= 6) * 7 + (col >= 9) * 10;
            int subTreeAdj = (col < 3) * 0 + (col < 6 && col >= 3) * 3 + (col < 9 && col >= 6) * 6 + (col >= 9) * 9;
            int jid_subtree = (jid + 5) + (col - subTreeAdj);
            T *src = &s_F[0 + 108*(jid + 5) + 6*jid_subtree]; T *dst = &s_F[0 + 108*(5 + s_topology_helpers[jid]) + 6*jid_subtree];
            // adjust for temp comps
            if (col >= 12) {
                col -= 12; src = &s_temp[805 + 6*col]; dst = &s_temp[949 + 6*col];
                int jid_selector = col / 6;
                // non-branching pointer selector
                jid = (jid_selector == 0) * 1 + (jid_selector == 1) * 4 + (jid_selector == 2) * 7 + (jid_selector == 3) * 10;
            }
            dst[row] = dot_prod<T,6,1,1>(&s_XImats[36*jid + 6*row],src);
        }
        __syncthreads();
        // IA[parent_ind] += IA_Update_Temp * Xmat
        // deterministic parent-major fixed-order sum (shared parent): IA[parent] += sum_slot IA_Update_Temp[slot] * X[jid_slot]
        {
            static const int s_jid_lvl[] = { 1, 4, 7, 10 };
            static const int s_par_lvl[] = { 0, 0, 0, 0 };
            static const int s_upar_lvl[] = { 0 };
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 36; ind += blockDim.x*blockDim.y){
                int up = ind / 36; int rc = ind % 36;
                int col_max6 = rc / 6; int row = rc % 6;
                int par_l = s_upar_lvl[up];
                T acc = static_cast<T>(0);
                for (int slot = 0; slot < 4; slot++) { if (s_par_lvl[slot] != par_l) continue;
                    T * src = &s_temp[949 + 36*slot + row];
                    acc += dot_prod<T,6,6,1>(src,&s_XImats[36*s_jid_lvl[slot] + 6*col_max6]); }
                s_temp[0 + 36*par_l + 6*col_max6 + row] += acc;
            }
            __syncthreads();
        }
        // backward pass updates where bfs_level is 0
        //     joints are: floating_base_joint
        //     links are: base
        // U = IA*S = IA, D = S^T*U = U = IA => Minv[:6, :6] = IA^{-1}
        invert_matrix(6, &s_temp[0], &s_temp[769], &s_temp[949]);
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 36; ind += blockDim.x*blockDim.y){
            int row = ind % 6, col = ind / 6;
            s_Minv[col*18+row] = s_temp[769+ind];
        }
        __syncthreads();
        // Minv[i,subTreeInds] -= Dinv*F[i,Srow,SubTreeInds]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 72; ind += blockDim.x*blockDim.y){
            int row = ind % 6, col = ind / 6;
            s_Minv[(6+col)*18+row] -= dot_prod<T,6,1,1>(&s_temp[769+6*row], &s_F[576+6*col]);
        }
        __syncthreads();
        //
        // Forward Pass
        //   Note that due to the i: operation we need to go serially over all n
        //
        // forward pass for jid: 0
        // F[i,:,i:] = S * Minv[i,i:] as parent is base so rest is skipped
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 108; ind += blockDim.x*blockDim.y){
            int row = ind % 6; int col = ind / 6;
            s_F[ind] = s_Minv[row + 18 * col];
        }
        __syncthreads();
        // forward pass for jid: 1
        // Minv[i,i:] -= Dinv*U^T*Xmat*F[parent,:,i:] across cols i...N
        // F[i,:,i:] = S * Minv[i,i:] + Xmat*F[parent,:,i:] across cols i...N
        //   Per column: F[i,:,col]=Xmat*F[parent,:,col], then
        //   Minv[i,col]-=Dinv*U^T*F[i,:,col] and F[i,Srow,col]+=S*Minv[i,col]
        for(int c = threadIdx.x + threadIdx.y*blockDim.x; c < 17; c += blockDim.x*blockDim.y){
            int col_ind = c + 1;
            T *s_Fcol = &s_F[108 + 6*col_ind];
            T *s_Fpcol = &s_F[0 + 6*col_ind];
            for (int row = 0; row < 6; row++) {
                s_Fcol[row] = dot_prod<T,6,6,1>(&s_XImats[36 + row], s_Fpcol);
            }
            if (c >= 5) {
                s_Minv[18 * col_ind + 6] -= s_temp[757] * dot_prod<T,6,1,1>(s_Fcol,&s_temp[654]);
                s_Fcol[0] += (1) * s_Minv[18 * col_ind + 6];
            }
        }
        __syncthreads();
        // forward pass for jid: 2
        // Minv[i,i:] -= Dinv*U^T*Xmat*F[parent,:,i:] across cols i...N
        // F[i,:,i:] = S * Minv[i,i:] + Xmat*F[parent,:,i:] across cols i...N
        //   Per column: F[i,:,col]=Xmat*F[parent,:,col], then
        //   Minv[i,col]-=Dinv*U^T*F[i,:,col] and F[i,Srow,col]+=S*Minv[i,col]
        for(int c = threadIdx.x + threadIdx.y*blockDim.x; c < 16; c += blockDim.x*blockDim.y){
            int col_ind = c + 2;
            T *s_Fcol = &s_F[216 + 6*col_ind];
            T *s_Fpcol = &s_F[108 + 6*col_ind];
            for (int row = 0; row < 6; row++) {
                s_Fcol[row] = dot_prod<T,6,6,1>(&s_XImats[72 + row], s_Fpcol);
            }
            if (c >= 5) {
                s_Minv[18 * col_ind + 7] -= s_temp[758] * dot_prod<T,6,1,1>(s_Fcol,&s_temp[660]);
                s_Fcol[1] += (1) * s_Minv[18 * col_ind + 7];
            }
        }
        __syncthreads();
        // forward pass for jid: 3
        // Minv[i,i:] -= Dinv*U^T*Xmat*F[parent,:,i:] across cols i...N
        // F[i,:,i:] = S * Minv[i,i:] + Xmat*F[parent,:,i:] across cols i...N
        //   Per column: F[i,:,col]=Xmat*F[parent,:,col], then
        //   Minv[i,col]-=Dinv*U^T*F[i,:,col] and F[i,Srow,col]+=S*Minv[i,col]
        for(int c = threadIdx.x + threadIdx.y*blockDim.x; c < 15; c += blockDim.x*blockDim.y){
            int col_ind = c + 3;
            T *s_Fcol = &s_F[324 + 6*col_ind];
            T *s_Fpcol = &s_F[216 + 6*col_ind];
            for (int row = 0; row < 6; row++) {
                s_Fcol[row] = dot_prod<T,6,6,1>(&s_XImats[108 + row], s_Fpcol);
            }
            if (c >= 5) {
                s_Minv[18 * col_ind + 8] -= s_temp[759] * dot_prod<T,6,1,1>(s_Fcol,&s_temp[666]);
                s_Fcol[1] += (1) * s_Minv[18 * col_ind + 8];
            }
        }
        __syncthreads();
        // forward pass for jid: 4
        // Minv[i,i:] -= Dinv*U^T*Xmat*F[parent,:,i:] across cols i...N
        // F[i,:,i:] = S * Minv[i,i:] + Xmat*F[parent,:,i:] across cols i...N
        //   Per column: F[i,:,col]=Xmat*F[parent,:,col], then
        //   Minv[i,col]-=Dinv*U^T*F[i,:,col] and F[i,Srow,col]+=S*Minv[i,col]
        for(int c = threadIdx.x + threadIdx.y*blockDim.x; c < 14; c += blockDim.x*blockDim.y){
            int col_ind = c + 4;
            T *s_Fcol = &s_F[432 + 6*col_ind];
            T *s_Fpcol = &s_F[0 + 6*col_ind];
            for (int row = 0; row < 6; row++) {
                s_Fcol[row] = dot_prod<T,6,6,1>(&s_XImats[144 + row], s_Fpcol);
            }
            if (c >= 5) {
                s_Minv[18 * col_ind + 9] -= s_temp[760] * dot_prod<T,6,1,1>(s_Fcol,&s_temp[672]);
                s_Fcol[0] += (1) * s_Minv[18 * col_ind + 9];
            }
        }
        __syncthreads();
        // forward pass for jid: 5
        // Minv[i,i:] -= Dinv*U^T*Xmat*F[parent,:,i:] across cols i...N
        // F[i,:,i:] = S * Minv[i,i:] + Xmat*F[parent,:,i:] across cols i...N
        //   Per column: F[i,:,col]=Xmat*F[parent,:,col], then
        //   Minv[i,col]-=Dinv*U^T*F[i,:,col] and F[i,Srow,col]+=S*Minv[i,col]
        for(int c = threadIdx.x + threadIdx.y*blockDim.x; c < 13; c += blockDim.x*blockDim.y){
            int col_ind = c + 5;
            T *s_Fcol = &s_F[540 + 6*col_ind];
            T *s_Fpcol = &s_F[432 + 6*col_ind];
            for (int row = 0; row < 6; row++) {
                s_Fcol[row] = dot_prod<T,6,6,1>(&s_XImats[180 + row], s_Fpcol);
            }
            if (c >= 5) {
                s_Minv[18 * col_ind + 10] -= s_temp[761] * dot_prod<T,6,1,1>(s_Fcol,&s_temp[678]);
                s_Fcol[1] += (1) * s_Minv[18 * col_ind + 10];
            }
        }
        __syncthreads();
        // forward pass for jid: 6
        // Minv[i,i:] -= Dinv*U^T*Xmat*F[parent,:,i:] across cols i...N
        // F[i,:,i:] = S * Minv[i,i:] + Xmat*F[parent,:,i:] across cols i...N
        //   Per column: F[i,:,col]=Xmat*F[parent,:,col], then
        //   Minv[i,col]-=Dinv*U^T*F[i,:,col] and F[i,Srow,col]+=S*Minv[i,col]
        for(int c = threadIdx.x + threadIdx.y*blockDim.x; c < 12; c += blockDim.x*blockDim.y){
            int col_ind = c + 6;
            T *s_Fcol = &s_F[648 + 6*col_ind];
            T *s_Fpcol = &s_F[540 + 6*col_ind];
            for (int row = 0; row < 6; row++) {
                s_Fcol[row] = dot_prod<T,6,6,1>(&s_XImats[216 + row], s_Fpcol);
            }
            if (c >= 5) {
                s_Minv[18 * col_ind + 11] -= s_temp[762] * dot_prod<T,6,1,1>(s_Fcol,&s_temp[684]);
                s_Fcol[1] += (1) * s_Minv[18 * col_ind + 11];
            }
        }
        __syncthreads();
        // forward pass for jid: 7
        // Minv[i,i:] -= Dinv*U^T*Xmat*F[parent,:,i:] across cols i...N
        // F[i,:,i:] = S * Minv[i,i:] + Xmat*F[parent,:,i:] across cols i...N
        //   Per column: F[i,:,col]=Xmat*F[parent,:,col], then
        //   Minv[i,col]-=Dinv*U^T*F[i,:,col] and F[i,Srow,col]+=S*Minv[i,col]
        for(int c = threadIdx.x + threadIdx.y*blockDim.x; c < 11; c += blockDim.x*blockDim.y){
            int col_ind = c + 7;
            T *s_Fcol = &s_F[756 + 6*col_ind];
            T *s_Fpcol = &s_F[0 + 6*col_ind];
            for (int row = 0; row < 6; row++) {
                s_Fcol[row] = dot_prod<T,6,6,1>(&s_XImats[252 + row], s_Fpcol);
            }
            if (c >= 5) {
                s_Minv[18 * col_ind + 12] -= s_temp[763] * dot_prod<T,6,1,1>(s_Fcol,&s_temp[690]);
                s_Fcol[0] += (1) * s_Minv[18 * col_ind + 12];
            }
        }
        __syncthreads();
        // forward pass for jid: 8
        // Minv[i,i:] -= Dinv*U^T*Xmat*F[parent,:,i:] across cols i...N
        // F[i,:,i:] = S * Minv[i,i:] + Xmat*F[parent,:,i:] across cols i...N
        //   Per column: F[i,:,col]=Xmat*F[parent,:,col], then
        //   Minv[i,col]-=Dinv*U^T*F[i,:,col] and F[i,Srow,col]+=S*Minv[i,col]
        for(int c = threadIdx.x + threadIdx.y*blockDim.x; c < 10; c += blockDim.x*blockDim.y){
            int col_ind = c + 8;
            T *s_Fcol = &s_F[864 + 6*col_ind];
            T *s_Fpcol = &s_F[756 + 6*col_ind];
            for (int row = 0; row < 6; row++) {
                s_Fcol[row] = dot_prod<T,6,6,1>(&s_XImats[288 + row], s_Fpcol);
            }
            if (c >= 5) {
                s_Minv[18 * col_ind + 13] -= s_temp[764] * dot_prod<T,6,1,1>(s_Fcol,&s_temp[696]);
                s_Fcol[1] += (1) * s_Minv[18 * col_ind + 13];
            }
        }
        __syncthreads();
        // forward pass for jid: 9
        // Minv[i,i:] -= Dinv*U^T*Xmat*F[parent,:,i:] across cols i...N
        // F[i,:,i:] = S * Minv[i,i:] + Xmat*F[parent,:,i:] across cols i...N
        //   Per column: F[i,:,col]=Xmat*F[parent,:,col], then
        //   Minv[i,col]-=Dinv*U^T*F[i,:,col] and F[i,Srow,col]+=S*Minv[i,col]
        for(int c = threadIdx.x + threadIdx.y*blockDim.x; c < 9; c += blockDim.x*blockDim.y){
            int col_ind = c + 9;
            T *s_Fcol = &s_F[972 + 6*col_ind];
            T *s_Fpcol = &s_F[864 + 6*col_ind];
            for (int row = 0; row < 6; row++) {
                s_Fcol[row] = dot_prod<T,6,6,1>(&s_XImats[324 + row], s_Fpcol);
            }
            if (c >= 5) {
                s_Minv[18 * col_ind + 14] -= s_temp[765] * dot_prod<T,6,1,1>(s_Fcol,&s_temp[702]);
                s_Fcol[1] += (1) * s_Minv[18 * col_ind + 14];
            }
        }
        __syncthreads();
        // forward pass for jid: 10
        // Minv[i,i:] -= Dinv*U^T*Xmat*F[parent,:,i:] across cols i...N
        // F[i,:,i:] = S * Minv[i,i:] + Xmat*F[parent,:,i:] across cols i...N
        //   Per column: F[i,:,col]=Xmat*F[parent,:,col], then
        //   Minv[i,col]-=Dinv*U^T*F[i,:,col] and F[i,Srow,col]+=S*Minv[i,col]
        for(int c = threadIdx.x + threadIdx.y*blockDim.x; c < 8; c += blockDim.x*blockDim.y){
            int col_ind = c + 10;
            T *s_Fcol = &s_F[1080 + 6*col_ind];
            T *s_Fpcol = &s_F[0 + 6*col_ind];
            for (int row = 0; row < 6; row++) {
                s_Fcol[row] = dot_prod<T,6,6,1>(&s_XImats[360 + row], s_Fpcol);
            }
            if (c >= 5) {
                s_Minv[18 * col_ind + 15] -= s_temp[766] * dot_prod<T,6,1,1>(s_Fcol,&s_temp[708]);
                s_Fcol[0] += (1) * s_Minv[18 * col_ind + 15];
            }
        }
        __syncthreads();
        // forward pass for jid: 11
        // Minv[i,i:] -= Dinv*U^T*Xmat*F[parent,:,i:] across cols i...N
        // F[i,:,i:] = S * Minv[i,i:] + Xmat*F[parent,:,i:] across cols i...N
        //   Per column: F[i,:,col]=Xmat*F[parent,:,col], then
        //   Minv[i,col]-=Dinv*U^T*F[i,:,col] and F[i,Srow,col]+=S*Minv[i,col]
        for(int c = threadIdx.x + threadIdx.y*blockDim.x; c < 7; c += blockDim.x*blockDim.y){
            int col_ind = c + 11;
            T *s_Fcol = &s_F[1188 + 6*col_ind];
            T *s_Fpcol = &s_F[1080 + 6*col_ind];
            for (int row = 0; row < 6; row++) {
                s_Fcol[row] = dot_prod<T,6,6,1>(&s_XImats[396 + row], s_Fpcol);
            }
            if (c >= 5) {
                s_Minv[18 * col_ind + 16] -= s_temp[767] * dot_prod<T,6,1,1>(s_Fcol,&s_temp[714]);
                s_Fcol[1] += (1) * s_Minv[18 * col_ind + 16];
            }
        }
        __syncthreads();
        // forward pass for jid: 12
        // Minv[i,i:] -= Dinv*U^T*Xmat*F[parent,:,i:] across cols i...N
        // F[i,:,i:] = S * Minv[i,i:] + Xmat*F[parent,:,i:] across cols i...N
        //   Per column: F[i,:,col]=Xmat*F[parent,:,col], then
        //   Minv[i,col]-=Dinv*U^T*F[i,:,col] and F[i,Srow,col]+=S*Minv[i,col]
        for(int c = threadIdx.x + threadIdx.y*blockDim.x; c < 6; c += blockDim.x*blockDim.y){
            int col_ind = c + 12;
            T *s_Fcol = &s_F[1296 + 6*col_ind];
            T *s_Fpcol = &s_F[1188 + 6*col_ind];
            for (int row = 0; row < 6; row++) {
                s_Fcol[row] = dot_prod<T,6,6,1>(&s_XImats[432 + row], s_Fpcol);
            }
            if (c >= 5) {
                s_Minv[18 * col_ind + 17] -= s_temp[768] * dot_prod<T,6,1,1>(s_Fcol,&s_temp[720]);
                s_Fcol[1] += (1) * s_Minv[18 * col_ind + 17];
            }
        }
        __syncthreads();
        // Convert floating-base Minv from internal spatial order to public velocity order.
        // Internal root vectors are [angular, linear]; public qd/u/qdd are [linear, angular].
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 324; ind += blockDim.x*blockDim.y){
            int row = ind % 18; int col = ind / 18;
            T val = static_cast<T>(0);
            if (row <= col) {
                int src_row = row < 6 ? (row < 3 ? row + 3 : row - 3) : row;
                int src_col = col < 6 ? (col < 3 ? col + 3 : col - 3) : col;
                int read_row = src_row <= src_col ? src_row : src_col;
                int read_col = src_row <= src_col ? src_col : src_row;
                val = s_Minv[read_col * 18 + read_row];
            }
            s_F[ind] = val;
        }
        __syncthreads();
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 324; ind += blockDim.x*blockDim.y){
            s_Minv[ind] = s_F[ind];
        }
        __syncthreads();
    }

    /**
     * Compute the inverse of the mass matrix
     *
     * Notes:
     *   Outputs a SYMMETRIC_UPPER triangular matrix for Minv
     *
     * @param s_Minv is a pointer to memory for the final result
     * @param s_q is the vector of joint positions
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     */
    template <typename T>
    __device__
    void minv_device(T *s_Minv, const T *s_q, const robotModel<T> *d_robotModel){
        // GRID shared arena layout
        //   T s_XImats[936]
        //   T s_temp[3037]
        //   int s_topology_helpers[115]
        //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
        extern __shared__ __align__(16) unsigned char s_arena[];
        size_t s_arena_offset = 0;
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(936);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(3037);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
        int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(int) * static_cast<size_t>(115);
        unsigned char *s_linalg_smem = nullptr;
        if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
            s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
