                    reinterpret_cast<volatile T *>(s_q_qd_u)[(rep + 1) % (57)] += _aopt_fb1;
                    reinterpret_cast<volatile T *>(s_q_qd_u)[(rep + 2) % (57)] += _aopt_fb2;
                    reinterpret_cast<volatile T *>(s_q_qd_u)[(rep + 3) % (57)] += _aopt_fb3;
