            int parent_jid = ((ind_du) < 108) * 2 + ((ind_du) < 216 && (ind_du) >= 108) * 5 + ((ind_du) < 324 && (ind_du) >= 216) * 8 + ((ind_du) >= 324) * 11;
            bool dq_flag = ind < 432;
            int du_col_offset = dq_flag * 5616 + !dq_flag * 7020 + 6*col;
            T *dst = grid_id_du_temp_ptr<T, USE_DA_DF_SPILL>(s_temp, d_temp_spill, du_col_offset + parent_jid*108 + row);
            T update_val = dot_prod<T,6,1,1>(&s_XImats[36*jid + 6*row],grid_id_du_temp_ptr<T, USE_DA_DF_SPILL>(s_temp, d_temp_spill, du_col_offset + jid*108))
                          + dq_flag * (col == jid+5) * (*grid_id_du_temp_ptr<T, USE_DA_DF_SPILL>(s_temp, d_temp_spill, 9072 + 6*jid + row));
            *dst += update_val;
        }
        __syncthreads();
        // df/du update where bfs_level is 2
        //     joints are: FL_thigh_joint, FR_thigh_joint, RL_thigh_joint, RR_thigh_joint
        //     links are: FL_thigh, FR_thigh, RL_thigh, RR_thigh
        // df_lambda/du += X^T * df/du + {Xmx(f), 0}
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 864; ind += blockDim.x*blockDim.y){
            int row = ind % 6; int col = (ind / 6) % 18;
            int ind_du = ind % 432;
            // non-branching pointer selector
            int jid = ((ind_du) < 108) * 2 + ((ind_du) < 216 && (ind_du) >= 108) * 5 + ((ind_du) < 324 && (ind_du) >= 216) * 8 + ((ind_du) >= 324) * 11;
            // non-branching pointer selector
            int parent_jid = ((ind_du) < 108) * 1 + ((ind_du) < 216 && (ind_du) >= 108) * 4 + ((ind_du) < 324 && (ind_du) >= 216) * 7 + ((ind_du) >= 324) * 10;
            bool dq_flag = ind < 432;
            int du_col_offset = dq_flag * 5616 + !dq_flag * 7020 + 6*col;
            T *dst = grid_id_du_temp_ptr<T, USE_DA_DF_SPILL>(s_temp, d_temp_spill, du_col_offset + parent_jid*108 + row);
            T update_val = dot_prod<T,6,1,1>(&s_XImats[36*jid + 6*row],grid_id_du_temp_ptr<T, USE_DA_DF_SPILL>(s_temp, d_temp_spill, du_col_offset + jid*108))
                          + dq_flag * (col == jid+5) * (*grid_id_du_temp_ptr<T, USE_DA_DF_SPILL>(s_temp, d_temp_spill, 9072 + 6*jid + row));
            *dst += update_val;
        }
        __syncthreads();
        // df/du update where bfs_level is 1
        //     joints are: FL_hip_joint, FR_hip_joint, RL_hip_joint, RR_hip_joint
        //     links are: FL_hip, FR_hip, RL_hip, RR_hip
        // df_lambda/du += X^T * df/du + {Xmx(f), 0}
        {
            static const int s_jid_lvl[] = { 1, 4, 7, 10 };
            static const int s_par_lvl[] = { 0, 0, 0, 0 };
            static const int s_upar_lvl[] = { 0 };
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 216; ind += blockDim.x*blockDim.y){
                bool dq_flag = ind < 108;
                int loc = ind % 108;
                int up = loc / 108; int rc = loc % 108;
                int col = rc / 6; int row = rc % 6;
                int par_l = s_upar_lvl[up];
                int du_col_offset = dq_flag * 5616 + !dq_flag * 7020 + 6*col;
                T *dst = grid_id_du_temp_ptr<T, USE_DA_DF_SPILL>(s_temp, d_temp_spill, du_col_offset + par_l*108 + row);
                T acc = static_cast<T>(0);
                for (int slot = 0; slot < 4; slot++) { if (s_par_lvl[slot] != par_l) continue;
                    int jid = s_jid_lvl[slot];
                    acc += dot_prod<T,6,1,1>(&s_XImats[36*jid + 6*row],grid_id_du_temp_ptr<T, USE_DA_DF_SPILL>(s_temp, d_temp_spill, du_col_offset + jid*108))
                          + dq_flag * (col == jid+5) * (*grid_id_du_temp_ptr<T, USE_DA_DF_SPILL>(s_temp, d_temp_spill, 9072 + 6*jid + row)); }
                *dst += acc;
            }
            __syncthreads();
        }
        // Finally dc[i]/du = S[i]^T*df[i]/du
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 648; ind += blockDim.x*blockDim.y){
            bool dq_flag = ind < 324; int row = ind % 18; int col = (ind / 18) % 18;
            int jid = row < 6 ? 0 : row - 5;
            int srcOffset = dq_flag * 5616 + !dq_flag * 7020 + 108*jid + 6*col + ((s_topology_helpers[13 + row]) > 0 ? (s_topology_helpers[13 + row]) - 1 : -(s_topology_helpers[13 + row]) - 1);
            s_dc_du[!dq_flag * 324 + 18*col + row] = (((s_topology_helpers[13 + row]) > 0 ? 1 : -1)) * (*grid_id_du_temp_ptr<T, USE_DA_DF_SPILL>(s_temp, d_temp_spill, srcOffset));
        }
        __syncthreads();
    }

    /**
     * inverse_dynamics_gradient orchestration as a single inner-owns-placement device function
     *
     * Notes:
     *   Owns the s_temp pool placement; the repoint covers every consumer below (incl. the XImats helper's sincos scratch)
     *
     * @param s_dc_du is the output buffer (caller places); size 2*NUM_VEL*NUM_VEL = 648
     * @param s_q is the vector of joint positions
     * @param s_qd is the vector of joint velocities
     * @param s_vaf is the id intermediate band (caller places); size 18*NUM_JOINTS = 324
     * @param s_qdd is the vector of joint accelerations
     * @param s_temp is the shared scratch pool (used when SCRATCH_IN_SMEM)
     * @param d_workspace is the global scratch pool (used when !SCRATCH_IN_SMEM)
     * @param d_temp_spill is the inverse_dynamics_gradient da_df band spill region (used when USE_DA_DF_SPILL)
     * @param s_XImats is the (shared) memory holding the updated XI matricies for the given s_q
     * @param s_topology_helpers is the (shared) memory location for the topology_helpers (nullptr/unused for serial chains with identical Ss)
     * @param d_robotModel holds XImats/topology; gravity is the gravity constant
     * @param d_f_ext is the (optional) GLOBAL external forces, body-major 6*NUM_BODIES local-frame, or nullptr
     */
    template <typename T, bool TEMP_IN_SMEM>
    __device__
    void crba_inner(T *s_M, const T *s_q, const T *s_qd, T *s_XImats, int *s_topology_helpers, T *s_temp, T *d_workspace, const T gravity);  // fwd decl (default arg lives on the definition)
    template <typename T, bool SCRATCH_IN_SMEM = true, bool USE_DA_DF_SPILL = false, bool MUJOCO_OUTPUT = false>
    __device__ __forceinline__
    void inverse_dynamics_gradient_device_qdd(T *s_dc_du, const T *s_q, const T *s_qd, T *s_vaf, const T *s_qdd, T *s_XImats, int *s_topology_helpers, T *s_temp, T *d_workspace, T *d_temp_spill, const robotModel<T> *d_robotModel, T *d_f_ext, const T gravity) {
        if constexpr (!SCRATCH_IN_SMEM) { s_temp = d_workspace; } else { (void)d_workspace; }
        load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
        inverse_dynamics_inner_vaf<T>(s_vaf, s_q, s_qd, s_qdd, s_XImats, s_topology_helpers, s_temp, d_f_ext, gravity);
        T mjx_tau_lin0 = static_cast<T>(0), mjx_tau_lin1 = static_cast<T>(0), mjx_tau_lin2 = static_cast<T>(0);
        if constexpr (MUJOCO_OUTPUT) {
            __syncthreads();
            if (threadIdx.x == 0 && threadIdx.y == 0) {
                mjx_tau_lin0 = s_vaf[159]; mjx_tau_lin1 = s_vaf[160]; mjx_tau_lin2 = s_vaf[161];
            }
        }
        inverse_dynamics_gradient_inner<T, USE_DA_DF_SPILL>(s_dc_du, s_q, s_qd, s_vaf, s_XImats, s_topology_helpers, s_temp, d_temp_spill, gravity);
        __syncthreads();
        if constexpr (MUJOCO_OUTPUT) {
            // === mjx output convention (floating-base id-gradient) ===
            // build the generalized mass matrix M into the (dead) gradient pool via crba_inner
            crba_inner<T, SCRATCH_IN_SMEM>((s_temp + 0), s_q, s_qd, s_XImats, s_topology_helpers, (s_temp + 324), nullptr, gravity);
            __syncthreads();
            // precompute shared helpers (R + base source vectors) into dead crba scratch
            T *s_mjxh = s_temp + 324;
            if (threadIdx.x == 0 && threadIdx.y == 0) {
                T qx = s_q[3], qy = s_q[4], qz = s_q[5], qw = s_q[6];
                T xx = qx*qx, yy = qy*qy, zz = qz*qz;
                T xy = qx*qy, xz = qx*qz, yz = qy*qz, wx = qw*qx, wy = qw*qy, wz = qw*qz;
                s_mjxh[0] = static_cast<T>(1) - static_cast<T>(2)*(yy+zz); s_mjxh[1] = static_cast<T>(2)*(xy-wz);                    s_mjxh[2] = static_cast<T>(2)*(xz+wy);
                s_mjxh[3] = static_cast<T>(2)*(xy+wz);                    s_mjxh[4] = static_cast<T>(1) - static_cast<T>(2)*(xx+zz); s_mjxh[5] = static_cast<T>(2)*(yz-wx);
                s_mjxh[6] = static_cast<T>(2)*(xz-wy);                    s_mjxh[7] = static_cast<T>(2)*(yz+wx);                    s_mjxh[8] = static_cast<T>(1) - static_cast<T>(2)*(xx+yy);
                s_mjxh[9] = s_qd[0]; s_mjxh[10] = s_qd[1]; s_mjxh[11] = s_qd[2];
                s_mjxh[12] = s_qd[3]; s_mjxh[13] = s_qd[4]; s_mjxh[14] = s_qd[5];
                s_mjxh[15] = s_qdd[0]; s_mjxh[16] = s_qdd[1]; s_mjxh[17] = s_qdd[2];
                s_mjxh[18] = mjx_tau_lin0; s_mjxh[19] = mjx_tau_lin1; s_mjxh[20] = mjx_tau_lin2;
            }
            __syncthreads();
            // Phase A: dc_dq column_reframe (cols 0:3) + couplings (cols 3:6), per row
            for(int r = threadIdx.x + threadIdx.y*blockDim.x; r < 18; r += blockDim.x*blockDim.y){
                T R[9]; R[0]=s_mjxh[0];R[1]=s_mjxh[1];R[2]=s_mjxh[2];R[3]=s_mjxh[3];R[4]=s_mjxh[4];R[5]=s_mjxh[5];R[6]=s_mjxh[6];R[7]=s_mjxh[7];R[8]=s_mjxh[8];
                T v_lin[3] = {s_mjxh[9], s_mjxh[10], s_mjxh[11]};
                T omega[3] = {s_mjxh[12], s_mjxh[13], s_mjxh[14]};
                T qdd_lin[3] = {s_mjxh[15], s_mjxh[16], s_mjxh[17]};
                T tau_lin[3] = {s_mjxh[18], s_mjxh[19], s_mjxh[20]};
                T *s_M = s_temp + 0;
                // dc_dq: column_reframe cols 0:3 <- cols . R^T
                T c0 = s_dc_du[0 + 0*18 + r], c1 = s_dc_du[0 + 1*18 + r], c2 = s_dc_du[0 + 2*18 + r];
                s_dc_du[0 + 0*18 + r] = c0*R[0] + c1*R[1] + c2*R[2];
                s_dc_du[0 + 1*18 + r] = c0*R[3] + c1*R[4] + c2*R[5];
                s_dc_du[0 + 2*18 + r] = c0*R[6] + c1*R[7] + c2*R[8];
                // dc_dq: base-velocity couplings into angular cols 3+a (this row)
                for (int a = 0; a < 3; a++) {
                    T jv[3], ja[3];
                    jv[0] = -((a==1)*( v_lin[2]) + (a==2)*(-v_lin[1]));
                    jv[1] = -((a==0)*(-v_lin[2]) + (a==2)*( v_lin[0]));
                    jv[2] = -((a==0)*( v_lin[1]) + (a==1)*(-v_lin[0]));
                    T ov0 = omega[1]*v_lin[2] - omega[2]*v_lin[1];
                    T ov1 = omega[2]*v_lin[0] - omega[0]*v_lin[2];
                    T ov2 = omega[0]*v_lin[1] - omega[1]*v_lin[0];
                    T ev0 = (a==1)*( v_lin[2]) + (a==2)*(-v_lin[1]);
                    T ev1 = (a==0)*(-v_lin[2]) + (a==2)*( v_lin[0]);
                    T ev2 = (a==0)*( v_lin[1]) + (a==1)*(-v_lin[0]);
                    T eq0 = (a==1)*( qdd_lin[2]) + (a==2)*(-qdd_lin[1]);
                    T eq1 = (a==0)*(-qdd_lin[2]) + (a==2)*( qdd_lin[0]);
                    T eq2 = (a==0)*( qdd_lin[1]) + (a==1)*(-qdd_lin[0]);
                    T eov0 = (a==1)*( ov2) + (a==2)*(-ov1);
                    T eov1 = (a==0)*(-ov2) + (a==2)*( ov0);
                    T eov2 = (a==0)*( ov1) + (a==1)*(-ov0);
                    T oev0 = omega[1]*ev2 - omega[2]*ev1;
                    T oev1 = omega[2]*ev0 - omega[0]*ev2;
                    T oev2 = omega[0]*ev1 - omega[1]*ev0;
                    ja[0] = -eq0 - eov0 + oev0;
                    ja[1] = -eq1 - eov1 + oev1;
                    ja[2] = -eq2 - eov2 + oev2;
                    T acc = static_cast<T>(0);
                    for (int k = 0; k < 3; k++) { acc += s_dc_du[324 + k*18 + r]*jv[k] + s_M[r + 18*k]*ja[k]; }
                    s_dc_du[0 + (3+a)*18 + r] += acc;
                }
            }
            __syncthreads();
            // Phase B: dc_dq base_rotate_rows rows 0:3 <- R . rows, per col
            for(int c = threadIdx.x + threadIdx.y*blockDim.x; c < 18; c += blockDim.x*blockDim.y){
                T R[9]; R[0]=s_mjxh[0];R[1]=s_mjxh[1];R[2]=s_mjxh[2];R[3]=s_mjxh[3];R[4]=s_mjxh[4];R[5]=s_mjxh[5];R[6]=s_mjxh[6];R[7]=s_mjxh[7];R[8]=s_mjxh[8];
                T v_lin[3] = {s_mjxh[9], s_mjxh[10], s_mjxh[11]};
                T omega[3] = {s_mjxh[12], s_mjxh[13], s_mjxh[14]};
                T qdd_lin[3] = {s_mjxh[15], s_mjxh[16], s_mjxh[17]};
                T tau_lin[3] = {s_mjxh[18], s_mjxh[19], s_mjxh[20]};
                T *s_M = s_temp + 0;
                T m0 = s_dc_du[0 + c*18 + 0], m1 = s_dc_du[0 + c*18 + 1], m2 = s_dc_du[0 + c*18 + 2];
                s_dc_du[0 + c*18 + 0] = R[0]*m0 + R[1]*m1 + R[2]*m2;
                s_dc_du[0 + c*18 + 1] = R[3]*m0 + R[4]*m1 + R[5]*m2;
                s_dc_du[0 + c*18 + 2] = R[6]*m0 + R[7]*m1 + R[8]*m2;
            }
            __syncthreads();
            // Phase C: dc_dq pref  dq[0:3, 3+a] += R @ (e_a x tau_lin), per a
            for(int a = threadIdx.x + threadIdx.y*blockDim.x; a < 3; a += blockDim.x*blockDim.y){
                T R[9]; R[0]=s_mjxh[0];R[1]=s_mjxh[1];R[2]=s_mjxh[2];R[3]=s_mjxh[3];R[4]=s_mjxh[4];R[5]=s_mjxh[5];R[6]=s_mjxh[6];R[7]=s_mjxh[7];R[8]=s_mjxh[8];
                T v_lin[3] = {s_mjxh[9], s_mjxh[10], s_mjxh[11]};
                T omega[3] = {s_mjxh[12], s_mjxh[13], s_mjxh[14]};
                T qdd_lin[3] = {s_mjxh[15], s_mjxh[16], s_mjxh[17]};
                T tau_lin[3] = {s_mjxh[18], s_mjxh[19], s_mjxh[20]};
                T *s_M = s_temp + 0;
                T et0 = (a==1)*( tau_lin[2]) + (a==2)*(-tau_lin[1]);
                T et1 = (a==0)*(-tau_lin[2]) + (a==2)*( tau_lin[0]);
                T et2 = (a==0)*( tau_lin[1]) + (a==1)*(-tau_lin[0]);
                T w0 = R[0]*et0 + R[1]*et1 + R[2]*et2;
                T w1 = R[3]*et0 + R[4]*et1 + R[5]*et2;
                T w2 = R[6]*et0 + R[7]*et1 + R[8]*et2;
                s_dc_du[0 + (3+a)*18 + 0] += w0;
                s_dc_du[0 + (3+a)*18 + 1] += w1;
                s_dc_du[0 + (3+a)*18 + 2] += w2;
            }
            __syncthreads();
            // Phase D: dc_dqd column_reframe cols 0:3 <- cols . R^T, per row
            for(int r = threadIdx.x + threadIdx.y*blockDim.x; r < 18; r += blockDim.x*blockDim.y){
                T R[9]; R[0]=s_mjxh[0];R[1]=s_mjxh[1];R[2]=s_mjxh[2];R[3]=s_mjxh[3];R[4]=s_mjxh[4];R[5]=s_mjxh[5];R[6]=s_mjxh[6];R[7]=s_mjxh[7];R[8]=s_mjxh[8];
                T v_lin[3] = {s_mjxh[9], s_mjxh[10], s_mjxh[11]};
                T omega[3] = {s_mjxh[12], s_mjxh[13], s_mjxh[14]};
                T qdd_lin[3] = {s_mjxh[15], s_mjxh[16], s_mjxh[17]};
                T tau_lin[3] = {s_mjxh[18], s_mjxh[19], s_mjxh[20]};
                T *s_M = s_temp + 0;
                T c0 = s_dc_du[324 + 0*18 + r], c1 = s_dc_du[324 + 1*18 + r], c2 = s_dc_du[324 + 2*18 + r];
                s_dc_du[324 + 0*18 + r] = c0*R[0] + c1*R[1] + c2*R[2];
                s_dc_du[324 + 1*18 + r] = c0*R[3] + c1*R[4] + c2*R[5];
                s_dc_du[324 + 2*18 + r] = c0*R[6] + c1*R[7] + c2*R[8];
            }
            __syncthreads();
            // Phase E: dc_dqd couplings  col 0+a += M[:,0:3]@(-(omega x R^T e_a)) ; col 3+a += M[:,0:3]@(-(e_a x v_lin)), per row
            for(int r = threadIdx.x + threadIdx.y*blockDim.x; r < 18; r += blockDim.x*blockDim.y){
                T R[9]; R[0]=s_mjxh[0];R[1]=s_mjxh[1];R[2]=s_mjxh[2];R[3]=s_mjxh[3];R[4]=s_mjxh[4];R[5]=s_mjxh[5];R[6]=s_mjxh[6];R[7]=s_mjxh[7];R[8]=s_mjxh[8];
                T v_lin[3] = {s_mjxh[9], s_mjxh[10], s_mjxh[11]};
                T omega[3] = {s_mjxh[12], s_mjxh[13], s_mjxh[14]};
                T qdd_lin[3] = {s_mjxh[15], s_mjxh[16], s_mjxh[17]};
                T tau_lin[3] = {s_mjxh[18], s_mjxh[19], s_mjxh[20]};
                T *s_M = s_temp + 0;
                T mr0 = s_M[r + 18*0], mr1 = s_M[r + 18*1], mr2 = s_M[r + 18*2];
                for (int a = 0; a < 3; a++) {
                    T rte0 = R[3*a + 0], rte1 = R[3*a + 1], rte2 = R[3*a + 2];
                    T jl0 = -(omega[1]*rte2 - omega[2]*rte1);
                    T jl1 = -(omega[2]*rte0 - omega[0]*rte2);
                    T jl2 = -(omega[0]*rte1 - omega[1]*rte0);
                    T jn0 = -((a==1)*( v_lin[2]) + (a==2)*(-v_lin[1]));
                    T jn1 = -((a==0)*(-v_lin[2]) + (a==2)*( v_lin[0]));
                    T jn2 = -((a==0)*( v_lin[1]) + (a==1)*(-v_lin[0]));
                    s_dc_du[324 + (0+a)*18 + r] += mr0*jl0 + mr1*jl1 + mr2*jl2;
                    s_dc_du[324 + (3+a)*18 + r] += mr0*jn0 + mr1*jn1 + mr2*jn2;
                }
            }
            __syncthreads();
            // Phase F: dc_dqd base_rotate_rows rows 0:3 <- R . rows, per col
            for(int c = threadIdx.x + threadIdx.y*blockDim.x; c < 18; c += blockDim.x*blockDim.y){
                T R[9]; R[0]=s_mjxh[0];R[1]=s_mjxh[1];R[2]=s_mjxh[2];R[3]=s_mjxh[3];R[4]=s_mjxh[4];R[5]=s_mjxh[5];R[6]=s_mjxh[6];R[7]=s_mjxh[7];R[8]=s_mjxh[8];
                T v_lin[3] = {s_mjxh[9], s_mjxh[10], s_mjxh[11]};
                T omega[3] = {s_mjxh[12], s_mjxh[13], s_mjxh[14]};
                T qdd_lin[3] = {s_mjxh[15], s_mjxh[16], s_mjxh[17]};
                T tau_lin[3] = {s_mjxh[18], s_mjxh[19], s_mjxh[20]};
                T *s_M = s_temp + 0;
                T m0 = s_dc_du[324 + c*18 + 0], m1 = s_dc_du[324 + c*18 + 1], m2 = s_dc_du[324 + c*18 + 2];
                s_dc_du[324 + c*18 + 0] = R[0]*m0 + R[1]*m1 + R[2]*m2;
                s_dc_du[324 + c*18 + 1] = R[3]*m0 + R[4]*m1 + R[5]*m2;
                s_dc_du[324 + c*18 + 2] = R[6]*m0 + R[7]*m1 + R[8]*m2;
            }
            __syncthreads();
        }
    }

    /**
     * inverse_dynamics_gradient orchestration as a single inner-owns-placement device function
     *
     * Notes:
     *   Owns the s_temp pool placement; the repoint covers every consumer below (incl. the XImats helper's sincos scratch)
     *
     * @param s_dc_du is the output buffer (caller places); size 2*NUM_VEL*NUM_VEL = 648
     * @param s_q is the vector of joint positions
     * @param s_qd is the vector of joint velocities
     * @param s_vaf is the id intermediate band (caller places); size 18*NUM_JOINTS = 324
     * @param s_temp is the shared scratch pool (used when SCRATCH_IN_SMEM)
     * @param d_workspace is the global scratch pool (used when !SCRATCH_IN_SMEM)
     * @param d_temp_spill is the inverse_dynamics_gradient da_df band spill region (used when USE_DA_DF_SPILL)
     * @param s_XImats is the (shared) memory holding the updated XI matricies for the given s_q
     * @param s_topology_helpers is the (shared) memory location for the topology_helpers (nullptr/unused for serial chains with identical Ss)
     * @param d_robotModel holds XImats/topology; gravity is the gravity constant
     * @param d_f_ext is the (optional) GLOBAL external forces, body-major 6*NUM_BODIES local-frame, or nullptr
     */
    template <typename T, bool TEMP_IN_SMEM>
    __device__
    void crba_inner(T *s_M, const T *s_q, const T *s_qd, T *s_XImats, int *s_topology_helpers, T *s_temp, T *d_workspace, const T gravity);  // fwd decl (default arg lives on the definition)
    template <typename T, bool SCRATCH_IN_SMEM = true, bool USE_DA_DF_SPILL = false, bool MUJOCO_OUTPUT = false>
    __device__ __forceinline__
    void inverse_dynamics_gradient_device(T *s_dc_du, const T *s_q, const T *s_qd, T *s_vaf, T *s_XImats, int *s_topology_helpers, T *s_temp, T *d_workspace, T *d_temp_spill, const robotModel<T> *d_robotModel, T *d_f_ext, const T gravity) {
        if constexpr (!SCRATCH_IN_SMEM) { s_temp = d_workspace; } else { (void)d_workspace; }
        load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
        inverse_dynamics_inner_vaf<T>(s_vaf, s_q, s_qd, s_XImats, s_topology_helpers, s_temp, d_f_ext, gravity);
        T mjx_tau_lin0 = static_cast<T>(0), mjx_tau_lin1 = static_cast<T>(0), mjx_tau_lin2 = static_cast<T>(0);
        if constexpr (MUJOCO_OUTPUT) {
            __syncthreads();
            if (threadIdx.x == 0 && threadIdx.y == 0) {
                mjx_tau_lin0 = s_vaf[159]; mjx_tau_lin1 = s_vaf[160]; mjx_tau_lin2 = s_vaf[161];
            }
        }
        inverse_dynamics_gradient_inner<T, USE_DA_DF_SPILL>(s_dc_du, s_q, s_qd, s_vaf, s_XImats, s_topology_helpers, s_temp, d_temp_spill, gravity);
        __syncthreads();
        if constexpr (MUJOCO_OUTPUT) {
            // === mjx output convention (floating-base id-gradient) ===
            // build the generalized mass matrix M into the (dead) gradient pool via crba_inner
            crba_inner<T, SCRATCH_IN_SMEM>((s_temp + 0), s_q, s_qd, s_XImats, s_topology_helpers, (s_temp + 324), nullptr, gravity);
            __syncthreads();
            // precompute shared helpers (R + base source vectors) into dead crba scratch
            T *s_mjxh = s_temp + 324;
            if (threadIdx.x == 0 && threadIdx.y == 0) {
                T qx = s_q[3], qy = s_q[4], qz = s_q[5], qw = s_q[6];
                T xx = qx*qx, yy = qy*qy, zz = qz*qz;
                T xy = qx*qy, xz = qx*qz, yz = qy*qz, wx = qw*qx, wy = qw*qy, wz = qw*qz;
                s_mjxh[0] = static_cast<T>(1) - static_cast<T>(2)*(yy+zz); s_mjxh[1] = static_cast<T>(2)*(xy-wz);                    s_mjxh[2] = static_cast<T>(2)*(xz+wy);
                s_mjxh[3] = static_cast<T>(2)*(xy+wz);                    s_mjxh[4] = static_cast<T>(1) - static_cast<T>(2)*(xx+zz); s_mjxh[5] = static_cast<T>(2)*(yz-wx);
                s_mjxh[6] = static_cast<T>(2)*(xz-wy);                    s_mjxh[7] = static_cast<T>(2)*(yz+wx);                    s_mjxh[8] = static_cast<T>(1) - static_cast<T>(2)*(xx+yy);
                s_mjxh[9] = s_qd[0]; s_mjxh[10] = s_qd[1]; s_mjxh[11] = s_qd[2];
                s_mjxh[12] = s_qd[3]; s_mjxh[13] = s_qd[4]; s_mjxh[14] = s_qd[5];
                s_mjxh[15] = static_cast<T>(0); s_mjxh[16] = static_cast<T>(0); s_mjxh[17] = static_cast<T>(0);
                s_mjxh[18] = mjx_tau_lin0; s_mjxh[19] = mjx_tau_lin1; s_mjxh[20] = mjx_tau_lin2;
            }
            __syncthreads();
            // Phase A: dc_dq column_reframe (cols 0:3) + couplings (cols 3:6), per row
            for(int r = threadIdx.x + threadIdx.y*blockDim.x; r < 18; r += blockDim.x*blockDim.y){
                T R[9]; R[0]=s_mjxh[0];R[1]=s_mjxh[1];R[2]=s_mjxh[2];R[3]=s_mjxh[3];R[4]=s_mjxh[4];R[5]=s_mjxh[5];R[6]=s_mjxh[6];R[7]=s_mjxh[7];R[8]=s_mjxh[8];
                T v_lin[3] = {s_mjxh[9], s_mjxh[10], s_mjxh[11]};
                T omega[3] = {s_mjxh[12], s_mjxh[13], s_mjxh[14]};
                T qdd_lin[3] = {s_mjxh[15], s_mjxh[16], s_mjxh[17]};
                T tau_lin[3] = {s_mjxh[18], s_mjxh[19], s_mjxh[20]};
                T *s_M = s_temp + 0;
                // dc_dq: column_reframe cols 0:3 <- cols . R^T
                T c0 = s_dc_du[0 + 0*18 + r], c1 = s_dc_du[0 + 1*18 + r], c2 = s_dc_du[0 + 2*18 + r];
                s_dc_du[0 + 0*18 + r] = c0*R[0] + c1*R[1] + c2*R[2];
                s_dc_du[0 + 1*18 + r] = c0*R[3] + c1*R[4] + c2*R[5];
                s_dc_du[0 + 2*18 + r] = c0*R[6] + c1*R[7] + c2*R[8];
                // dc_dq: base-velocity couplings into angular cols 3+a (this row)
                for (int a = 0; a < 3; a++) {
                    T jv[3], ja[3];
                    jv[0] = -((a==1)*( v_lin[2]) + (a==2)*(-v_lin[1]));
                    jv[1] = -((a==0)*(-v_lin[2]) + (a==2)*( v_lin[0]));
                    jv[2] = -((a==0)*( v_lin[1]) + (a==1)*(-v_lin[0]));
                    T ov0 = omega[1]*v_lin[2] - omega[2]*v_lin[1];
                    T ov1 = omega[2]*v_lin[0] - omega[0]*v_lin[2];
                    T ov2 = omega[0]*v_lin[1] - omega[1]*v_lin[0];
                    T ev0 = (a==1)*( v_lin[2]) + (a==2)*(-v_lin[1]);
                    T ev1 = (a==0)*(-v_lin[2]) + (a==2)*( v_lin[0]);
                    T ev2 = (a==0)*( v_lin[1]) + (a==1)*(-v_lin[0]);
                    T eq0 = (a==1)*( qdd_lin[2]) + (a==2)*(-qdd_lin[1]);
                    T eq1 = (a==0)*(-qdd_lin[2]) + (a==2)*( qdd_lin[0]);
                    T eq2 = (a==0)*( qdd_lin[1]) + (a==1)*(-qdd_lin[0]);
                    T eov0 = (a==1)*( ov2) + (a==2)*(-ov1);
                    T eov1 = (a==0)*(-ov2) + (a==2)*( ov0);
                    T eov2 = (a==0)*( ov1) + (a==1)*(-ov0);
                    T oev0 = omega[1]*ev2 - omega[2]*ev1;
                    T oev1 = omega[2]*ev0 - omega[0]*ev2;
                    T oev2 = omega[0]*ev1 - omega[1]*ev0;
                    ja[0] = -eq0 - eov0 + oev0;
                    ja[1] = -eq1 - eov1 + oev1;
                    ja[2] = -eq2 - eov2 + oev2;
                    T acc = static_cast<T>(0);
                    for (int k = 0; k < 3; k++) { acc += s_dc_du[324 + k*18 + r]*jv[k] + s_M[r + 18*k]*ja[k]; }
                    s_dc_du[0 + (3+a)*18 + r] += acc;
                }
            }
            __syncthreads();
            // Phase B: dc_dq base_rotate_rows rows 0:3 <- R . rows, per col
            for(int c = threadIdx.x + threadIdx.y*blockDim.x; c < 18; c += blockDim.x*blockDim.y){
                T R[9]; R[0]=s_mjxh[0];R[1]=s_mjxh[1];R[2]=s_mjxh[2];R[3]=s_mjxh[3];R[4]=s_mjxh[4];R[5]=s_mjxh[5];R[6]=s_mjxh[6];R[7]=s_mjxh[7];R[8]=s_mjxh[8];
                T v_lin[3] = {s_mjxh[9], s_mjxh[10], s_mjxh[11]};
                T omega[3] = {s_mjxh[12], s_mjxh[13], s_mjxh[14]};
                T qdd_lin[3] = {s_mjxh[15], s_mjxh[16], s_mjxh[17]};
                T tau_lin[3] = {s_mjxh[18], s_mjxh[19], s_mjxh[20]};
                T *s_M = s_temp + 0;
                T m0 = s_dc_du[0 + c*18 + 0], m1 = s_dc_du[0 + c*18 + 1], m2 = s_dc_du[0 + c*18 + 2];
                s_dc_du[0 + c*18 + 0] = R[0]*m0 + R[1]*m1 + R[2]*m2;
                s_dc_du[0 + c*18 + 1] = R[3]*m0 + R[4]*m1 + R[5]*m2;
                s_dc_du[0 + c*18 + 2] = R[6]*m0 + R[7]*m1 + R[8]*m2;
            }
            __syncthreads();
            // Phase C: dc_dq pref  dq[0:3, 3+a] += R @ (e_a x tau_lin), per a
            for(int a = threadIdx.x + threadIdx.y*blockDim.x; a < 3; a += blockDim.x*blockDim.y){
                T R[9]; R[0]=s_mjxh[0];R[1]=s_mjxh[1];R[2]=s_mjxh[2];R[3]=s_mjxh[3];R[4]=s_mjxh[4];R[5]=s_mjxh[5];R[6]=s_mjxh[6];R[7]=s_mjxh[7];R[8]=s_mjxh[8];
                T v_lin[3] = {s_mjxh[9], s_mjxh[10], s_mjxh[11]};
                T omega[3] = {s_mjxh[12], s_mjxh[13], s_mjxh[14]};
                T qdd_lin[3] = {s_mjxh[15], s_mjxh[16], s_mjxh[17]};
                T tau_lin[3] = {s_mjxh[18], s_mjxh[19], s_mjxh[20]};
                T *s_M = s_temp + 0;
                T et0 = (a==1)*( tau_lin[2]) + (a==2)*(-tau_lin[1]);
                T et1 = (a==0)*(-tau_lin[2]) + (a==2)*( tau_lin[0]);
                T et2 = (a==0)*( tau_lin[1]) + (a==1)*(-tau_lin[0]);
                T w0 = R[0]*et0 + R[1]*et1 + R[2]*et2;
                T w1 = R[3]*et0 + R[4]*et1 + R[5]*et2;
                T w2 = R[6]*et0 + R[7]*et1 + R[8]*et2;
                s_dc_du[0 + (3+a)*18 + 0] += w0;
                s_dc_du[0 + (3+a)*18 + 1] += w1;
                s_dc_du[0 + (3+a)*18 + 2] += w2;
            }
            __syncthreads();
            // Phase D: dc_dqd column_reframe cols 0:3 <- cols . R^T, per row
            for(int r = threadIdx.x + threadIdx.y*blockDim.x; r < 18; r += blockDim.x*blockDim.y){
                T R[9]; R[0]=s_mjxh[0];R[1]=s_mjxh[1];R[2]=s_mjxh[2];R[3]=s_mjxh[3];R[4]=s_mjxh[4];R[5]=s_mjxh[5];R[6]=s_mjxh[6];R[7]=s_mjxh[7];R[8]=s_mjxh[8];
                T v_lin[3] = {s_mjxh[9], s_mjxh[10], s_mjxh[11]};
                T omega[3] = {s_mjxh[12], s_mjxh[13], s_mjxh[14]};
                T qdd_lin[3] = {s_mjxh[15], s_mjxh[16], s_mjxh[17]};
                T tau_lin[3] = {s_mjxh[18], s_mjxh[19], s_mjxh[20]};
                T *s_M = s_temp + 0;
                T c0 = s_dc_du[324 + 0*18 + r], c1 = s_dc_du[324 + 1*18 + r], c2 = s_dc_du[324 + 2*18 + r];
                s_dc_du[324 + 0*18 + r] = c0*R[0] + c1*R[1] + c2*R[2];
                s_dc_du[324 + 1*18 + r] = c0*R[3] + c1*R[4] + c2*R[5];
                s_dc_du[324 + 2*18 + r] = c0*R[6] + c1*R[7] + c2*R[8];
            }
            __syncthreads();
            // Phase E: dc_dqd couplings  col 0+a += M[:,0:3]@(-(omega x R^T e_a)) ; col 3+a += M[:,0:3]@(-(e_a x v_lin)), per row
            for(int r = threadIdx.x + threadIdx.y*blockDim.x; r < 18; r += blockDim.x*blockDim.y){
                T R[9]; R[0]=s_mjxh[0];R[1]=s_mjxh[1];R[2]=s_mjxh[2];R[3]=s_mjxh[3];R[4]=s_mjxh[4];R[5]=s_mjxh[5];R[6]=s_mjxh[6];R[7]=s_mjxh[7];R[8]=s_mjxh[8];
                T v_lin[3] = {s_mjxh[9], s_mjxh[10], s_mjxh[11]};
                T omega[3] = {s_mjxh[12], s_mjxh[13], s_mjxh[14]};
                T qdd_lin[3] = {s_mjxh[15], s_mjxh[16], s_mjxh[17]};
                T tau_lin[3] = {s_mjxh[18], s_mjxh[19], s_mjxh[20]};
                T *s_M = s_temp + 0;
                T mr0 = s_M[r + 18*0], mr1 = s_M[r + 18*1], mr2 = s_M[r + 18*2];
                for (int a = 0; a < 3; a++) {
                    T rte0 = R[3*a + 0], rte1 = R[3*a + 1], rte2 = R[3*a + 2];
                    T jl0 = -(omega[1]*rte2 - omega[2]*rte1);
                    T jl1 = -(omega[2]*rte0 - omega[0]*rte2);
                    T jl2 = -(omega[0]*rte1 - omega[1]*rte0);
                    T jn0 = -((a==1)*( v_lin[2]) + (a==2)*(-v_lin[1]));
                    T jn1 = -((a==0)*(-v_lin[2]) + (a==2)*( v_lin[0]));
                    T jn2 = -((a==0)*( v_lin[1]) + (a==1)*(-v_lin[0]));
                    s_dc_du[324 + (0+a)*18 + r] += mr0*jl0 + mr1*jl1 + mr2*jl2;
                    s_dc_du[324 + (3+a)*18 + r] += mr0*jn0 + mr1*jn1 + mr2*jn2;
                }
            }
            __syncthreads();
            // Phase F: dc_dqd base_rotate_rows rows 0:3 <- R . rows, per col
            for(int c = threadIdx.x + threadIdx.y*blockDim.x; c < 18; c += blockDim.x*blockDim.y){
                T R[9]; R[0]=s_mjxh[0];R[1]=s_mjxh[1];R[2]=s_mjxh[2];R[3]=s_mjxh[3];R[4]=s_mjxh[4];R[5]=s_mjxh[5];R[6]=s_mjxh[6];R[7]=s_mjxh[7];R[8]=s_mjxh[8];
                T v_lin[3] = {s_mjxh[9], s_mjxh[10], s_mjxh[11]};
                T omega[3] = {s_mjxh[12], s_mjxh[13], s_mjxh[14]};
                T qdd_lin[3] = {s_mjxh[15], s_mjxh[16], s_mjxh[17]};
                T tau_lin[3] = {s_mjxh[18], s_mjxh[19], s_mjxh[20]};
                T *s_M = s_temp + 0;
                T m0 = s_dc_du[324 + c*18 + 0], m1 = s_dc_du[324 + c*18 + 1], m2 = s_dc_du[324 + c*18 + 2];
                s_dc_du[324 + c*18 + 0] = R[0]*m0 + R[1]*m1 + R[2]*m2;
                s_dc_du[324 + c*18 + 1] = R[3]*m0 + R[4]*m1 + R[5]*m2;
                s_dc_du[324 + c*18 + 2] = R[6]*m0 + R[7]*m1 + R[8]*m2;
            }
            __syncthreads();
        }
    }

    /**
     * Computes the gradient of inverse dynamics
     *
     * @param d_dc_du is a pointer to memory for the final result of size 2*NUM_VEL*NUM_VEL = 648
     * @param d_q_dq is the vector of joint positions and velocities
     * @param stride_q_qd is the stide between each q, qd
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param d_f_ext is the (optional) GLOBAL external forces, body-major 6*NUM_BODIES local-frame, or nullptr
     * @param d_qdd is the vector of joint accelerations
     * @param gravity is the gravity constant
     * @param num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
     */
    template <typename T, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER, bool MUJOCO_OUTPUT = false>
    __global__
    __launch_bounds__(tier_max_threads<RESOURCE_TIER>())
    void inverse_dynamics_gradient_kernel_single_timing(T *d_dc_du, unsigned char *d_workspace, const T *d_q_qd, const int stride_q_qd, const T *d_qdd, T *d_f_ext, const robotModel<T> *d_robotModel, const T gravity, const int NUM_TIMESTEPS) {
        if constexpr (RESOURCE_TIER == TIER_SHARED) {
            // GRID shared arena layout
            //   T s_q_qd[37]
            //   T s_dc_du[648]
            //   T s_vaf[324]
            //   T s_qdd[18]
            //   T s_XImats[936]
            //   T s_temp[9612]
            //   int s_topology_helpers[115]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q_qd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(37);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_dc_du = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(648);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_vaf = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(324);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(18);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(936);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(9612);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
            int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(int) * static_cast<size_t>(115);
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(11575, 115, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            T *d_temp_spill = nullptr; (void)d_temp_spill;
            T *s_q = s_q_qd; T *s_qd = &s_q_qd[19];
            // load to shared mem
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 37; ind += blockDim.x*blockDim.y){
                s_q_qd[ind] = d_q_qd[ind];
            }
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 18; ind += blockDim.x*blockDim.y){
                s_qdd[ind] = d_qdd[ind];
            }
            __syncthreads();
            // compute with NUM_TIMESTEPS as NUM_REPS for timing
            for (int rep = 0; rep < NUM_TIMESTEPS; rep++){
                // anti-LICM: volatile reload of inputs each rep
                for(int _aopt_i = threadIdx.x + threadIdx.y*blockDim.x; _aopt_i < 37; _aopt_i += blockDim.x*blockDim.y){
                    reinterpret_cast<volatile T *>(s_q_qd)[_aopt_i] = reinterpret_cast<const volatile T *>(d_q_qd)[_aopt_i];
                }
                for(int _aopt_i = threadIdx.x + threadIdx.y*blockDim.x; _aopt_i < 18; _aopt_i += blockDim.x*blockDim.y){
                    reinterpret_cast<volatile T *>(s_qdd)[_aopt_i] = reinterpret_cast<const volatile T *>(d_qdd)[_aopt_i];
                }
                __syncthreads();
                // anti-LICM (1/2): stomp one input slot with `rep`
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    reinterpret_cast<volatile T *>(s_q_qd)[rep % (37)] = static_cast<T>(rep);
                    reinterpret_cast<volatile T *>(s_qdd)[rep % (18)] = static_cast<T>(rep);
                }
                // anti-LICM (2/2): feedback prev rep's d_dc_du into s_q_qd (true loop-carried dep)
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    T _aopt_fb1 = reinterpret_cast<const volatile T *>(d_dc_du)[(rep + 0x3FF) & 0x3FF];
                    T _aopt_fb2 = reinterpret_cast<const volatile T *>(d_dc_du)[(rep + 0x3FE) & 0x3FF];
                    T _aopt_fb3 = reinterpret_cast<const volatile T *>(d_dc_du)[(rep + 0x3FD) & 0x3FF];
                    reinterpret_cast<volatile T *>(s_q_qd)[(rep + 1) % (37)] += _aopt_fb1;
                    reinterpret_cast<volatile T *>(s_q_qd)[(rep + 2) % (37)] += _aopt_fb2;
                    reinterpret_cast<volatile T *>(s_q_qd)[(rep + 3) % (37)] += _aopt_fb3;
                }
                __syncthreads();
                inverse_dynamics_gradient_device_qdd<T, true, false, MUJOCO_OUTPUT>(s_dc_du, s_q, s_qd, s_vaf, s_qdd, s_XImats, s_topology_helpers, s_temp, nullptr, nullptr, d_robotModel, d_f_ext, gravity);
                __syncthreads();
