                }
                __syncthreads();
                forward_dynamics_gradient_device<T, true, false, MUJOCO_OUTPUT>(s_temp, s_q, s_qd, s_u, s_vaf, s_dc_du, s_qdd, s_Minv, s_XImats, s_topology_helpers, s_temp, nullptr, nullptr, d_robotModel, d_f_ext, gravity);
