            }
            __syncthreads();
            // compute with NUM_TIMESTEPS as NUM_REPS for timing
            for (int rep = 0; rep < NUM_TIMESTEPS; rep++){
                // anti-LICM: volatile reload of inputs each rep
                for(int _aopt_i = threadIdx.x + threadIdx.y*blockDim.x; _aopt_i < 57; _aopt_i += blockDim.x*blockDim.y){
                    reinterpret_cast<volatile T *>(s_q_qd_u)[_aopt_i] = reinterpret_cast<const volatile T *>(d_q_qd_u)[_aopt_i];
                }
                __syncthreads();
                // anti-LICM (1/2): stomp one input slot with `rep`
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    reinterpret_cast<volatile T *>(s_q_qd_u)[rep % (57)] = static_cast<T>(rep);
                }
                __syncthreads();
                forward_dynamics_gradient_device<T, true, false, MUJOCO_OUTPUT>(s_temp, s_q, s_qd, s_u, s_vaf, s_dc_du, s_qdd, s_Minv, s_XImats, s_topology_helpers, s_temp, nullptr, nullptr, d_robotModel, d_f_ext, gravity);
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) { reinterpret_cast<volatile T *>(d_df_du)[rep & 63] = s_temp[rep & 63]; }
            }
            // save down to global
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 648; ind += blockDim.x*blockDim.y){
