                    reinterpret_cast<volatile T *>(s_q_qd)[(rep + 1) % (37)] += _aopt_fb1;
                    reinterpret_cast<volatile T *>(s_q_qd)[(rep + 2) % (37)] += _aopt_fb2;
                    reinterpret_cast<volatile T *>(s_q_qd)[(rep + 3) % (37)] += _aopt_fb3;
                }
                __syncthreads();
                load_update_XImats_helpers<T, true>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                crba_inner<T, false>(s_M, s_q, s_qd, s_XImats, s_topology_helpers, s_temp, crba_d_workspace, gravity);
                __syncthreads();
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) { reinterpret_cast<volatile T *>(d_M)[rep & 1023] = reinterpret_cast<const volatile T *>(s_M)[rep & 7]; }
            }
            // save down to global
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 324; ind += blockDim.x*blockDim.y){
                d_M[ind] = s_M[ind];
