                        s_q[3] = s_q[4]; s_q[4] = s_q[5]; s_q[5] = s_q[6]; s_q[6] = qw_in;
                    }
                    __syncthreads();
                }
                // compute
                load_update_XImats_helpers<T, true>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                crba_inner<T, false>(s_M, s_q, s_qd, s_XImats, s_topology_helpers, s_temp, crba_d_workspace, gravity);
                __syncthreads();
                if constexpr (MUJOCO_OUTPUT) {
                    // mjx output: congruence G s_M G^T (base rows then base cols)
                    if (threadIdx.x == 0 && threadIdx.y == 0) {
                        T qx = s_q[3], qy = s_q[4], qz = s_q[5], qw = s_q[6];
                        T xx = qx*qx, yy = qy*qy, zz = qz*qz;
                        T xy = qx*qy, xz = qx*qz, yz = qy*qz, wx = qw*qx, wy = qw*qy, wz = qw*qz;
                        T R[9];
                        R[0] = static_cast<T>(1) - static_cast<T>(2)*(yy+zz); R[1] = static_cast<T>(2)*(xy-wz);                    R[2] = static_cast<T>(2)*(xz+wy);
                        R[3] = static_cast<T>(2)*(xy+wz);                    R[4] = static_cast<T>(1) - static_cast<T>(2)*(xx+zz); R[5] = static_cast<T>(2)*(yz-wx);
                        R[6] = static_cast<T>(2)*(xz-wy);                    R[7] = static_cast<T>(2)*(yz+wx);                    R[8] = static_cast<T>(1) - static_cast<T>(2)*(xx+yy);
                        for (int c = 0; c < 18; c++) { T m0 = s_M[0 + 18*c], m1 = s_M[1 + 18*c], m2 = s_M[2 + 18*c]; s_M[0 + 18*c] = R[0]*m0 + R[1]*m1 + R[2]*m2; s_M[1 + 18*c] = R[3]*m0 + R[4]*m1 + R[5]*m2; s_M[2 + 18*c] = R[6]*m0 + R[7]*m1 + R[8]*m2; }
                        for (int r = 0; r < 18; r++) { T m0 = s_M[r + 18*0], m1 = s_M[r + 18*1], m2 = s_M[r + 18*2]; s_M[r + 18*0] = m0*R[0] + m1*R[1] + m2*R[2]; s_M[r + 18*1] = m0*R[3] + m1*R[4] + m2*R[5]; s_M[r + 18*2] = m0*R[6] + m1*R[7] + m2*R[8]; }
                    }
                    __syncthreads();
                }
                // save down to global
                T *d_M_k = &d_M[k*324];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 324; ind += blockDim.x*blockDim.y){
                    d_M_k[ind] = s_M[ind];
                }
                __syncthreads();
            }
        }
    }

    /**
     * Compute the CRBA (Composite Rigid Body Algorithm)
     *
     * @param hd_data is the packaged input and output pointers
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param gravity is the gravity constant,
     * @param num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
     * @param streams are pointers to CUDA streams for async memory transfers (if needed)
     */
    template <typename T, bool USE_COMPRESSED_MEM = false, gridDataKind KIND = GRID_DATA_ALL, bool MUJOCO_OUTPUT = false, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void crba(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const T gravity, const int num_timesteps,
                          const dim3 block_dimms, const dim3 thread_dimms, cudaStream_t *streams) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_DYNAMICS, "crba requires all-data or dynamics gridData");
        // start code with memory transfer
        int stride_q_qd;
        if (USE_COMPRESSED_MEM) {stride_q_qd = 2*NUM_JOINTS; gpuErrchk(cudaMemcpyAsync(hd_data->d_q_qd,hd_data->h_q_qd,stride_q_qd*num_timesteps*sizeof(T),cudaMemcpyHostToDevice,streams[0]));}
        else {stride_q_qd = 3*NUM_JOINTS; gpuErrchk(cudaMemcpyAsync(hd_data->d_q_qd_u,hd_data->h_q_qd_u,stride_q_qd*num_timesteps*sizeof(T),cudaMemcpyHostToDevice,streams[0]));}
        // then call the kernel
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("crba", CRBA_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()));
        const int _grid_ws_n = (hd_data->workspace_timestep_slots > 0 && hd_data->workspace_timestep_slots < num_timesteps) ? hd_data->workspace_timestep_slots : num_timesteps;
        dim3 _ws_grid = block_dimms;
        if ((int)(_ws_grid.x*_ws_grid.y*_ws_grid.z) > _grid_ws_n) { _ws_grid = dim3(_grid_ws_n,1,1); }
        dim3 _grid_thr_clamped_46 = grid_host_clamp_threads((const void*)&crba_kernel<T, RESOURCE_TIER, MUJOCO_OUTPUT>, thread_dimms);
        if (USE_COMPRESSED_MEM) {crba_kernel<T, RESOURCE_TIER, MUJOCO_OUTPUT><<<_ws_grid,_grid_thr_clamped_46,CRBA_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_M,hd_data->d_workspace,hd_data->d_q_qd,stride_q_qd,d_robotModel,gravity,num_timesteps);}
        else                    {crba_kernel<T, RESOURCE_TIER, MUJOCO_OUTPUT><<<_ws_grid,_grid_thr_clamped_46,CRBA_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_M,hd_data->d_workspace,hd_data->d_q_qd_u,stride_q_qd,d_robotModel,gravity,num_timesteps);}
        gpuErrchkKernel();
        // finally transfer the result back
        gpuErrchk(cudaMemcpy(hd_data->h_M,hd_data->d_M,NUM_VEL*NUM_VEL*num_timesteps*sizeof(T),cudaMemcpyDeviceToHost));
        gpuErrchkKernel();
    }

    /**
     * Compute the CRBA (Composite Rigid Body Algorithm)
     *
     * @param hd_data is the packaged input and output pointers
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param gravity is the gravity constant,
     * @param num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
     * @param streams are pointers to CUDA streams for async memory transfers (if needed)
     */
    template <typename T, bool USE_COMPRESSED_MEM = false, gridDataKind KIND = GRID_DATA_ALL, bool MUJOCO_OUTPUT = false, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void crba_single_timing(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const T gravity, const int num_timesteps,
                                        const dim3 block_dimms, const dim3 thread_dimms, cudaStream_t *streams) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_DYNAMICS, "crba requires all-data or dynamics gridData");
        // start code with memory transfer
        int stride_q_qd;
        if (USE_COMPRESSED_MEM) {stride_q_qd = 2*NUM_JOINTS; gpuErrchk(cudaMemcpyAsync(hd_data->d_q_qd,hd_data->h_q_qd,stride_q_qd*sizeof(T),cudaMemcpyHostToDevice,streams[0]));}
        else {stride_q_qd = 3*NUM_JOINTS; gpuErrchk(cudaMemcpyAsync(hd_data->d_q_qd_u,hd_data->h_q_qd_u,stride_q_qd*sizeof(T),cudaMemcpyHostToDevice,streams[0]));}
        // then call the kernel
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("crba", CRBA_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()));
        struct timespec start, end; clock_gettime(CLOCK_MONOTONIC,&start);
        dim3 _grid_thr_clamped_47 = grid_host_clamp_threads((const void*)&crba_kernel_single_timing<T, RESOURCE_TIER, MUJOCO_OUTPUT>, thread_dimms);
        if (USE_COMPRESSED_MEM) {crba_kernel_single_timing<T, RESOURCE_TIER, MUJOCO_OUTPUT><<<block_dimms,_grid_thr_clamped_47,CRBA_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_M,hd_data->d_workspace,hd_data->d_q_qd,stride_q_qd,d_robotModel,gravity,num_timesteps);}
        else                    {crba_kernel_single_timing<T, RESOURCE_TIER, MUJOCO_OUTPUT><<<block_dimms,_grid_thr_clamped_47,CRBA_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_M,hd_data->d_workspace,hd_data->d_q_qd_u,stride_q_qd,d_robotModel,gravity,num_timesteps);}
        gpuErrchkKernel();
        clock_gettime(CLOCK_MONOTONIC,&end);
        // finally transfer the result back
        gpuErrchk(cudaMemcpy(hd_data->h_M,hd_data->d_M,NUM_VEL*NUM_VEL*sizeof(T),cudaMemcpyDeviceToHost));
        gpuErrchkKernel();
        printf("Single Call CRBA %fus\n",time_delta_us_timespec(start,end)/static_cast<double>(num_timesteps));
    }

    /**
     * Compute the CRBA (Composite Rigid Body Algorithm)
     *
     * @param hd_data is the packaged input and output pointers
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param gravity is the gravity constant,
     * @param num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
     * @param streams are pointers to CUDA streams for async memory transfers (if needed)
     */
    template <typename T, bool USE_COMPRESSED_MEM = false, gridDataKind KIND = GRID_DATA_ALL, bool MUJOCO_OUTPUT = false, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void crba_compute_only(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const T gravity, const int num_timesteps,
                                       const dim3 block_dimms, const dim3 thread_dimms) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_DYNAMICS, "crba requires all-data or dynamics gridData");
        int stride_q_qd = USE_COMPRESSED_MEM ? 2*NUM_JOINTS : 3*NUM_JOINTS;
        // then call the kernel
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("crba", CRBA_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()));
        const int _grid_ws_n = (hd_data->workspace_timestep_slots > 0 && hd_data->workspace_timestep_slots < num_timesteps) ? hd_data->workspace_timestep_slots : num_timesteps;
        dim3 _ws_grid = block_dimms;
        if ((int)(_ws_grid.x*_ws_grid.y*_ws_grid.z) > _grid_ws_n) { _ws_grid = dim3(_grid_ws_n,1,1); }
        dim3 _grid_thr_clamped_48 = grid_host_clamp_threads((const void*)&crba_kernel<T, RESOURCE_TIER, MUJOCO_OUTPUT>, thread_dimms);
        if (USE_COMPRESSED_MEM) {crba_kernel<T, RESOURCE_TIER, MUJOCO_OUTPUT><<<_ws_grid,_grid_thr_clamped_48,CRBA_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_M,hd_data->d_workspace,hd_data->d_q_qd,stride_q_qd,d_robotModel,gravity,num_timesteps);}
        else                    {crba_kernel<T, RESOURCE_TIER, MUJOCO_OUTPUT><<<_ws_grid,_grid_thr_clamped_48,CRBA_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_M,hd_data->d_workspace,hd_data->d_q_qd_u,stride_q_qd,d_robotModel,gravity,num_timesteps);}
        gpuErrchkKernel();
    }

    /**
     * Finish the integrator step: write x_{k+1} from (q, qd, qdd) per the integrator type
     *
     * Notes:
     *   Assumes s_qdd is already computed for the current (s_q, s_qd, s_u)
     *   Floating-base: q-update uses an SE(3) Lie-group retract (grid_integrate_floating_q)
     *   Does not internally sync the thread group, so it should be called after all threads have finished computing their values
     *
     * @param s_x_kp1 is a pointer to memory for the next state (size NUM_POS + NUM_VEL)
     * @param s_q is the vector of joint positions (size NUM_POS)
     * @param s_qd is the vector of joint velocities (size NUM_VEL)
     * @param s_qdd is the vector of joint accelerations (size NUM_VEL, output of forward_dynamics)
     * @param dt is the integration timestep
     */
    template <typename T, IntegratorType IT>
    __device__
    void integrator_finish(T *s_x_kp1, const T *s_q, const T *s_qd, const T *s_qdd, const T dt) {
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 18; ind += blockDim.x*blockDim.y){
            s_x_kp1[19 + ind] = s_qd[ind] + dt * s_qdd[ind];
        }
        __syncthreads();
        if constexpr (IT == IntegratorType::TRAPEZOIDAL) {
            if(threadIdx.x == 0 && threadIdx.y == 0){
                T v_scaled[18];
                for (int i = 0; i < 18; ++i) v_scaled[i] = dt * s_qd[i] + static_cast<T>(0.5) * dt * dt * s_qdd[i];
                grid_integrate_floating_q<T, 19>(s_q, v_scaled, s_x_kp1);
            }
        }
        else {
            const T *s_src_v = (IT == IntegratorType::SEMI_IMPLICIT_EULER) ? &s_x_kp1[19] : s_qd;
            if(threadIdx.x == 0 && threadIdx.y == 0){
                T v_scaled[18];
                for (int i = 0; i < 18; ++i) v_scaled[i] = dt * s_src_v[i];
                grid_integrate_floating_q<T, 19>(s_q, v_scaled, s_x_kp1);
            }
        }
        static_assert(IT == IntegratorType::EULER || IT == IntegratorType::SEMI_IMPLICIT_EULER || IT == IntegratorType::TRAPEZOIDAL,
                      "integrator_finish only handles single-stage IT; multi-stage uses inner directly.");
    }

    /**
     * Computes a single integrator step (x_{k+1} = integrator(x_k, u_k, dt))
     *
     * Notes:
     *   Assumes s_XImats is updated already for the current s_q
     *   MINV_F_IN_SMEM selects where the FD inner's Minv 6*NV*NV F-region lives (s_temp vs d_workspace)
     *   For Midpoint/RK3/RK4, re-runs forward_dynamics at intermediate states and weights stage qdd outputs.
     *
     * @param s_x_kp1 is a pointer to memory for the next state (size NUM_POS + NUM_VEL)
     * @param s_q is the vector of joint positions
     * @param s_qd is the vector of joint velocities
     * @param s_u is the vector of joint input torques
     * @param s_qdd is shared memory for the stage-1 joint accelerations (size NUM_VEL)
     * @param s_stage_qdd is shared memory for stages 2..N qdd outputs (size 54)
     * @param s_stage_point is shared memory for stages 2..N intermediate (q,qd) states (size 111)
     * @param s_XImats is the (shared) memory holding the updated XI matricies for the given s_q
     * @param s_topology_helpers is the (shared) memory location for the topology_helpers (nullptr/unused for serial chains with identical Ss)
     * @param s_temp is the pointer to the shared memory needed of size: 3398
     * @param gravity is the gravity constant
     * @param dt is the integration timestep
     * @param d_workspace is the L2-pinned global scratch for the spilled Minv F-region (LITE/MINIMAL); nullptr at PERF
     * @param d_f_ext is the (optional) GLOBAL external forces, body-major 6*NUM_BODIES local-frame, or nullptr
     */
    template <typename T, IntegratorType IT, bool MINV_F_IN_SMEM = true>
    __device__
    void integrator_inner(T *s_x_kp1, const T *s_q, const T *s_qd, const T *s_u, T *s_qdd, T *s_stage_qdd, T *s_stage_point, T *s_XImats, int *s_topology_helpers, const robotModel<T> *d_robotModel, T *s_temp, T *d_workspace, T *d_f_ext, const T gravity, const T dt) {
        forward_dynamics_inner<T, MINV_F_IN_SMEM>(s_qdd, s_q, s_qd, s_u, s_XImats, s_topology_helpers, s_temp, d_workspace, d_f_ext, gravity);
        __syncthreads();
        if constexpr (IT == IntegratorType::EULER || IT == IntegratorType::SEMI_IMPLICIT_EULER || IT == IntegratorType::TRAPEZOIDAL) {
            integrator_finish<T, IT>(s_x_kp1, s_q, s_qd, s_qdd, dt);
        }
        else {
            T *s_qdd_2 = &s_stage_qdd[0];
            T *s_p1_q  = &s_stage_point[0];
            T *s_p1_qd = &s_stage_point[19];
            T *s_qdd_3 = &s_stage_qdd[18];
            T *s_p2_q  = &s_stage_point[37];
            T *s_p2_qd = &s_stage_point[56];
            T *s_qdd_4 = &s_stage_qdd[36];
            T *s_p3_q  = &s_stage_point[74];
            T *s_p3_qd = &s_stage_point[93];
            constexpr T c1 = static_cast<T>(0.5);
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 18; ind += blockDim.x*blockDim.y){
                s_p1_qd[ind] = s_qd[ind] + c1 * dt * s_qdd[ind];
            }
            __syncthreads();
            if(threadIdx.x == 0 && threadIdx.y == 0){
                T v_scaled[18];
                for (int i = 0; i < 18; ++i) v_scaled[i] = c1 * dt * s_qd[i];
                grid_integrate_floating_q<T, 19>(s_q, v_scaled, s_p1_q);
            }
            __syncthreads();
            load_update_XImats_helpers<T>(s_XImats, s_p1_q, s_topology_helpers, d_robotModel, s_temp);
            __syncthreads();
            forward_dynamics_inner<T, MINV_F_IN_SMEM>(s_qdd_2, s_p1_q, s_p1_qd, s_u, s_XImats, s_topology_helpers, s_temp, d_workspace, d_f_ext, gravity);
            __syncthreads();
            if constexpr (IT == IntegratorType::RK3 || IT == IntegratorType::RK4) {
                constexpr T c2 = (IT == IntegratorType::RK3) ? static_cast<T>(0.75) : static_cast<T>(0.5);
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 18; ind += blockDim.x*blockDim.y){
                    s_p2_qd[ind] = s_qd[ind] + c2 * dt * s_qdd_2[ind];
                }
                __syncthreads();
                if(threadIdx.x == 0 && threadIdx.y == 0){
                    T v_scaled[18];
                    for (int i = 0; i < 18; ++i) v_scaled[i] = c2 * dt * s_qd[i];
                    grid_integrate_floating_q<T, 19>(s_q, v_scaled, s_p2_q);
                }
                __syncthreads();
                load_update_XImats_helpers<T>(s_XImats, s_p2_q, s_topology_helpers, d_robotModel, s_temp);
                __syncthreads();
                forward_dynamics_inner<T, MINV_F_IN_SMEM>(s_qdd_3, s_p2_q, s_p2_qd, s_u, s_XImats, s_topology_helpers, s_temp, d_workspace, d_f_ext, gravity);
                __syncthreads();
            }
            if constexpr (IT == IntegratorType::RK4) {
                constexpr T c3 = static_cast<T>(1.0);
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 18; ind += blockDim.x*blockDim.y){
                    s_p3_qd[ind] = s_qd[ind] + c3 * dt * s_qdd_3[ind];
                }
                __syncthreads();
                if(threadIdx.x == 0 && threadIdx.y == 0){
                    T v_scaled[18];
                    for (int i = 0; i < 18; ++i) v_scaled[i] = c3 * dt * s_qd[i];
                    grid_integrate_floating_q<T, 19>(s_q, v_scaled, s_p3_q);
                }
                __syncthreads();
                load_update_XImats_helpers<T>(s_XImats, s_p3_q, s_topology_helpers, d_robotModel, s_temp);
                __syncthreads();
                forward_dynamics_inner<T, MINV_F_IN_SMEM>(s_qdd_4, s_p3_q, s_p3_qd, s_u, s_XImats, s_topology_helpers, s_temp, d_workspace, d_f_ext, gravity);
                __syncthreads();
            }
            // final assembly: v_{k+1} part — qd + dt * sum(b_i * qdd_i)
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 18; ind += blockDim.x*blockDim.y){
                T accel = static_cast<T>(0);
                if constexpr (IT == IntegratorType::MIDPOINT) {
                    accel = s_qdd_2[ind];
                } else if constexpr (IT == IntegratorType::RK3) {
                    constexpr T b1 = static_cast<T>(2.0/9.0);
                    constexpr T b2 = static_cast<T>(3.0/9.0);
                    constexpr T b3 = static_cast<T>(4.0/9.0);
                    accel = b1 * s_qdd[ind] + b2 * s_qdd_2[ind] + b3 * s_qdd_3[ind];
                } else if constexpr (IT == IntegratorType::RK4) {
                    constexpr T b1 = static_cast<T>(1.0/6.0);
                    constexpr T b2 = static_cast<T>(2.0/6.0);
                    constexpr T b3 = static_cast<T>(2.0/6.0);
                    constexpr T b4 = static_cast<T>(1.0/6.0);
                    accel = b1 * s_qdd[ind] + b2 * s_qdd_2[ind] + b3 * s_qdd_3[ind] + b4 * s_qdd_4[ind];
                }
                s_x_kp1[19 + ind] = s_qd[ind] + dt * accel;
            }
            __syncthreads();
            // q_{k+1} part — Euler-style integrate(q, dt*qd) (TrajoptPlant convention)
            if(threadIdx.x == 0 && threadIdx.y == 0){
                T v_scaled[18];
                for (int i = 0; i < 18; ++i) v_scaled[i] = dt * s_qd[i];
                grid_integrate_floating_q<T, 19>(s_q, v_scaled, s_x_kp1);
            }
        }
    }

    /**
     * Computes a single integrator step using the precomputed robotModel
     *
     * @param s_x_kp1 is a pointer to memory for the next state (size NUM_POS + NUM_VEL)
     * @param s_q is the vector of joint positions
     * @param s_qd is the vector of joint velocities
     * @param s_u is the vector of joint input torques
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param d_f_ext is the (optional) GLOBAL external forces, body-major 6*NUM_BODIES local-frame, or nullptr
     * @param gravity is the gravity constant
     * @param dt is the integration timestep
     */
    template <typename T, IntegratorType IT = IntegratorType::EULER>
    __device__
    void integrator_device(T *s_x_kp1, const T *s_q, const T *s_qd, const T *s_u, const robotModel<T> *d_robotModel, T *d_f_ext, const T gravity, const T dt) {
        // GRID shared arena layout
        //   T s_qdd[18]
        //   T s_stage_qdd[54]
        //   T s_stage_point[111]
        //   T s_XImats[936]
        //   T s_temp[3398]
        //   int s_topology_helpers[115]
        //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
        extern __shared__ __align__(16) unsigned char s_arena[];
        size_t s_arena_offset = 0;
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(18);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_stage_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(54);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_stage_point = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(111);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(936);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(3398);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
        int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(int) * static_cast<size_t>(115);
        unsigned char *s_linalg_smem = nullptr;
        if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
            s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
            s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
            s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
        }
        #ifdef GRID_CUDA_DEBUG_LAYOUT
        assert(s_arena_offset == grid_shared_arena_bytes<T>(4517, 115, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
        #endif
        (void)s_arena_offset;
        load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
        integrator_inner<T, IT, true>(s_x_kp1, s_q, s_qd, s_u, s_qdd, s_stage_qdd, s_stage_point, s_XImats, s_topology_helpers, d_robotModel, s_temp, nullptr, d_f_ext, gravity, dt);
    }

    /**
     * Computes a single integrator step per timestep (Euler by default)
     *
     * @param d_x_kp1 is a pointer to memory for the next state (size 2*NUM_VEL per timestep)
     * @param d_workspace is the L2-pinned global scratch for the spilled Minv F-region (LITE/MINIMAL tiers)
     * @param d_q_qd_u is the packed joint positions, velocities, and input torques
     * @param stride_q_qd_u is the stride between each (q, qd, u) tuple in d_q_qd_u
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU
     * @param d_f_ext is the (optional) GLOBAL external forces, body-major 6*NUM_BODIES local-frame, or nullptr
     * @param gravity is the gravity constant
     * @param dt is the integration timestep
     * @param num_timesteps is the length of the trajectory (or overloaded as test_iters for timing)
     */
    template <typename T, IntegratorType IT = IntegratorType::EULER, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER, bool MUJOCO_OUTPUT = false>
    __global__
    __launch_bounds__(MAX_PERF_LEVEL_THREADS)
    void integrator_kernel_single_timing(T *d_x_kp1, unsigned char *d_workspace, const T *d_q_qd_u, const int stride_q_qd_u, const robotModel<T> *d_robotModel, T *d_f_ext, const T gravity, const T dt, const int NUM_TIMESTEPS) {
        if constexpr (RESOURCE_TIER == TIER_SHARED) {
            // GRID shared arena layout
            //   T s_q_qd_u[57]
            //   T s_qdd[18]
            //   T s_stage_qdd[54]
            //   T s_stage_point[111]
            //   T s_x_kp1[37]
            //   T s_XImats[936]
            //   T s_temp[3398]
            //   int s_topology_helpers[115]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q_qd_u = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(57);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(18);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_stage_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(54);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_stage_point = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(111);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_x_kp1 = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(37);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(936);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(3398);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
            int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(int) * static_cast<size_t>(115);
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(4611, 115, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            T *s_q = s_q_qd_u; T *s_qd = &s_q_qd_u[19]; T *s_u = &s_q_qd_u[38];
            // load to shared mem
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 57; ind += blockDim.x*blockDim.y){
                s_q_qd_u[ind] = d_q_qd_u[ind];
            }
            __syncthreads();
            (void)d_workspace;
            // compute with NUM_TIMESTEPS as NUM_REPS for timing
            for (int rep = 0; rep < NUM_TIMESTEPS; rep++){
                // anti-LICM: volatile reload of inputs each rep
                for(int _aopt_i = threadIdx.x + threadIdx.y*blockDim.x; _aopt_i < 57; _aopt_i += blockDim.x*blockDim.y){
                    reinterpret_cast<volatile T *>(s_q_qd_u)[_aopt_i] = reinterpret_cast<const volatile T *>(d_q_qd_u)[_aopt_i];
                }
                __syncthreads();
                // anti-LICM (1/2): stomp one input slot with `rep`
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    reinterpret_cast<volatile T *>(s_q_qd_u)[rep % (57)] = static_cast<T>(rep);
                }
                // anti-LICM (2/2): feedback prev rep's d_x_kp1 into s_q_qd_u (true loop-carried dep)
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    T _aopt_fb1 = reinterpret_cast<const volatile T *>(d_x_kp1)[(rep + 0x3FF) & 0x3FF];
                    T _aopt_fb2 = reinterpret_cast<const volatile T *>(d_x_kp1)[(rep + 0x3FE) & 0x3FF];
                    T _aopt_fb3 = reinterpret_cast<const volatile T *>(d_x_kp1)[(rep + 0x3FD) & 0x3FF];
                    reinterpret_cast<volatile T *>(s_q_qd_u)[(rep + 1) % (57)] += _aopt_fb1;
                    reinterpret_cast<volatile T *>(s_q_qd_u)[(rep + 2) % (57)] += _aopt_fb2;
                    reinterpret_cast<volatile T *>(s_q_qd_u)[(rep + 3) % (57)] += _aopt_fb3;
                }
                __syncthreads();
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                integrator_inner<T, IT, true>(s_x_kp1, s_q, s_qd, s_u, s_qdd, s_stage_qdd, s_stage_point, s_XImats, s_topology_helpers, d_robotModel, s_temp, nullptr, d_f_ext, gravity, dt);
                __syncthreads();
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) { reinterpret_cast<volatile T *>(d_x_kp1)[rep & 1023] = reinterpret_cast<const volatile T *>(s_x_kp1)[rep & 7]; }
            }
            // save down to global
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 37; ind += blockDim.x*blockDim.y){
                d_x_kp1[ind] = s_x_kp1[ind];
            }
            __syncthreads();
        }
        else if constexpr (RESOURCE_TIER == TIER_LITE) {
            // GRID shared arena layout
            //   T s_q_qd_u[57]
            //   T s_qdd[18]
            //   T s_stage_qdd[54]
            //   T s_stage_point[111]
            //   T s_x_kp1[37]
            //   T s_XImats[936]
            //   T s_temp[3398]
            //   int s_topology_helpers[115]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q_qd_u = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(57);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(18);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_stage_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(54);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_stage_point = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(111);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_x_kp1 = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(37);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(936);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(3398);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
            int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(int) * static_cast<size_t>(115);
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(4611, 115, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            T *s_q = s_q_qd_u; T *s_qd = &s_q_qd_u[19]; T *s_u = &s_q_qd_u[38];
            // load to shared mem
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 57; ind += blockDim.x*blockDim.y){
                s_q_qd_u[ind] = d_q_qd_u[ind];
            }
            __syncthreads();
            (void)d_workspace;
            // compute with NUM_TIMESTEPS as NUM_REPS for timing
            for (int rep = 0; rep < NUM_TIMESTEPS; rep++){
                // anti-LICM: volatile reload of inputs each rep
                for(int _aopt_i = threadIdx.x + threadIdx.y*blockDim.x; _aopt_i < 57; _aopt_i += blockDim.x*blockDim.y){
                    reinterpret_cast<volatile T *>(s_q_qd_u)[_aopt_i] = reinterpret_cast<const volatile T *>(d_q_qd_u)[_aopt_i];
                }
                __syncthreads();
                // anti-LICM (1/2): stomp one input slot with `rep`
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    reinterpret_cast<volatile T *>(s_q_qd_u)[rep % (57)] = static_cast<T>(rep);
                }
                // anti-LICM (2/2): feedback prev rep's d_x_kp1 into s_q_qd_u (true loop-carried dep)
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    T _aopt_fb1 = reinterpret_cast<const volatile T *>(d_x_kp1)[(rep + 0x3FF) & 0x3FF];
                    T _aopt_fb2 = reinterpret_cast<const volatile T *>(d_x_kp1)[(rep + 0x3FE) & 0x3FF];
                    T _aopt_fb3 = reinterpret_cast<const volatile T *>(d_x_kp1)[(rep + 0x3FD) & 0x3FF];
                    reinterpret_cast<volatile T *>(s_q_qd_u)[(rep + 1) % (57)] += _aopt_fb1;
                    reinterpret_cast<volatile T *>(s_q_qd_u)[(rep + 2) % (57)] += _aopt_fb2;
                    reinterpret_cast<volatile T *>(s_q_qd_u)[(rep + 3) % (57)] += _aopt_fb3;
                }
                __syncthreads();
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                integrator_inner<T, IT, true>(s_x_kp1, s_q, s_qd, s_u, s_qdd, s_stage_qdd, s_stage_point, s_XImats, s_topology_helpers, d_robotModel, s_temp, nullptr, d_f_ext, gravity, dt);
                __syncthreads();
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) { reinterpret_cast<volatile T *>(d_x_kp1)[rep & 1023] = reinterpret_cast<const volatile T *>(s_x_kp1)[rep & 7]; }
            }
            // save down to global
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 37; ind += blockDim.x*blockDim.y){
                d_x_kp1[ind] = s_x_kp1[ind];
            }
            __syncthreads();
        }
        else if constexpr (RESOURCE_TIER == TIER_MINIMAL) {
            // GRID shared arena layout
            //   T s_q_qd_u[57]
            //   T s_qdd[18]
            //   T s_stage_qdd[54]
            //   T s_stage_point[111]
            //   T s_x_kp1[37]
            //   T s_XImats[936]
            //   T s_temp[1454]
            //   int s_topology_helpers[115]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q_qd_u = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(57);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(18);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_stage_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(54);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_stage_point = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(111);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_x_kp1 = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(37);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(936);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(1454);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
            int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(int) * static_cast<size_t>(115);
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(2667, 115, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            T *s_q = s_q_qd_u; T *s_qd = &s_q_qd_u[19]; T *s_u = &s_q_qd_u[38];
            // load to shared mem
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 57; ind += blockDim.x*blockDim.y){
                s_q_qd_u[ind] = d_q_qd_u[ind];
            }
            __syncthreads();
            T *int_d_workspace = reinterpret_cast<T *>(&d_workspace[GRID_MINV_F_WORKSPACE_OFFSET_BYTES<T>()]);
            // compute with NUM_TIMESTEPS as NUM_REPS for timing
            for (int rep = 0; rep < NUM_TIMESTEPS; rep++){
                // anti-LICM: volatile reload of inputs each rep
                for(int _aopt_i = threadIdx.x + threadIdx.y*blockDim.x; _aopt_i < 57; _aopt_i += blockDim.x*blockDim.y){
                    reinterpret_cast<volatile T *>(s_q_qd_u)[_aopt_i] = reinterpret_cast<const volatile T *>(d_q_qd_u)[_aopt_i];
                }
                __syncthreads();
                // anti-LICM (1/2): stomp one input slot with `rep`
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    reinterpret_cast<volatile T *>(s_q_qd_u)[rep % (57)] = static_cast<T>(rep);
                }
                // anti-LICM (2/2): feedback prev rep's d_x_kp1 into s_q_qd_u (true loop-carried dep)
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    T _aopt_fb1 = reinterpret_cast<const volatile T *>(d_x_kp1)[(rep + 0x3FF) & 0x3FF];
                    T _aopt_fb2 = reinterpret_cast<const volatile T *>(d_x_kp1)[(rep + 0x3FE) & 0x3FF];
                    T _aopt_fb3 = reinterpret_cast<const volatile T *>(d_x_kp1)[(rep + 0x3FD) & 0x3FF];
                    reinterpret_cast<volatile T *>(s_q_qd_u)[(rep + 1) % (57)] += _aopt_fb1;
                    reinterpret_cast<volatile T *>(s_q_qd_u)[(rep + 2) % (57)] += _aopt_fb2;
                    reinterpret_cast<volatile T *>(s_q_qd_u)[(rep + 3) % (57)] += _aopt_fb3;
                }
                __syncthreads();
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                integrator_inner<T, IT, false>(s_x_kp1, s_q, s_qd, s_u, s_qdd, s_stage_qdd, s_stage_point, s_XImats, s_topology_helpers, d_robotModel, s_temp, int_d_workspace, d_f_ext, gravity, dt);
                __syncthreads();
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) { reinterpret_cast<volatile T *>(d_x_kp1)[rep & 1023] = reinterpret_cast<const volatile T *>(s_x_kp1)[rep & 7]; }
            }
            // save down to global
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 37; ind += blockDim.x*blockDim.y){
                d_x_kp1[ind] = s_x_kp1[ind];
            }
            __syncthreads();
        }
    }

    /**
     * Computes a single integrator step per timestep (Euler by default)
     *
     * @param d_x_kp1 is a pointer to memory for the next state (size 2*NUM_VEL per timestep)
     * @param d_workspace is the L2-pinned global scratch for the spilled Minv F-region (LITE/MINIMAL tiers)
     * @param d_q_qd_u is the packed joint positions, velocities, and input torques
     * @param stride_q_qd_u is the stride between each (q, qd, u) tuple in d_q_qd_u
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU
     * @param d_f_ext is the (optional) GLOBAL external forces, body-major 6*NUM_BODIES local-frame, or nullptr
     * @param gravity is the gravity constant
     * @param dt is the integration timestep
     * @param num_timesteps is the length of the trajectory (or overloaded as test_iters for timing)
     */
    template <typename T, IntegratorType IT = IntegratorType::EULER, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER, bool MUJOCO_OUTPUT = false>
    __global__
    __launch_bounds__(MAX_PERF_LEVEL_THREADS)
    void integrator_kernel(T *d_x_kp1, unsigned char *d_workspace, const T *d_q_qd_u, const int stride_q_qd_u, const robotModel<T> *d_robotModel, T *d_f_ext, const T gravity, const T dt, const int NUM_TIMESTEPS) {
        if constexpr (RESOURCE_TIER == TIER_SHARED) {
            // GRID shared arena layout
            //   T s_q_qd_u[57]
            //   T s_qdd[18]
            //   T s_stage_qdd[54]
            //   T s_stage_point[111]
            //   T s_x_kp1[37]
            //   T s_XImats[936]
            //   T s_temp[3398]
            //   int s_topology_helpers[115]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q_qd_u = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(57);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(18);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_stage_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(54);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_stage_point = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(111);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_x_kp1 = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(37);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(936);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(3398);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
            int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(int) * static_cast<size_t>(115);
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(4611, 115, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            T *s_q = s_q_qd_u; T *s_qd = &s_q_qd_u[19]; T *s_u = &s_q_qd_u[38];
            for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
                // load to shared mem
                const T *d_q_qd_u_k = &d_q_qd_u[k*stride_q_qd_u];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 57; ind += blockDim.x*blockDim.y){
                    s_q_qd_u[ind] = d_q_qd_u_k[ind];
                }
                __syncthreads();
                (void)d_workspace;
                if constexpr (MUJOCO_OUTPUT) {
                    // mjx input convert: base quaternion wxyz->xyzw (q-only; value frame-independent)
                    if (threadIdx.x == 0 && threadIdx.y == 0) {
                        T qw_in = s_q[3];
                        s_q[3] = s_q[4]; s_q[4] = s_q[5]; s_q[5] = s_q[6]; s_q[6] = qw_in;
                    }
                    __syncthreads();
                }
                // compute
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                integrator_inner<T, IT, true>(s_x_kp1, s_q, s_qd, s_u, s_qdd, s_stage_qdd, s_stage_point, s_XImats, s_topology_helpers, d_robotModel, s_temp, nullptr, d_f_ext, gravity, dt);
                __syncthreads();
                if constexpr (MUJOCO_OUTPUT) {
                    // mjx retract: base position global additive step (q_out[0:3] = q_in[0:3] + dt*qd[0:3])
                    if (threadIdx.x == 0 && threadIdx.y == 0) {
                        s_x_kp1[0] = s_q[0] + (dt) * s_qd[0];
                        s_x_kp1[1] = s_q[1] + (dt) * s_qd[1];
                        s_x_kp1[2] = s_q[2] + (dt) * s_qd[2];
                    }
                    __syncthreads();
                    // mjx output: base quaternion xyzw->wxyz (inverse of input reorder)
                    if (threadIdx.x == 0 && threadIdx.y == 0) {
                        T qw_out = s_x_kp1[6];
                        s_x_kp1[6] = s_x_kp1[5]; s_x_kp1[5] = s_x_kp1[4]; s_x_kp1[4] = s_x_kp1[3]; s_x_kp1[3] = qw_out;
                    }
                    __syncthreads();
                }
                // save down to global
                T *d_x_kp1_k = &d_x_kp1[k*37];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 37; ind += blockDim.x*blockDim.y){
                    d_x_kp1_k[ind] = s_x_kp1[ind];
                }
                __syncthreads();
            }
        }
        else if constexpr (RESOURCE_TIER == TIER_LITE) {
            // GRID shared arena layout
            //   T s_q_qd_u[57]
            //   T s_qdd[18]
            //   T s_stage_qdd[54]
            //   T s_stage_point[111]
            //   T s_x_kp1[37]
            //   T s_XImats[936]
            //   T s_temp[3398]
            //   int s_topology_helpers[115]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q_qd_u = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(57);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(18);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_stage_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(54);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_stage_point = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(111);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_x_kp1 = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(37);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(936);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(3398);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
            int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(int) * static_cast<size_t>(115);
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(4611, 115, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            T *s_q = s_q_qd_u; T *s_qd = &s_q_qd_u[19]; T *s_u = &s_q_qd_u[38];
            for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
                // load to shared mem
                const T *d_q_qd_u_k = &d_q_qd_u[k*stride_q_qd_u];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 57; ind += blockDim.x*blockDim.y){
                    s_q_qd_u[ind] = d_q_qd_u_k[ind];
                }
                __syncthreads();
                (void)d_workspace;
                if constexpr (MUJOCO_OUTPUT) {
                    // mjx input convert: base quaternion wxyz->xyzw (q-only; value frame-independent)
                    if (threadIdx.x == 0 && threadIdx.y == 0) {
                        T qw_in = s_q[3];
                        s_q[3] = s_q[4]; s_q[4] = s_q[5]; s_q[5] = s_q[6]; s_q[6] = qw_in;
                    }
                    __syncthreads();
                }
                // compute
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                integrator_inner<T, IT, true>(s_x_kp1, s_q, s_qd, s_u, s_qdd, s_stage_qdd, s_stage_point, s_XImats, s_topology_helpers, d_robotModel, s_temp, nullptr, d_f_ext, gravity, dt);
                __syncthreads();
                if constexpr (MUJOCO_OUTPUT) {
                    // mjx retract: base position global additive step (q_out[0:3] = q_in[0:3] + dt*qd[0:3])
                    if (threadIdx.x == 0 && threadIdx.y == 0) {
                        s_x_kp1[0] = s_q[0] + (dt) * s_qd[0];
                        s_x_kp1[1] = s_q[1] + (dt) * s_qd[1];
                        s_x_kp1[2] = s_q[2] + (dt) * s_qd[2];
                    }
                    __syncthreads();
                    // mjx output: base quaternion xyzw->wxyz (inverse of input reorder)
                    if (threadIdx.x == 0 && threadIdx.y == 0) {
                        T qw_out = s_x_kp1[6];
                        s_x_kp1[6] = s_x_kp1[5]; s_x_kp1[5] = s_x_kp1[4]; s_x_kp1[4] = s_x_kp1[3]; s_x_kp1[3] = qw_out;
                    }
                    __syncthreads();
                }
                // save down to global
                T *d_x_kp1_k = &d_x_kp1[k*37];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 37; ind += blockDim.x*blockDim.y){
                    d_x_kp1_k[ind] = s_x_kp1[ind];
                }
                __syncthreads();
            }
        }
        else if constexpr (RESOURCE_TIER == TIER_MINIMAL) {
            // GRID shared arena layout
            //   T s_q_qd_u[57]
            //   T s_qdd[18]
            //   T s_stage_qdd[54]
            //   T s_stage_point[111]
            //   T s_x_kp1[37]
            //   T s_XImats[936]
            //   T s_temp[1454]
            //   int s_topology_helpers[115]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q_qd_u = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(57);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(18);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_stage_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(54);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_stage_point = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(111);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_x_kp1 = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(37);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(936);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(1454);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
            int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(int) * static_cast<size_t>(115);
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(2667, 115, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            T *s_q = s_q_qd_u; T *s_qd = &s_q_qd_u[19]; T *s_u = &s_q_qd_u[38];
            for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
                // load to shared mem
                const T *d_q_qd_u_k = &d_q_qd_u[k*stride_q_qd_u];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 57; ind += blockDim.x*blockDim.y){
                    s_q_qd_u[ind] = d_q_qd_u_k[ind];
                }
                __syncthreads();
                T *int_d_workspace = reinterpret_cast<T *>(&d_workspace[grid_workspace_slot()*GRID_WORKSPACE_BYTES_PER_TIMESTEP<T>() + GRID_MINV_F_WORKSPACE_OFFSET_BYTES<T>()]);
                if constexpr (MUJOCO_OUTPUT) {
                    // mjx input convert: base quaternion wxyz->xyzw (q-only; value frame-independent)
                    if (threadIdx.x == 0 && threadIdx.y == 0) {
                        T qw_in = s_q[3];
                        s_q[3] = s_q[4]; s_q[4] = s_q[5]; s_q[5] = s_q[6]; s_q[6] = qw_in;
                    }
                    __syncthreads();
                }
                // compute
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                integrator_inner<T, IT, false>(s_x_kp1, s_q, s_qd, s_u, s_qdd, s_stage_qdd, s_stage_point, s_XImats, s_topology_helpers, d_robotModel, s_temp, int_d_workspace, d_f_ext, gravity, dt);
                __syncthreads();
                if constexpr (MUJOCO_OUTPUT) {
                    // mjx retract: base position global additive step (q_out[0:3] = q_in[0:3] + dt*qd[0:3])
                    if (threadIdx.x == 0 && threadIdx.y == 0) {
                        s_x_kp1[0] = s_q[0] + (dt) * s_qd[0];
                        s_x_kp1[1] = s_q[1] + (dt) * s_qd[1];
                        s_x_kp1[2] = s_q[2] + (dt) * s_qd[2];
                    }
                    __syncthreads();
                    // mjx output: base quaternion xyzw->wxyz (inverse of input reorder)
                    if (threadIdx.x == 0 && threadIdx.y == 0) {
                        T qw_out = s_x_kp1[6];
                        s_x_kp1[6] = s_x_kp1[5]; s_x_kp1[5] = s_x_kp1[4]; s_x_kp1[4] = s_x_kp1[3]; s_x_kp1[3] = qw_out;
                    }
                    __syncthreads();
                }
                // save down to global
                T *d_x_kp1_k = &d_x_kp1[k*37];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 37; ind += blockDim.x*blockDim.y){
                    d_x_kp1_k[ind] = s_x_kp1[ind];
                }
                __syncthreads();
            }
        }
    }

    /**
     * Run a single integrator step (default Euler) per timestep
     *
     * @param hd_data is the packaged input and output pointers
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU
     * @param gravity is the gravity constant
     * @param dt is the integration timestep
     * @param num_timesteps is the length of the trajectory (or overloaded as test_iters for timing)
     * @param streams are pointers to CUDA streams for async memory transfers (if needed)
     */
    template <typename T, IntegratorType IT = IntegratorType::EULER, gridDataKind KIND = GRID_DATA_ALL, bool MUJOCO_OUTPUT = false, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void integrator(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const T gravity, const T dt, const int num_timesteps,
                      const dim3 block_dimms, const dim3 thread_dimms, cudaStream_t *streams) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_DYNAMICS, "integrator requires all-data or dynamics gridData");
        int stride_q_qd_u = 3*NUM_JOINTS;
        // start code with memory transfer
        gpuErrchk(cudaMemcpyAsync(hd_data->d_q_qd_u,hd_data->h_q_qd_u,stride_q_qd_u*num_timesteps*sizeof(T),cudaMemcpyHostToDevice,streams[0]));
        gpuErrchkKernel();
        // then call the kernel
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("integrator", INTEGRATOR_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()));
        const int _grid_ws_n = (hd_data->workspace_timestep_slots > 0 && hd_data->workspace_timestep_slots < num_timesteps) ? hd_data->workspace_timestep_slots : num_timesteps;
        if (GRID_INTEGRATOR_USES_WORKSPACE) {gpuErrchk(grid_begin_l2_persisting(0, hd_data->d_workspace, GRID_WORKSPACE_BYTES_PER_TIMESTEP<T>()*static_cast<size_t>(_grid_ws_n)));}
        dim3 _ws_grid = block_dimms;
        if ((int)(_ws_grid.x*_ws_grid.y*_ws_grid.z) > _grid_ws_n) { _ws_grid = dim3(_grid_ws_n,1,1); }
        dim3 _grid_thr_clamped_49 = grid_host_clamp_threads((const void*)&integrator_kernel<T, IT, RESOURCE_TIER, MUJOCO_OUTPUT>, thread_dimms);
        integrator_kernel<T, IT, RESOURCE_TIER, MUJOCO_OUTPUT><<<_ws_grid,_grid_thr_clamped_49,INTEGRATOR_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_x_kp1,hd_data->d_workspace,hd_data->d_q_qd_u,stride_q_qd_u,d_robotModel,hd_data->d_f_ext,gravity,dt,num_timesteps);
        gpuErrchkKernel();
        if (GRID_INTEGRATOR_USES_WORKSPACE) {gpuErrchk(grid_end_l2_persisting(0));}
        // finally transfer the result back
        gpuErrchk(cudaMemcpy(hd_data->h_x_kp1,hd_data->d_x_kp1,(NUM_POS + NUM_VEL)*num_timesteps*sizeof(T),cudaMemcpyDeviceToHost));
        gpuErrchkKernel();
    }

    /**
     * Run a single integrator step (default Euler) per timestep
     *
     * @param hd_data is the packaged input and output pointers
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU
     * @param gravity is the gravity constant
     * @param dt is the integration timestep
     * @param num_timesteps is the length of the trajectory (or overloaded as test_iters for timing)
     * @param streams are pointers to CUDA streams for async memory transfers (if needed)
     */
    template <typename T, IntegratorType IT = IntegratorType::EULER, gridDataKind KIND = GRID_DATA_ALL, bool MUJOCO_OUTPUT = false, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void integrator_single_timing(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const T gravity, const T dt, const int num_timesteps,
                                    const dim3 block_dimms, const dim3 thread_dimms, cudaStream_t *streams) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_DYNAMICS, "integrator requires all-data or dynamics gridData");
        int stride_q_qd_u = 3*NUM_JOINTS;
        // start code with memory transfer
        gpuErrchk(cudaMemcpyAsync(hd_data->d_q_qd_u,hd_data->h_q_qd_u,stride_q_qd_u*sizeof(T),cudaMemcpyHostToDevice,streams[0]));
        gpuErrchkKernel();
        // then call the kernel
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("integrator", INTEGRATOR_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()));
        if (GRID_INTEGRATOR_USES_WORKSPACE) {gpuErrchk(grid_begin_l2_persisting(0, hd_data->d_workspace, GRID_WORKSPACE_BYTES_PER_TIMESTEP<T>()));}
        struct timespec start, end; clock_gettime(CLOCK_MONOTONIC,&start);
        dim3 _grid_thr_clamped_50 = grid_host_clamp_threads((const void*)&integrator_kernel_single_timing<T, IT, RESOURCE_TIER, MUJOCO_OUTPUT>, thread_dimms);
        integrator_kernel_single_timing<T, IT, RESOURCE_TIER, MUJOCO_OUTPUT><<<block_dimms,_grid_thr_clamped_50,INTEGRATOR_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_x_kp1,hd_data->d_workspace,hd_data->d_q_qd_u,stride_q_qd_u,d_robotModel,hd_data->d_f_ext,gravity,dt,num_timesteps);
        gpuErrchkKernel();
        clock_gettime(CLOCK_MONOTONIC,&end);
        if (GRID_INTEGRATOR_USES_WORKSPACE) {gpuErrchk(grid_end_l2_persisting(0));}
        // finally transfer the result back
        gpuErrchk(cudaMemcpy(hd_data->h_x_kp1,hd_data->d_x_kp1,(NUM_POS + NUM_VEL)*sizeof(T),cudaMemcpyDeviceToHost));
        gpuErrchkKernel();
        printf("Single Call INTEGRATOR %fus\n",time_delta_us_timespec(start,end)/static_cast<double>(num_timesteps));
    }

    /**
     * Run a single integrator step (default Euler) per timestep
     *
     * @param hd_data is the packaged input and output pointers
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU
     * @param gravity is the gravity constant
     * @param dt is the integration timestep
     * @param num_timesteps is the length of the trajectory (or overloaded as test_iters for timing)
     * @param streams are pointers to CUDA streams for async memory transfers (if needed)
     */
    template <typename T, IntegratorType IT = IntegratorType::EULER, gridDataKind KIND = GRID_DATA_ALL, bool MUJOCO_OUTPUT = false, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void integrator_compute_only(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const T gravity, const T dt, const int num_timesteps,
                                   const dim3 block_dimms, const dim3 thread_dimms) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_DYNAMICS, "integrator requires all-data or dynamics gridData");
        int stride_q_qd_u = 3*NUM_JOINTS;
        // then call the kernel
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("integrator", INTEGRATOR_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()));
        const int _grid_ws_n = (hd_data->workspace_timestep_slots > 0 && hd_data->workspace_timestep_slots < num_timesteps) ? hd_data->workspace_timestep_slots : num_timesteps;
        if (GRID_INTEGRATOR_USES_WORKSPACE) {gpuErrchk(grid_begin_l2_persisting(0, hd_data->d_workspace, GRID_WORKSPACE_BYTES_PER_TIMESTEP<T>()*static_cast<size_t>(_grid_ws_n)));}
        dim3 _ws_grid = block_dimms;
        if ((int)(_ws_grid.x*_ws_grid.y*_ws_grid.z) > _grid_ws_n) { _ws_grid = dim3(_grid_ws_n,1,1); }
        dim3 _grid_thr_clamped_51 = grid_host_clamp_threads((const void*)&integrator_kernel<T, IT, RESOURCE_TIER, MUJOCO_OUTPUT>, thread_dimms);
        integrator_kernel<T, IT, RESOURCE_TIER, MUJOCO_OUTPUT><<<_ws_grid,_grid_thr_clamped_51,INTEGRATOR_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_x_kp1,hd_data->d_workspace,hd_data->d_q_qd_u,stride_q_qd_u,d_robotModel,hd_data->d_f_ext,gravity,dt,num_timesteps);
        gpuErrchkKernel();
        if (GRID_INTEGRATOR_USES_WORKSPACE) {gpuErrchk(grid_end_l2_persisting(0));}
    }

    /**
     * integrator_arena: carve struct mirroring the integrator kernel's TIER_SHARED shared-arena layout; allocate INTEGRATOR_DYNAMIC_SHARED_MEM_BYTES<T, TIER_SHARED>() bytes (e.g. an external solver's own smem block) and call carve(base).
     *
     */
    template <typename T>
    struct integrator_arena {
        T *s_q_qd_u;
        T *s_qdd;
        T *s_stage_qdd;
        T *s_stage_point;
        T *s_x_kp1;
        T *s_XImats;
        T *s_temp;
        int *s_topology_helpers;
        unsigned char *s_linalg_smem;
        static __device__ integrator_arena<T> carve(void *base) {
            unsigned char *s_arena = reinterpret_cast<unsigned char *>(base);
            size_t s_arena_offset = 0;
            integrator_arena<T> a;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            a.s_q_qd_u = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(57);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            a.s_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(18);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            a.s_stage_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(54);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            a.s_stage_point = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(111);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            a.s_x_kp1 = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(37);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            a.s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(936);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            a.s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(3398);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
            a.s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(int) * static_cast<size_t>(115);
            a.s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                a.s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset <= INTEGRATOR_DYNAMIC_SHARED_MEM_BYTES<T, TIER_SHARED>());
            #endif
            (void)s_arena_offset;
            return a;
        }
    };

    /**
     * integrator gradient orchestration as a single inner-owns-placement device function
     *
     * Notes:
     *   Owns the FD-grad inner s_temp pool placement; the repoint covers every consumer below (incl. the XImats helper's sincos scratch and the per-stage XImats refresh)
     *
     * @param s_dAB is the output [A | B] buffer (caller places); size 2*NUM_VEL*3*NUM_VEL = 1944
     * @param s_q is the vector of joint positions (NON-const: mutated across RK stages)
     * @param s_qd is the vector of joint velocities (NON-const: mutated across RK stages)
     * @param s_u is the vector of joint input torques
     * @param s_df_du / s_dc_du / s_vaf / s_Minv / s_qdd are FD-grad in/out scratch (caller places)
     * @param s_q_orig / s_qd_orig / s_stage_grad_qdd / s_D_qdd_stage are multi-stage scratch (caller places; s_D_qdd_stage is a de-aliased workspace band when spilled)
     * @param s_dInt_q_6x6 / s_dInt_v_6x6 are the floating-base SE(3) dIntegrate blocks (unused fixed-base)
     * @param s_temp is the FD-grad inner scratch pool (used when SCRATCH_IN_SMEM)
     * @param d_workspace is the global scratch pool the FD-grad inner s_temp routes to (used when !SCRATCH_IN_SMEM)
     * @param d_temp_spill is the inverse_dynamics_gradient da_df band spill region (used when USE_DA_DF_SPILL)
     * @param s_XImats is the (shared) memory holding the updated XI matricies for the given s_q
     * @param s_topology_helpers is the (shared) memory location for the topology_helpers (nullptr/unused for serial chains with identical Ss)
     * @param d_robotModel holds XImats/topology; gravity is the gravity constant; dt is the timestep
     * @param d_f_ext is the (optional) GLOBAL external forces, body-major 6*NUM_BODIES local-frame, or nullptr
     */
    template <typename T, IntegratorType IT = IntegratorType::EULER, bool SCRATCH_IN_SMEM = true, bool USE_DA_DF_SPILL = false, bool MUJOCO_OUTPUT = false>
    __device__ __forceinline__
    void integrator_gradient_device(T *s_dAB, T *s_q, T *s_qd, const T *s_u, T *s_df_du, T *s_dc_du, T *s_vaf, T *s_Minv, T *s_qdd, T *s_q_orig, T *s_qd_orig, T *s_stage_grad_qdd, T *s_D_qdd_stage, T *s_dInt_q_6x6, T *s_dInt_v_6x6, T *s_XImats, int *s_topology_helpers, T *s_temp, T *d_workspace, T *d_temp_spill, const robotModel<T> *d_robotModel, T *d_f_ext, const T gravity, const T dt) {
        if constexpr(!SCRATCH_IN_SMEM){ s_temp = d_workspace; } else { (void)d_workspace; }
        load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
        if constexpr (IT == IntegratorType::EULER || IT == IntegratorType::SEMI_IMPLICIT_EULER || IT == IntegratorType::TRAPEZOIDAL) {
            //TODO: there is a slightly faster way as s_v does not change -- thus no recompute needed
            minv_inner<T, true>(s_Minv, s_q, s_XImats, s_topology_helpers, s_temp, nullptr);
            inverse_dynamics_inner<T>(s_temp, s_vaf, s_q, s_qd, s_XImats, s_topology_helpers, &s_temp[18], d_f_ext, gravity);
            forward_dynamics_finish<T>(s_qdd, s_u, s_temp, s_Minv);
            __syncthreads();
            inverse_dynamics_inner_vaf<T>(s_vaf, s_q, s_qd, s_qdd, s_XImats, s_topology_helpers, s_temp, d_f_ext, gravity);
            inverse_dynamics_gradient_inner<T, USE_DA_DF_SPILL>(s_dc_du, s_q, s_qd, s_vaf, s_XImats, s_topology_helpers, s_temp, d_temp_spill, gravity);
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 648; ind += blockDim.x*blockDim.y){
                int row = ind % 18; int dc_col_offset = ind - row;
                // account for the fact that Minv is an SYMMETRIC_UPPER triangular matrix
                T val = static_cast<T>(0);
                for(int col = 0; col < 18; col++) {
                    int index = (row <= col) * (col * 18 + row) + (row > col) * (row * 18 + col);
                    val += s_Minv[index] * s_dc_du[dc_col_offset + col];
                }
                s_df_du[ind] = -val;
            }
            __syncthreads();
            if(threadIdx.x == 0 && threadIdx.y == 0){
                T v_dt_for_dInt[18];
                if constexpr (IT == IntegratorType::SEMI_IMPLICIT_EULER) {
                    for (int i = 0; i < 18; ++i) v_dt_for_dInt[i] = dt * (s_qd[i] + dt * s_qdd[i]);
                } else if constexpr (IT == IntegratorType::TRAPEZOIDAL) {
                    for (int i = 0; i < 18; ++i) v_dt_for_dInt[i] = dt * s_qd[i] + static_cast<T>(0.5) * dt * dt * s_qdd[i];
                } else {
                    for (int i = 0; i < 18; ++i) v_dt_for_dInt[i] = dt * s_qd[i];
                }
                grid_dIntegrate_q_block<T>(v_dt_for_dInt, s_dInt_q_6x6);
                grid_dIntegrate_v_block<T>(v_dt_for_dInt, s_dInt_v_6x6);
            }
            __syncthreads();
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 1944; ind += blockDim.x*blockDim.y){
                int row = ind % 36;
                int col = ind / 36;
                if constexpr (IT == IntegratorType::EULER) {
                    T val = static_cast<T>(0);
                    if (col < 18) {
                        // d/dq column
                        if (row < 18) {
                            if (row < 6 && col < 6) {
                                val = s_dInt_q_6x6[row * 6 + col];
                            } else if (row >= 6 && col >= 6) {
                                val = (row == col) ? static_cast<T>(1) : static_cast<T>(0);
                            } else { val = static_cast<T>(0); }
                        } else {
                            int i_local = row - 18;
                            val = dt * s_df_du[col * 18 + i_local];
                        }
                    } else if (col < 36) {
                        // d/dqd column
                        int j_local = col - 18;
                        if (row < 18) {
                            if (row < 6 && j_local < 6) {
                                val = dt * s_dInt_v_6x6[row * 6 + j_local];
                            } else if (row >= 6 && j_local >= 6) {
                                val = (row == j_local) ? dt : static_cast<T>(0);
                            } else { val = static_cast<T>(0); }
                        } else {
                            int i_local = row - 18;
                            T diag = (i_local == j_local) ? static_cast<T>(1) : static_cast<T>(0);
                            val = diag + dt * s_df_du[324 + j_local * 18 + i_local];
                        }
                    } else {
                        // d/du column   (dqdd/du = Minv)
                        int j_local = col - 36;
                        if (row < 18) {
                            val = static_cast<T>(0);
                        } else {
                            int i_local = row - 18;
                            int midx = (i_local <= j_local) * (j_local * 18 + i_local) + (i_local > j_local) * (i_local * 18 + j_local);
                            val = dt * s_Minv[midx];
                        }
                    }
                    s_dAB[ind] = val;
                }
                else if constexpr (IT == IntegratorType::SEMI_IMPLICIT_EULER) {
                    T val = static_cast<T>(0);
                    if (col < 18) {
                        // d/dq column. dvdq[k,c] = dt*J_qq[k,c] = dt*s_df_du[c*n + k].
                        int c = col;
                        if (row < 18) {
                            T dInt_q_term = (row < 6 && c < 6) ? s_dInt_q_6x6[row * 6 + c]
                                           : ((row >= 6 && c >= 6) ? ((row == c) ? static_cast<T>(1) : static_cast<T>(0)) : static_cast<T>(0));
                            T mm;
                            if (row < 6) { mm = static_cast<T>(0); for (int k = 0; k < 6; ++k) mm += s_dInt_v_6x6[row * 6 + k] * (dt * s_df_du[c * 18 + k]); }
                            else { mm = dt * s_df_du[c * 18 + row]; }
                            val = dInt_q_term + dt * mm;
                        } else {
                            int i_local = row - 18;
                            val = dt * s_df_du[c * 18 + i_local];
                        }
                    } else if (col < 36) {
                        // d/dqd column. dvdv[k,c] = (k==c) + dt*J_qv[k,c].
                        int c = col - 18;
                        if (row < 18) {
                            T mm;
                            if (row < 6) { mm = static_cast<T>(0); for (int k = 0; k < 6; ++k) { T dvdv_k = ((k == c) ? static_cast<T>(1) : static_cast<T>(0)) + dt * s_df_du[324 + c * 18 + k]; mm += s_dInt_v_6x6[row * 6 + k] * dvdv_k; } }
                            else { mm = ((row == c) ? static_cast<T>(1) : static_cast<T>(0)) + dt * s_df_du[324 + c * 18 + row]; }
                            val = dt * mm;
                        } else {
                            int i_local = row - 18;
                            T diag = (i_local == c) ? static_cast<T>(1) : static_cast<T>(0);
                            val = diag + dt * s_df_du[324 + c * 18 + i_local];
                        }
                    } else {
                        // d/du column. dvdu[k,c] = dt*Minv[k,c] (SYMMETRIC_UPPER).
                        int c = col - 36;
                        if (row < 18) {
                            T mm;
                            if (row < 6) { mm = static_cast<T>(0); for (int k = 0; k < 6; ++k) { int midx = (k <= c) * (c * 18 + k) + (k > c) * (k * 18 + c); mm += s_dInt_v_6x6[row * 6 + k] * (dt * s_Minv[midx]); } }
                            else { int midx = (row <= c) * (c * 18 + row) + (row > c) * (row * 18 + c); mm = dt * s_Minv[midx]; }
                            val = dt * mm;
                        } else {
                            int i_local = row - 18;
                            int midx = (i_local <= c) * (c * 18 + i_local) + (i_local > c) * (i_local * 18 + c);
                            val = dt * s_Minv[midx];
                        }
                    }
                    s_dAB[ind] = val;
                }
                else if constexpr (IT == IntegratorType::TRAPEZOIDAL) {
                    T val = static_cast<T>(0);
                    T dt2h = static_cast<T>(0.5) * dt * dt;
                    if (col < 18) {
                        // d/dq column. dw/dq[k] = dt2h*J_qq[c*n+k].
                        int c = col;
                        if (row < 18) {
                            T dInt_q_term = (row < 6 && c < 6) ? s_dInt_q_6x6[row * 6 + c]
                                           : ((row >= 6 && c >= 6) ? ((row == c) ? static_cast<T>(1) : static_cast<T>(0)) : static_cast<T>(0));
                            T mm;
                            if (row < 6) { mm = static_cast<T>(0); for (int k = 0; k < 6; ++k) mm += s_dInt_v_6x6[row * 6 + k] * (dt2h * s_df_du[c * 18 + k]); }
                            else { mm = dt2h * s_df_du[c * 18 + row]; }
                            val = dInt_q_term + mm;
                        } else {
                            int i_local = row - 18;
                            val = dt * s_df_du[c * 18 + i_local];
                        }
                    } else if (col < 36) {
                        // d/dqd column. dw/dqd[k] = (k==c?dt:0) + dt2h*J_qv[k].
                        int c = col - 18;
                        if (row < 18) {
                            T mm;
                            if (row < 6) { mm = static_cast<T>(0); for (int k = 0; k < 6; ++k) { T dw_k = ((k == c) ? dt : static_cast<T>(0)) + dt2h * s_df_du[324 + c * 18 + k]; mm += s_dInt_v_6x6[row * 6 + k] * dw_k; } }
                            else { mm = ((row == c) ? dt : static_cast<T>(0)) + dt2h * s_df_du[324 + c * 18 + row]; }
                            val = mm;
                        } else {
                            int i_local = row - 18;
                            T diag = (i_local == c) ? static_cast<T>(1) : static_cast<T>(0);
                            val = diag + dt * s_df_du[324 + c * 18 + i_local];
                        }
                    } else {
                        // d/du column. dw/du[k] = dt2h*Minv[k,c] (SYMMETRIC_UPPER).
                        int c = col - 36;
                        if (row < 18) {
                            T mm;
                            if (row < 6) { mm = static_cast<T>(0); for (int k = 0; k < 6; ++k) { int midx = (k <= c) * (c * 18 + k) + (k > c) * (k * 18 + c); mm += s_dInt_v_6x6[row * 6 + k] * (dt2h * s_Minv[midx]); } }
                            else { int midx = (row <= c) * (c * 18 + row) + (row > c) * (row * 18 + c); mm = dt2h * s_Minv[midx]; }
                            val = mm;
                        } else {
                            int i_local = row - 18;
                            int midx = (i_local <= c) * (c * 18 + i_local) + (i_local > c) * (i_local * 18 + c);
                            val = dt * s_Minv[midx];
                        }
                    }
                    s_dAB[ind] = val;
                }
                else {
                    static_assert(IT == IntegratorType::EULER || IT == IntegratorType::SEMI_IMPLICIT_EULER || IT == IntegratorType::TRAPEZOIDAL,
                                  "dAB assembly handles single-stage IT only; Midpoint/RK3/RK4 are routed through gen_integrator_gradient_multistage.");
                }
            }
            if constexpr (MUJOCO_OUTPUT) {
                // === mjx output convention (floating-base integrator gradient) ===
                __syncthreads();
                T *s_mjx = s_temp;   // 2n*3n mjx output band (dead FD-grad pool)
                const bool si_mjx = (IT == IntegratorType::SEMI_IMPLICIT_EULER);
                // Phase 1: per (half, output-column) reframe (reads s_dAB, writes s_mjx)
                for(int gi = threadIdx.x + threadIdx.y*blockDim.x; gi < 108; gi += blockDim.x*blockDim.y){
                    T qx = s_q[3], qy = s_q[4], qz = s_q[5], qw = s_q[6];
                    T xx = qx*qx, yy = qy*qy, zz = qz*qz;
                    T xy = qx*qy, xz = qx*qz, yz = qy*qz, wx = qw*qx, wy = qw*qy, wz = qw*qz;
                    T R[9];
                    R[0] = static_cast<T>(1) - static_cast<T>(2)*(yy+zz); R[1] = static_cast<T>(2)*(xy-wz);                    R[2] = static_cast<T>(2)*(xz+wy);
                    R[3] = static_cast<T>(2)*(xy+wz);                    R[4] = static_cast<T>(1) - static_cast<T>(2)*(xx+zz); R[5] = static_cast<T>(2)*(yz-wx);
                    R[6] = static_cast<T>(2)*(xz-wy);                    R[7] = static_cast<T>(2)*(yz+wx);                    R[8] = static_cast<T>(1) - static_cast<T>(2)*(xx+yy);
                    T vlin[3] = {s_qd[0], s_qd[1], s_qd[2]};
                    T ulin[3] = {s_u[0],  s_u[1],  s_u[2]};
                    // qd_{k+1,pin}[lin] = (qd + dt*qdd)[lin] (for the g_dot velocity-output term)
                    T qk1lin[3] = {s_qd[0] + dt*s_qdd[0], s_qd[1] + dt*s_qdd[1], s_qd[2] + dt*s_qdd[2]};
                    int half = gi / 54;
                    int c    = gi % 54;
                    int base = half * 18;
                    int cblk = c / 18;   // 0=q-block, 1=qd-block, 2=u-block
                    int cl   = c % 18;   // column-local index within the block
                    int boff = cblk * 18;   // block column offset (0, n, 2n)
                    T inner[18];
                    for (int r = 0; r < 18; ++r) {
                      int o = base + r;
                      if (cl < 3) { inner[r] = s_dAB[(boff+0)*36+o]*R[cl*3+0] + s_dAB[(boff+1)*36+o]*R[cl*3+1] + s_dAB[(boff+2)*36+o]*R[cl*3+2]; }
                      else { inner[r] = s_dAB[c*36+o]; }
                    }
                    if (cblk == 0 && c >= 3 && c < 6) {
                      int a = c - 3;
                      T ea[3] = {static_cast<T>(0),static_cast<T>(0),static_cast<T>(0)}; ea[a] = static_cast<T>(1);
                      T jc[3] = {ea[1]*vlin[2]-ea[2]*vlin[1], ea[2]*vlin[0]-ea[0]*vlin[2], ea[0]*vlin[1]-ea[1]*vlin[0]};
                      T uc[3] = {ea[1]*ulin[2]-ea[2]*ulin[1], ea[2]*ulin[0]-ea[0]*ulin[2], ea[0]*ulin[1]-ea[1]*ulin[0]};
                      for (int r = 0; r < 18; ++r) {
                        int o = base + r;
                        inner[r] += s_dAB[(18+0)*36+o]*(-jc[0]) + s_dAB[(18+1)*36+o]*(-jc[1]) + s_dAB[(18+2)*36+o]*(-jc[2]);
                        inner[r] += s_dAB[(36+0)*36+o]*(-uc[0]) + s_dAB[(36+1)*36+o]*(-uc[1]) + s_dAB[(36+2)*36+o]*(-uc[2]);
                      }
                    }
                    T l0 = inner[0], l1 = inner[1], l2 = inner[2];
                    inner[0] = R[0]*l0 + R[1]*l1 + R[2]*l2;
                    inner[1] = R[3]*l0 + R[4]*l1 + R[5]*l2;
                    inner[2] = R[6]*l0 + R[7]*l1 + R[8]*l2;
                    if (half == 1 && cblk == 0 && c >= 3 && c < 6) {
                      int a = c - 3;
                      T ea[3] = {static_cast<T>(0),static_cast<T>(0),static_cast<T>(0)}; ea[a] = static_cast<T>(1);
                      T sk[3] = {ea[1]*qk1lin[2]-ea[2]*qk1lin[1], ea[2]*qk1lin[0]-ea[0]*qk1lin[2], ea[0]*qk1lin[1]-ea[1]*qk1lin[0]};
                      inner[0] += R[0]*sk[0] + R[1]*sk[1] + R[2]*sk[2];
                      inner[1] += R[3]*sk[0] + R[4]*sk[1] + R[5]*sk[2];
                      inner[2] += R[6]*sk[0] + R[7]*sk[1] + R[8]*sk[2];
                    }
                    for (int r = 0; r < 18; ++r) s_mjx[c*36+(base+r)] = inner[r];
                }
                __syncthreads();
                // Phase 2: top-half base-linear rows = mjx global-add tangent (reads s_mjx bottom rows)
                for(int a = threadIdx.x + threadIdx.y*blockDim.x; a < 3; a += blockDim.x*blockDim.y){
                    int o = a;
                    for (int c = 0; c < 54; ++c) s_mjx[c*36+o] = static_cast<T>(0);
                    s_mjx[a*36+o] = static_cast<T>(1);   // identity on base-linear q col a
                    if (si_mjx) {
                      for (int c = 0; c < 54; ++c) s_mjx[c*36+o] += dt * s_mjx[c*36+(18+a)];
                    } else {
                      s_mjx[(18+a)*36+o] += dt;   // dt on qd base-linear col a
                    }
                }
                __syncthreads();
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 1944; ind += blockDim.x*blockDim.y){
                    s_dAB[ind] = s_mjx[ind];
                }
                __syncthreads();
            }
        }
        else {
            static_assert(!MUJOCO_OUTPUT, "integrator_gradient MUJOCO_OUTPUT is single-stage (EULER/SEMI_IMPLICIT_EULER) only; "
                          "multi-stage RK mjx is deferred.");
            // --- multi-stage gradient: save original q, qd ---
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 19; ind += blockDim.x*blockDim.y){
                s_q_orig[ind] = s_q[ind];
            }
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 18; ind += blockDim.x*blockDim.y){
                s_qd_orig[ind] = s_qd[ind];
            }
            __syncthreads();
            // --- multi-stage gradient: stage 1 ---
            if constexpr (IT == IntegratorType::MIDPOINT || IT == IntegratorType::RK3 || IT == IntegratorType::RK4) {
                //TODO: there is a slightly faster way as s_v does not change -- thus no recompute needed
                minv_inner<T, true>(s_Minv, s_q, s_XImats, s_topology_helpers, s_temp, nullptr);
                inverse_dynamics_inner<T>(s_temp, s_vaf, s_q, s_qd, s_XImats, s_topology_helpers, &s_temp[18], d_f_ext, gravity);
                forward_dynamics_finish<T>(s_qdd, s_u, s_temp, s_Minv);
                __syncthreads();
                inverse_dynamics_inner_vaf<T>(s_vaf, s_q, s_qd, s_qdd, s_XImats, s_topology_helpers, s_temp, d_f_ext, gravity);
                inverse_dynamics_gradient_inner<T, USE_DA_DF_SPILL>(s_dc_du, s_q, s_qd, s_vaf, s_XImats, s_topology_helpers, s_temp, d_temp_spill, gravity);
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 648; ind += blockDim.x*blockDim.y){
                    int row = ind % 18; int dc_col_offset = ind - row;
                    // account for the fact that Minv is an SYMMETRIC_UPPER triangular matrix
                    T val = static_cast<T>(0);
                    for(int col = 0; col < 18; col++) {
                        int index = (row <= col) * (col * 18 + row) + (row > col) * (row * 18 + col);
                        val += s_Minv[index] * s_dc_du[dc_col_offset + col];
                    }
                    s_df_du[ind] = -val;
                }
                __syncthreads();
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 18; ind += blockDim.x*blockDim.y){
                    s_stage_grad_qdd[0 + ind] = s_qdd[ind];
                }
                __syncthreads();
                constexpr T c_prev_s1 = static_cast<T>(0);
                T *s_D_qdd_cur = &s_D_qdd_stage[0 * 972];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 972; ind += blockDim.x*blockDim.y){
                    int r = ind % 18;
                    int c = ind / 18;
                    T base = static_cast<T>(0);
                    if (c < 18) {
                        base = s_df_du[c * 18 + r];                       // J_qq[r, c]
                    } else if (c < 36) {
                        int cc = c - 18;
                        base = c_prev_s1 * dt * s_df_du[cc * 18 + r] + s_df_du[324 + cc * 18 + r];  // c*dt*J_qq + J_qv
                    } else {
                        int cc = c - 36;
                        int midx = (r <= cc) * (cc * 18 + r) + (r > cc) * (r * 18 + cc);
                        base = s_Minv[midx];                                  // Minv[r, cc]
                    }
                    s_D_qdd_cur[c * 18 + r] = base;
                }
                __syncthreads();
            }
            // --- multi-stage gradient: stage 2 ---
            if constexpr (IT == IntegratorType::MIDPOINT || IT == IntegratorType::RK3 || IT == IntegratorType::RK4) {
                constexpr T c_offset = (IT == IntegratorType::MIDPOINT) ? static_cast<T>(0.5) : (IT == IntegratorType::RK3) ? static_cast<T>(0.5) : (IT == IntegratorType::RK4) ? static_cast<T>(0.5) : static_cast<T>(0);
                if(threadIdx.x == 0 && threadIdx.y == 0){
                    T v_scaled[18];
                    for (int i = 0; i < 18; ++i) v_scaled[i] = c_offset * dt * s_qd_orig[i];
                    grid_integrate_floating_q<T, 19>(s_q_orig, v_scaled, s_q);
                }
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 18; ind += blockDim.x*blockDim.y){
                    s_qd[ind] = s_qd_orig[ind] + c_offset * dt * s_stage_grad_qdd[0 + ind];
                }
                __syncthreads();
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                __syncthreads();
                if(threadIdx.x == 0 && threadIdx.y == 0){
                    T v_dt_stage[18];
                    for (int i = 0; i < 18; ++i) v_dt_stage[i] = c_offset * dt * s_qd_orig[i];
                    grid_dIntegrate_q_block<T>(v_dt_stage, s_dInt_q_6x6);
                    grid_dIntegrate_v_block<T>(v_dt_stage, s_dInt_v_6x6);
                }
                __syncthreads();
                //TODO: there is a slightly faster way as s_v does not change -- thus no recompute needed
                minv_inner<T, true>(s_Minv, s_q, s_XImats, s_topology_helpers, s_temp, nullptr);
                inverse_dynamics_inner<T>(s_temp, s_vaf, s_q, s_qd, s_XImats, s_topology_helpers, &s_temp[18], d_f_ext, gravity);
                forward_dynamics_finish<T>(s_qdd, s_u, s_temp, s_Minv);
                __syncthreads();
                inverse_dynamics_inner_vaf<T>(s_vaf, s_q, s_qd, s_qdd, s_XImats, s_topology_helpers, s_temp, d_f_ext, gravity);
                inverse_dynamics_gradient_inner<T, USE_DA_DF_SPILL>(s_dc_du, s_q, s_qd, s_vaf, s_XImats, s_topology_helpers, s_temp, d_temp_spill, gravity);
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 648; ind += blockDim.x*blockDim.y){
                    int row = ind % 18; int dc_col_offset = ind - row;
                    // account for the fact that Minv is an SYMMETRIC_UPPER triangular matrix
                    T val = static_cast<T>(0);
                    for(int col = 0; col < 18; col++) {
                        int index = (row <= col) * (col * 18 + row) + (row > col) * (row * 18 + col);
                        val += s_Minv[index] * s_dc_du[dc_col_offset + col];
                    }
                    s_df_du[ind] = -val;
                }
                __syncthreads();
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 18; ind += blockDim.x*blockDim.y){
                    s_stage_grad_qdd[18 + ind] = s_qdd[ind];
                }
                __syncthreads();
                constexpr T c_prev_s2 = (IT == IntegratorType::MIDPOINT) ? static_cast<T>(0.5) : (IT == IntegratorType::RK3) ? static_cast<T>(0.5) : (IT == IntegratorType::RK4) ? static_cast<T>(0.5) : static_cast<T>(0);
                T *s_D_qdd_cur = &s_D_qdd_stage[1 * 972];
                T *s_D_qdd_prev = &s_D_qdd_stage[0];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 972; ind += blockDim.x*blockDim.y){
                    int r = ind % 18;
                    int c = ind / 18;
                    T base = static_cast<T>(0);
                    if (c < 18) {
                        // (J_qq @ dInt_q)[r, c]
                        if (c < 6) {
                            for (int k = 0; k < 6; ++k) base += s_df_du[k * 18 + r] * s_dInt_q_6x6[k * 6 + c];
                        } else {
                            base = s_df_du[c * 18 + r];
                        }
                    } else if (c < 36) {
                        int cc = c - 18;
                        // c*dt*(J_qq @ dInt_v)[r, cc] + J_qv[r, cc]
                        T proj = static_cast<T>(0);
                        if (cc < 6) {
                            for (int k = 0; k < 6; ++k) proj += s_df_du[k * 18 + r] * s_dInt_v_6x6[k * 6 + cc];
                        } else {
                            proj = s_df_du[cc * 18 + r];
                        }
                        base = c_prev_s2 * dt * proj + s_df_du[324 + cc * 18 + r];
                    } else {
                        int cc = c - 36;
                        int midx = (r <= cc) * (cc * 18 + r) + (r > cc) * (r * 18 + cc);
                        base = s_Minv[midx];                                  // Minv[r, cc]
                    }
                    T chain = static_cast<T>(0);
                    for (int k = 0; k < 18; ++k) {
                        chain += s_df_du[324 + k * 18 + r] * s_D_qdd_prev[c * 18 + k];
                    }
                    s_D_qdd_cur[c * 18 + r] = base + c_prev_s2 * dt * chain;
                }
                __syncthreads();
            }
            // --- multi-stage gradient: stage 3 ---
            if constexpr (IT == IntegratorType::RK3 || IT == IntegratorType::RK4) {
                constexpr T c_offset = (IT == IntegratorType::RK3) ? static_cast<T>(0.75) : (IT == IntegratorType::RK4) ? static_cast<T>(0.5) : static_cast<T>(0);
                if(threadIdx.x == 0 && threadIdx.y == 0){
                    T v_scaled[18];
                    for (int i = 0; i < 18; ++i) v_scaled[i] = c_offset * dt * s_qd_orig[i];
                    grid_integrate_floating_q<T, 19>(s_q_orig, v_scaled, s_q);
                }
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 18; ind += blockDim.x*blockDim.y){
                    s_qd[ind] = s_qd_orig[ind] + c_offset * dt * s_stage_grad_qdd[18 + ind];
                }
                __syncthreads();
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                __syncthreads();
                if(threadIdx.x == 0 && threadIdx.y == 0){
                    T v_dt_stage[18];
                    for (int i = 0; i < 18; ++i) v_dt_stage[i] = c_offset * dt * s_qd_orig[i];
                    grid_dIntegrate_q_block<T>(v_dt_stage, s_dInt_q_6x6);
                    grid_dIntegrate_v_block<T>(v_dt_stage, s_dInt_v_6x6);
                }
                __syncthreads();
                //TODO: there is a slightly faster way as s_v does not change -- thus no recompute needed
                minv_inner<T, true>(s_Minv, s_q, s_XImats, s_topology_helpers, s_temp, nullptr);
                inverse_dynamics_inner<T>(s_temp, s_vaf, s_q, s_qd, s_XImats, s_topology_helpers, &s_temp[18], d_f_ext, gravity);
                forward_dynamics_finish<T>(s_qdd, s_u, s_temp, s_Minv);
                __syncthreads();
                inverse_dynamics_inner_vaf<T>(s_vaf, s_q, s_qd, s_qdd, s_XImats, s_topology_helpers, s_temp, d_f_ext, gravity);
                inverse_dynamics_gradient_inner<T, USE_DA_DF_SPILL>(s_dc_du, s_q, s_qd, s_vaf, s_XImats, s_topology_helpers, s_temp, d_temp_spill, gravity);
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 648; ind += blockDim.x*blockDim.y){
                    int row = ind % 18; int dc_col_offset = ind - row;
                    // account for the fact that Minv is an SYMMETRIC_UPPER triangular matrix
                    T val = static_cast<T>(0);
                    for(int col = 0; col < 18; col++) {
                        int index = (row <= col) * (col * 18 + row) + (row > col) * (row * 18 + col);
                        val += s_Minv[index] * s_dc_du[dc_col_offset + col];
                    }
                    s_df_du[ind] = -val;
                }
                __syncthreads();
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 18; ind += blockDim.x*blockDim.y){
                    s_stage_grad_qdd[36 + ind] = s_qdd[ind];
                }
                __syncthreads();
                constexpr T c_prev_s3 = (IT == IntegratorType::RK3) ? static_cast<T>(0.75) : (IT == IntegratorType::RK4) ? static_cast<T>(0.5) : static_cast<T>(0);
                T *s_D_qdd_cur = &s_D_qdd_stage[2 * 972];
                T *s_D_qdd_prev = &s_D_qdd_stage[972];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 972; ind += blockDim.x*blockDim.y){
                    int r = ind % 18;
                    int c = ind / 18;
                    T base = static_cast<T>(0);
                    if (c < 18) {
                        // (J_qq @ dInt_q)[r, c]
                        if (c < 6) {
                            for (int k = 0; k < 6; ++k) base += s_df_du[k * 18 + r] * s_dInt_q_6x6[k * 6 + c];
                        } else {
                            base = s_df_du[c * 18 + r];
                        }
                    } else if (c < 36) {
                        int cc = c - 18;
                        // c*dt*(J_qq @ dInt_v)[r, cc] + J_qv[r, cc]
                        T proj = static_cast<T>(0);
                        if (cc < 6) {
                            for (int k = 0; k < 6; ++k) proj += s_df_du[k * 18 + r] * s_dInt_v_6x6[k * 6 + cc];
                        } else {
                            proj = s_df_du[cc * 18 + r];
                        }
                        base = c_prev_s3 * dt * proj + s_df_du[324 + cc * 18 + r];
                    } else {
                        int cc = c - 36;
                        int midx = (r <= cc) * (cc * 18 + r) + (r > cc) * (r * 18 + cc);
                        base = s_Minv[midx];                                  // Minv[r, cc]
                    }
                    T chain = static_cast<T>(0);
                    for (int k = 0; k < 18; ++k) {
                        chain += s_df_du[324 + k * 18 + r] * s_D_qdd_prev[c * 18 + k];
                    }
                    s_D_qdd_cur[c * 18 + r] = base + c_prev_s3 * dt * chain;
                }
                __syncthreads();
            }
            // --- multi-stage gradient: stage 4 ---
            if constexpr (IT == IntegratorType::RK4) {
                constexpr T c_offset = (IT == IntegratorType::RK4) ? static_cast<T>(1.0) : static_cast<T>(0);
                if(threadIdx.x == 0 && threadIdx.y == 0){
                    T v_scaled[18];
                    for (int i = 0; i < 18; ++i) v_scaled[i] = c_offset * dt * s_qd_orig[i];
                    grid_integrate_floating_q<T, 19>(s_q_orig, v_scaled, s_q);
                }
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 18; ind += blockDim.x*blockDim.y){
                    s_qd[ind] = s_qd_orig[ind] + c_offset * dt * s_stage_grad_qdd[36 + ind];
                }
                __syncthreads();
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                __syncthreads();
                if(threadIdx.x == 0 && threadIdx.y == 0){
                    T v_dt_stage[18];
                    for (int i = 0; i < 18; ++i) v_dt_stage[i] = c_offset * dt * s_qd_orig[i];
                    grid_dIntegrate_q_block<T>(v_dt_stage, s_dInt_q_6x6);
                    grid_dIntegrate_v_block<T>(v_dt_stage, s_dInt_v_6x6);
                }
                __syncthreads();
                //TODO: there is a slightly faster way as s_v does not change -- thus no recompute needed
                minv_inner<T, true>(s_Minv, s_q, s_XImats, s_topology_helpers, s_temp, nullptr);
                inverse_dynamics_inner<T>(s_temp, s_vaf, s_q, s_qd, s_XImats, s_topology_helpers, &s_temp[18], d_f_ext, gravity);
                forward_dynamics_finish<T>(s_qdd, s_u, s_temp, s_Minv);
                __syncthreads();
                inverse_dynamics_inner_vaf<T>(s_vaf, s_q, s_qd, s_qdd, s_XImats, s_topology_helpers, s_temp, d_f_ext, gravity);
                inverse_dynamics_gradient_inner<T, USE_DA_DF_SPILL>(s_dc_du, s_q, s_qd, s_vaf, s_XImats, s_topology_helpers, s_temp, d_temp_spill, gravity);
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 648; ind += blockDim.x*blockDim.y){
                    int row = ind % 18; int dc_col_offset = ind - row;
                    // account for the fact that Minv is an SYMMETRIC_UPPER triangular matrix
                    T val = static_cast<T>(0);
                    for(int col = 0; col < 18; col++) {
                        int index = (row <= col) * (col * 18 + row) + (row > col) * (row * 18 + col);
                        val += s_Minv[index] * s_dc_du[dc_col_offset + col];
                    }
                    s_df_du[ind] = -val;
                }
                __syncthreads();
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 18; ind += blockDim.x*blockDim.y){
                    s_stage_grad_qdd[54 + ind] = s_qdd[ind];
                }
                __syncthreads();
                constexpr T c_prev_s4 = (IT == IntegratorType::RK4) ? static_cast<T>(1.0) : static_cast<T>(0);
                T *s_D_qdd_cur = &s_D_qdd_stage[3 * 972];
                T *s_D_qdd_prev = &s_D_qdd_stage[1944];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 972; ind += blockDim.x*blockDim.y){
                    int r = ind % 18;
                    int c = ind / 18;
                    T base = static_cast<T>(0);
                    if (c < 18) {
                        // (J_qq @ dInt_q)[r, c]
                        if (c < 6) {
                            for (int k = 0; k < 6; ++k) base += s_df_du[k * 18 + r] * s_dInt_q_6x6[k * 6 + c];
                        } else {
                            base = s_df_du[c * 18 + r];
                        }
                    } else if (c < 36) {
                        int cc = c - 18;
                        // c*dt*(J_qq @ dInt_v)[r, cc] + J_qv[r, cc]
                        T proj = static_cast<T>(0);
                        if (cc < 6) {
                            for (int k = 0; k < 6; ++k) proj += s_df_du[k * 18 + r] * s_dInt_v_6x6[k * 6 + cc];
                        } else {
                            proj = s_df_du[cc * 18 + r];
                        }
                        base = c_prev_s4 * dt * proj + s_df_du[324 + cc * 18 + r];
                    } else {
                        int cc = c - 36;
                        int midx = (r <= cc) * (cc * 18 + r) + (r > cc) * (r * 18 + cc);
                        base = s_Minv[midx];                                  // Minv[r, cc]
                    }
                    T chain = static_cast<T>(0);
                    for (int k = 0; k < 18; ++k) {
                        chain += s_df_du[324 + k * 18 + r] * s_D_qdd_prev[c * 18 + k];
                    }
                    s_D_qdd_cur[c * 18 + r] = base + c_prev_s4 * dt * chain;
                }
                __syncthreads();
            }
            if(threadIdx.x == 0 && threadIdx.y == 0){
                T v_dt_final[18];
                for (int i = 0; i < 18; ++i) v_dt_final[i] = dt * s_qd_orig[i];
                grid_dIntegrate_q_block<T>(v_dt_final, s_dInt_q_6x6);
                grid_dIntegrate_v_block<T>(v_dt_final, s_dInt_v_6x6);
            }
            __syncthreads();
            // --- multi-stage gradient: assemble final dAB ---
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 1944; ind += blockDim.x*blockDim.y){
                int row = ind % 36;
                int col = ind / 36;
                T val = static_cast<T>(0);
                if (row < 18) {
                    if (col < 18) {
                        if (row < 6 && col < 6) { val = s_dInt_q_6x6[row * 6 + col]; }
                        else if (row >= 6 && col >= 6) { val = (row == col) ? static_cast<T>(1) : static_cast<T>(0); }
                        else { val = static_cast<T>(0); }
                    } else if (col < 36) {
                        int j = col - 18;
                        if (row < 6 && j < 6) { val = dt * s_dInt_v_6x6[row * 6 + j]; }
                        else if (row >= 6 && j >= 6) { val = (row == j) ? dt : static_cast<T>(0); }
                        else { val = static_cast<T>(0); }
                    } else {
                        val = static_cast<T>(0);
                    }
                } else {
                    int r = row - 18;
                    // bottom half: qd_{k+1} = qd + dt * sum(b_i * qdd_i)
                    T identity_term = ((col >= 18 && col < 36) && (r == col - 18)) ? static_cast<T>(1) : static_cast<T>(0);
                    T accel_term = static_cast<T>(0);
                    if constexpr (IT == IntegratorType::MIDPOINT) {
                        accel_term += static_cast<T>(1.0) * s_D_qdd_stage[972 + col * 18 + r];
                    }
                    if constexpr (IT == IntegratorType::RK3) {
                        accel_term += static_cast<T>(0.2222222222222222) * s_D_qdd_stage[0 + col * 18 + r];
                        accel_term += static_cast<T>(0.3333333333333333) * s_D_qdd_stage[972 + col * 18 + r];
                        accel_term += static_cast<T>(0.4444444444444444) * s_D_qdd_stage[1944 + col * 18 + r];
                    }
                    if constexpr (IT == IntegratorType::RK4) {
                        accel_term += static_cast<T>(0.16666666666666666) * s_D_qdd_stage[0 + col * 18 + r];
                        accel_term += static_cast<T>(0.3333333333333333) * s_D_qdd_stage[972 + col * 18 + r];
                        accel_term += static_cast<T>(0.3333333333333333) * s_D_qdd_stage[1944 + col * 18 + r];
                        accel_term += static_cast<T>(0.16666666666666666) * s_D_qdd_stage[2916 + col * 18 + r];
                    }
                    val = identity_term + dt * accel_term;
                }
                s_dAB[ind] = val;
            }
            __syncthreads();
        }
    }

    /**
     * integrator gradient orchestration as a single inner-owns-placement device function
     *
     * Notes:
     *   Owns the FD-grad inner s_temp pool placement; the repoint covers every consumer below (incl. the XImats helper's sincos scratch and the per-stage XImats refresh)
     *
     * @param s_dAB is the output [A | B] buffer (caller places); size 2*NUM_VEL*3*NUM_VEL = 1944
     * @param s_x_kp1 is the next-state output (caller places); size NUM_POS + NUM_VEL
     * @param s_q is the vector of joint positions (NON-const: mutated across RK stages)
     * @param s_qd is the vector of joint velocities (NON-const: mutated across RK stages)
     * @param s_u is the vector of joint input torques
     * @param s_df_du / s_dc_du / s_vaf / s_Minv / s_qdd are FD-grad in/out scratch (caller places)
     * @param s_q_orig / s_qd_orig / s_stage_grad_qdd / s_D_qdd_stage are multi-stage scratch (caller places; s_D_qdd_stage is a de-aliased workspace band when spilled)
     * @param s_dInt_q_6x6 / s_dInt_v_6x6 are the floating-base SE(3) dIntegrate blocks (unused fixed-base)
     * @param s_temp is the FD-grad inner scratch pool (used when SCRATCH_IN_SMEM)
     * @param d_workspace is the global scratch pool the FD-grad inner s_temp routes to (used when !SCRATCH_IN_SMEM)
     * @param d_temp_spill is the inverse_dynamics_gradient da_df band spill region (used when USE_DA_DF_SPILL)
     * @param s_XImats is the (shared) memory holding the updated XI matricies for the given s_q
     * @param s_topology_helpers is the (shared) memory location for the topology_helpers (nullptr/unused for serial chains with identical Ss)
     * @param d_robotModel holds XImats/topology; gravity is the gravity constant; dt is the timestep
     * @param d_f_ext is the (optional) GLOBAL external forces, body-major 6*NUM_BODIES local-frame, or nullptr
     */
    template <typename T, IntegratorType IT = IntegratorType::EULER, bool SCRATCH_IN_SMEM = true, bool USE_DA_DF_SPILL = false, bool MUJOCO_OUTPUT = false>
    __device__ __forceinline__
    void integrator_with_gradient_device(T *s_dAB, T *s_x_kp1, T *s_q, T *s_qd, const T *s_u, T *s_df_du, T *s_dc_du, T *s_vaf, T *s_Minv, T *s_qdd, T *s_q_orig, T *s_qd_orig, T *s_stage_grad_qdd, T *s_D_qdd_stage, T *s_dInt_q_6x6, T *s_dInt_v_6x6, T *s_XImats, int *s_topology_helpers, T *s_temp, T *d_workspace, T *d_temp_spill, const robotModel<T> *d_robotModel, T *d_f_ext, const T gravity, const T dt) {
        if constexpr(!SCRATCH_IN_SMEM){ s_temp = d_workspace; } else { (void)d_workspace; }
        load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
        if constexpr (IT == IntegratorType::EULER || IT == IntegratorType::SEMI_IMPLICIT_EULER || IT == IntegratorType::TRAPEZOIDAL) {
            //TODO: there is a slightly faster way as s_v does not change -- thus no recompute needed
            minv_inner<T, true>(s_Minv, s_q, s_XImats, s_topology_helpers, s_temp, nullptr);
            inverse_dynamics_inner<T>(s_temp, s_vaf, s_q, s_qd, s_XImats, s_topology_helpers, &s_temp[18], d_f_ext, gravity);
            forward_dynamics_finish<T>(s_qdd, s_u, s_temp, s_Minv);
            __syncthreads();
            inverse_dynamics_inner_vaf<T>(s_vaf, s_q, s_qd, s_qdd, s_XImats, s_topology_helpers, s_temp, d_f_ext, gravity);
            inverse_dynamics_gradient_inner<T, USE_DA_DF_SPILL>(s_dc_du, s_q, s_qd, s_vaf, s_XImats, s_topology_helpers, s_temp, d_temp_spill, gravity);
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 648; ind += blockDim.x*blockDim.y){
                int row = ind % 18; int dc_col_offset = ind - row;
                // account for the fact that Minv is an SYMMETRIC_UPPER triangular matrix
                T val = static_cast<T>(0);
                for(int col = 0; col < 18; col++) {
                    int index = (row <= col) * (col * 18 + row) + (row > col) * (row * 18 + col);
                    val += s_Minv[index] * s_dc_du[dc_col_offset + col];
                }
                s_df_du[ind] = -val;
            }
            __syncthreads();
            if(threadIdx.x == 0 && threadIdx.y == 0){
                T v_dt_for_dInt[18];
                if constexpr (IT == IntegratorType::SEMI_IMPLICIT_EULER) {
                    for (int i = 0; i < 18; ++i) v_dt_for_dInt[i] = dt * (s_qd[i] + dt * s_qdd[i]);
                } else if constexpr (IT == IntegratorType::TRAPEZOIDAL) {
                    for (int i = 0; i < 18; ++i) v_dt_for_dInt[i] = dt * s_qd[i] + static_cast<T>(0.5) * dt * dt * s_qdd[i];
                } else {
                    for (int i = 0; i < 18; ++i) v_dt_for_dInt[i] = dt * s_qd[i];
                }
                grid_dIntegrate_q_block<T>(v_dt_for_dInt, s_dInt_q_6x6);
                grid_dIntegrate_v_block<T>(v_dt_for_dInt, s_dInt_v_6x6);
            }
            __syncthreads();
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 1944; ind += blockDim.x*blockDim.y){
                int row = ind % 36;
                int col = ind / 36;
                if constexpr (IT == IntegratorType::EULER) {
                    T val = static_cast<T>(0);
                    if (col < 18) {
                        // d/dq column
                        if (row < 18) {
                            if (row < 6 && col < 6) {
                                val = s_dInt_q_6x6[row * 6 + col];
                            } else if (row >= 6 && col >= 6) {
                                val = (row == col) ? static_cast<T>(1) : static_cast<T>(0);
                            } else { val = static_cast<T>(0); }
                        } else {
                            int i_local = row - 18;
                            val = dt * s_df_du[col * 18 + i_local];
                        }
                    } else if (col < 36) {
                        // d/dqd column
                        int j_local = col - 18;
                        if (row < 18) {
                            if (row < 6 && j_local < 6) {
                                val = dt * s_dInt_v_6x6[row * 6 + j_local];
                            } else if (row >= 6 && j_local >= 6) {
                                val = (row == j_local) ? dt : static_cast<T>(0);
                            } else { val = static_cast<T>(0); }
                        } else {
                            int i_local = row - 18;
                            T diag = (i_local == j_local) ? static_cast<T>(1) : static_cast<T>(0);
                            val = diag + dt * s_df_du[324 + j_local * 18 + i_local];
                        }
                    } else {
                        // d/du column   (dqdd/du = Minv)
                        int j_local = col - 36;
                        if (row < 18) {
                            val = static_cast<T>(0);
                        } else {
                            int i_local = row - 18;
                            int midx = (i_local <= j_local) * (j_local * 18 + i_local) + (i_local > j_local) * (i_local * 18 + j_local);
                            val = dt * s_Minv[midx];
                        }
                    }
                    s_dAB[ind] = val;
                }
                else if constexpr (IT == IntegratorType::SEMI_IMPLICIT_EULER) {
                    T val = static_cast<T>(0);
                    if (col < 18) {
                        // d/dq column. dvdq[k,c] = dt*J_qq[k,c] = dt*s_df_du[c*n + k].
                        int c = col;
                        if (row < 18) {
                            T dInt_q_term = (row < 6 && c < 6) ? s_dInt_q_6x6[row * 6 + c]
                                           : ((row >= 6 && c >= 6) ? ((row == c) ? static_cast<T>(1) : static_cast<T>(0)) : static_cast<T>(0));
                            T mm;
                            if (row < 6) { mm = static_cast<T>(0); for (int k = 0; k < 6; ++k) mm += s_dInt_v_6x6[row * 6 + k] * (dt * s_df_du[c * 18 + k]); }
                            else { mm = dt * s_df_du[c * 18 + row]; }
                            val = dInt_q_term + dt * mm;
                        } else {
                            int i_local = row - 18;
                            val = dt * s_df_du[c * 18 + i_local];
                        }
                    } else if (col < 36) {
                        // d/dqd column. dvdv[k,c] = (k==c) + dt*J_qv[k,c].
                        int c = col - 18;
                        if (row < 18) {
                            T mm;
                            if (row < 6) { mm = static_cast<T>(0); for (int k = 0; k < 6; ++k) { T dvdv_k = ((k == c) ? static_cast<T>(1) : static_cast<T>(0)) + dt * s_df_du[324 + c * 18 + k]; mm += s_dInt_v_6x6[row * 6 + k] * dvdv_k; } }
                            else { mm = ((row == c) ? static_cast<T>(1) : static_cast<T>(0)) + dt * s_df_du[324 + c * 18 + row]; }
                            val = dt * mm;
                        } else {
                            int i_local = row - 18;
                            T diag = (i_local == c) ? static_cast<T>(1) : static_cast<T>(0);
                            val = diag + dt * s_df_du[324 + c * 18 + i_local];
                        }
                    } else {
                        // d/du column. dvdu[k,c] = dt*Minv[k,c] (SYMMETRIC_UPPER).
                        int c = col - 36;
                        if (row < 18) {
                            T mm;
                            if (row < 6) { mm = static_cast<T>(0); for (int k = 0; k < 6; ++k) { int midx = (k <= c) * (c * 18 + k) + (k > c) * (k * 18 + c); mm += s_dInt_v_6x6[row * 6 + k] * (dt * s_Minv[midx]); } }
                            else { int midx = (row <= c) * (c * 18 + row) + (row > c) * (row * 18 + c); mm = dt * s_Minv[midx]; }
                            val = dt * mm;
                        } else {
                            int i_local = row - 18;
                            int midx = (i_local <= c) * (c * 18 + i_local) + (i_local > c) * (i_local * 18 + c);
                            val = dt * s_Minv[midx];
                        }
                    }
                    s_dAB[ind] = val;
                }
                else if constexpr (IT == IntegratorType::TRAPEZOIDAL) {
                    T val = static_cast<T>(0);
                    T dt2h = static_cast<T>(0.5) * dt * dt;
                    if (col < 18) {
                        // d/dq column. dw/dq[k] = dt2h*J_qq[c*n+k].
                        int c = col;
                        if (row < 18) {
                            T dInt_q_term = (row < 6 && c < 6) ? s_dInt_q_6x6[row * 6 + c]
                                           : ((row >= 6 && c >= 6) ? ((row == c) ? static_cast<T>(1) : static_cast<T>(0)) : static_cast<T>(0));
                            T mm;
                            if (row < 6) { mm = static_cast<T>(0); for (int k = 0; k < 6; ++k) mm += s_dInt_v_6x6[row * 6 + k] * (dt2h * s_df_du[c * 18 + k]); }
                            else { mm = dt2h * s_df_du[c * 18 + row]; }
                            val = dInt_q_term + mm;
                        } else {
                            int i_local = row - 18;
                            val = dt * s_df_du[c * 18 + i_local];
                        }
                    } else if (col < 36) {
                        // d/dqd column. dw/dqd[k] = (k==c?dt:0) + dt2h*J_qv[k].
                        int c = col - 18;
                        if (row < 18) {
                            T mm;
                            if (row < 6) { mm = static_cast<T>(0); for (int k = 0; k < 6; ++k) { T dw_k = ((k == c) ? dt : static_cast<T>(0)) + dt2h * s_df_du[324 + c * 18 + k]; mm += s_dInt_v_6x6[row * 6 + k] * dw_k; } }
                            else { mm = ((row == c) ? dt : static_cast<T>(0)) + dt2h * s_df_du[324 + c * 18 + row]; }
                            val = mm;
                        } else {
                            int i_local = row - 18;
                            T diag = (i_local == c) ? static_cast<T>(1) : static_cast<T>(0);
                            val = diag + dt * s_df_du[324 + c * 18 + i_local];
                        }
                    } else {
                        // d/du column. dw/du[k] = dt2h*Minv[k,c] (SYMMETRIC_UPPER).
                        int c = col - 36;
                        if (row < 18) {
                            T mm;
                            if (row < 6) { mm = static_cast<T>(0); for (int k = 0; k < 6; ++k) { int midx = (k <= c) * (c * 18 + k) + (k > c) * (k * 18 + c); mm += s_dInt_v_6x6[row * 6 + k] * (dt2h * s_Minv[midx]); } }
                            else { int midx = (row <= c) * (c * 18 + row) + (row > c) * (row * 18 + c); mm = dt2h * s_Minv[midx]; }
                            val = mm;
                        } else {
                            int i_local = row - 18;
                            int midx = (i_local <= c) * (c * 18 + i_local) + (i_local > c) * (i_local * 18 + c);
                            val = dt * s_Minv[midx];
                        }
                    }
                    s_dAB[ind] = val;
                }
                else {
                    static_assert(IT == IntegratorType::EULER || IT == IntegratorType::SEMI_IMPLICIT_EULER || IT == IntegratorType::TRAPEZOIDAL,
                                  "dAB assembly handles single-stage IT only; Midpoint/RK3/RK4 are routed through gen_integrator_gradient_multistage.");
                }
            }
            __syncthreads();
            integrator_finish<T, IT>(s_x_kp1, s_q, s_qd, s_qdd, dt);
            if constexpr (MUJOCO_OUTPUT) {
                // === mjx output convention (floating-base integrator gradient) ===
                __syncthreads();
                T *s_mjx = s_temp;   // 2n*3n mjx output band (dead FD-grad pool)
                const bool si_mjx = (IT == IntegratorType::SEMI_IMPLICIT_EULER);
                // Phase 1: per (half, output-column) reframe (reads s_dAB, writes s_mjx)
                for(int gi = threadIdx.x + threadIdx.y*blockDim.x; gi < 108; gi += blockDim.x*blockDim.y){
                    T qx = s_q[3], qy = s_q[4], qz = s_q[5], qw = s_q[6];
                    T xx = qx*qx, yy = qy*qy, zz = qz*qz;
                    T xy = qx*qy, xz = qx*qz, yz = qy*qz, wx = qw*qx, wy = qw*qy, wz = qw*qz;
                    T R[9];
                    R[0] = static_cast<T>(1) - static_cast<T>(2)*(yy+zz); R[1] = static_cast<T>(2)*(xy-wz);                    R[2] = static_cast<T>(2)*(xz+wy);
                    R[3] = static_cast<T>(2)*(xy+wz);                    R[4] = static_cast<T>(1) - static_cast<T>(2)*(xx+zz); R[5] = static_cast<T>(2)*(yz-wx);
                    R[6] = static_cast<T>(2)*(xz-wy);                    R[7] = static_cast<T>(2)*(yz+wx);                    R[8] = static_cast<T>(1) - static_cast<T>(2)*(xx+yy);
                    T vlin[3] = {s_qd[0], s_qd[1], s_qd[2]};
                    T ulin[3] = {s_u[0],  s_u[1],  s_u[2]};
                    // qd_{k+1,pin}[lin] = (qd + dt*qdd)[lin] (for the g_dot velocity-output term)
                    T qk1lin[3] = {s_qd[0] + dt*s_qdd[0], s_qd[1] + dt*s_qdd[1], s_qd[2] + dt*s_qdd[2]};
                    int half = gi / 54;
                    int c    = gi % 54;
                    int base = half * 18;
                    int cblk = c / 18;   // 0=q-block, 1=qd-block, 2=u-block
                    int cl   = c % 18;   // column-local index within the block
                    int boff = cblk * 18;   // block column offset (0, n, 2n)
                    T inner[18];
                    for (int r = 0; r < 18; ++r) {
                      int o = base + r;
                      if (cl < 3) { inner[r] = s_dAB[(boff+0)*36+o]*R[cl*3+0] + s_dAB[(boff+1)*36+o]*R[cl*3+1] + s_dAB[(boff+2)*36+o]*R[cl*3+2]; }
                      else { inner[r] = s_dAB[c*36+o]; }
                    }
                    if (cblk == 0 && c >= 3 && c < 6) {
                      int a = c - 3;
                      T ea[3] = {static_cast<T>(0),static_cast<T>(0),static_cast<T>(0)}; ea[a] = static_cast<T>(1);
                      T jc[3] = {ea[1]*vlin[2]-ea[2]*vlin[1], ea[2]*vlin[0]-ea[0]*vlin[2], ea[0]*vlin[1]-ea[1]*vlin[0]};
                      T uc[3] = {ea[1]*ulin[2]-ea[2]*ulin[1], ea[2]*ulin[0]-ea[0]*ulin[2], ea[0]*ulin[1]-ea[1]*ulin[0]};
                      for (int r = 0; r < 18; ++r) {
                        int o = base + r;
                        inner[r] += s_dAB[(18+0)*36+o]*(-jc[0]) + s_dAB[(18+1)*36+o]*(-jc[1]) + s_dAB[(18+2)*36+o]*(-jc[2]);
                        inner[r] += s_dAB[(36+0)*36+o]*(-uc[0]) + s_dAB[(36+1)*36+o]*(-uc[1]) + s_dAB[(36+2)*36+o]*(-uc[2]);
                      }
                    }
                    T l0 = inner[0], l1 = inner[1], l2 = inner[2];
                    inner[0] = R[0]*l0 + R[1]*l1 + R[2]*l2;
                    inner[1] = R[3]*l0 + R[4]*l1 + R[5]*l2;
                    inner[2] = R[6]*l0 + R[7]*l1 + R[8]*l2;
                    if (half == 1 && cblk == 0 && c >= 3 && c < 6) {
                      int a = c - 3;
                      T ea[3] = {static_cast<T>(0),static_cast<T>(0),static_cast<T>(0)}; ea[a] = static_cast<T>(1);
                      T sk[3] = {ea[1]*qk1lin[2]-ea[2]*qk1lin[1], ea[2]*qk1lin[0]-ea[0]*qk1lin[2], ea[0]*qk1lin[1]-ea[1]*qk1lin[0]};
                      inner[0] += R[0]*sk[0] + R[1]*sk[1] + R[2]*sk[2];
                      inner[1] += R[3]*sk[0] + R[4]*sk[1] + R[5]*sk[2];
                      inner[2] += R[6]*sk[0] + R[7]*sk[1] + R[8]*sk[2];
                    }
                    for (int r = 0; r < 18; ++r) s_mjx[c*36+(base+r)] = inner[r];
                }
                __syncthreads();
                // Phase 2: top-half base-linear rows = mjx global-add tangent (reads s_mjx bottom rows)
                for(int a = threadIdx.x + threadIdx.y*blockDim.x; a < 3; a += blockDim.x*blockDim.y){
                    int o = a;
                    for (int c = 0; c < 54; ++c) s_mjx[c*36+o] = static_cast<T>(0);
                    s_mjx[a*36+o] = static_cast<T>(1);   // identity on base-linear q col a
                    if (si_mjx) {
                      for (int c = 0; c < 54; ++c) s_mjx[c*36+o] += dt * s_mjx[c*36+(18+a)];
                    } else {
                      s_mjx[(18+a)*36+o] += dt;   // dt on qd base-linear col a
                    }
                }
                __syncthreads();
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 1944; ind += blockDim.x*blockDim.y){
                    s_dAB[ind] = s_mjx[ind];
                }
                __syncthreads();
                // mjx retract: base position global additive step (q_out[0:3] = q_in[0:3] + dt*qd[0:3])
                if (threadIdx.x == 0 && threadIdx.y == 0) {
                    s_x_kp1[0] = s_q[0] + (dt) * s_qd[0];
                    s_x_kp1[1] = s_q[1] + (dt) * s_qd[1];
                    s_x_kp1[2] = s_q[2] + (dt) * s_qd[2];
                }
                __syncthreads();
                // mjx output: base-linear rows of (s_x_kp1 + 19) <- R * rows
                if (threadIdx.x == 0 && threadIdx.y == 0) {
                    T qx = s_q[3], qy = s_q[4], qz = s_q[5], qw = s_q[6];
                    T xx = qx*qx, yy = qy*qy, zz = qz*qz;
                    T xy = qx*qy, xz = qx*qz, yz = qy*qz, wx = qw*qx, wy = qw*qy, wz = qw*qz;
                    T R[9];
                    R[0] = static_cast<T>(1) - static_cast<T>(2)*(yy+zz); R[1] = static_cast<T>(2)*(xy-wz);                    R[2] = static_cast<T>(2)*(xz+wy);
                    R[3] = static_cast<T>(2)*(xy+wz);                    R[4] = static_cast<T>(1) - static_cast<T>(2)*(xx+zz); R[5] = static_cast<T>(2)*(yz-wx);
                    R[6] = static_cast<T>(2)*(xz-wy);                    R[7] = static_cast<T>(2)*(yz+wx);                    R[8] = static_cast<T>(1) - static_cast<T>(2)*(xx+yy);
                    T b0 = (s_x_kp1 + 19)[0], b1 = (s_x_kp1 + 19)[1], b2 = (s_x_kp1 + 19)[2];
                    (s_x_kp1 + 19)[0] = R[0]*b0 + R[1]*b1 + R[2]*b2;
                    (s_x_kp1 + 19)[1] = R[3]*b0 + R[4]*b1 + R[5]*b2;
                    (s_x_kp1 + 19)[2] = R[6]*b0 + R[7]*b1 + R[8]*b2;
                }
                __syncthreads();
                // mjx x_kp1: base quaternion xyzw->wxyz (inverse of input reorder)
                if (threadIdx.x == 0 && threadIdx.y == 0) {
                    T qw_out = s_x_kp1[6];
                    s_x_kp1[6] = s_x_kp1[5]; s_x_kp1[5] = s_x_kp1[4]; s_x_kp1[4] = s_x_kp1[3]; s_x_kp1[3] = qw_out;
                }
                __syncthreads();
            }
        }
        else {
            static_assert(!MUJOCO_OUTPUT, "integrator_gradient MUJOCO_OUTPUT is single-stage (EULER/SEMI_IMPLICIT_EULER) only; "
                          "multi-stage RK mjx is deferred.");
            // --- multi-stage gradient: save original q, qd ---
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 19; ind += blockDim.x*blockDim.y){
                s_q_orig[ind] = s_q[ind];
            }
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 18; ind += blockDim.x*blockDim.y){
                s_qd_orig[ind] = s_qd[ind];
            }
            __syncthreads();
            // --- multi-stage gradient: stage 1 ---
            if constexpr (IT == IntegratorType::MIDPOINT || IT == IntegratorType::RK3 || IT == IntegratorType::RK4) {
                //TODO: there is a slightly faster way as s_v does not change -- thus no recompute needed
                minv_inner<T, true>(s_Minv, s_q, s_XImats, s_topology_helpers, s_temp, nullptr);
                inverse_dynamics_inner<T>(s_temp, s_vaf, s_q, s_qd, s_XImats, s_topology_helpers, &s_temp[18], d_f_ext, gravity);
                forward_dynamics_finish<T>(s_qdd, s_u, s_temp, s_Minv);
                __syncthreads();
                inverse_dynamics_inner_vaf<T>(s_vaf, s_q, s_qd, s_qdd, s_XImats, s_topology_helpers, s_temp, d_f_ext, gravity);
                inverse_dynamics_gradient_inner<T, USE_DA_DF_SPILL>(s_dc_du, s_q, s_qd, s_vaf, s_XImats, s_topology_helpers, s_temp, d_temp_spill, gravity);
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 648; ind += blockDim.x*blockDim.y){
                    int row = ind % 18; int dc_col_offset = ind - row;
                    // account for the fact that Minv is an SYMMETRIC_UPPER triangular matrix
                    T val = static_cast<T>(0);
                    for(int col = 0; col < 18; col++) {
                        int index = (row <= col) * (col * 18 + row) + (row > col) * (row * 18 + col);
                        val += s_Minv[index] * s_dc_du[dc_col_offset + col];
                    }
                    s_df_du[ind] = -val;
                }
                __syncthreads();
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 18; ind += blockDim.x*blockDim.y){
                    s_stage_grad_qdd[0 + ind] = s_qdd[ind];
                }
                __syncthreads();
                constexpr T c_prev_s1 = static_cast<T>(0);
                T *s_D_qdd_cur = &s_D_qdd_stage[0 * 972];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 972; ind += blockDim.x*blockDim.y){
                    int r = ind % 18;
                    int c = ind / 18;
                    T base = static_cast<T>(0);
                    if (c < 18) {
                        base = s_df_du[c * 18 + r];                       // J_qq[r, c]
                    } else if (c < 36) {
                        int cc = c - 18;
                        base = c_prev_s1 * dt * s_df_du[cc * 18 + r] + s_df_du[324 + cc * 18 + r];  // c*dt*J_qq + J_qv
                    } else {
                        int cc = c - 36;
                        int midx = (r <= cc) * (cc * 18 + r) + (r > cc) * (r * 18 + cc);
                        base = s_Minv[midx];                                  // Minv[r, cc]
                    }
                    s_D_qdd_cur[c * 18 + r] = base;
                }
                __syncthreads();
            }
            // --- multi-stage gradient: stage 2 ---
            if constexpr (IT == IntegratorType::MIDPOINT || IT == IntegratorType::RK3 || IT == IntegratorType::RK4) {
                constexpr T c_offset = (IT == IntegratorType::MIDPOINT) ? static_cast<T>(0.5) : (IT == IntegratorType::RK3) ? static_cast<T>(0.5) : (IT == IntegratorType::RK4) ? static_cast<T>(0.5) : static_cast<T>(0);
                if(threadIdx.x == 0 && threadIdx.y == 0){
                    T v_scaled[18];
                    for (int i = 0; i < 18; ++i) v_scaled[i] = c_offset * dt * s_qd_orig[i];
                    grid_integrate_floating_q<T, 19>(s_q_orig, v_scaled, s_q);
                }
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 18; ind += blockDim.x*blockDim.y){
                    s_qd[ind] = s_qd_orig[ind] + c_offset * dt * s_stage_grad_qdd[0 + ind];
                }
                __syncthreads();
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                __syncthreads();
                if(threadIdx.x == 0 && threadIdx.y == 0){
                    T v_dt_stage[18];
                    for (int i = 0; i < 18; ++i) v_dt_stage[i] = c_offset * dt * s_qd_orig[i];
                    grid_dIntegrate_q_block<T>(v_dt_stage, s_dInt_q_6x6);
                    grid_dIntegrate_v_block<T>(v_dt_stage, s_dInt_v_6x6);
                }
                __syncthreads();
                //TODO: there is a slightly faster way as s_v does not change -- thus no recompute needed
                minv_inner<T, true>(s_Minv, s_q, s_XImats, s_topology_helpers, s_temp, nullptr);
                inverse_dynamics_inner<T>(s_temp, s_vaf, s_q, s_qd, s_XImats, s_topology_helpers, &s_temp[18], d_f_ext, gravity);
                forward_dynamics_finish<T>(s_qdd, s_u, s_temp, s_Minv);
                __syncthreads();
                inverse_dynamics_inner_vaf<T>(s_vaf, s_q, s_qd, s_qdd, s_XImats, s_topology_helpers, s_temp, d_f_ext, gravity);
                inverse_dynamics_gradient_inner<T, USE_DA_DF_SPILL>(s_dc_du, s_q, s_qd, s_vaf, s_XImats, s_topology_helpers, s_temp, d_temp_spill, gravity);
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 648; ind += blockDim.x*blockDim.y){
                    int row = ind % 18; int dc_col_offset = ind - row;
                    // account for the fact that Minv is an SYMMETRIC_UPPER triangular matrix
                    T val = static_cast<T>(0);
                    for(int col = 0; col < 18; col++) {
                        int index = (row <= col) * (col * 18 + row) + (row > col) * (row * 18 + col);
                        val += s_Minv[index] * s_dc_du[dc_col_offset + col];
                    }
                    s_df_du[ind] = -val;
                }
                __syncthreads();
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 18; ind += blockDim.x*blockDim.y){
                    s_stage_grad_qdd[18 + ind] = s_qdd[ind];
                }
                __syncthreads();
                constexpr T c_prev_s2 = (IT == IntegratorType::MIDPOINT) ? static_cast<T>(0.5) : (IT == IntegratorType::RK3) ? static_cast<T>(0.5) : (IT == IntegratorType::RK4) ? static_cast<T>(0.5) : static_cast<T>(0);
                T *s_D_qdd_cur = &s_D_qdd_stage[1 * 972];
                T *s_D_qdd_prev = &s_D_qdd_stage[0];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 972; ind += blockDim.x*blockDim.y){
                    int r = ind % 18;
                    int c = ind / 18;
                    T base = static_cast<T>(0);
                    if (c < 18) {
                        // (J_qq @ dInt_q)[r, c]
                        if (c < 6) {
                            for (int k = 0; k < 6; ++k) base += s_df_du[k * 18 + r] * s_dInt_q_6x6[k * 6 + c];
                        } else {
                            base = s_df_du[c * 18 + r];
                        }
                    } else if (c < 36) {
                        int cc = c - 18;
                        // c*dt*(J_qq @ dInt_v)[r, cc] + J_qv[r, cc]
                        T proj = static_cast<T>(0);
                        if (cc < 6) {
                            for (int k = 0; k < 6; ++k) proj += s_df_du[k * 18 + r] * s_dInt_v_6x6[k * 6 + cc];
                        } else {
                            proj = s_df_du[cc * 18 + r];
                        }
                        base = c_prev_s2 * dt * proj + s_df_du[324 + cc * 18 + r];
                    } else {
                        int cc = c - 36;
                        int midx = (r <= cc) * (cc * 18 + r) + (r > cc) * (r * 18 + cc);
                        base = s_Minv[midx];                                  // Minv[r, cc]
                    }
                    T chain = static_cast<T>(0);
                    for (int k = 0; k < 18; ++k) {
                        chain += s_df_du[324 + k * 18 + r] * s_D_qdd_prev[c * 18 + k];
                    }
                    s_D_qdd_cur[c * 18 + r] = base + c_prev_s2 * dt * chain;
                }
                __syncthreads();
            }
            // --- multi-stage gradient: stage 3 ---
            if constexpr (IT == IntegratorType::RK3 || IT == IntegratorType::RK4) {
                constexpr T c_offset = (IT == IntegratorType::RK3) ? static_cast<T>(0.75) : (IT == IntegratorType::RK4) ? static_cast<T>(0.5) : static_cast<T>(0);
                if(threadIdx.x == 0 && threadIdx.y == 0){
                    T v_scaled[18];
                    for (int i = 0; i < 18; ++i) v_scaled[i] = c_offset * dt * s_qd_orig[i];
                    grid_integrate_floating_q<T, 19>(s_q_orig, v_scaled, s_q);
                }
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 18; ind += blockDim.x*blockDim.y){
                    s_qd[ind] = s_qd_orig[ind] + c_offset * dt * s_stage_grad_qdd[18 + ind];
                }
                __syncthreads();
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                __syncthreads();
                if(threadIdx.x == 0 && threadIdx.y == 0){
                    T v_dt_stage[18];
                    for (int i = 0; i < 18; ++i) v_dt_stage[i] = c_offset * dt * s_qd_orig[i];
                    grid_dIntegrate_q_block<T>(v_dt_stage, s_dInt_q_6x6);
                    grid_dIntegrate_v_block<T>(v_dt_stage, s_dInt_v_6x6);
                }
                __syncthreads();
                //TODO: there is a slightly faster way as s_v does not change -- thus no recompute needed
                minv_inner<T, true>(s_Minv, s_q, s_XImats, s_topology_helpers, s_temp, nullptr);
                inverse_dynamics_inner<T>(s_temp, s_vaf, s_q, s_qd, s_XImats, s_topology_helpers, &s_temp[18], d_f_ext, gravity);
                forward_dynamics_finish<T>(s_qdd, s_u, s_temp, s_Minv);
                __syncthreads();
                inverse_dynamics_inner_vaf<T>(s_vaf, s_q, s_qd, s_qdd, s_XImats, s_topology_helpers, s_temp, d_f_ext, gravity);
                inverse_dynamics_gradient_inner<T, USE_DA_DF_SPILL>(s_dc_du, s_q, s_qd, s_vaf, s_XImats, s_topology_helpers, s_temp, d_temp_spill, gravity);
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 648; ind += blockDim.x*blockDim.y){
                    int row = ind % 18; int dc_col_offset = ind - row;
                    // account for the fact that Minv is an SYMMETRIC_UPPER triangular matrix
                    T val = static_cast<T>(0);
                    for(int col = 0; col < 18; col++) {
                        int index = (row <= col) * (col * 18 + row) + (row > col) * (row * 18 + col);
                        val += s_Minv[index] * s_dc_du[dc_col_offset + col];
                    }
                    s_df_du[ind] = -val;
                }
                __syncthreads();
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 18; ind += blockDim.x*blockDim.y){
                    s_stage_grad_qdd[36 + ind] = s_qdd[ind];
                }
                __syncthreads();
                constexpr T c_prev_s3 = (IT == IntegratorType::RK3) ? static_cast<T>(0.75) : (IT == IntegratorType::RK4) ? static_cast<T>(0.5) : static_cast<T>(0);
                T *s_D_qdd_cur = &s_D_qdd_stage[2 * 972];
                T *s_D_qdd_prev = &s_D_qdd_stage[972];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 972; ind += blockDim.x*blockDim.y){
                    int r = ind % 18;
                    int c = ind / 18;
                    T base = static_cast<T>(0);
                    if (c < 18) {
                        // (J_qq @ dInt_q)[r, c]
                        if (c < 6) {
                            for (int k = 0; k < 6; ++k) base += s_df_du[k * 18 + r] * s_dInt_q_6x6[k * 6 + c];
                        } else {
                            base = s_df_du[c * 18 + r];
                        }
                    } else if (c < 36) {
                        int cc = c - 18;
                        // c*dt*(J_qq @ dInt_v)[r, cc] + J_qv[r, cc]
                        T proj = static_cast<T>(0);
                        if (cc < 6) {
                            for (int k = 0; k < 6; ++k) proj += s_df_du[k * 18 + r] * s_dInt_v_6x6[k * 6 + cc];
                        } else {
                            proj = s_df_du[cc * 18 + r];
                        }
                        base = c_prev_s3 * dt * proj + s_df_du[324 + cc * 18 + r];
                    } else {
                        int cc = c - 36;
                        int midx = (r <= cc) * (cc * 18 + r) + (r > cc) * (r * 18 + cc);
                        base = s_Minv[midx];                                  // Minv[r, cc]
                    }
                    T chain = static_cast<T>(0);
                    for (int k = 0; k < 18; ++k) {
                        chain += s_df_du[324 + k * 18 + r] * s_D_qdd_prev[c * 18 + k];
                    }
                    s_D_qdd_cur[c * 18 + r] = base + c_prev_s3 * dt * chain;
                }
                __syncthreads();
            }
            // --- multi-stage gradient: stage 4 ---
            if constexpr (IT == IntegratorType::RK4) {
                constexpr T c_offset = (IT == IntegratorType::RK4) ? static_cast<T>(1.0) : static_cast<T>(0);
                if(threadIdx.x == 0 && threadIdx.y == 0){
                    T v_scaled[18];
                    for (int i = 0; i < 18; ++i) v_scaled[i] = c_offset * dt * s_qd_orig[i];
                    grid_integrate_floating_q<T, 19>(s_q_orig, v_scaled, s_q);
                }
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 18; ind += blockDim.x*blockDim.y){
                    s_qd[ind] = s_qd_orig[ind] + c_offset * dt * s_stage_grad_qdd[36 + ind];
                }
                __syncthreads();
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                __syncthreads();
                if(threadIdx.x == 0 && threadIdx.y == 0){
                    T v_dt_stage[18];
                    for (int i = 0; i < 18; ++i) v_dt_stage[i] = c_offset * dt * s_qd_orig[i];
                    grid_dIntegrate_q_block<T>(v_dt_stage, s_dInt_q_6x6);
                    grid_dIntegrate_v_block<T>(v_dt_stage, s_dInt_v_6x6);
                }
                __syncthreads();
                //TODO: there is a slightly faster way as s_v does not change -- thus no recompute needed
                minv_inner<T, true>(s_Minv, s_q, s_XImats, s_topology_helpers, s_temp, nullptr);
                inverse_dynamics_inner<T>(s_temp, s_vaf, s_q, s_qd, s_XImats, s_topology_helpers, &s_temp[18], d_f_ext, gravity);
                forward_dynamics_finish<T>(s_qdd, s_u, s_temp, s_Minv);
                __syncthreads();
                inverse_dynamics_inner_vaf<T>(s_vaf, s_q, s_qd, s_qdd, s_XImats, s_topology_helpers, s_temp, d_f_ext, gravity);
                inverse_dynamics_gradient_inner<T, USE_DA_DF_SPILL>(s_dc_du, s_q, s_qd, s_vaf, s_XImats, s_topology_helpers, s_temp, d_temp_spill, gravity);
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 648; ind += blockDim.x*blockDim.y){
                    int row = ind % 18; int dc_col_offset = ind - row;
                    // account for the fact that Minv is an SYMMETRIC_UPPER triangular matrix
                    T val = static_cast<T>(0);
                    for(int col = 0; col < 18; col++) {
                        int index = (row <= col) * (col * 18 + row) + (row > col) * (row * 18 + col);
                        val += s_Minv[index] * s_dc_du[dc_col_offset + col];
                    }
                    s_df_du[ind] = -val;
                }
                __syncthreads();
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 18; ind += blockDim.x*blockDim.y){
                    s_stage_grad_qdd[54 + ind] = s_qdd[ind];
                }
                __syncthreads();
                constexpr T c_prev_s4 = (IT == IntegratorType::RK4) ? static_cast<T>(1.0) : static_cast<T>(0);
                T *s_D_qdd_cur = &s_D_qdd_stage[3 * 972];
                T *s_D_qdd_prev = &s_D_qdd_stage[1944];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 972; ind += blockDim.x*blockDim.y){
                    int r = ind % 18;
                    int c = ind / 18;
                    T base = static_cast<T>(0);
                    if (c < 18) {
                        // (J_qq @ dInt_q)[r, c]
                        if (c < 6) {
                            for (int k = 0; k < 6; ++k) base += s_df_du[k * 18 + r] * s_dInt_q_6x6[k * 6 + c];
                        } else {
                            base = s_df_du[c * 18 + r];
                        }
                    } else if (c < 36) {
                        int cc = c - 18;
                        // c*dt*(J_qq @ dInt_v)[r, cc] + J_qv[r, cc]
                        T proj = static_cast<T>(0);
                        if (cc < 6) {
                            for (int k = 0; k < 6; ++k) proj += s_df_du[k * 18 + r] * s_dInt_v_6x6[k * 6 + cc];
                        } else {
                            proj = s_df_du[cc * 18 + r];
                        }
                        base = c_prev_s4 * dt * proj + s_df_du[324 + cc * 18 + r];
                    } else {
                        int cc = c - 36;
                        int midx = (r <= cc) * (cc * 18 + r) + (r > cc) * (r * 18 + cc);
                        base = s_Minv[midx];                                  // Minv[r, cc]
                    }
                    T chain = static_cast<T>(0);
                    for (int k = 0; k < 18; ++k) {
                        chain += s_df_du[324 + k * 18 + r] * s_D_qdd_prev[c * 18 + k];
                    }
                    s_D_qdd_cur[c * 18 + r] = base + c_prev_s4 * dt * chain;
                }
                __syncthreads();
            }
            if(threadIdx.x == 0 && threadIdx.y == 0){
                T v_dt_final[18];
                for (int i = 0; i < 18; ++i) v_dt_final[i] = dt * s_qd_orig[i];
                grid_dIntegrate_q_block<T>(v_dt_final, s_dInt_q_6x6);
                grid_dIntegrate_v_block<T>(v_dt_final, s_dInt_v_6x6);
            }
            __syncthreads();
            // --- multi-stage gradient: assemble final dAB ---
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 1944; ind += blockDim.x*blockDim.y){
                int row = ind % 36;
                int col = ind / 36;
                T val = static_cast<T>(0);
                if (row < 18) {
                    if (col < 18) {
                        if (row < 6 && col < 6) { val = s_dInt_q_6x6[row * 6 + col]; }
                        else if (row >= 6 && col >= 6) { val = (row == col) ? static_cast<T>(1) : static_cast<T>(0); }
                        else { val = static_cast<T>(0); }
                    } else if (col < 36) {
                        int j = col - 18;
                        if (row < 6 && j < 6) { val = dt * s_dInt_v_6x6[row * 6 + j]; }
                        else if (row >= 6 && j >= 6) { val = (row == j) ? dt : static_cast<T>(0); }
                        else { val = static_cast<T>(0); }
                    } else {
                        val = static_cast<T>(0);
                    }
                } else {
                    int r = row - 18;
                    // bottom half: qd_{k+1} = qd + dt * sum(b_i * qdd_i)
                    T identity_term = ((col >= 18 && col < 36) && (r == col - 18)) ? static_cast<T>(1) : static_cast<T>(0);
                    T accel_term = static_cast<T>(0);
                    if constexpr (IT == IntegratorType::MIDPOINT) {
                        accel_term += static_cast<T>(1.0) * s_D_qdd_stage[972 + col * 18 + r];
                    }
                    if constexpr (IT == IntegratorType::RK3) {
                        accel_term += static_cast<T>(0.2222222222222222) * s_D_qdd_stage[0 + col * 18 + r];
                        accel_term += static_cast<T>(0.3333333333333333) * s_D_qdd_stage[972 + col * 18 + r];
                        accel_term += static_cast<T>(0.4444444444444444) * s_D_qdd_stage[1944 + col * 18 + r];
                    }
                    if constexpr (IT == IntegratorType::RK4) {
                        accel_term += static_cast<T>(0.16666666666666666) * s_D_qdd_stage[0 + col * 18 + r];
                        accel_term += static_cast<T>(0.3333333333333333) * s_D_qdd_stage[972 + col * 18 + r];
                        accel_term += static_cast<T>(0.3333333333333333) * s_D_qdd_stage[1944 + col * 18 + r];
                        accel_term += static_cast<T>(0.16666666666666666) * s_D_qdd_stage[2916 + col * 18 + r];
                    }
                    val = identity_term + dt * accel_term;
                }
                s_dAB[ind] = val;
            }
            __syncthreads();
            // --- multi-stage gradient: assemble x_{k+1} ---
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 18; ind += blockDim.x*blockDim.y){
                T accel = static_cast<T>(0);
                if constexpr (IT == IntegratorType::MIDPOINT) {
                    accel += static_cast<T>(1.0) * s_stage_grad_qdd[18 + ind];
                }
                if constexpr (IT == IntegratorType::RK3) {
                    accel += static_cast<T>(0.2222222222222222) * s_stage_grad_qdd[0 + ind];
                    accel += static_cast<T>(0.3333333333333333) * s_stage_grad_qdd[18 + ind];
                    accel += static_cast<T>(0.4444444444444444) * s_stage_grad_qdd[36 + ind];
                }
                if constexpr (IT == IntegratorType::RK4) {
                    accel += static_cast<T>(0.16666666666666666) * s_stage_grad_qdd[0 + ind];
                    accel += static_cast<T>(0.3333333333333333) * s_stage_grad_qdd[18 + ind];
                    accel += static_cast<T>(0.3333333333333333) * s_stage_grad_qdd[36 + ind];
                    accel += static_cast<T>(0.16666666666666666) * s_stage_grad_qdd[54 + ind];
                }
                s_x_kp1[19 + ind] = s_qd_orig[ind] + dt * accel;
            }
            __syncthreads();
            if(threadIdx.x == 0 && threadIdx.y == 0){
                T v_scaled_x[18];
                for (int i = 0; i < 18; ++i) v_scaled_x[i] = dt * s_qd_orig[i];
                grid_integrate_floating_q<T, 19>(s_q_orig, v_scaled_x, s_x_kp1);
            }
            __syncthreads();
        }
    }

    /**
     * Computes the gradient of the integrator step per timestep
     *
     * @param d_dAB is a pointer to memory for [A | B] of size 2*NUM_VEL*3*NUM_VEL per timestep
     * @param d_workspace is the L2-pinned global scratch for the spilled s_D_qdd_stage (LITE/MINIMAL tiers)
     * @param d_q_qd_u is the packed joint positions, velocities, and input torques
     * @param stride_q_qd_u is the stride between each (q, qd, u) tuple in d_q_qd_u
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU
     * @param d_f_ext is the (optional) GLOBAL external forces, body-major 6*NUM_BODIES local-frame, or nullptr
     * @param gravity is the gravity constant
     * @param dt is the integration timestep
     * @param num_timesteps is the length of the trajectory (or overloaded as test_iters for timing)
     */
    template <typename T, IntegratorType IT = IntegratorType::EULER, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER, bool MUJOCO_OUTPUT = false>
    __global__
    __launch_bounds__(MAX_PERF_LEVEL_THREADS)
    void integrator_gradient_kernel_single_timing(T *d_dAB, unsigned char *d_workspace, const T *d_q_qd_u, const int stride_q_qd_u, const robotModel<T> *d_robotModel, T *d_f_ext, const T gravity, const T dt, const int NUM_TIMESTEPS) {
        if constexpr (RESOURCE_TIER == TIER_SHARED) {
            // GRID shared arena layout
            //   T s_q_qd_u[57]
            //   T s_dAB[1944]
            //   T s_df_du[648]
            //   T s_dc_du[648]
            //   T s_vaf[324]
            //   T s_Minv[324]
            //   T s_qdd[18]
            //   T s_q_orig[19]
            //   T s_qd_orig[18]
            //   T s_stage_grad_qdd[72]
            //   T s_D_qdd_stage[3888]
            //   T s_dInt_q_6x6[36]
            //   T s_dInt_v_6x6[36]
            //   T s_XImats[936]
            //   T s_temp[9612]
            //   int s_topology_helpers[115]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q_qd_u = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(57);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_dAB = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(1944);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_df_du = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(648);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_dc_du = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(648);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_vaf = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(324);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_Minv = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(324);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(18);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q_orig = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(19);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_qd_orig = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(18);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_stage_grad_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(72);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_D_qdd_stage = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(3888);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_dInt_q_6x6 = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(36);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_dInt_v_6x6 = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(36);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(936);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(9612);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
            int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(int) * static_cast<size_t>(115);
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(18580, 115, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            T *s_q = s_q_qd_u; T *s_qd = &s_q_qd_u[19]; T *s_u = &s_q_qd_u[38];
            T *d_temp_spill = nullptr; (void)d_temp_spill;
            // load to shared mem
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 57; ind += blockDim.x*blockDim.y){
                s_q_qd_u[ind] = d_q_qd_u[ind];
            }
            __syncthreads();
            if constexpr (MUJOCO_OUTPUT) {
                // mjx input convert: quaternion wxyz->xyzw, base-linear velocity/accel/force -> pin frame
                if (threadIdx.x == 0 && threadIdx.y == 0) {
                    T qw_in = s_q[3];
                    s_q[3] = s_q[4]; s_q[4] = s_q[5]; s_q[5] = s_q[6]; s_q[6] = qw_in;
                    T qx = s_q[3], qy = s_q[4], qz = s_q[5], qw = s_q[6];
                    T xx = qx*qx, yy = qy*qy, zz = qz*qz;
                    T xy = qx*qy, xz = qx*qz, yz = qy*qz, wx = qw*qx, wy = qw*qy, wz = qw*qz;
