                }
                __syncthreads();
                for (int r = threadIdx.x + threadIdx.y*blockDim.x; r < 18; r += blockDim.x*blockDim.y) {
                  T c0 = s_dc_du[324+0*18+r], c1 = s_dc_du[324+1*18+r], c2 = s_dc_du[324+2*18+r];
                  s_work1[0*18+r] = c0*Rd[0] + c1*Rd[1] + c2*Rd[2];
                  s_work1[1*18+r] = c0*Rd[3] + c1*Rd[4] + c2*Rd[5];
                  s_work1[2*18+r] = c0*Rd[6] + c1*Rd[7] + c2*Rd[8];
                  for (int c = 3; c < 18; c++) s_work1[c*18+r] = static_cast<T>(0);
                }
                __syncthreads();
                for (int a = 0; a < 3; a++) {
                  T dv0 = jvk[0], dv1 = jvk[1], dv2 = jvk[2];
                  T dom0 = jvk[3], dom1 = jvk[4], dom2 = jvk[5];
                  T rte0 = R[3*a+0], rte1 = R[3*a+1], rte2 = R[3*a+2];
                  T rdte0 = Rd[3*a+0], rdte1 = Rd[3*a+1], rdte2 = Rd[3*a+2];
                  T jl0 = -((dom1*rte2 - dom2*rte1) + (omega[1]*rdte2 - omega[2]*rdte1));
                  T jl1 = -((dom2*rte0 - dom0*rte2) + (omega[2]*rdte0 - omega[0]*rdte2));
                  T jl2 = -((dom0*rte1 - dom1*rte0) + (omega[0]*rdte1 - omega[1]*rdte0));
                  T edvx = (a==1)*( dv2) + (a==2)*(-dv1);
                  T edvy = (a==0)*(-dv2) + (a==2)*( dv0);
                  T edvz = (a==0)*( dv1) + (a==1)*(-dv0);
                  T jn0 = -edvx, jn1 = -edvy, jn2 = -edvz;
                  for (int r = threadIdx.x + threadIdx.y*blockDim.x; r < 18; r += blockDim.x*blockDim.y) {
                    T m0 = s_M[r + 18*0], m1 = s_M[r + 18*1], m2 = s_M[r + 18*2];
                    s_work1[(0+a)*18+r] += m0*jl0 + m1*jl1 + m2*jl2;
                    s_work1[(3+a)*18+r] += m0*jn0 + m1*jn1 + m2*jn2;
                  }
                }
                __syncthreads();
                for (int c = threadIdx.x + threadIdx.y*blockDim.x; c < 18; c += blockDim.x*blockDim.y) {
                  T m0 = s_work1[c*18+0], m1 = s_work1[c*18+1], m2 = s_work1[c*18+2];
                  s_work2[c*18+0] += R[0]*m0 + R[1]*m1 + R[2]*m2;
                  s_work2[c*18+1] += R[3]*m0 + R[4]*m1 + R[5]*m2;
                  s_work2[c*18+2] += R[6]*m0 + R[7]*m1 + R[8]*m2;
                  for (int r = 3; r < 18; r++) s_work2[c*18+r] += s_work1[c*18+r];
                }
                __syncthreads();
                for (int i = threadIdx.x + threadIdx.y*blockDim.x; i < 18; i += blockDim.x*blockDim.y) {
                  for (int j = 0; j < 18; j++) O_cross[(i*18 + j)*18 + k] = s_work2[j*18 + i];
                }
                __syncthreads();
                // --- d2tau_dqd2 slab[:,:,k] (qvel perturbation, R fixed) (block-parallel) ---
                for (int i = threadIdx.x + threadIdx.y*blockDim.x; i < 18; i += blockDim.x*blockDim.y) {
                  for (int j = 0; j < 18; j++) {
                    T s = static_cast<T>(0);
                    for (int nn = 0; nn < 18; nn++) s += T_d2qd[(i*18 + j)*18 + nn]*jqk[nn];
                    s_work1[j*18 + i] = s;
                  }
                }
                __syncthreads();
                for (int r = threadIdx.x + threadIdx.y*blockDim.x; r < 18; r += blockDim.x*blockDim.y) {
                  T c0 = s_work1[0*18+r], c1 = s_work1[1*18+r], c2 = s_work1[2*18+r];
                  s_work2[0*18+r] = c0*R[0] + c1*R[1] + c2*R[2];
                  s_work2[1*18+r] = c0*R[3] + c1*R[4] + c2*R[5];
                  s_work2[2*18+r] = c0*R[6] + c1*R[7] + c2*R[8];
                  for (int c = 3; c < 18; c++) s_work2[c*18+r] = s_work1[c*18+r];
                }
                __syncthreads();
                for (int c = threadIdx.x + threadIdx.y*blockDim.x; c < 18; c += blockDim.x*blockDim.y) {
                  T m0 = s_work2[c*18+0], m1 = s_work2[c*18+1], m2 = s_work2[c*18+2];
                  s_work1[c*18+0] = R[0]*m0 + R[1]*m1 + R[2]*m2;
                  s_work1[c*18+1] = R[3]*m0 + R[4]*m1 + R[5]*m2;
                  s_work1[c*18+2] = R[6]*m0 + R[7]*m1 + R[8]*m2;
                  for (int r = 3; r < 18; r++) s_work1[c*18+r] = s_work2[c*18+r];
                }
                __syncthreads();
                for (int rr = threadIdx.x + threadIdx.y*blockDim.x; rr < 324; rr += blockDim.x*blockDim.y) {
                  s_work2[rr] = static_cast<T>(0);
                }
                __syncthreads();
                for (int r = threadIdx.x + threadIdx.y*blockDim.x; r < 18; r += blockDim.x*blockDim.y) {
                  for (int a = 0; a < 3; a++) {
                    T rte0 = R[3*a+0], rte1 = R[3*a+1], rte2 = R[3*a+2];
                    T dvo0 = jqk[3], dvo1 = jqk[4], dvo2 = jqk[5];
                    T dvv0 = jqk[0], dvv1 = jqk[1], dvv2 = jqk[2];
                    T jl0 = -(dvo1*rte2 - dvo2*rte1);
                    T jl1 = -(dvo2*rte0 - dvo0*rte2);
                    T jl2 = -(dvo0*rte1 - dvo1*rte0);
                    T evx = (a==1)*( dvv2) + (a==2)*(-dvv1);
                    T evy = (a==0)*(-dvv2) + (a==2)*( dvv0);
                    T evz = (a==0)*( dvv1) + (a==1)*(-dvv0);
                    T jn0 = -evx, jn1 = -evy, jn2 = -evz;
                    T mr0 = s_M[r + 18*0], mr1 = s_M[r + 18*1], mr2 = s_M[r + 18*2];
                    s_work2[(0+a)*18+r] += mr0*jl0 + mr1*jl1 + mr2*jl2;
                    s_work2[(3+a)*18+r] += mr0*jn0 + mr1*jn1 + mr2*jn2;
                  }
                }
                __syncthreads();
                for (int c = threadIdx.x + threadIdx.y*blockDim.x; c < 18; c += blockDim.x*blockDim.y) {
                  T m0 = s_work2[c*18+0], m1 = s_work2[c*18+1], m2 = s_work2[c*18+2];
                  s_work1[c*18+0] += R[0]*m0 + R[1]*m1 + R[2]*m2;
                  s_work1[c*18+1] += R[3]*m0 + R[4]*m1 + R[5]*m2;
                  s_work1[c*18+2] += R[6]*m0 + R[7]*m1 + R[8]*m2;
                  for (int r = 3; r < 18; r++) s_work1[c*18+r] += s_work2[c*18+r];
                }
                __syncthreads();
                for (int i = threadIdx.x + threadIdx.y*blockDim.x; i < 18; i += blockDim.x*blockDim.y) {
                  for (int j = 0; j < 18; j++) O_d2qd[(i*18 + j)*18 + k] = s_work1[j*18 + i];
                }
                __syncthreads();
            }
            __syncthreads();
            // --- dM_dq (block3) closed form, BLOCK-PARALLEL: Step1 reframe, Step2 congruence, Step3 frame ---
            #pragma unroll 1
            for (int k = 0; k < 18; k++) {
                T qx = s_q[3], qy = s_q[4], qz = s_q[5], qw = s_q[6];
                T xx = qx*qx, yy = qy*qy, zz = qz*qz;
                T xy = qx*qy, xz = qx*qz, yz = qy*qz, wx = qw*qx, wy = qw*qy, wz = qw*qz;
                T R[9];
                R[0] = static_cast<T>(1) - static_cast<T>(2)*(yy+zz); R[1] = static_cast<T>(2)*(xy-wz);                    R[2] = static_cast<T>(2)*(xz+wy);
                R[3] = static_cast<T>(2)*(xy+wz);                    R[4] = static_cast<T>(1) - static_cast<T>(2)*(xx+zz); R[5] = static_cast<T>(2)*(yz-wx);
                R[6] = static_cast<T>(2)*(xz-wy);                    R[7] = static_cast<T>(2)*(yz+wx);                    R[8] = static_cast<T>(1) - static_cast<T>(2)*(xx+yy);
                T v_lin[3]   = {s_qd[0], s_qd[1], s_qd[2]};
                T omega[3]   = {s_qd[3], s_qd[4], s_qd[5]};
                T qdd_lin[3] = {s_qdd[0], s_qdd[1], s_qdd[2]};
                T tau_lin[3] = {s_vaf[159], s_vaf[160], s_vaf[161]};
                // pin tensor blocks in s_idsva_so (row-major tensors):
                T *T_d2q   = s_idsva_so + 0;
                T *T_d2qd  = s_idsva_so + 5832;
                T *T_cross = s_idsva_so + 11664;
                T *T_dM    = s_idsva_so + 17496;
                // mjx output blocks in s_mjx_out (same layout):
                T *O_d2q   = s_mjx_out + 0;
                T *O_d2qd  = s_mjx_out + 5832;
                T *O_cross = s_mjx_out + 11664;
                T *O_dM    = s_mjx_out + 17496;
                for (int i = threadIdx.x + threadIdx.y*blockDim.x; i < 18; i += blockDim.x*blockDim.y) {
                  for (int l = 0; l < 18; l++) {
                    T val;
                    if (k < 3) { val = static_cast<T>(0); for (int m = 0; m < 3; m++) val += T_dM[(i*18 + l)*18 + m]*R[3*k+m]; }
                    else { val = T_dM[(i*18 + l)*18 + k]; }
                    s_work1[l*18 + i] = val;
                  }
                }
                __syncthreads();
                for (int c = threadIdx.x + threadIdx.y*blockDim.x; c < 18; c += blockDim.x*blockDim.y) {
                  T m0 = s_work1[c*18+0], m1 = s_work1[c*18+1], m2 = s_work1[c*18+2];
                  s_work2[c*18+0] = R[0]*m0 + R[1]*m1 + R[2]*m2;
                  s_work2[c*18+1] = R[3]*m0 + R[4]*m1 + R[5]*m2;
                  s_work2[c*18+2] = R[6]*m0 + R[7]*m1 + R[8]*m2;
                  for (int r = 3; r < 18; r++) s_work2[c*18+r] = s_work1[c*18+r];
                }
                __syncthreads();
                for (int i = threadIdx.x + threadIdx.y*blockDim.x; i < 18; i += blockDim.x*blockDim.y) {
                  T c0 = s_work2[0*18+i], c1 = s_work2[1*18+i], c2 = s_work2[2*18+i];
                  s_work1[0*18+i] = c0*R[0] + c1*R[1] + c2*R[2];
                  s_work1[1*18+i] = c0*R[3] + c1*R[4] + c2*R[5];
                  s_work1[2*18+i] = c0*R[6] + c1*R[7] + c2*R[8];
                  for (int l = 3; l < 18; l++) s_work1[l*18+i] = s_work2[l*18+i];
                }
                __syncthreads();
                for (int i = threadIdx.x + threadIdx.y*blockDim.x; i < 18; i += blockDim.x*blockDim.y) {
                  for (int l = 0; l < 18; l++) O_dM[(i*18 + l)*18 + k] = s_work1[l*18 + i];
                }
                __syncthreads();
            }
            // Step3: base-rot frame term added to columns kk=3+c
            #pragma unroll 1
            for (int c = 0; c < 3; c++) {
                T qx = s_q[3], qy = s_q[4], qz = s_q[5], qw = s_q[6];
                T xx = qx*qx, yy = qy*qy, zz = qz*qz;
                T xy = qx*qy, xz = qx*qz, yz = qy*qz, wx = qw*qx, wy = qw*qy, wz = qw*qz;
                T R[9];
                R[0] = static_cast<T>(1) - static_cast<T>(2)*(yy+zz); R[1] = static_cast<T>(2)*(xy-wz);                    R[2] = static_cast<T>(2)*(xz+wy);
                R[3] = static_cast<T>(2)*(xy+wz);                    R[4] = static_cast<T>(1) - static_cast<T>(2)*(xx+zz); R[5] = static_cast<T>(2)*(yz-wx);
                R[6] = static_cast<T>(2)*(xz-wy);                    R[7] = static_cast<T>(2)*(yz+wx);                    R[8] = static_cast<T>(1) - static_cast<T>(2)*(xx+yy);
                T v_lin[3]   = {s_qd[0], s_qd[1], s_qd[2]};
                T omega[3]   = {s_qd[3], s_qd[4], s_qd[5]};
                T qdd_lin[3] = {s_qdd[0], s_qdd[1], s_qdd[2]};
                T tau_lin[3] = {s_vaf[159], s_vaf[160], s_vaf[161]};
                // pin tensor blocks in s_idsva_so (row-major tensors):
                T *T_d2q   = s_idsva_so + 0;
                T *T_d2qd  = s_idsva_so + 5832;
                T *T_cross = s_idsva_so + 11664;
                T *T_dM    = s_idsva_so + 17496;
                // mjx output blocks in s_mjx_out (same layout):
                T *O_d2q   = s_mjx_out + 0;
                T *O_d2qd  = s_mjx_out + 5832;
                T *O_cross = s_mjx_out + 11664;
                T *O_dM    = s_mjx_out + 17496;
                int kk = 3 + c;
                T Rdc[9]; for (int ii=0; ii<9; ii++) Rdc[ii]=static_cast<T>(0);
                T skc[9]; for (int ii=0; ii<9; ii++) skc[ii]=static_cast<T>(0);
                if (c==0){ skc[1*3+2]=static_cast<T>(-1); skc[2*3+1]=static_cast<T>(1); }
                if (c==1){ skc[2*3+0]=static_cast<T>(-1); skc[0*3+2]=static_cast<T>(1); }
                if (c==2){ skc[0*3+1]=static_cast<T>(-1); skc[1*3+0]=static_cast<T>(1); }
                for (int r = 0; r < 3; r++) for (int cc = 0; cc < 3; cc++) {
                  T acc = static_cast<T>(0);
                  for (int p = 0; p < 3; p++) acc += R[3*r+p]*skc[3*p+cc];
                  Rdc[3*r+cc] = acc;
                }
                for (int a = threadIdx.x + threadIdx.y*blockDim.x; a < 18; a += blockDim.x*blockDim.y) {
                  T m0 = s_M[a + 18*0], m1 = s_M[a + 18*1], m2 = s_M[a + 18*2];
                  s_work1[0*18+a] = m0*R[0] + m1*R[1] + m2*R[2];
                  s_work1[1*18+a] = m0*R[3] + m1*R[4] + m2*R[5];
                  s_work1[2*18+a] = m0*R[6] + m1*R[7] + m2*R[8];
                  for (int b = 3; b < 18; b++) s_work1[b*18+a] = s_M[a + 18*b];
                }
                __syncthreads();
                for (int rr = threadIdx.x + threadIdx.y*blockDim.x; rr < 324; rr += blockDim.x*blockDim.y) {
                  s_work2[rr] = static_cast<T>(0);
                }
                __syncthreads();
                for (int b = threadIdx.x + threadIdx.y*blockDim.x; b < 18; b += blockDim.x*blockDim.y) {
                  T r0 = s_work1[b*18+0], r1 = s_work1[b*18+1], r2 = s_work1[b*18+2];
                  s_work2[b*18+0] += Rdc[0]*r0 + Rdc[1]*r1 + Rdc[2]*r2;
                  s_work2[b*18+1] += Rdc[3]*r0 + Rdc[4]*r1 + Rdc[5]*r2;
                  s_work2[b*18+2] += Rdc[6]*r0 + Rdc[7]*r1 + Rdc[8]*r2;
                }
                __syncthreads();
                for (int b = threadIdx.x + threadIdx.y*blockDim.x; b < 18; b += blockDim.x*blockDim.y) {
                  T r0 = s_M[0 + 18*b], r1 = s_M[1 + 18*b], r2 = s_M[2 + 18*b];
                  s_work1[b*18+0] = R[0]*r0 + R[1]*r1 + R[2]*r2;
                  s_work1[b*18+1] = R[3]*r0 + R[4]*r1 + R[5]*r2;
                  s_work1[b*18+2] = R[6]*r0 + R[7]*r1 + R[8]*r2;
                  for (int a = 3; a < 18; a++) s_work1[b*18+a] = s_M[a + 18*b];
                }
                __syncthreads();
                for (int a = threadIdx.x + threadIdx.y*blockDim.x; a < 18; a += blockDim.x*blockDim.y) {
                  T c0 = s_work1[0*18+a], c1 = s_work1[1*18+a], c2 = s_work1[2*18+a];
                  s_work2[0*18+a] += c0*Rdc[0] + c1*Rdc[1] + c2*Rdc[2];
                  s_work2[1*18+a] += c0*Rdc[3] + c1*Rdc[4] + c2*Rdc[5];
                  s_work2[2*18+a] += c0*Rdc[6] + c1*Rdc[7] + c2*Rdc[8];
                }
                __syncthreads();
                for (int a = threadIdx.x + threadIdx.y*blockDim.x; a < 18; a += blockDim.x*blockDim.y) {
                  for (int l = 0; l < 18; l++) O_dM[(a*18 + l)*18 + kk] += s_work2[l*18 + a];
                }
                __syncthreads();
            }
            __syncthreads();
            for(int ci = threadIdx.x + threadIdx.y*blockDim.x; ci < 23328; ci += blockDim.x*blockDim.y){
                s_idsva_so[ci] = s_mjx_out[ci];
            }
            __syncthreads();
        }
    }

    /**
     * Computes IDSVA-SO via the world-frame single-pass formulation
     *
     * Notes:
     *   world-frame IDSVA-SO kernel: clean single-pass reference path.
     *
     * @param d_idsva_so is a pointer to memory for the final result of size 4*SECOND_ORDER_COORDS*SECOND_ORDER_COORDS*SECOND_ORDER_COORDS = 23328
     * @param d_workspace is a per-timestep global-memory scratch buffer (unused at TIER_SHARED; cold buffers spill here at LITE/MINIMAL)
     * @param d_q_dq_u is the vector of joint positions, velocities, and accelerations
     * @param stride_q_qd_u is the stride between each q, qd, u
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param gravity is the gravity constant
     * @param num_timesteps is the length of the trajectory points
     */
    template <typename T, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER, bool MUJOCO_OUTPUT = false>
    __global__
    __launch_bounds__(tier_max_threads<RESOURCE_TIER>())
    void idsva_so_world_frame_kernel(T *d_idsva_so, unsigned char *d_workspace, const T *d_q_qd_u, const int stride_q_qd_u, const robotModel<T> *d_robotModel, const T gravity, const int NUM_TIMESTEPS) {
        if constexpr (RESOURCE_TIER == TIER_SHARED) {
            // GRID shared arena layout
            //   T s_q_qd_u[57]
            //   T s_XImats[936]
            //   T s_temp[3030]
            //   int s_topology_helpers[115]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q_qd_u = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(57);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(936);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(3030);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
            int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(int) * static_cast<size_t>(115);
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(4023, 115, 0));
            #endif
            (void)s_arena_offset;
            T *d_temp_spill = nullptr; (void)d_temp_spill;
            T *d_mjx_scratch = nullptr; (void)d_mjx_scratch;
            T *s_q = s_q_qd_u; T *s_qd = &s_q_qd_u[19]; T *s_qdd = &s_q_qd_u[38];
            for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
                // load to shared mem
                const T *d_q_qd_u_k = &d_q_qd_u[k*stride_q_qd_u];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 57; ind += blockDim.x*blockDim.y){
                    s_q_qd_u[ind] = d_q_qd_u_k[ind];
                }
                __syncthreads();
                if constexpr (MUJOCO_OUTPUT) {
                    d_mjx_scratch = reinterpret_cast<T *>(&d_workspace[grid_workspace_slot()*GRID_WORKSPACE_BYTES_PER_TIMESTEP<T>() + GRID_SO_WORKSPACE_TEMP_OFFSET_BYTES<T>()]);
                    // mjx input convert: quaternion wxyz->xyzw, base-linear velocity/accel/force -> pin frame
                    if (threadIdx.x == 0 && threadIdx.y == 0) {
                        T qw_in = s_q[3];
                        s_q[3] = s_q[4]; s_q[4] = s_q[5]; s_q[5] = s_q[6]; s_q[6] = qw_in;
                        T qx = s_q[3], qy = s_q[4], qz = s_q[5], qw = s_q[6];
                        T xx = qx*qx, yy = qy*qy, zz = qz*qz;
                        T xy = qx*qy, xz = qx*qz, yz = qy*qz, wx = qw*qx, wy = qw*qy, wz = qw*qz;
                        T R[9];
                        R[0] = static_cast<T>(1) - static_cast<T>(2)*(yy+zz); R[1] = static_cast<T>(2)*(xy-wz);                    R[2] = static_cast<T>(2)*(xz+wy);
