    /**
     * Second Order of Forward Dynamics with Spatial Vector Algebra
     *
     * Notes:
     *   Assumes works with IDSVA
     *   Inline-CUDA users: SCRATCH_IN_SMEM selects where the 4*NV^3 scratch arena lives.
     *     true  -> s_temp (shared memory; fastest, current default).
     *     false -> d_workspace (global; frees shared memory for the caller's outer kernel).
     *   The placement is the INNER's choice (made at the top of this function) so the
     *   kernel/device caller just sizes both arenas from the exposed *_BYTES constants
     *   and hands both pointers in. Codegen maps each RESOURCE_TIER to a SCRATCH_IN_SMEM
     *   value per robot (small robots keep all tiers in smem; large robots spill).
     *
     * @param s_df2 are the second derivatives of forward dynamics WRT q,qd,tau
     * @param s_idsva_so are the second derivative tensors of inverse dynamics
     * @param s_Minv is the inverse mass matrix
     * @param s_df_du is the gradient of the forward dynamics
     * @param s_XImats is the (shared) memory holding the updated XI matricies for the given s_q
     * @param s_topology_helpers is the (shared) memory location for the topology_helpers (nullptr/unused for serial chains with identical Ss)
     * @param s_temp is the (shared) scratch buffer; size FDSVA_SO_INNER_SMEM_BYTES<T, SCRATCH_IN_SMEM>() bytes (= 23328*sizeof(T) when SCRATCH_IN_SMEM, else 0)
     * @param d_workspace is the global scratch buffer; size FDSVA_SO_INNER_WORKSPACE_BYTES<T, SCRATCH_IN_SMEM>() bytes (= 23328*sizeof(T) when !SCRATCH_IN_SMEM, else 0). Pass nullptr when SCRATCH_IN_SMEM
     * @param gravity is the gravity constant
     */
    template <typename T, bool SCRATCH_IN_SMEM = true>
    __device__
    void fdsva_so_contract(T *s_df2, T *s_idsva_so, T *s_Minv, T *s_df_du, T *s_XImats, int *s_topology_helpers, T *s_temp, T *d_workspace, const T gravity) {
        // Second Derivatives of Inverse Dynamics
        T *d2tau_dqdq = &s_idsva_so[0];
        T *d2tau_dvdv = &s_idsva_so[5832];
        T *d2tau_dvdq = &s_idsva_so[11664];
        T *dM_dq = &s_idsva_so[17496];
        


        // First Derivatives of Forward Dynamics
        T *s_df_dq = s_df_du; T *s_df_dqd = &s_df_du[324];
        


        // Second Derivatives of Forward Dynamics
        T *d2a_dqdq = s_df2;
        T *d2a_dvdq = &s_df2[5832];
        T *d2a_dvdv = &s_df2[11664];
        T *d2a_dtdq = &s_df2[17496];
        


        // Temporary Variables. The 4*n^3 scratch arena placement is the INNER's
        // choice, keyed on SCRATCH_IN_SMEM: s_temp (shared) when true, d_workspace
        // (global) when false. A surgical-spill change is local here: repoint a
        // sub-buffer + update FDSVA_SO_INNER_{SMEM,WORKSPACE}_BYTES.
        T *inner_arena;
        if constexpr (SCRATCH_IN_SMEM) {
            (void)d_workspace;
            inner_arena = s_temp;
        }
        else {
            (void)s_temp;
            inner_arena = d_workspace;
        }
        T *inner_dq = inner_arena; // Inner term for d2a_dqdq
        T *inner_cross = inner_dq + 5832; // Inner term for d2a_dvdq (dM_dq*Minv)
        T *inner_tau = inner_cross + 5832; // Inner term for d2a_dtdq (d2tau_dvdq + dM_dq*da_dv)
        T *rot_dq = inner_tau + 5832; // Rotated (dM_dq*da_dq)^R term used to compute inner_dq
        


        // Start inner term for d2a_dqdq & Fill out Minv
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 6156; ind += blockDim.x*blockDim.y){
            int i = ind / 324 % 18; int j = ind / 18 % 18; int k = ind % 18;
            if (ind < 5832) {
                inner_dq[ind] = dot_prod<T, 18, 18, 1>(&dM_dq[324*i + k], &s_df_dq[18*j]);
                rot_dq[i*324 + k*18 + j] = inner_dq[ind];
            }
            else if (k > j) s_Minv[j*18 + k] = s_Minv[k*18 + j];
        }
        __syncthreads();
        // Compute relevant inner subterms in parallel
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 17496; ind += blockDim.x*blockDim.y){
            int i = ind / 324 % 18; int j = ind / 18 % 18; int k = ind % 18;
            if (ind < 5832) inner_dq[ind] += rot_dq[ind] + d2tau_dqdq[i*324 + k*18 + j]; // Started with dM_dq*da_dq
            else if (ind < 11664) inner_cross[i*324 + k*18 + j] = dot_prod<T, 18, 18, 1>(&dM_dq[324*i + k], &s_df_dqd[18*j]) + d2tau_dvdq[i*324 + j*18 + k];
            else inner_tau[i*324 + k*18 + j] = dot_prod<T, 18, 18, 1>(&dM_dq[324*i + k], &s_Minv[18*j]);
        }
        __syncthreads();
        // Multiply by -Minv to finish algorithm
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 23328; ind += blockDim.x*blockDim.y){
            int i = ind / 324 % 18; int j = ind / 18 % 18; int k = ind % 18;
            if (ind < 5832) d2a_dqdq[i*324 + j*18 + k] = -dot_prod<T, 18, 18, 324>(&s_Minv[i], &inner_dq[j + k*18]);
            else if (ind < 11664) d2a_dvdq[i*324 + j*18 + k] = -dot_prod<T, 18, 18, 324>(&s_Minv[i], &inner_cross[j + k*18]);
            else if (ind < 17496) d2a_dvdv[i*324 + j*18 + k] = -dot_prod<T, 18, 18, 324>(&s_Minv[i], &d2tau_dvdv[j + k*18]);
            else d2a_dtdq[i*324 + j*18 + k] = -dot_prod<T, 18, 18, 324>(&s_Minv[i], &inner_tau[j + k*18]);
        }
        __syncthreads();
    }

    /**
     * fdsva_so orchestration as a single inner-owns-placement device function
     *
     * @param s_df2/s_idsva_so/s_Minv/s_df_du/s_qdd/s_q/s_qd/s_u are the in/out buffers (caller places)
     * @param s_temp is the shared scratch pool (used when SCRATCH_IN_SMEM)
     * @param d_workspace is the global scratch pool (used when !SCRATCH_IN_SMEM)
     * @param d_fd_grad_spill is the fd-gradient da_df spill band (used when FD_GRAD_USE_SPILL)
     * @param s_fdsva_temp is the 4*NV^3 contraction scratch (smem or workspace per CONTRACT_IN_SMEM)
     * @param d_robotModel holds XImats/topology; gravity is the gravity constant
     * @param s_XImats is the (shared) memory holding the updated XI matricies for the given s_q
     * @param s_topology_helpers is the (shared) memory location for the topology_helpers (nullptr/unused for serial chains with identical Ss)
     * @param d_mjx_scratch is the mjx-epilogue scratch arena (SO-temp region of d_workspace; only read when MUJOCO_OUTPUT)
     * @param d_idsva_cold_spill is the SO-temp d_workspace region backing the WORLD idsva_so inner's cold trio (only read when !IDSVA_COLD_IN_SMEM)
     */
    template <typename T, bool SCRATCH_IN_SMEM = true, bool FD_GRAD_USE_SPILL = false, bool CONTRACT_IN_SMEM = true, bool MUJOCO_OUTPUT = false, bool IDSVA_COLD_IN_SMEM = true>
    __device__ __forceinline__
    void fdsva_so_device(T *s_df2, T *s_idsva_so, T *s_Minv, T *s_df_du, T *s_qdd, const T *s_q, const T *s_qd, const T *s_u, T *s_XImats, int *s_topology_helpers, T *s_temp, T *d_workspace, T *d_fd_grad_spill, T *s_fdsva_temp, const robotModel<T> *d_robotModel, const T gravity, T *d_mjx_scratch = nullptr, T *d_idsva_cold_spill = nullptr) {
        if constexpr (!SCRATCH_IN_SMEM) { s_temp = d_workspace; } else { (void)d_workspace; }
        T *d_temp_spill = nullptr;
        if constexpr (!IDSVA_COLD_IN_SMEM) { d_temp_spill = d_idsva_cold_spill; } else { (void)d_idsva_cold_spill; }
        load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
        minv_inner<T, true>(s_Minv, s_q, s_XImats, s_topology_helpers, s_temp, nullptr);
        forward_dynamics_inner<T, true>(s_qdd, s_q, s_qd, s_u, s_XImats, s_topology_helpers, s_temp, nullptr, nullptr, gravity);
        __syncthreads();
        if constexpr (FD_GRAD_USE_SPILL) {
            // Compute FD gradient inline so nested device wrappers do not carve a second shared arena
            T *s_fd_vaf = s_temp;
            T *s_fd_dc_du = s_fd_vaf + 234;
            T *s_fd_temp = s_fd_dc_du + 648;
            inverse_dynamics_inner_vaf<T>(s_fd_vaf, s_q, s_qd, s_qdd, s_XImats, s_topology_helpers, s_fd_temp, nullptr, gravity);
            inverse_dynamics_gradient_inner<T, true>(s_fd_dc_du, s_q, s_qd, s_fd_vaf, s_XImats, s_topology_helpers, s_fd_temp, d_fd_grad_spill, gravity);
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 648; ind += blockDim.x*blockDim.y){
                int row = ind % 18; int dc_col_offset = ind - row;
                T val = static_cast<T>(0);
                for(int col = 0; col < 18; col++) {
                    int index = (row <= col) * (col * 18 + row) + (row > col) * (row * 18 + col);
                    val += s_Minv[index] * s_fd_dc_du[dc_col_offset + col];
                }
                s_df_du[ind] = -val;
            }
            __syncthreads();
        }
        else {
            (void)d_fd_grad_spill;
            // Compute FD gradient inline so nested device wrappers do not carve a second shared arena
            T *s_fd_vaf = s_temp;
            T *s_fd_dc_du = s_fd_vaf + 234;
            T *s_fd_temp = s_fd_dc_du + 648;
            inverse_dynamics_inner_vaf<T>(s_fd_vaf, s_q, s_qd, s_qdd, s_XImats, s_topology_helpers, s_fd_temp, nullptr, gravity);
            inverse_dynamics_gradient_inner<T, false>(s_fd_dc_du, s_q, s_qd, s_fd_vaf, s_XImats, s_topology_helpers, s_fd_temp, nullptr, gravity);
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 648; ind += blockDim.x*blockDim.y){
                int row = ind % 18; int dc_col_offset = ind - row;
                T val = static_cast<T>(0);
                for(int col = 0; col < 18; col++) {
                    int index = (row <= col) * (col * 18 + row) + (row > col) * (row * 18 + col);
                    val += s_Minv[index] * s_fd_dc_du[dc_col_offset + col];
                }
                s_df_du[ind] = -val;
            }
            __syncthreads();
        }
        idsva_so_world_frame_inner<T, true, IDSVA_COLD_IN_SMEM>(s_idsva_so, s_q, s_qd, s_qdd, s_XImats, s_topology_helpers, s_temp, d_temp_spill, d_robotModel, gravity);
        fdsva_so_contract<T, CONTRACT_IN_SMEM>(s_df2, s_idsva_so, s_Minv, s_df_du, s_XImats, s_topology_helpers, s_temp, s_fdsva_temp, gravity);
        if constexpr (MUJOCO_OUTPUT) {
            // === mjx output convention (floating-base fdsva_so) ===
            T *s_M        = d_mjx_scratch + 0;       // dense mass matrix (crba_inner)
            T *s_dc_du    = d_mjx_scratch + 324;    // pin dtau_dq | dtau_dqd
            T *s_mjx_Minv = d_mjx_scratch + 972;    // dense symmetric Minv = inv(M)
            T *s_mjx_dfdu = d_mjx_scratch + 1296;    // fd gradient dqdd_dq | dqdd_dqd (col-major)
            T *s_mjx_qdd  = d_mjx_scratch + 1944;     // fd value qdd
            T *s_vaf      = d_mjx_scratch + 1962;     // id-value band
            T *s_mjx_tmp  = d_mjx_scratch + 2196;    // reused-inner scratch (one at a time)
            T *s_mjx_out  = d_mjx_scratch + 11808;     // 4*NV^3 mjx output band
            T *s_work1 = d_mjx_scratch + 35136; T *s_work2 = d_mjx_scratch + 35460; T *s_inner_u = d_mjx_scratch + 35784;  // block-shared per-k work
            T *s_d_dq = d_mjx_scratch + 36108; T *s_d_dqd = d_mjx_scratch + 36432; T *s_d_Mi = d_mjx_scratch + 36756;  // block-shared per-k sensitivities
            // recompute Minv / qdd / dqdd_dq|dqdd_dqd FRESH (the spilled in-flight copies may be clobbered)
            forward_dynamics_inner<T, true>(s_mjx_qdd, s_q, s_qd, s_u, s_XImats, s_topology_helpers, s_mjx_tmp, nullptr, nullptr, gravity);
            __syncthreads();
            crba_inner<T, true>(s_M, s_q, s_qd, s_XImats, s_topology_helpers, s_mjx_tmp, nullptr, gravity);
            __syncthreads();
            invert_matrix(18, s_M, s_mjx_Minv, s_mjx_tmp);
            __syncthreads();
            inverse_dynamics_inner_vaf<T>(s_vaf, s_q, s_qd, s_mjx_qdd, s_XImats, s_topology_helpers, s_mjx_tmp, nullptr, gravity);
            __syncthreads();
            inverse_dynamics_gradient_inner<T, false>(s_dc_du, s_q, s_qd, s_vaf, s_XImats, s_topology_helpers, s_mjx_tmp, nullptr, gravity);
            __syncthreads();
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 648; ind += blockDim.x*blockDim.y){
                int row = ind % 18; int dc_col_offset = ind - row;
                T val = static_cast<T>(0);
                for(int col = 0; col < 18; col++) {
                    int index = (row <= col) * (col * 18 + row) + (row > col) * (row * 18 + col);
                    val += s_mjx_Minv[index] * s_dc_du[dc_col_offset + col];
                }
                s_mjx_dfdu[ind] = -val;
            }
            __syncthreads();
            // === block-parallel per-k assembly (whole block cooperates per k) ===
            #pragma unroll 1
            for (int k = 0; k < 18; k++) {
                T qx = s_q[3], qy = s_q[4], qz = s_q[5], qw = s_q[6];
                T xx = qx*qx, yy = qy*qy, zz = qz*qz;
                T xy = qx*qy, xz = qx*qz, yz = qy*qz, wx = qw*qx, wy = qw*qy, wz = qw*qz;
                T R[9];
                R[0] = static_cast<T>(1) - static_cast<T>(2)*(yy+zz); R[1] = static_cast<T>(2)*(xy-wz);                    R[2] = static_cast<T>(2)*(xz+wy);
                R[3] = static_cast<T>(2)*(xy+wz);                    R[4] = static_cast<T>(1) - static_cast<T>(2)*(xx+zz); R[5] = static_cast<T>(2)*(yz-wx);
                R[6] = static_cast<T>(2)*(xz-wy);                    R[7] = static_cast<T>(2)*(yz+wx);                    R[8] = static_cast<T>(1) - static_cast<T>(2)*(xx+yy);
                T v_lin[3]   = {s_qd[0], s_qd[1], s_qd[2]};
                T omega[3]   = {s_qd[3], s_qd[4], s_qd[5]};
                T u_lin[3]   = {s_u[0], s_u[1], s_u[2]};
                T qdd_lin[3] = {s_mjx_qdd[0], s_mjx_qdd[1], s_mjx_qdd[2]};
                T *s_dqdd_dq  = s_mjx_dfdu;                 // col-major dqdd_dq  [c*NV+r]
                T *s_dqdd_dqd = s_mjx_dfdu + 324;   // col-major dqdd_dqd [c*NV+r]
                T *s_Minv     = s_mjx_Minv;                 // dense symmetric Minv (fresh)
                // pin tensor blocks in s_df2 (row-major [(i*NV+j)*NV+k]):
                T *T_d2q   = s_df2 + 0;   // daba_dqdq
                T *T_cross = s_df2 + 5832;   // daba_dvdq [i,qd,q]
                T *T_d2qd  = s_df2 + 11664;   // daba_dvdv
                T *T_dtdq  = s_df2 + 17496;   // daba_dtdq = dMinv/dq [i,u,q]
                // mjx output blocks (same layout/order):
                T *O_d2q   = s_mjx_out + 0;
                T *O_cross = s_mjx_out + 5832;
                T *O_d2qd  = s_mjx_out + 11664;
                T *O_dtdq  = s_mjx_out + 17496;
                T jqk[18], jvk[18], juk[18], jvvk[18], juuk[18];
                for (int q_ = 0; q_ < 18; q_++) { jqk[q_] = static_cast<T>(0); jvk[q_] = static_cast<T>(0); juk[q_] = static_cast<T>(0); jvvk[q_] = static_cast<T>(0); juuk[q_] = static_cast<T>(0); }
                bool is_rot = (k >= 3 && k < 6);
                int a_rot = k - 3;
                if (k < 3) { jqk[0] = R[3*k+0]; jqk[1] = R[3*k+1]; jqk[2] = R[3*k+2]; }
                else { jqk[k] = static_cast<T>(1); }
                for (int q_ = 0; q_ < 18; q_++) { jvvk[q_] = jqk[q_]; juuk[q_] = jqk[q_]; }
                if (is_rot) {
                  T evx = (a_rot==1)*( v_lin[2]) + (a_rot==2)*(-v_lin[1]);
                  T evy = (a_rot==0)*(-v_lin[2]) + (a_rot==2)*( v_lin[0]);
                  T evz = (a_rot==0)*( v_lin[1]) + (a_rot==1)*(-v_lin[0]);
                  jvk[0] = -evx; jvk[1] = -evy; jvk[2] = -evz;
                  T eux = (a_rot==1)*( u_lin[2]) + (a_rot==2)*(-u_lin[1]);
                  T euy = (a_rot==0)*(-u_lin[2]) + (a_rot==2)*( u_lin[0]);
                  T euz = (a_rot==0)*( u_lin[1]) + (a_rot==1)*(-u_lin[0]);
                  juk[0] = -eux; juk[1] = -euy; juk[2] = -euz;
                }
                T Rd[9];
                for (int ii = 0; ii < 9; ii++) Rd[ii] = static_cast<T>(0);
                if (is_rot) {
                  T sk[9]; for (int ii=0; ii<9; ii++) sk[ii]=static_cast<T>(0);
                  if (a_rot==0){ sk[1*3+2] = static_cast<T>(-1); sk[2*3+1] = static_cast<T>(1); }
                  if (a_rot==1){ sk[2*3+0] = static_cast<T>(-1); sk[0*3+2] = static_cast<T>(1); }
                  if (a_rot==2){ sk[0*3+1] = static_cast<T>(-1); sk[1*3+0] = static_cast<T>(1); }
                  for (int r = 0; r < 3; r++) for (int c = 0; c < 3; c++) {
                    T acc = static_cast<T>(0);
                    for (int p = 0; p < 3; p++) acc += R[3*r+p]*sk[3*p+c];
                    Rd[3*r+c] = acc;
                  }
                }
                for (int i = threadIdx.x + threadIdx.y*blockDim.x; i < 18; i += blockDim.x*blockDim.y) {
                  for (int j = 0; j < 18; j++) {
                    T s = static_cast<T>(0);
                    for (int m = 0; m < 18; m++) s += T_d2q[((i)*18 + (j))*18 + (m)]*jqk[m];
                    for (int nn = 0; nn < 18; nn++) s += T_cross[((i)*18 + (nn))*18 + (j)]*jvk[nn];
                    for (int l = 0; l < 18; l++) s += T_dtdq[((i)*18 + (l))*18 + (j)]*juk[l];
                    s_d_dq[j*18 + i] = s;
                    T s2 = static_cast<T>(0);
                    for (int m = 0; m < 18; m++) s2 += T_cross[((i)*18 + (j))*18 + (m)]*jqk[m];
                    for (int nn = 0; nn < 18; nn++) s2 += T_d2qd[((i)*18 + (j))*18 + (nn)]*jvk[nn];
                    s_d_dqd[j*18 + i] = s2;
                    T s3 = static_cast<T>(0);
                    for (int m = 0; m < 18; m++) s3 += T_dtdq[((i)*18 + (j))*18 + (m)]*jqk[m];
                    s_d_Mi[j*18 + i] = s3;
                  }
                }
                __syncthreads();
                T d_qd[3];
                for (int i = 0; i < 3; i++) {
                  T st = static_cast<T>(0);
                  for (int j = 0; j < 18; j++) {
                    T mij = s_Minv[(i<=j) ? (j*18+i) : (i*18+j)];
                    st += s_dqdd_dq[j*18+i]*jqk[j] + s_dqdd_dqd[j*18+i]*jvk[j] + mij*juk[j];
                  }
                  d_qd[i] = st;
                }
                {
                    // --- d2qdd/dq2 slab[:,:,k] (block-parallel) ---
                    for (int r = threadIdx.x + threadIdx.y*blockDim.x; r < 18; r += blockDim.x*blockDim.y) {
                      T c0 = s_dqdd_dq[0*18+r], c1 = s_dqdd_dq[1*18+r], c2 = s_dqdd_dq[2*18+r];
                      s_work1[0*18+r] = c0*R[0] + c1*R[1] + c2*R[2];
                      s_work1[1*18+r] = c0*R[3] + c1*R[4] + c2*R[5];
                      s_work1[2*18+r] = c0*R[6] + c1*R[7] + c2*R[8];
                      for (int c = 3; c < 18; c++) s_work1[c*18+r] = s_dqdd_dq[c*18+r];
                    }
                    __syncthreads();
                    for (int a = 0; a < 3; a++) {
                      T evx = (a==1)*( v_lin[2]) + (a==2)*(-v_lin[1]);
                      T evy = (a==0)*(-v_lin[2]) + (a==2)*( v_lin[0]);
                      T evz = (a==0)*( v_lin[1]) + (a==1)*(-v_lin[0]);
                      T jc0 = -evx, jc1 = -evy, jc2 = -evz;
                      for (int r = threadIdx.x + threadIdx.y*blockDim.x; r < 18; r += blockDim.x*blockDim.y) s_work1[(3+a)*18+r] += s_dqdd_dqd[0*18+r]*jc0 + s_dqdd_dqd[1*18+r]*jc1 + s_dqdd_dqd[2*18+r]*jc2;
                    }
                    __syncthreads();
                    for (int a = 0; a < 3; a++) {
                      T evx = (a==1)*( u_lin[2]) + (a==2)*(-u_lin[1]);
                      T evy = (a==0)*(-u_lin[2]) + (a==2)*( u_lin[0]);
                      T evz = (a==0)*( u_lin[1]) + (a==1)*(-u_lin[0]);
                      T jc0 = -evx, jc1 = -evy, jc2 = -evz;
                      for (int r = threadIdx.x + threadIdx.y*blockDim.x; r < 18; r += blockDim.x*blockDim.y) {
                        T m0 = s_Minv[(r<=0) ? (0*18+r) : (r*18+0)], m1 = s_Minv[(r<=1) ? (1*18+r) : (r*18+1)], m2 = s_Minv[(r<=2) ? (2*18+r) : (r*18+2)];
                        s_work1[(3+a)*18+r] += m0*jc0 + m1*jc1 + m2*jc2;
                      }
                    }
                    __syncthreads();
                    for (int r = threadIdx.x + threadIdx.y*blockDim.x; r < 18; r += blockDim.x*blockDim.y) {
                      T c0 = s_d_dq[0*18+r], c1 = s_d_dq[1*18+r], c2 = s_d_dq[2*18+r];
