                      s_work2[c*18+2] = R[6]*m0 + R[7]*m1 + R[8]*m2;
                      for (int r = 3; r < 18; r++) s_work2[c*18+r] = s_inner_u[c*18+r];
                    }
                    __syncthreads();
                    T duq0 = static_cast<T>(0), duq1 = static_cast<T>(0), duq2 = static_cast<T>(0);
                    for (int j = 0; j < 18; j++) {
                      duq0 += s_Minv[(0<=j) ? (j*18+0) : (0*18+j)]*juuk[j];
                      duq1 += s_Minv[(1<=j) ? (j*18+1) : (1*18+j)]*juuk[j];
                      duq2 += s_Minv[(2<=j) ? (j*18+2) : (2*18+j)]*juuk[j];
                    }
                    for (int a = threadIdx.x + threadIdx.y*blockDim.x; a < 3; a += blockDim.x*blockDim.y) {
                      T w0 = (a==1)*( duq2) + (a==2)*(-duq1);
                      T w1 = (a==0)*(-duq2) + (a==2)*( duq0);
                      T w2 = (a==0)*( duq1) + (a==1)*(-duq0);
                      s_work2[(3+a)*18+0] += R[0]*w0 + R[1]*w1 + R[2]*w2;
                      s_work2[(3+a)*18+1] += R[3]*w0 + R[4]*w1 + R[5]*w2;
                      s_work2[(3+a)*18+2] += R[6]*w0 + R[7]*w1 + R[8]*w2;
                    }
                    __syncthreads();
                    for (int i = threadIdx.x + threadIdx.y*blockDim.x; i < 18; i += blockDim.x*blockDim.y) {
                      for (int j = 0; j < 18; j++) O_dtdq[(i*18 + j)*18 + k] = s_work2[j*18 + i];
                    }
                    __syncthreads();
                }
            }
            __syncthreads();
            for(int ci = threadIdx.x + threadIdx.y*blockDim.x; ci < 23328; ci += blockDim.x*blockDim.y){
                s_df2[ci] = s_mjx_out[ci];
            }
            __syncthreads();
        }
    }

    /**
