        int stride_q_qd_qdd = Q_QD_U_STRIDE;
        // start code with memory transfer
        gpuErrchk(cudaMemcpyAsync(hd_data->d_q_qd_u,hd_data->h_q_qd_u,stride_q_qd_qdd*sizeof(T),cudaMemcpyHostToDevice,streams[0]));
        gpuErrchkKernel();
        // call the kernel
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("fdsva_so", FDSVA_SO_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()));
        if (GRID_FDSVA_SO_USES_WORKSPACE_ANY_TIER) {gpuErrchk(grid_begin_l2_persisting(0, hd_data->d_workspace, GRID_WORKSPACE_BYTES_PER_TIMESTEP<T>()*GRID_WORKSPACE_SLOTS*1));}
        struct timespec start, end; clock_gettime(CLOCK_MONOTONIC,&start);
        dim3 _grid_thr_clamped_66 = grid_host_clamp_threads((const void*)&fdsva_so_kernel_single_timing<T, RESOURCE_TIER, MUJOCO_OUTPUT>, thread_dimms);
        fdsva_so_kernel_single_timing<T, RESOURCE_TIER, MUJOCO_OUTPUT><<<block_dimms,_grid_thr_clamped_66,FDSVA_SO_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_df2,hd_data->d_workspace,hd_data->d_q_qd_u,stride_q_qd_qdd,hd_data->d_idsva_so,d_robotModel,gravity,num_timesteps);
        gpuErrchkKernel();
        clock_gettime(CLOCK_MONOTONIC,&end);
        if (GRID_FDSVA_SO_USES_WORKSPACE_ANY_TIER) {gpuErrchk(grid_end_l2_persisting(0));}
        // finally transfer the result back
        gpuErrchk(cudaMemcpy(hd_data->h_df2,hd_data->d_df2,sizeof(T)*23328,cudaMemcpyDeviceToHost));
        gpuErrchkKernel();
        printf("Single Call FDSVA_SO %fus\n",time_delta_us_timespec(start,end)/static_cast<double>(num_timesteps));
    }

    /**
     * Compute the FDSVA_SO (Second Order of Forward Dynamics with Spacial Vector Algebra)
     *
     * @param hd_data is the packaged input and output pointers
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param gravity is the gravity constant,
     * @param num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
     * @param streams are pointers to CUDA streams for async memory transfers (if needed)
     */
    template <typename T, gridDataKind KIND = GRID_DATA_ALL, bool MUJOCO_OUTPUT = false, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void fdsva_so_compute_only(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const T gravity, const int num_timesteps,
                                       const dim3 block_dimms, const dim3 thread_dimms) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_DYNAMICS, "fdsva_so requires all-data or dynamics gridData");
        int stride_q_qd_qdd = Q_QD_U_STRIDE;
        // call the kernel
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("fdsva_so", FDSVA_SO_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()));
        const int _grid_ws_n = (hd_data->workspace_timestep_slots > 0 && hd_data->workspace_timestep_slots < num_timesteps) ? hd_data->workspace_timestep_slots : num_timesteps;
        if (GRID_FDSVA_SO_USES_WORKSPACE_ANY_TIER) {gpuErrchk(grid_begin_l2_persisting(0, hd_data->d_workspace, GRID_WORKSPACE_BYTES_PER_TIMESTEP<T>()*GRID_WORKSPACE_SLOTS*static_cast<size_t>(_grid_ws_n)));}
        dim3 _ws_grid = block_dimms;
        if ((int)(_ws_grid.x*_ws_grid.y*_ws_grid.z) > _grid_ws_n) { _ws_grid = dim3(_grid_ws_n,1,1); }
        dim3 _grid_thr_clamped_67 = grid_host_clamp_threads((const void*)&fdsva_so_kernel<T, RESOURCE_TIER, MUJOCO_OUTPUT>, thread_dimms);
        fdsva_so_kernel<T, RESOURCE_TIER, MUJOCO_OUTPUT><<<_ws_grid,_grid_thr_clamped_67,FDSVA_SO_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_df2,hd_data->d_workspace,hd_data->d_q_qd_u,stride_q_qd_qdd,hd_data->d_idsva_so,d_robotModel,gravity,num_timesteps);
        gpuErrchkKernel();
        if (GRID_FDSVA_SO_USES_WORKSPACE_ANY_TIER) {gpuErrchk(grid_end_l2_persisting(0));}
    }

    /**
     * integrator hessian (plant_step_hessian s_d2AB surface): composes fdsva_so + dt-scaled assembly
     *
     * @param s_d2AB is the output Hessian (2*NUM_VEL x 3*NUM_VEL x 3*NUM_VEL, row-major); size 104976
     * @param s_df2/s_idsva_so/s_Minv/s_df_du/s_qdd are fdsva_so in/out scratch (caller places)
     * @param s_q/s_qd/s_u are the joint positions, velocities, and input torques
     * @param s_temp is the fdsva_so shared scratch pool (used when SCRATCH_IN_SMEM)
     * @param s_XImats is the (shared) memory holding the updated XI matricies for the given s_q
     * @param s_topology_helpers is the (shared) memory location for the topology_helpers (nullptr/unused for serial chains with identical Ss)
     * @param d_workspace/d_fd_grad_spill/s_fdsva_temp are fdsva_so spill regions (SHARED tier: nullptr)
     * @param d_robotModel holds XImats/topology; gravity is the gravity constant; dt is the timestep
     */
    template <typename T, IntegratorType IT = IntegratorType::EULER, bool SCRATCH_IN_SMEM = true, bool FD_GRAD_USE_SPILL = false, bool CONTRACT_IN_SMEM = true, bool MUJOCO_OUTPUT = false>
    __device__ __forceinline__
    void integrator_hessian_device(T *s_d2AB, T *s_df2, T *s_idsva_so, T *s_Minv, T *s_df_du, T *s_qdd, const T *s_q, const T *s_qd, const T *s_u, T *s_XImats, int *s_topology_helpers, T *s_temp, T *d_workspace, T *d_fd_grad_spill, T *s_fdsva_temp, T *d_mjx_ws, const robotModel<T> *d_robotModel, const T gravity, const T dt) {
        static_assert(IT == IntegratorType::EULER || IT == IntegratorType::SEMI_IMPLICIT_EULER,
            "integrator_hessian_device: only EULER / SEMI_IMPLICIT_EULER are supported "
            "(multi-stage RK 2nd-order chain rule is deferred; see f1_plant_step_hessian_plan.md).");
        fdsva_so_device<T, SCRATCH_IN_SMEM, FD_GRAD_USE_SPILL, CONTRACT_IN_SMEM>(s_df2, s_idsva_so, s_Minv, s_df_du, s_qdd, s_q, s_qd, s_u, s_XImats, s_topology_helpers, s_temp, d_workspace, d_fd_grad_spill, s_fdsva_temp, d_robotModel, gravity);
        __syncthreads();
        T *d2a_dqdq = s_df2;
        T *d2a_dvdq = &s_df2[5832];
        T *d2a_dvdv = &s_df2[11664];
        T *d2a_dtdq = &s_df2[17496];
        const bool si = (IT == IntegratorType::SEMI_IMPLICIT_EULER);
        const T dt2 = dt * dt;
        // SE(3) retract scratch (block-shared, carved from the freed fdsva_so pool).
        T *s_se3 = (SCRATCH_IN_SMEM) ? s_temp : d_workspace;
        T *s_w       = &s_se3[0];
        T *s_dInt_v  = &s_se3[6];          // 6x6 first-order dIntegrate_v
        T *s_d2Int_qv = &s_se3[6 + 36];    // 6x6x6 [o*36 + j*6 + k]
        T *s_d2Int_vv = &s_se3[6 + 36 + 216];
        if(threadIdx.x == 0 && threadIdx.y == 0){
            for (int m = 0; m < 6; ++m) s_w[m] = si ? (dt * (s_qd[m] + dt * s_qdd[m])) : (dt * s_qd[m]);
        }
        __syncthreads();
        if(threadIdx.x == 0 && threadIdx.y == 0){
            double w_d[6]; for (int m = 0; m < 6; ++m) w_d[m] = static_cast<double>(s_w[m]);
            double dIv_d[36]; grid_dIntegrate_v_block<double>(w_d, dIv_d);
            for (int m = 0; m < 36; ++m) s_dInt_v[m] = static_cast<T>(dIv_d[m]);
            grid_d2Integrate_block<T, true >(s_w, s_d2Int_qv);
            grid_d2Integrate_block<T, false>(s_w, s_d2Int_vv);
        }
        __syncthreads();
        auto D2qdd = [&](int m, int p, int q) -> T {
            int pblk = p / 18, qblk = q / 18;
            int pj = p % 18, qk = q % 18;
            if (pblk == 0 && qblk == 0) return d2a_dqdq[m*324 + pj*18 + qk];
            if (pblk == 1 && qblk == 1) return d2a_dvdv[m*324 + pj*18 + qk];
            if (pblk == 1 && qblk == 0) return d2a_dvdq[m*324 + pj*18 + qk];
            if (pblk == 0 && qblk == 1) return d2a_dvdq[m*324 + qk*18 + pj];
            if (pblk == 2 && qblk == 0) return d2a_dtdq[m*324 + pj*18 + qk];
            if (pblk == 0 && qblk == 2) return d2a_dtdq[m*324 + qk*18 + pj];
            return static_cast<T>(0);
        };
        auto Vgrad = [&](int c, int axis) -> T {
            int blk = axis / 18, a2 = axis % 18;
            if (blk == 0) return dt * s_df_du[a2*18 + c];
            if (blk == 1) return ((c == a2) ? static_cast<T>(1) : static_cast<T>(0)) + dt * s_df_du[324 + a2*18 + c];
            int midx = (c <= a2) * (a2*18 + c) + (c > a2) * (c*18 + a2);
            return dt * s_Minv[midx];
        };
        auto dIntv = [&](int i, int m) -> T {
            if (i < 6 && m < 6) return s_dInt_v[i*6 + m];
            return (i == m) ? static_cast<T>(1) : static_cast<T>(0);
        };
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 104976; ind += blockDim.x*blockDim.y){
            int o = ind / 2916;
            int a = (ind / 54) % 54;
            int b = ind % 54;
            T val = static_cast<T>(0);
            if (o >= 18) {
                // velocity rows: dt * D2qdd[i, b, a]  (a/b transposed vs the fixed sweep).
                int i = o - 18;
                val = dt * D2qdd(i, b, a);
            }
            else if (!si) {
                // position rows, EULER: nonzero only when a is in the qd block.
                int i = o;
                if (a >= 18 && a < 36 && i < 6) {
                    int aL = a - 18;
                    if (b < 18) { if (b < 6 && aL < 6) val = dt * s_d2Int_qv[i*36 + b*6 + aL]; }
                    else if (b < 36) { int bL = b - 18; if (bL < 6 && aL < 6) val = dt2 * s_d2Int_vv[i*36 + bL*6 + aL]; }
                }
            }
            else {
                // position rows, SI-EULER: t1 + t2 + t3.
                int i = o;
                T acc = static_cast<T>(0);
                if (i < 6) {
                    // t1 (b in q only): dt * sum_c d2Int_qv[i,b,c] * Vgrad[c,a].
                    if (b < 18 && b < 6) { for (int c = 0; c < 6; ++c) acc += dt * s_d2Int_qv[i*36 + b*6 + c] * Vgrad(c, a); }
                    // t2: dt^2 * sum_{m,c} d2Int_vv[i,m,c] * Vgrad[c,a] * Vgrad[m,b].
                    for (int m = 0; m < 6; ++m) { T vmb = Vgrad(m, b); if (vmb != static_cast<T>(0)) for (int c = 0; c < 6; ++c) acc += dt2 * s_d2Int_vv[i*36 + m*6 + c] * Vgrad(c, a) * vmb; }
                }
                // t3: dt^2 * sum_m dInt_v[i,m] * D2qdd[m,a,b]. dInt_v is block-diagonal
                //     (6x6 free-flyer corner + identity revolute), so the m-sum is the 6
                //     free-flyer rows plus the single identity term m==i for i>=6.
                if (i < 6) { for (int m = 0; m < 6; ++m) acc += dt2 * dIntv(i, m) * D2qdd(m, a, b); }
                else { acc += dt2 * D2qdd(i, a, b); }
                val = acc;
            }
            s_d2AB[ind] = val;
        }
        __syncthreads();
        if constexpr (MUJOCO_OUTPUT) {
            T *s_d2AB_pin = d_mjx_ws;                       // read-only pin-hessian copy (2nv*nz*nz)
            T *s_dInt_q  = &d_mjx_ws[104976];          // 6x6 dIntegrate_q
            T *s_dAB_pin = &d_mjx_ws[105012];      // pin dAB [A|B] col-major (2nv*3nv)
            if(threadIdx.x == 0 && threadIdx.y == 0){
                double wq_d[6]; for (int m = 0; m < 6; ++m) wq_d[m] = static_cast<double>(s_w[m]);
                double dIq_d[36]; grid_dIntegrate_q_block<double>(wq_d, dIq_d);
                for (int m = 0; m < 36; ++m) s_dInt_q[m] = static_cast<T>(dIq_d[m]);
            }
            __syncthreads();
            // reconstruct the pin dAB = [A|B] (col-major) from the SE(3) + fd-grad blocks
            T *s_dInt_q_6x6 = s_dInt_q; T *s_dInt_v_6x6 = s_dInt_v; (void)s_dInt_q_6x6; (void)s_dInt_v_6x6;
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 1944; ind += blockDim.x*blockDim.y){
                int row = ind % 36;
                int col = ind / 36;
                if constexpr (IT == IntegratorType::EULER) {
                    T val = static_cast<T>(0);
                    if (col < 18) {
                        // d/dq column
                        if (row < 18) {
                            if (row < 6 && col < 6) {
                                val = s_dInt_q_6x6[row * 6 + col];
                            } else if (row >= 6 && col >= 6) {
                                val = (row == col) ? static_cast<T>(1) : static_cast<T>(0);
                            } else { val = static_cast<T>(0); }
                        } else {
                            int i_local = row - 18;
                            val = dt * s_df_du[col * 18 + i_local];
                        }
                    } else if (col < 36) {
                        // d/dqd column
                        int j_local = col - 18;
                        if (row < 18) {
                            if (row < 6 && j_local < 6) {
                                val = dt * s_dInt_v_6x6[row * 6 + j_local];
                            } else if (row >= 6 && j_local >= 6) {
                                val = (row == j_local) ? dt : static_cast<T>(0);
                            } else { val = static_cast<T>(0); }
                        } else {
                            int i_local = row - 18;
                            T diag = (i_local == j_local) ? static_cast<T>(1) : static_cast<T>(0);
                            val = diag + dt * s_df_du[324 + j_local * 18 + i_local];
                        }
                    } else {
                        // d/du column   (dqdd/du = Minv)
                        int j_local = col - 36;
                        if (row < 18) {
                            val = static_cast<T>(0);
                        } else {
                            int i_local = row - 18;
                            int midx = (i_local <= j_local) * (j_local * 18 + i_local) + (i_local > j_local) * (i_local * 18 + j_local);
                            val = dt * s_Minv[midx];
                        }
                    }
                    s_dAB_pin[ind] = val;
                }
                else if constexpr (IT == IntegratorType::SEMI_IMPLICIT_EULER) {
                    T val = static_cast<T>(0);
                    if (col < 18) {
                        // d/dq column. dvdq[k,c] = dt*J_qq[k,c] = dt*s_df_du[c*n + k].
                        int c = col;
                        if (row < 18) {
                            T dInt_q_term = (row < 6 && c < 6) ? s_dInt_q_6x6[row * 6 + c]
                                           : ((row >= 6 && c >= 6) ? ((row == c) ? static_cast<T>(1) : static_cast<T>(0)) : static_cast<T>(0));
                            T mm;
                            if (row < 6) { mm = static_cast<T>(0); for (int k = 0; k < 6; ++k) mm += s_dInt_v_6x6[row * 6 + k] * (dt * s_df_du[c * 18 + k]); }
                            else { mm = dt * s_df_du[c * 18 + row]; }
                            val = dInt_q_term + dt * mm;
                        } else {
                            int i_local = row - 18;
                            val = dt * s_df_du[c * 18 + i_local];
                        }
                    } else if (col < 36) {
                        // d/dqd column. dvdv[k,c] = (k==c) + dt*J_qv[k,c].
                        int c = col - 18;
                        if (row < 18) {
                            T mm;
                            if (row < 6) { mm = static_cast<T>(0); for (int k = 0; k < 6; ++k) { T dvdv_k = ((k == c) ? static_cast<T>(1) : static_cast<T>(0)) + dt * s_df_du[324 + c * 18 + k]; mm += s_dInt_v_6x6[row * 6 + k] * dvdv_k; } }
                            else { mm = ((row == c) ? static_cast<T>(1) : static_cast<T>(0)) + dt * s_df_du[324 + c * 18 + row]; }
                            val = dt * mm;
                        } else {
                            int i_local = row - 18;
                            T diag = (i_local == c) ? static_cast<T>(1) : static_cast<T>(0);
                            val = diag + dt * s_df_du[324 + c * 18 + i_local];
                        }
                    } else {
                        // d/du column. dvdu[k,c] = dt*Minv[k,c] (SYMMETRIC_UPPER).
                        int c = col - 36;
                        if (row < 18) {
                            T mm;
                            if (row < 6) { mm = static_cast<T>(0); for (int k = 0; k < 6; ++k) { int midx = (k <= c) * (c * 18 + k) + (k > c) * (k * 18 + c); mm += s_dInt_v_6x6[row * 6 + k] * (dt * s_Minv[midx]); } }
                            else { int midx = (row <= c) * (c * 18 + row) + (row > c) * (row * 18 + c); mm = dt * s_Minv[midx]; }
                            val = dt * mm;
                        } else {
                            int i_local = row - 18;
                            int midx = (i_local <= c) * (c * 18 + i_local) + (i_local > c) * (i_local * 18 + c);
                            val = dt * s_Minv[midx];
                        }
                    }
                    s_dAB_pin[ind] = val;
                }
                else if constexpr (IT == IntegratorType::TRAPEZOIDAL) {
                    T val = static_cast<T>(0);
                    T dt2h = static_cast<T>(0.5) * dt * dt;
                    if (col < 18) {
                        // d/dq column. dw/dq[k] = dt2h*J_qq[c*n+k].
                        int c = col;
                        if (row < 18) {
                            T dInt_q_term = (row < 6 && c < 6) ? s_dInt_q_6x6[row * 6 + c]
                                           : ((row >= 6 && c >= 6) ? ((row == c) ? static_cast<T>(1) : static_cast<T>(0)) : static_cast<T>(0));
                            T mm;
                            if (row < 6) { mm = static_cast<T>(0); for (int k = 0; k < 6; ++k) mm += s_dInt_v_6x6[row * 6 + k] * (dt2h * s_df_du[c * 18 + k]); }
                            else { mm = dt2h * s_df_du[c * 18 + row]; }
                            val = dInt_q_term + mm;
                        } else {
                            int i_local = row - 18;
                            val = dt * s_df_du[c * 18 + i_local];
                        }
                    } else if (col < 36) {
                        // d/dqd column. dw/dqd[k] = (k==c?dt:0) + dt2h*J_qv[k].
                        int c = col - 18;
                        if (row < 18) {
                            T mm;
                            if (row < 6) { mm = static_cast<T>(0); for (int k = 0; k < 6; ++k) { T dw_k = ((k == c) ? dt : static_cast<T>(0)) + dt2h * s_df_du[324 + c * 18 + k]; mm += s_dInt_v_6x6[row * 6 + k] * dw_k; } }
                            else { mm = ((row == c) ? dt : static_cast<T>(0)) + dt2h * s_df_du[324 + c * 18 + row]; }
                            val = mm;
                        } else {
                            int i_local = row - 18;
                            T diag = (i_local == c) ? static_cast<T>(1) : static_cast<T>(0);
                            val = diag + dt * s_df_du[324 + c * 18 + i_local];
                        }
                    } else {
                        // d/du column. dw/du[k] = dt2h*Minv[k,c] (SYMMETRIC_UPPER).
                        int c = col - 36;
                        if (row < 18) {
                            T mm;
                            if (row < 6) { mm = static_cast<T>(0); for (int k = 0; k < 6; ++k) { int midx = (k <= c) * (c * 18 + k) + (k > c) * (k * 18 + c); mm += s_dInt_v_6x6[row * 6 + k] * (dt2h * s_Minv[midx]); } }
                            else { int midx = (row <= c) * (c * 18 + row) + (row > c) * (row * 18 + c); mm = dt2h * s_Minv[midx]; }
                            val = mm;
                        } else {
                            int i_local = row - 18;
                            int midx = (i_local <= c) * (c * 18 + i_local) + (i_local > c) * (i_local * 18 + c);
                            val = dt * s_Minv[midx];
                        }
                    }
                    s_dAB_pin[ind] = val;
                }
                else {
                    static_assert(IT == IntegratorType::EULER || IT == IntegratorType::SEMI_IMPLICIT_EULER || IT == IntegratorType::TRAPEZOIDAL,
                                  "dAB assembly handles single-stage IT only; Midpoint/RK3/RK4 are routed through gen_integrator_gradient_multistage.");
                }
            }
            __syncthreads();
            for(int ci = threadIdx.x + threadIdx.y*blockDim.x; ci < 104976; ci += blockDim.x*blockDim.y){
                s_d2AB_pin[ci] = s_d2AB[ci];
            }
            __syncthreads();
            for(int k = threadIdx.x + threadIdx.y*blockDim.x; k < 54; k += blockDim.x*blockDim.y){
                const bool si_mjx = si;
                T qx = s_q[3], qy = s_q[4], qz = s_q[5], qw = s_q[6];
                T xx = qx*qx, yy = qy*qy, zz = qz*qz;
                T xy = qx*qy, xz = qx*qz, yz = qy*qz, wx = qw*qx, wy = qw*qy, wz = qw*qz;
                T R[9];
                R[0] = static_cast<T>(1) - static_cast<T>(2)*(yy+zz); R[1] = static_cast<T>(2)*(xy-wz);                    R[2] = static_cast<T>(2)*(xz+wy);
                R[3] = static_cast<T>(2)*(xy+wz);                    R[4] = static_cast<T>(1) - static_cast<T>(2)*(xx+zz); R[5] = static_cast<T>(2)*(yz-wx);
                R[6] = static_cast<T>(2)*(xz-wy);                    R[7] = static_cast<T>(2)*(yz+wx);                    R[8] = static_cast<T>(1) - static_cast<T>(2)*(xx+yy);
                T v_lin[3] = {s_qd[0], s_qd[1], s_qd[2]};
                T u_lin[3] = {s_u[0],  s_u[1],  s_u[2]};
                T qdd_v[3] = {s_qdd[0], s_qdd[1], s_qdd[2]};
                T jqk[18], jvk[18], juk[18];
                T dABd[1944];                 // dot of pin dAB (col-major [c*2n+r])
                T d_qdd[18];
