            const T *s_var = &d_var[k*18]; const T *s_lo = &d_lower[k*18]; const T *s_hi = &d_upper[k*18];
            joint_velocity_barrier<T>(&d_out[k], s_var, s_lo, s_hi, mu, s_scratch);
            __syncthreads();
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 18; i += blockDim.x*blockDim.y){
                d_grad[k*18 + i] = grid_plant_log_barrier_grad<T>(s_var[i], s_lo[i], s_hi[i], mu);
                d_hess_diag[k*18 + i] = grid_plant_log_barrier_hess<T>(s_var[i], s_lo[i], s_hi[i], mu);
            }
            __syncthreads();
        }
    }

    /**
     * joint_torque_barrier_kernel: value + grad + hess-diagonal per timestep
     *
     * @param d_out scalar barrier cost (1 per timestep)
     * @param d_grad per-DOF gradient (18 per timestep)
     * @param d_hess_diag per-DOF hessian diagonal (18 per timestep)
     * @param d_var variable vector (18 per timestep)
     * @param d_lower / d_upper per-DOF bounds (18 per timestep)
     * @param mu barrier weight; NUM_TIMESTEPS is the batch size
     */
    template <typename T>
    __global__
    void joint_torque_barrier_kernel(T *d_out, T *d_grad, T *d_hess_diag, const T *d_var, const T *d_lower, const T *d_upper, const T mu, const int NUM_TIMESTEPS) {
        __shared__ T s_scratch[18];
        for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
            if(threadIdx.x == 0 && threadIdx.y == 0){
                d_out[k] = static_cast<T>(0);
            }
            __syncthreads();
            const T *s_var = &d_var[k*18]; const T *s_lo = &d_lower[k*18]; const T *s_hi = &d_upper[k*18];
            joint_torque_barrier<T>(&d_out[k], s_var, s_lo, s_hi, mu, s_scratch);
            __syncthreads();
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 18; i += blockDim.x*blockDim.y){
                d_grad[k*18 + i] = grid_plant_log_barrier_grad<T>(s_var[i], s_lo[i], s_hi[i], mu);
                d_hess_diag[k*18 + i] = grid_plant_log_barrier_hess<T>(s_var[i], s_lo[i], s_hi[i], mu);
            }
            __syncthreads();
        }
    }

    /**
     * plant_step kernel: x_{k+1} = integrator(x_k, u_k, dt) per timestep
     *
     * @param d_x_kp1 is the next-state output (NUM_POS+NUM_VEL per timestep)
     * @param d_x is the packed current state [q; qd] (NUM_POS+NUM_VEL per timestep)
     * @param d_u is the packed control torque (NUM_VEL per timestep)
     * @param stride_x / stride_u are the per-timestep strides
     * @param d_robotModel / gravity / dt as for plant_step
     * @param NUM_TIMESTEPS is the batch size
     */
    template <typename T, grid::IntegratorType IT = grid::IntegratorType::EULER, bool MUJOCO_OUTPUT = false>
    __global__
    void plant_step_kernel(T *d_x_kp1, const T *d_x, const T *d_u, const int stride_x, const int stride_u, const grid::robotModel<T> *d_robotModel, const T gravity, const T dt, const int NUM_TIMESTEPS) {
        __shared__ T s_x_mjx[37];
        for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
            if constexpr (MUJOCO_OUTPUT) {
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 37; ind += blockDim.x*blockDim.y){
                    s_x_mjx[ind] = d_x[k*stride_x + ind];
                }
                __syncthreads();
                // mjx input convert: base quaternion wxyz->xyzw (q-only; value frame-independent)
                if (threadIdx.x == 0 && threadIdx.y == 0) {
                    T qw_in = s_x_mjx[3];
                    s_x_mjx[3] = s_x_mjx[4]; s_x_mjx[4] = s_x_mjx[5]; s_x_mjx[5] = s_x_mjx[6]; s_x_mjx[6] = qw_in;
                }
                __syncthreads();
                plant_step<T, IT, true>(&d_x_kp1[k*37], s_x_mjx, &d_u[k*stride_u], d_robotModel, gravity, dt);
            }
            else {
                plant_step<T, IT, false>(&d_x_kp1[k*37], &d_x[k*stride_x], &d_u[k*stride_u], d_robotModel, gravity, dt);
            }
            __syncthreads();
        }
    }

    #define GRID_PLANT_HAS_STEP 1
    /**
     * plant_step_gradient kernel: [A|B] = integrator_gradient([q;qd], u, dt) per timestep (full-smem scratch arena; pass-through to grid::integrator_gradient_device)
     *
     * @param d_dAB is the [A|B] output (2*NUM_VEL*3*NUM_VEL per timestep, column-major)
     * @param d_x is the packed current state [q; qd] (NUM_POS+NUM_VEL per timestep)
     * @param d_u is the packed control torque (NUM_VEL per timestep)
     * @param stride_x / stride_u are the per-timestep strides
     * @param d_robotModel / gravity / dt as for plant_step
     * @param NUM_TIMESTEPS is the batch size
     */
    template <typename T, grid::IntegratorType IT = grid::IntegratorType::EULER, bool MUJOCO_OUTPUT = false>
    __global__
    __launch_bounds__(grid::MAX_PERF_LEVEL_THREADS)
    void plant_step_gradient_kernel(T *d_dAB, const T *d_x, const T *d_u, const int stride_x, const int stride_u, const grid::robotModel<T> *d_robotModel, const T gravity, const T dt, const int NUM_TIMESTEPS) {
        using namespace grid;
        // GRID shared arena layout
        //   T s_x[37]
        //   T s_u[18]
        //   T s_dAB[1944]
        //   T s_df_du[648]
        //   T s_dc_du[648]
        //   T s_vaf[324]
        //   T s_Minv[324]
        //   T s_qdd[18]
        //   T s_q_orig[19]
        //   T s_qd_orig[18]
        //   T s_stage_grad_qdd[72]
        //   T s_D_qdd_stage[3888]
        //   T s_dInt_q_6x6[36]
        //   T s_dInt_v_6x6[36]
        //   T s_XImats[936]
        //   T s_temp[9612]
        //   int s_topology_helpers[115]
        //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
        extern __shared__ __align__(16) unsigned char s_arena[];
        size_t s_arena_offset = 0;
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_x = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(37);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_u = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(18);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_dAB = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(1944);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_df_du = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(648);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_dc_du = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(648);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_vaf = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(324);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_Minv = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(324);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(18);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_q_orig = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(19);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_qd_orig = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(18);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_stage_grad_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(72);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_D_qdd_stage = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(3888);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_dInt_q_6x6 = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(36);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_dInt_v_6x6 = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(36);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(936);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(9612);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
        int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(int) * static_cast<size_t>(115);
        unsigned char *s_linalg_smem = nullptr;
        if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
            s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
            s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
            s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
        }
        #ifdef GRID_CUDA_DEBUG_LAYOUT
        assert(s_arena_offset == grid_shared_arena_bytes<T>(18578, 115, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
        #endif
        (void)s_arena_offset;
        for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 37; ind += blockDim.x*blockDim.y){
                s_x[ind] = d_x[k*stride_x + ind];
            }
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 18; ind += blockDim.x*blockDim.y){
                s_u[ind] = d_u[k*stride_u + ind];
            }
            __syncthreads();
            if constexpr (MUJOCO_OUTPUT) {
                // mjx input convert: quaternion wxyz->xyzw, base-linear velocity/accel/force -> pin frame
                if (threadIdx.x == 0 && threadIdx.y == 0) {
                    T qw_in = s_x[3];
                    s_x[3] = s_x[4]; s_x[4] = s_x[5]; s_x[5] = s_x[6]; s_x[6] = qw_in;
                    T qx = s_x[3], qy = s_x[4], qz = s_x[5], qw = s_x[6];
                    T xx = qx*qx, yy = qy*qy, zz = qz*qz;
                    T xy = qx*qy, xz = qx*qz, yz = qy*qz, wx = qw*qx, wy = qw*qy, wz = qw*qz;
                    T R[9];
                    R[0] = static_cast<T>(1) - static_cast<T>(2)*(yy+zz); R[1] = static_cast<T>(2)*(xy-wz);                    R[2] = static_cast<T>(2)*(xz+wy);
                    R[3] = static_cast<T>(2)*(xy+wz);                    R[4] = static_cast<T>(1) - static_cast<T>(2)*(xx+zz); R[5] = static_cast<T>(2)*(yz-wx);
                    R[6] = static_cast<T>(2)*(xz-wy);                    R[7] = static_cast<T>(2)*(yz+wx);                    R[8] = static_cast<T>(1) - static_cast<T>(2)*(xx+yy);
                    T vlx = (s_x + 19)[0], vly = (s_x + 19)[1], vlz = (s_x + 19)[2];
                    (s_x + 19)[0] = R[0]*vlx + R[3]*vly + R[6]*vlz;
                    (s_x + 19)[1] = R[1]*vlx + R[4]*vly + R[7]*vlz;
                    (s_x + 19)[2] = R[2]*vlx + R[5]*vly + R[8]*vlz;
                    T ufx = s_u[0], ufy = s_u[1], ufz = s_u[2];
                    s_u[0] = R[0]*ufx + R[3]*ufy + R[6]*ufz;
                    s_u[1] = R[1]*ufx + R[4]*ufy + R[7]*ufz;
                    s_u[2] = R[2]*ufx + R[5]*ufy + R[8]*ufz;
                }
                __syncthreads();
            }
            plant_step_gradient<T, IT, true, false, MUJOCO_OUTPUT>(s_dAB, s_x, s_u, s_df_du, s_dc_du, s_vaf, s_Minv, s_qdd, s_q_orig, s_qd_orig, s_stage_grad_qdd, s_D_qdd_stage, s_dInt_q_6x6, s_dInt_v_6x6, s_XImats, s_topology_helpers, s_temp, nullptr, nullptr, d_robotModel, gravity, dt);
            __syncthreads();
            if(threadIdx.x == 0 && threadIdx.y == 0){
                for (int ind = 0; ind < 1944; ++ind) d_dAB[k*1944 + ind] = s_dAB[ind];
            }
            __syncthreads();
        }
    }

    /**
     * plant_step_gradient_arena: carve struct mirroring plant_step_gradient_kernel's full-smem scratch layout; members map 1:1 onto plant_step_gradient's caller-placed buffer arguments. Allocate INTEGRATOR_DU_DYNAMIC_SHARED_MEM_BYTES<T, TIER_SHARED>() bytes and call carve(base).
     *
     */
    template <typename T>
    struct plant_step_gradient_arena {
        T *s_x;
        T *s_u;
        T *s_dAB;
        T *s_df_du;
        T *s_dc_du;
        T *s_vaf;
        T *s_Minv;
        T *s_qdd;
        T *s_q_orig;
        T *s_qd_orig;
        T *s_stage_grad_qdd;
        T *s_D_qdd_stage;
        T *s_dInt_q_6x6;
        T *s_dInt_v_6x6;
        T *s_XImats;
        T *s_temp;
        int *s_topology_helpers;
        unsigned char *s_linalg_smem;
        static __device__ plant_step_gradient_arena<T> carve(void *base) {
            unsigned char *s_arena = reinterpret_cast<unsigned char *>(base);
            size_t s_arena_offset = 0;
            plant_step_gradient_arena<T> a;
            s_arena_offset = grid::grid_align_up(s_arena_offset, alignof(T));
            a.s_x = grid::grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(37);
            s_arena_offset = grid::grid_align_up(s_arena_offset, alignof(T));
            a.s_u = grid::grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(18);
            s_arena_offset = grid::grid_align_up(s_arena_offset, alignof(T));
            a.s_dAB = grid::grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(1944);
            s_arena_offset = grid::grid_align_up(s_arena_offset, alignof(T));
            a.s_df_du = grid::grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(648);
            s_arena_offset = grid::grid_align_up(s_arena_offset, alignof(T));
            a.s_dc_du = grid::grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(648);
            s_arena_offset = grid::grid_align_up(s_arena_offset, alignof(T));
            a.s_vaf = grid::grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(324);
            s_arena_offset = grid::grid_align_up(s_arena_offset, alignof(T));
            a.s_Minv = grid::grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(324);
            s_arena_offset = grid::grid_align_up(s_arena_offset, alignof(T));
            a.s_qdd = grid::grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(18);
            s_arena_offset = grid::grid_align_up(s_arena_offset, alignof(T));
            a.s_q_orig = grid::grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(19);
            s_arena_offset = grid::grid_align_up(s_arena_offset, alignof(T));
            a.s_qd_orig = grid::grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(18);
            s_arena_offset = grid::grid_align_up(s_arena_offset, alignof(T));
            a.s_stage_grad_qdd = grid::grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(72);
            s_arena_offset = grid::grid_align_up(s_arena_offset, alignof(T));
            a.s_D_qdd_stage = grid::grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(3888);
            s_arena_offset = grid::grid_align_up(s_arena_offset, alignof(T));
            a.s_dInt_q_6x6 = grid::grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(36);
            s_arena_offset = grid::grid_align_up(s_arena_offset, alignof(T));
            a.s_dInt_v_6x6 = grid::grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(36);
            s_arena_offset = grid::grid_align_up(s_arena_offset, alignof(T));
            a.s_XImats = grid::grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(936);
            s_arena_offset = grid::grid_align_up(s_arena_offset, alignof(T));
            a.s_temp = grid::grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(9612);
            s_arena_offset = grid::grid_align_up(s_arena_offset, alignof(int));
            a.s_topology_helpers = grid::grid_arena_ptr<int>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(int) * static_cast<size_t>(115);
            a.s_linalg_smem = nullptr;
            if (static_cast<size_t>(grid::GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid::grid_align_up(s_arena_offset, static_cast<size_t>(16));
                a.s_linalg_smem = grid::grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(grid::GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset <= grid::INTEGRATOR_DU_DYNAMIC_SHARED_MEM_BYTES<T, grid::TIER_SHARED>());
            #endif
            (void)s_arena_offset;
            return a;
        }
    };

    #define GRID_PLANT_HAS_STEP_GRADIENT 1
    template <typename T> __host__ __device__ inline size_t PLANT_HESSIAN_WORKSPACE_BYTES_PER_TIMESTEP() { return sizeof(T) * static_cast<size_t>(281916); }
    /**
     * plant_step_hessian kernel: s_d2AB = d^2 integrator([q;qd], u, dt) per timestep (tier-aware scratch; pass-through to grid::integrator_hessian_device)
     *
     * @param d_d2AB is the Hessian output (2*NUM_VEL*3*NUM_VEL*3*NUM_VEL per timestep, row-major)
     * @param d_workspace is the generated global spill workspace (nullptr at TIER_SHARED)
     * @param d_x is the packed current state [q; qd] (NUM_POS+NUM_VEL per timestep)
     * @param d_u is the packed control torque (NUM_VEL per timestep)
     * @param stride_x / stride_u are the per-timestep strides
     * @param d_robotModel / gravity / dt as for plant_step
     * @param NUM_TIMESTEPS is the batch size
     */
    template <typename T, grid::IntegratorType IT = grid::IntegratorType::EULER, int RESOURCE_TIER = grid::GRID_DEFAULT_RESOURCE_TIER, bool MUJOCO_OUTPUT = false>
    __global__
    __launch_bounds__(grid::tier_max_threads<RESOURCE_TIER>())
    void plant_step_hessian_kernel(T *d_d2AB, unsigned char *d_workspace, const T *d_x, const T *d_u, const int stride_x, const int stride_u, const grid::robotModel<T> *d_robotModel, const T gravity, const T dt, const int NUM_TIMESTEPS) {
        using namespace grid;
        // GRID shared arena layout
        //   T s_x[37]
        //   T s_u[18]
        //   T s_Minv[324]
        //   T s_df_du[648]
        //   T s_qdd[18]
        //   T s_XImats[936]
        //   int s_topology_helpers[115]
        //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
        extern __shared__ __align__(16) unsigned char s_arena[];
        size_t s_arena_offset = 0;
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_x = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(37);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_u = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(18);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_Minv = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(324);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_df_du = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(648);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(18);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(936);
        T *s_temp = nullptr;
        s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
        int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(int) * static_cast<size_t>(115);
        unsigned char *s_linalg_smem = nullptr;
        if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
            s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
            s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
            s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
        }
        #ifdef GRID_CUDA_DEBUG_LAYOUT
        assert(s_arena_offset == grid_shared_arena_bytes<T>(1981, 115, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
        #endif
        (void)s_arena_offset;
        for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 37; ind += blockDim.x*blockDim.y){
                s_x[ind] = d_x[k*stride_x + ind];
            }
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 18; ind += blockDim.x*blockDim.y){
                s_u[ind] = d_u[k*stride_u + ind];
            }
            __syncthreads();
            if constexpr (MUJOCO_OUTPUT) {
                // mjx input convert: quaternion wxyz->xyzw, base-linear velocity/accel/force -> pin frame
                if (threadIdx.x == 0 && threadIdx.y == 0) {
                    T qw_in = s_x[3];
                    s_x[3] = s_x[4]; s_x[4] = s_x[5]; s_x[5] = s_x[6]; s_x[6] = qw_in;
                    T qx = s_x[3], qy = s_x[4], qz = s_x[5], qw = s_x[6];
                    T xx = qx*qx, yy = qy*qy, zz = qz*qz;
                    T xy = qx*qy, xz = qx*qz, yz = qy*qz, wx = qw*qx, wy = qw*qy, wz = qw*qz;
                    T R[9];
                    R[0] = static_cast<T>(1) - static_cast<T>(2)*(yy+zz); R[1] = static_cast<T>(2)*(xy-wz);                    R[2] = static_cast<T>(2)*(xz+wy);
                    R[3] = static_cast<T>(2)*(xy+wz);                    R[4] = static_cast<T>(1) - static_cast<T>(2)*(xx+zz); R[5] = static_cast<T>(2)*(yz-wx);
                    R[6] = static_cast<T>(2)*(xz-wy);                    R[7] = static_cast<T>(2)*(yz+wx);                    R[8] = static_cast<T>(1) - static_cast<T>(2)*(xx+yy);
                    T vlx = (s_x + 19)[0], vly = (s_x + 19)[1], vlz = (s_x + 19)[2];
                    (s_x + 19)[0] = R[0]*vlx + R[3]*vly + R[6]*vlz;
                    (s_x + 19)[1] = R[1]*vlx + R[4]*vly + R[7]*vlz;
                    (s_x + 19)[2] = R[2]*vlx + R[5]*vly + R[8]*vlz;
                    T ufx = s_u[0], ufy = s_u[1], ufz = s_u[2];
                    s_u[0] = R[0]*ufx + R[3]*ufy + R[6]*ufz;
                    s_u[1] = R[1]*ufx + R[4]*ufy + R[7]*ufz;
                    s_u[2] = R[2]*ufx + R[5]*ufy + R[8]*ufz;
                }
                __syncthreads();
            }
            T *d_ws = reinterpret_cast<T *>(&d_workspace[k*PLANT_HESSIAN_WORKSPACE_BYTES_PER_TIMESTEP<T>()]);
            size_t ws_off = 0;
            T *s_d2AB = &d_ws[ws_off]; ws_off += 104976;
            T *s_df2 = &d_ws[ws_off]; ws_off += 23328;
            T *s_idsva_so = &d_ws[ws_off]; ws_off += 23328;
            T *s_fdsva_pool = &d_ws[ws_off]; ws_off += 23328;
            T *d_mjx_ws = &d_ws[ws_off]; ws_off += 106956;
            (void)ws_off;
            plant_step_hessian<T, IT, false, false, false, MUJOCO_OUTPUT>(s_d2AB, s_x, s_u, s_df2, s_idsva_so, s_Minv, s_df_du, s_qdd, s_XImats, s_topology_helpers, s_temp, s_fdsva_pool, nullptr, s_fdsva_pool, d_mjx_ws, d_robotModel, gravity, dt);
            __syncthreads();
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 104976; ind += blockDim.x*blockDim.y){
                d_d2AB[k*104976 + ind] = s_d2AB[ind];
            }
            __syncthreads();
        }
    }

    template <typename T, int TIER = grid::GRID_DEFAULT_RESOURCE_TIER> __host__ __device__ inline size_t INTEGRATOR_HESSIAN_DYNAMIC_SHARED_MEM_BYTES() { if constexpr (TIER == grid::TIER_SHARED)    return grid::grid_shared_arena_bytes<T>(1981, grid::TOPOLOGY_HELPERS_COUNT, grid::GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()); else if constexpr (TIER == grid::TIER_LITE) return grid::grid_shared_arena_bytes<T>(1981, grid::TOPOLOGY_HELPERS_COUNT, grid::GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()); else                                        return grid::grid_shared_arena_bytes<T>(1981, grid::TOPOLOGY_HELPERS_COUNT, grid::GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()); }
    static const int GRID_PLANT_HESSIAN_USES_WORKSPACE_ANY_TIER = 1;
    #define GRID_PLANT_HAS_STEP_HESSIAN 1
    /**
     * ee_pos_cost_kernel: value + grad_x + GN hess_x per timestep (EE=0)
     *
     * @param d_out scalar cost (1 per timestep)
     * @param d_grad grad over x (37 per timestep)
     * @param d_hess dense col-major x-hessian (1369 per timestep)
     * @param d_q joint positions (NUM_POS per timestep)
     * @param d_p_des desired EE position (3 per timestep)
     * @param d_W per-axis weight (3 per timestep)
     * @param d_end_effector_pose / d_end_effector_pose_gradient global scratch (6*NUM_EES / 6*NUM_VEL*NUM_EES per timestep)
     * @param NUM_TIMESTEPS is the batch size
     */
    template <typename T, int EE = 0, bool MUJOCO_OUTPUT = false>
    __global__
    void ee_pos_cost_kernel(T *d_out, T *d_grad, T *d_hess, const T *d_q, const T *d_p_des, const T *d_W, T *d_end_effector_pose, T *d_end_effector_pose_gradient, const grid::robotModel<T> *d_robotModel, const int NUM_TIMESTEPS) {
        extern __shared__ __align__(16) T s_ee_arena[];
        for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
            const T *s_q = &d_q[k*19]; const T *s_p_des = &d_p_des[k*3]; const T *s_W = &d_W[k*3];
            T *s_end_effector_pose = &d_end_effector_pose[k*6]; T *s_end_effector_pose_gradient = &d_end_effector_pose_gradient[k*108];
            const T *s_q_use = s_q;
            if constexpr (MUJOCO_OUTPUT) {
                __shared__ T s_q_mjx[19];
                for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 19; i += blockDim.x*blockDim.y){
                    s_q_mjx[i] = s_q[i];
                }
                __syncthreads();
                // mjx input convert: base quaternion wxyz->xyzw
                if (threadIdx.x == 0 && threadIdx.y == 0) {
                    T qw_in = s_q_mjx[3];
                    s_q_mjx[3] = s_q_mjx[4]; s_q_mjx[4] = s_q_mjx[5]; s_q_mjx[5] = s_q_mjx[6]; s_q_mjx[6] = qw_in;
                }
                __syncthreads();
                s_q_use = s_q_mjx;
            }
            ee_pos_cost<T, EE>(&d_out[k], s_q_use, s_p_des, s_W, s_end_effector_pose, s_ee_arena, d_robotModel);
            __syncthreads();
            ee_pos_cost_gradient<T, EE, false, MUJOCO_OUTPUT>(&d_grad[k*37], s_q_use, s_p_des, s_W, s_end_effector_pose, s_end_effector_pose_gradient, s_ee_arena, d_robotModel);
            __syncthreads();
            ee_pos_cost_hessian<T, EE, false, true, MUJOCO_OUTPUT>(&d_hess[k*1369], s_q_use, s_p_des, s_W, s_end_effector_pose, s_end_effector_pose_gradient, nullptr, s_ee_arena, d_robotModel);
            __syncthreads();
        }
    }

    #define GRID_PLANT_HAS_EE_COST 1
    /**
     * com_cost_kernel: value + grad_x + GN hess_x per timestep
     *
     * @param d_out scalar cost (1 per timestep)
     * @param d_grad grad over x (37 per timestep)
     * @param d_hess dense col-major x-hessian (1369 per timestep)
     * @param d_q joint positions (NUM_POS per timestep)
     * @param d_p_des desired CoM position (3 per timestep)
     * @param d_W per-axis weight (3 per timestep)
     * @param NUM_TIMESTEPS is the batch size
     */
    template <typename T, bool MUJOCO_OUTPUT = false>
    __global__
    void com_cost_kernel(T *d_out, T *d_grad, T *d_hess, const T *d_q, const T *d_p_des, const T *d_W, const grid::robotModel<T> *d_robotModel, const int NUM_TIMESTEPS) {
        extern __shared__ __align__(16) T s_com_arena[];
        for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
            const T *s_q = &d_q[k*19]; const T *s_p_des = &d_p_des[k*3]; const T *s_W = &d_W[k*3];
            const T *s_q_use = s_q;
            if constexpr (MUJOCO_OUTPUT) {
                __shared__ T s_q_mjx[19];
                for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 19; i += blockDim.x*blockDim.y){
                    s_q_mjx[i] = s_q[i];
                }
                __syncthreads();
                // mjx input convert: base quaternion wxyz->xyzw
                if (threadIdx.x == 0 && threadIdx.y == 0) {
                    T qw_in = s_q_mjx[3];
                    s_q_mjx[3] = s_q_mjx[4]; s_q_mjx[4] = s_q_mjx[5]; s_q_mjx[5] = s_q_mjx[6]; s_q_mjx[6] = qw_in;
                }
                __syncthreads();
                s_q_use = s_q_mjx;
            }
            com_cost<T>(&d_out[k], s_q_use, s_p_des, s_W, s_com_arena, d_robotModel);
            __syncthreads();
            com_cost_gradient<T, false, MUJOCO_OUTPUT>(&d_grad[k*37], s_q_use, s_p_des, s_W, s_com_arena, d_robotModel);
            __syncthreads();
            com_cost_hessian<T, false, MUJOCO_OUTPUT>(&d_hess[k*1369], s_q_use, s_W, s_com_arena, d_robotModel);
            __syncthreads();
        }
    }

    #define GRID_PLANT_HAS_COM_COST 1
    /**
     * momentum_cost_kernel: value + grad_x + GN hess_x per timestep
     *
     * @param d_out scalar cost (1 per timestep)
     * @param d_grad grad over x (37 per timestep)
     * @param d_hess dense col-major x-hessian (1369 per timestep)
     * @param d_q / d_qd joint positions/velocities (NUM_POS / NUM_VEL per timestep)
     * @param d_h_des desired centroidal momentum (6 per timestep)
     * @param d_W per-component weight (6 per timestep)
     * @param NUM_TIMESTEPS is the batch size
     */
    template <typename T, bool MUJOCO_OUTPUT = false>
    __global__
    void momentum_cost_kernel(T *d_out, T *d_grad, T *d_hess, const T *d_q, const T *d_qd, const T *d_h_des, const T *d_W, const grid::robotModel<T> *d_robotModel, const int NUM_TIMESTEPS) {
        extern __shared__ __align__(16) T s_ccrba_arena[];
        for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
            const T *s_q = &d_q[k*19]; const T *s_qd = &d_qd[k*18];
            const T *s_h_des = &d_h_des[k*6]; const T *s_W = &d_W[k*6];
            const T *s_q_use = s_q; const T *s_qd_use = s_qd;
            if constexpr (MUJOCO_OUTPUT) {
                __shared__ T s_q_mjx[19];
                __shared__ T s_qd_mjx[18];
                for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 19; i += blockDim.x*blockDim.y){
                    s_q_mjx[i] = s_q[i];
                }
                for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 18; i += blockDim.x*blockDim.y){
                    s_qd_mjx[i] = s_qd[i];
                }
                __syncthreads();
                // mjx input convert: base quaternion wxyz->xyzw + base-linear velocity -> pin frame
                if (threadIdx.x == 0 && threadIdx.y == 0) {
                    T qw_in = s_q_mjx[3];
                    s_q_mjx[3] = s_q_mjx[4]; s_q_mjx[4] = s_q_mjx[5]; s_q_mjx[5] = s_q_mjx[6]; s_q_mjx[6] = qw_in;
                    T qx = s_q_mjx[3], qy = s_q_mjx[4], qz = s_q_mjx[5], qw = s_q_mjx[6];
                    T xx = qx*qx, yy = qy*qy, zz = qz*qz;
                    T xy = qx*qy, xz = qx*qz, yz = qy*qz, wx = qw*qx, wy = qw*qy, wz = qw*qz;
                    T R[9];
                    R[0] = static_cast<T>(1) - static_cast<T>(2)*(yy+zz); R[1] = static_cast<T>(2)*(xy-wz);                    R[2] = static_cast<T>(2)*(xz+wy);
                    R[3] = static_cast<T>(2)*(xy+wz);                    R[4] = static_cast<T>(1) - static_cast<T>(2)*(xx+zz); R[5] = static_cast<T>(2)*(yz-wx);
                    R[6] = static_cast<T>(2)*(xz-wy);                    R[7] = static_cast<T>(2)*(yz+wx);                    R[8] = static_cast<T>(1) - static_cast<T>(2)*(xx+yy);
                    T vlx = s_qd_mjx[0], vly = s_qd_mjx[1], vlz = s_qd_mjx[2];
                    s_qd_mjx[0] = R[0]*vlx + R[3]*vly + R[6]*vlz;
                    s_qd_mjx[1] = R[1]*vlx + R[4]*vly + R[7]*vlz;
                    s_qd_mjx[2] = R[2]*vlx + R[5]*vly + R[8]*vlz;
                }
                __syncthreads();
                s_q_use = s_q_mjx; s_qd_use = s_qd_mjx;
            }
            momentum_cost<T>(&d_out[k], s_q_use, s_qd_use, s_h_des, s_W, s_ccrba_arena, d_robotModel);
            __syncthreads();
            momentum_cost_gradient<T, false, MUJOCO_OUTPUT>(&d_grad[k*37], s_q_use, s_qd_use, s_h_des, s_W, s_ccrba_arena, d_robotModel);
            __syncthreads();
            momentum_cost_hessian<T, false, MUJOCO_OUTPUT>(&d_hess[k*1369], s_q_use, s_qd_use, s_W, s_ccrba_arena, d_robotModel);
            __syncthreads();
        }
    }

    #define GRID_PLANT_HAS_MOMENTUM_COST 1
}

#include "grid_collision_geometry.cuh"  // W3 Component E: SDF primitives (grid_collision::)
/**
 * Collision namespace: baked sphere data + config_free composed over grid::multi_target_position + the static SDF geometry header
 *
 */
namespace grid_collision {
    using grid::TIER_SHARED; using grid::TIER_LITE; using grid::TIER_MINIMAL;
    constexpr int NUM_COLLISION_SPHERES = 50;
    constexpr int NUM_COLLISION_SELF_CC_RANGES = 59;
    static_assert(NUM_COLLISION_SPHERES == grid::NUM_MULTI_TARGETS, "collision sphere batch must be the multi_target batch");
    __device__ const float g_collision_sphere_r[50] = {0.0967773346f, 0.0967773346f, 0.0967773346f, 0.0672681202f, 0.0672681202f, 0.047f, 0.0501597448f, 0.0501597448f, 0.0572243392f, 0.0572243392f, 0.0611882342f, 0.0611882342f, 0.0343110769f, 0.0343110769f, 0.0215696546f, 0.0215696546f, 0.022f, 0.0501597448f, 0.0501597448f, 0.0572243392f, 0.0572243392f, 0.0613921819f, 0.0613921819f, 0.0343110769f, 0.0343110769f, 0.0215696546f, 0.0215696546f, 0.022f, 0.0501597448f, 0.0501597448f, 0.0572243392f, 0.0572243392f, 0.0613921819f, 0.0613921819f, 0.0343110769f, 0.0343110769f, 0.0215696546f, 0.0215696546f, 0.022f, 0.0501597448f, 0.0501597448f, 0.0572243392f, 0.0572243392f, 0.0613921819f, 0.0613921819f, 0.0343110769f, 0.0343110769f, 0.0215696546f, 0.0215696546f, 0.022f};
    __device__ const int g_collision_self_cc_ranges[177] = {0, 8, 16, 0, 19, 27, 0, 30, 38, 0, 41, 49, 1, 8, 16, 1, 19, 27, 1, 30, 38, 1, 41, 49, 2, 8, 16, 2, 19, 27, 2, 30, 38, 2, 41, 49, 3, 8, 16, 3, 19, 27, 3, 30, 38, 3, 41, 49, 4, 8, 16, 4, 19, 27, 4, 30, 38, 4, 41, 49, 5, 8, 16, 5, 19, 27, 5, 30, 38, 5, 41, 49, 6, 10, 49, 7, 10, 49, 8, 17, 49, 9, 17, 49, 10, 17, 49, 11, 17, 49, 12, 17, 49, 13, 17, 49, 14, 17, 49, 15, 17, 49, 16, 17, 49, 17, 21, 49, 18, 21, 49, 19, 28, 49, 20, 28, 49, 21, 28, 49, 22, 28, 49, 23, 28, 49, 24, 28, 49, 25, 28, 49, 26, 28, 49, 27, 28, 49, 28, 32, 49, 29, 32, 49, 30, 39, 49, 31, 39, 49, 32, 39, 49, 33, 39, 49, 34, 39, 49, 35, 39, 49, 36, 39, 49, 37, 39, 49, 38, 39, 49, 39, 43, 49, 40, 43, 49};
    /**
     * Fill s_r[NUM_COLLISION_SPHERES] with the baked fp32 radii cast to T
     *
     * @param s_r is caller shared memory of size NUM_COLLISION_SPHERES
     */
    template <typename T>
    __device__ __forceinline__
    void load_collision_radii(T *s_r) {
        for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < NUM_COLLISION_SPHERES; i += blockDim.x*blockDim.y){
            s_r[i] = static_cast<T>(g_collision_sphere_r[i]);
        }
    }

    /**
     * Collision-free test for configuration q (self + environment)
     *
     * Notes:
     *   Returns true iff the current configuration q is COLLISION-FREE (self + environment).
     *   Sphere world positions via the W1b batched extractor; SDF self/env checks via the static header.
     *   Every thread computes the same verdict; the self/env range loops are serial (parallelize = W3 perf TODO).
     *
     * @param s_q is the vector of joint positions
     * @param d_robotModel is the initialized model-specific helpers on the GPU
     * @param env is the runtime obstacle set (grid_collision::Environment<T>)
     * @param s_sphere_pos is caller scratch of size 3*NUM_COLLISION_SPHERES (smem for small N, global for many)
     * @param s_sphere_r is caller scratch of size NUM_COLLISION_SPHERES (filled here from the baked radii)
     * @param d_workspace is the multi_target FK scratch at TIER_LITE+ (nullptr at TIER_SHARED)
     */
    template <typename T, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __device__
    bool config_free(const T *s_q, const grid::robotModel<T> *d_robotModel, const Environment<T> &env, T *s_sphere_pos, T *s_sphere_r, T *d_workspace = nullptr) {
        grid::multi_target_position_device<T, RESOURCE_TIER>(s_sphere_pos, s_q, d_robotModel, d_workspace);
        load_collision_radii<T>(s_sphere_r);
        __syncthreads();
        if (grid_cc_self_collision<T>(s_sphere_pos, s_sphere_r, g_collision_self_cc_ranges, NUM_COLLISION_SELF_CC_RANGES)) return false;
        for (int i = 0; i < NUM_COLLISION_SPHERES; ++i) {
            if (grid_cc_sphere_in_environment<T>(env, s_sphere_pos[3*i], s_sphere_pos[3*i+1], s_sphere_pos[3*i+2], s_sphere_r[i])) return false;
        }
        return true;
    }

    /**
     * collision_distance: per-sphere nearest signed clearance d_i(q) + surface normal (env only)
     *
     * Notes:
     *   d_i = min over environment obstacles of the signed distance (>0 clear, <0 penetrating).
     *   s_dist[i] = +1e30 sentinel when the environment is empty. Raw building block for any collision objective; the cost fns below reduce over it.
     *
     * @param s_dist is the per-sphere clearance output (size NUM_COLLISION_SPHERES)
     * @param s_normal is the per-sphere nearest-obstacle unit normal (size 3*NUM_COLLISION_SPHERES)
     * @param s_q is the vector of joint positions
     * @param d_robotModel is the initialized model-specific helpers on the GPU
     * @param env is the runtime obstacle set (grid_collision::Environment<T>)
     * @param s_sphere_pos is caller scratch of size 3*NUM_COLLISION_SPHERES (sphere world positions)
     * @param s_sphere_r is caller scratch of size NUM_COLLISION_SPHERES (filled here from the baked radii)
     * @param d_workspace is the multi_target FK scratch at TIER_LITE+ (nullptr at TIER_SHARED)
     */
    template <typename T, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __device__
    void collision_distance(T *s_dist, T *s_normal, const T *s_q, const grid::robotModel<T> *d_robotModel, const Environment<T> &env, T *s_sphere_pos, T *s_sphere_r, T *d_workspace = nullptr) {
        grid::multi_target_position_device<T, RESOURCE_TIER>(s_sphere_pos, s_q, d_robotModel, d_workspace);
        load_collision_radii<T>(s_sphere_r);
        __syncthreads();
        for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < NUM_COLLISION_SPHERES; i += blockDim.x*blockDim.y){
            T nx, ny, nz;
            s_dist[i] = grid_cc_nearest_obstacle<T>(env, s_sphere_pos[3*i], s_sphere_pos[3*i+1], s_sphere_pos[3*i+2], s_sphere_r[i], &nx, &ny, &nz);
            s_normal[3*i+0] = nx; s_normal[3*i+1] = ny; s_normal[3*i+2] = nz;
        }
        __syncthreads();
    }

    /**
     * collision_distance_gradient: per-sphere clearance Jacobian s_ddist[i*NV+vi] = d(d_i)/dq_vi = n_i^T dp_i/dq_vi
     *
     * Notes:
     *   Also returns s_dist (the clearances) so a consumer has value + Jacobian in one call.
     *   n_i^T (dp_i/dq) composes the SDF normal with grid::multi_target_position_gradient_device.
     *   s_ddist layout is per-sphere-major: sphere i's NV-gradient is s_ddist[i*NV .. i*NV+NV-1].
     *
     * @param s_dist is the per-sphere clearance output (size NUM_COLLISION_SPHERES)
     * @param s_ddist is the per-sphere clearance Jacobian output (size NUM_COLLISION_SPHERES*NUM_VEL, sphere-major)
     * @param s_q is the vector of joint positions
     * @param d_robotModel is the initialized model-specific helpers on the GPU
     * @param env is the runtime obstacle set (grid_collision::Environment<T>)
     * @param s_sphere_pos is caller scratch of size 3*NUM_COLLISION_SPHERES (sphere world positions)
     * @param s_sphere_r is caller scratch of size NUM_COLLISION_SPHERES (filled here from the baked radii)
     * @param d_workspace is the multi_target FK scratch at TIER_LITE+ (nullptr at TIER_SHARED)
     * @param s_normal is caller scratch of size 3*NUM_COLLISION_SPHERES (nearest-obstacle normals)
     * @param s_pos_grad is caller scratch of size 3*NUM_VEL*NUM_COLLISION_SPHERES (batched dp/dq)
     */
    template <typename T, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __device__
    void collision_distance_gradient(T *s_dist, T *s_ddist, const T *s_q, const grid::robotModel<T> *d_robotModel, const Environment<T> &env, T *s_sphere_pos, T *s_sphere_r, T *s_normal, T *s_pos_grad, T *d_workspace = nullptr) {
        collision_distance<T, RESOURCE_TIER>(s_dist, s_normal, s_q, d_robotModel, env, s_sphere_pos, s_sphere_r, d_workspace);
        grid::multi_target_position_gradient_device<T, RESOURCE_TIER>(s_pos_grad, s_q, d_robotModel, d_workspace);
        __syncthreads();
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < NUM_COLLISION_SPHERES * 18; ind += blockDim.x*blockDim.y){
            int vi = ind % 18; int i = ind / 18;
            int jb = 3 * (18 * i + vi);
            s_ddist[i*18 + vi] = s_normal[3*i+0]*s_pos_grad[jb+0] + s_normal[3*i+1]*s_pos_grad[jb+1] + s_normal[3*i+2]*s_pos_grad[jb+2];
        }
        __syncthreads();
    }

    /**
     * collision_distance_pairs: UN-REDUCED signed clearance d_io(q) + normal, for every (sphere, obstacle) pair
     *
     * Notes:
     *   Same SDFs as collision_distance but WITHOUT the min-over-obstacles reduction, which is non-smooth precisely where the nearest obstacle switches. Each pair row is smooth in q.
     *   Obstacle o indexes the FLATTENED env: spheres | capsules | cuboids | planes, o in [0, n_obs) with n_obs = grid_cc_num_obstacles(env). Pair index is pair = i*n_obs + o (sphere-major).
     *   n_obs == 0 (empty environment) is well-defined: the loop bound is 0 and nothing is written.
     *
     * @param s_dist is the per-PAIR clearance output (size NUM_COLLISION_SPHERES*n_obs, RUNTIME-sized)
     * @param s_normal is the per-PAIR unit surface normal (size 3*NUM_COLLISION_SPHERES*n_obs, RUNTIME-sized)
     * @param s_q is the vector of joint positions
     * @param d_robotModel is the initialized model-specific helpers on the GPU
     * @param env is the runtime obstacle set (grid_collision::Environment<T>)
     * @param s_sphere_pos is caller scratch of size 3*NUM_COLLISION_SPHERES (sphere world positions)
     * @param s_sphere_r is caller scratch of size NUM_COLLISION_SPHERES (filled here from the baked radii)
     * @param d_workspace is the multi_target FK scratch at TIER_LITE+ (nullptr at TIER_SHARED)
     */
    template <typename T, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __device__
    void collision_distance_pairs(T *s_dist, T *s_normal, const T *s_q, const grid::robotModel<T> *d_robotModel, const Environment<T> &env, T *s_sphere_pos, T *s_sphere_r, T *d_workspace = nullptr) {
        grid::multi_target_position_device<T, RESOURCE_TIER>(s_sphere_pos, s_q, d_robotModel, d_workspace);
        load_collision_radii<T>(s_sphere_r);
        __syncthreads();
        const int n_obs = grid_cc_num_obstacles<T>(env);
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < NUM_COLLISION_SPHERES * n_obs; ind += blockDim.x*blockDim.y){
            int o = ind % n_obs; int i = ind / n_obs;
            T nx, ny, nz;
            s_dist[ind] = grid_cc_obstacle_signed<T>(env, o, s_sphere_pos[3*i], s_sphere_pos[3*i+1], s_sphere_pos[3*i+2], s_sphere_r[i], &nx, &ny, &nz);
            s_normal[3*ind+0] = nx; s_normal[3*ind+1] = ny; s_normal[3*ind+2] = nz;
        }
        __syncthreads();
    }

    /**
     * collision_distance_pairs_gradient: per-PAIR clearance Jacobian s_ddist[pair*NV + vi] = d(d_io)/dq_vi = n_io^T dp_i/dq_vi
     *
     * Notes:
     *   The un-reduced twin of collision_distance_gradient: one NV-row per (sphere, obstacle) pair, each smooth in q. Also returns s_dist so a consumer has value + Jacobian in one call.
     *   Obstacle o indexes the FLATTENED env: spheres | capsules | cuboids | planes, o in [0, n_obs) with n_obs = grid_cc_num_obstacles(env). Pair index is pair = i*n_obs + o (sphere-major).
     *   s_ddist layout is pair-major: pair (i,o)'s NV-gradient is s_ddist[pair*NV .. pair*NV+NV-1].
     *
     * @param s_dist is the per-PAIR clearance output (size NUM_COLLISION_SPHERES*n_obs, RUNTIME-sized)
     * @param s_ddist is the per-PAIR clearance Jacobian output (size NUM_COLLISION_SPHERES*n_obs*NUM_VEL, pair-major, RUNTIME-sized)
     * @param s_q is the vector of joint positions
     * @param d_robotModel is the initialized model-specific helpers on the GPU
     * @param env is the runtime obstacle set (grid_collision::Environment<T>)
     * @param s_sphere_pos is caller scratch of size 3*NUM_COLLISION_SPHERES (sphere world positions)
     * @param s_sphere_r is caller scratch of size NUM_COLLISION_SPHERES (filled here from the baked radii)
     * @param d_workspace is the multi_target FK scratch at TIER_LITE+ (nullptr at TIER_SHARED)
     * @param s_normal is caller scratch of size 3*NUM_COLLISION_SPHERES*n_obs (per-pair normals, RUNTIME-sized)
     * @param s_pos_grad is caller scratch of size 3*NUM_VEL*NUM_COLLISION_SPHERES (batched dp/dq)
     */
    template <typename T, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __device__
    void collision_distance_pairs_gradient(T *s_dist, T *s_ddist, const T *s_q, const grid::robotModel<T> *d_robotModel, const Environment<T> &env, T *s_sphere_pos, T *s_sphere_r, T *s_normal, T *s_pos_grad, T *d_workspace = nullptr) {
        collision_distance_pairs<T, RESOURCE_TIER>(s_dist, s_normal, s_q, d_robotModel, env, s_sphere_pos, s_sphere_r, d_workspace);
        grid::multi_target_position_gradient_device<T, RESOURCE_TIER>(s_pos_grad, s_q, d_robotModel, d_workspace);
        __syncthreads();
        const int n_obs = grid_cc_num_obstacles<T>(env);
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < NUM_COLLISION_SPHERES * n_obs * 18; ind += blockDim.x*blockDim.y){
            int vi = ind % 18; int pair = ind / 18; int i = pair / n_obs;
            int jb = 3 * (18 * i + vi);
            s_ddist[ind] = s_normal[3*pair+0]*s_pos_grad[jb+0] + s_normal[3*pair+1]*s_pos_grad[jb+1] + s_normal[3*pair+2]*s_pos_grad[jb+2];
        }
        __syncthreads();
    }

